INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36508, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前", "is_correct": true, "explanation": "「寝る前」は寝る時点より手前を表し、「温かいお茶を飲む」と合う。"}, {"text": "夜明け", "is_correct": false, "explanation": "夜が明ける時刻を表す語で、「寝る夜明けに」は成り立たず、寝る時点を示せない。"}, {"text": "正午", "is_correct": false, "explanation": "昼の十二時を表す語で、「寝る正午に」は成り立たず、合わない。"}, {"text": "終点", "is_correct": false, "explanation": "行き着く最後の場所を表す語で、寝る時点を示すことはできず、合わない。"}], "explanations": {"前": "「寝る前」は寝る時点より手前を表し、「温かいお茶を飲む」と合う。", "夜明け": "夜が明ける時刻を表す語で、「寝る夜明けに」は成り立たず、寝る時点を示せない。", "正午": "昼の十二時を表す語で、「寝る正午に」は成り立たず、合わない。", "終点": "行き着く最後の場所を表す語で、寝る時点を示すことはできず、合わない。"}, "sentence_index": 0, "correct_answer": "前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "映画の前のほうで、エンドロールが流れた。", "explanation": "ここは〈終わりのほう〉の意味。前のほうは始まりの部分を指すので、エンドロールが流れる終わりには合わない。"}, {"text": "前の会議は、来週の月曜日です。", "explanation": "ここは〈次の〉の意味。「前の」は既に過ぎたものを指すので、来週の会議には合わない。"}, {"text": "今から三年前に会いましょう。", "explanation": "ここは〈これから〉の意味。前は過去の時点を指すので、今からの約束には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36508, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前", "is_correct": true, "explanation": "「列の前のほう」は列の中で先頭寄りの位置を表し、「座ると話がよく聞こえる」と合う。"}, {"text": "夕方", "is_correct": false, "explanation": "時間帯を表す語で、列の位置を示すことはできず、合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は天気を表す語で、『列の雨のほう』は位置を示せず、意味が通らない。"}, {"text": "月末", "is_correct": false, "explanation": "時期を表す語で、列の位置には使えない。"}], "explanations": {"前": "「列の前のほう」は列の中で先頭寄りの位置を表し、「座ると話がよく聞こえる」と合う。", "夕方": "時間帯を表す語で、列の位置を示すことはできず、合わない。", "雨": "雨は天気を表す語で、『列の雨のほう』は位置を示せず、意味が通らない。", "月末": "時期を表す語で、列の位置には使えない。"}, "sentence_index": 6, "correct_answer": "前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "箱の前に、りんごが入っている。", "explanation": "ここは〈中〉の意味。前は場所の手前を表すので、箱の内側に入っている意味には使わない。"}, {"text": "食べる前に、食べ終わった。", "explanation": "ここは〈後〉の意味。前は基準になる動作より先のことを表すので、食べ終わった後の出来事とは合わない。"}, {"text": "列の一番前は、最後尾だ。", "explanation": "ここは〈後ろ〉の意味。前は先頭側を表すので、最後尾を指す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36508, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出かける前を、鍵を確認する。", "corrected_sentence": "出かける前に、鍵を確認する。", "error_description": "時点の「〜前」には「に」を付ける。「前を」は目的語の「を」で、時点を表す使い方として誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36508, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝る前で、スマホを見ないようにしている。", "corrected_sentence": "寝る前に、スマホを見ないようにしている。", "error_description": "時点の『〜前』には『に』を付ける。『で』は場所や手段を示すので、時点には使えない。正しくは『に』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36510, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ペンや消しゴムの類」の「の」で、名詞の仲間を「類」につなぐ。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は動作の対象を示すので、「類」の前には入らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」で、名詞を「類」につなげられない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す「より」で、仲間をまとめる語にはつながらない。"}], "correct_answer": "の", "explanations": {"の": "「ペンや消しゴムの類」の「の」で、名詞の仲間を「類」につなぐ。", "を": "目的語の「を」は動作の対象を示すので、「類」の前には入らない。", "へ": "方向を示す「へ」で、名詞を「類」につなげられない。", "より": "比較を示す「より」で、仲間をまとめる語にはつながらない。"}, "error_tags": {"を": "目的語の「を」は動作の対象を示すので、「類」の前には入らない。", "へ": "方向を示す「へ」は、名詞を「類」につなげられない。", "より": "比較を示す「より」は、仲間をまとめる語にはつながらない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36510, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「バケツの類」の「の」で、名詞の仲間を「類」につなぐ。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」で、「バケツが類は」と文がつながらない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」で、「バケツで類」と仲間をつなげない。"}, {"text": "に", "is_correct": false, "explanation": "位置や対象を示す「に」で、「バケツに類は」と仲間をつなげない。"}], "correct_answer": "の", "explanations": {"の": "「バケツの類」の「の」で、名詞の仲間を「類」につなぐ。", "が": "主語を示す「が」で、「バケツが類は」と文がつながらない。", "で": "場所や手段を示す「で」で、「バケツで類」と仲間をつなげない。", "に": "位置や対象を示す「に」で、「バケツに類は」と仲間をつなげない。"}, "error_tags": {"が": "主語を示す「が」は、「バケツが類は」と文がつながらない。", "で": "場所や手段を示す「で」は、「バケツで類」と仲間をつなげられない。", "に": "位置や対象を示す「に」は、「バケツに類は」と仲間をつなげられない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36510, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "「るい」は、おなじようなものや、なかまのことです。", "primary_collocate": null, "pronunciation": "るい", "ipa": "ɾɯi", "syllable_count": 2, "sentences": [{"text": "シャツやズボンなどの類は、下の引き出しに入れてあります。", "target_word": "類", "complexity_tier": "T3", "furigana": "シャツやズボンなどの類[るい]は、下[した]の引[ひ]き出[だ]しに入[い]れてあります。", "sentence_source": "generated"}, {"text": "ペンや消しゴムの類は、かばんの小さなポケットに入れている。", "target_word": "類", "complexity_tier": "T3", "furigana": "ペンや消[け]しゴムの類[るい]は、かばんの小[ちい]さなポケットに入[い]れている。", "sentence_source": "generated"}, {"text": "「類は友を呼ぶ」というとおり、私の友達はみんな音楽が好きだ。", "target_word": "類", "complexity_tier": "T3", "furigana": "「類[るい]は友[とも]を呼[よ]ぶ」というとおり、私[わたし]の友達[ともだち]はみんな音楽[おんがく]が好[す]きだ。", "sentence_source": "generated"}, {"text": "この本棚には、辞典や図鑑の類がたくさん並んでいる。", "target_word": "類", "complexity_tier": "T3", "furigana": "この本棚[ほんだな]には、辞典[じてん]や図鑑[ずかん]の類[るい]がたくさん並[なら]んでいる。", "sentence_source": "generated"}, {"text": "りんごやみかんなどの類は、冷蔵庫で保存します。", "target_word": "類", "complexity_tier": "T3", "furigana": "りんごやみかんなどの類[るい]は、冷蔵庫[れいぞうこ]で保存[ほぞん]します。", "sentence_source": "generated"}, {"text": "古い手紙や写真の類は、箱に入れてしまっておいた。", "target_word": "類", "complexity_tier": "T3", "furigana": "古[ふる]い手紙[てがみ]や写真[しゃしん]の類[るい]は、箱[はこ]に入[い]れてしまっておいた。", "sentence_source": "generated"}, {"text": "その店では、パンやケーキの類を安く売っている。", "target_word": "類", "complexity_tier": "T3", "furigana": "その店[みせ]では、パンやケーキの類[るい]を安[やす]く売[う]っている。", "sentence_source": "generated"}, {"text": "掃除に使うほうきやバケツの類は、物置に置いてある。", "target_word": "類", "complexity_tier": "T3", "furigana": "掃除[そうじ]に使[つか]うほうきやバケツの類[るい]は、物置[ものおき]に置[お]いてある。", "sentence_source": "generated"}, {"text": "ナイフやはさみなどの刃物の類は、子どもの手が届かない所にしまう。", "target_word": "類", "complexity_tier": "T3", "furigana": "ナイフやはさみなどの刃物[はもの]の類[るい]は、子[こ]どもの手[て]が届[とど]かない所[ところ]にしまう。", "sentence_source": "generated"}, {"text": "テレビやラジオの類を持たない家も、今では少なくない。", "target_word": "類", "complexity_tier": "T3", "furigana": "テレビやラジオの類[るい]を持[も]たない家[いえ]も、今[いま]では少[すく]なくない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "類", "label": "基本形（漢字表記）"}, {"form": "ルイ", "label": "基本形（カタカナ表記）"}, {"form": "類の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "同じような性質を持つものの仲間、種類のまとまり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4e5da86-1411-4fd5-9f5f-e54c321bb1e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36510, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "類", "is_correct": true, "explanation": "「シャツやズボンなどの類」は同じ仲間をまとめて指し、文の意味が通る。"}, {"text": "色", "is_correct": false, "explanation": "衣類の性質を表す語で、「などの〜」の部分に入ると仲間をまとめる意味にならない。"}, {"text": "季節", "is_correct": false, "explanation": "時期を表す語で、衣類の仲間をまとめて指すことはできない。"}, {"text": "寿命", "is_correct": false, "explanation": "物が使える期間を表す語で、ここでは意味が通らない。"}], "explanations": {"類": "「シャツやズボンなどの類」は同じ仲間をまとめて指し、文の意味が通る。", "色": "衣類の性質を表す語で、「などの〜」の部分に入ると仲間をまとめる意味にならない。", "季節": "時期を表す語で、衣類の仲間をまとめて指すことはできない。", "寿命": "物が使える期間を表す語で、ここでは意味が通らない。"}, "sentence_index": 0, "correct_answer": "類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は、類を見ないほどよく効いた。", "explanation": "ここは〈比べるものがない〉の意味（『類を見ない』の慣用句）。仲間を表す義項とは違う。"}, {"text": "私の類は、来週の旅行に一緒に行く。", "explanation": "ここは〈仲間の一人〉の意味。類は似たものの集まりを指すので、一人の友人を言うのには使わない。"}, {"text": "この牛肉は、最高の類がついている。", "explanation": "ここは〈品質の段階〉の意味。「類」は似たものの集まりを指すので、等級は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36510, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "類", "is_correct": true, "explanation": "「パンやケーキの類」は似たものの仲間をまとめる語で、「安く売っている」と合う。"}, {"text": "湿度", "is_correct": false, "explanation": "空気の水分量を表す語で、売るものの仲間を指すことはできず、合わない。"}, {"text": "気候", "is_correct": false, "explanation": "地域の天気の傾向を表す語で、商品の仲間をまとめる語にはならない。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の性質を表す語で、ここでは「安く売る」対象の仲間をまとめる語にならない。"}], "explanations": {"類": "「パンやケーキの類」は似たものの仲間をまとめる語で、「安く売っている」と合う。", "湿度": "空気の水分量を表す語で、売るものの仲間を指すことはできず、合わない。", "気候": "地域の天気の傾向を表す語で、商品の仲間をまとめる語にはならない。", "味": "食べ物の性質を表す語で、ここでは「安く売る」対象の仲間をまとめる語にならない。"}, "sentence_index": 6, "correct_answer": "類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この犬は、昔の類を受け継いでいる。", "explanation": "ここは〈血のつながり〉の意味。「類」は似た性質の仲間で、受け継ぐ血統は表さない。"}, {"text": "その絵は類まれな美しさで、見る人を黙らせる。", "explanation": "ここは〈珍しい〉の意味（『類まれ』の慣用句）。仲間を表す義項とは違う。"}, {"text": "この布は類がよい。", "explanation": "ここは〈質の良さ〉の意味。「類」は似たものの仲間で、質の良し悪しは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36510, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ノートやペンなどを類は、机の引き出しに入れている。", "corrected_sentence": "ノートやペンなどの類は、机の引き出しに入れている。", "error_description": "「〜などの類」は「の」で名詞をつなぐ。「を」は目的語の助詞で、「などを類は」と名詞をつなげられず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36510, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "フライパンや鍋などの類の、台所の棚にまとめて置いてある。", "corrected_sentence": "フライパンや鍋などの類は、台所の棚にまとめて置いてある。", "error_description": "文の主題を示す「は」が必要な文で、「の」は名詞を修飾するため、文が続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b772f74f-5395-4c72-9d02-b305fd6c8efb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
