INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36512, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ふくろのこと。ものいれ。", "primary_collocate": null, "pronunciation": "のう", "ipa": "noɯ", "syllable_count": 2, "sentences": [{"text": "旅人は腰の嚢から、小さな地図を取り出した。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "旅人[たびびと]は腰[こし]の嚢[のう]から、小[ちい]さな地図[ちず]を取[と]り出[だ]した。", "sentence_source": "generated"}, {"text": "昔の兵士は、米を入れた嚢を肩にかけて歩いた。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "昔[むかし]の兵士[へいし]は、米[こめ]を入[い]れた嚢[のう]を肩[かた]にかけて歩[ある]いた。", "sentence_source": "generated"}, {"text": "嚢の口をひもでしっかり結んだので、中身はこぼれなかった。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "嚢[のう]の口[くち]をひもでしっかり結[むす]んだので、中身[なかみ]はこぼれなかった。", "sentence_source": "generated"}, {"text": "老人は古い嚢に、薬草をたくさん入れて持ち帰った。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "老人[ろうじん]は古[ふる]い嚢[のう]に、薬草[やくそう]をたくさん入[い]れて持[も]ち帰[かえ]った。", "sentence_source": "generated"}, {"text": "嚢が破れていたため、豆が道にばらばらと落ちた。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "嚢[のう]が破[やぶ]れていたため、豆[まめ]が道[みち]にばらばらと落[お]ちた。", "sentence_source": "generated"}, {"text": "少年は布でできた嚢を作り、お守りを入れた。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "少年[しょうねん]は布[ぬの]でできた嚢[のう]を作[つく]り、お守[まも]りを入[い]れた。", "sentence_source": "generated"}, {"text": "嚢の中には、銀貨が三枚だけ残っていた。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "嚢[のう]の中[なか]には、銀貨[ぎんか]が三枚[さんまい]だけ残[のこ]っていた。", "sentence_source": "generated"}, {"text": "嚢は軽かったが、長い道のりで肩が痛くなった。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "嚢[のう]は軽[かる]かったが、長[なが]い道[みち]のりで肩[かた]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "商人は嚢を開けて、珍しい香辛料を客に見せた。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "商人[しょうにん]は嚢[のう]を開[あ]けて、珍[めずら]しい香辛料[こうしんりょう]を客[きゃく]に見[み]せた。", "sentence_source": "generated"}, {"text": "山へ行くとき、祖父は水を入れた嚢を必ず持っていった。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "山[やま]へ行[い]くとき、祖父[そふ]は水[みず]を入[い]れた嚢[のう]を必[かなら]ず持[も]っていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "嚢", "label": "基本形"}], "register": "literary", "sense_fingerprint": "物を入れて持ち運ぶ、布などでできたふくろ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36512, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嚢", "is_correct": true, "explanation": "文中の〈嚢〉（物を入れる布などの袋）が入る。腰に下げて地図を取り出せる袋として自然。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の開口部で、腰から物を取り出す入れ物にはならない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理道具で、腰にさげて地図を取り出す入れ物としては合わない。"}, {"text": "皿", "is_correct": false, "explanation": "皿は食器で、腰から地図を取り出す入れ物にはならない。"}], "explanations": {"嚢": "文中の〈嚢〉（物を入れる布などの袋）が入る。腰に下げて地図を取り出せる袋として自然。", "窓": "窓は建物の開口部で、腰から物を取り出す入れ物にはならない。", "鍋": "鍋は調理道具で、腰にさげて地図を取り出す入れ物としては合わない。", "皿": "皿は食器で、腰から地図を取り出す入れ物にはならない。"}, "sentence_index": 0, "correct_answer": "嚢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は古い嚢を弾いて、故郷の歌を歌った。", "explanation": "ここは〈嚢〉（物を入れる袋）の意味。〈楽器〉の位置に入れた文で、楽器は弾くが、袋は弾く対象にならない。"}, {"text": "雨が降ってきたので、古い嚢を広げて差した。", "explanation": "〈傘〉の位置に入れた文。傘は差すが、嚢は差して使うものではないので合わない。"}, {"text": "朝になると、古い嚢がからりと晴れた。", "explanation": "ここは〈嚢〉（物を入れる袋）の意味。晴れるのは空や天気で、袋が晴れることはないので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36512, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嚢", "is_correct": true, "explanation": "文中の〈嚢〉が入る。銀貨が中に残っている入れ物として自然。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の開口部で、銀貨が中に残る入れ物ではない。"}, {"text": "橋", "is_correct": false, "explanation": "橋は川や道にかける構造物で、中に銀貨が残るものではない。"}, {"text": "階段", "is_correct": false, "explanation": "階段は建物の段差で、中に物を入れて残すことはできない。"}], "explanations": {"嚢": "文中の〈嚢〉が入る。銀貨が中に残っている入れ物として自然。", "窓": "窓は建物の開口部で、銀貨が中に残る入れ物ではない。", "橋": "橋は川や道にかける構造物で、中に銀貨が残るものではない。", "階段": "階段は建物の段差で、中に物を入れて残すことはできない。"}, "sentence_index": 6, "correct_answer": "嚢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は毎朝、鐘を嚢で鳴らして家族を起こした。", "explanation": "〈鐘〉の位置に入れた文。鐘は鳴らすものだが、袋は鐘を鳴らす道具にはならないので、この使い方は合わない。"}, {"text": "大雨の前に、嚢の柱が倒れて家が傾いた。", "explanation": "〈柱〉の位置に入れた文。柱は家を支える建材で、袋は建物の部材にはならないので合わない。"}, {"text": "嚢を三回ノックしてから、部屋に入った。", "explanation": "〈扉〉の位置に入れた文。ノックするのは扉で、袋を叩いて部屋に入る合図にはならないので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36512, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は布で作った嚢で、古いボタンを入れて保管していた。", "corrected_sentence": "祖母は布で作った嚢に、古いボタンを入れて保管していた。", "error_description": "「入れる」は入れ物を「に」で示す。嚢が入れる先なので「に」が正しく、「で」は場所や手段を表すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36512, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は、水を入れた嚢を必ず持っていかった。", "corrected_sentence": "父は、水を入れた嚢を必ず持っていった。", "error_description": "「行く」の過去形は「行った」。「行かった」は誤った活用形で、嚢を持つ動作の「持っていった」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36513, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「嚢ができた」の主語は嚢なので「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「できる」は目的語を取らないので、「を」は合わない。"}, {"text": "で", "is_correct": false, "explanation": "「嚢でできた」は場所や手段を表し、主語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「嚢とできた」は並列の意味になり、文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「嚢ができた」の主語は嚢なので「が」が正しい。", "を": "「できる」は目的語を取らないので、「を」は合わない。", "で": "「嚢でできた」は場所や手段を表し、主語にはならない。", "と": "「嚢とできた」は並列の意味になり、文として成り立たない。"}, "error_tags": {"を": "目的語の格", "で": "場所・手段", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36513, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「嚢があった」の主語。存在するものを示す「が」で正しい。"}, {"text": "を", "is_correct": false, "explanation": "「あった」は存在を表すので、目的語の「を」は合わない。"}, {"text": "の", "is_correct": false, "explanation": "「嚢の」は所属を示すだけで、「あった」の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「嚢と」は並列の相手を示し、存在の主語としては成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「嚢があった」の主語。存在するものを示す「が」で正しい。", "を": "「あった」は存在を表すので、目的語の「を」は合わない。", "の": "「嚢の」は所属を示すだけで、「あった」の主語にならない。", "と": "「嚢と」は並列の相手を示し、存在の主語としては成り立たない。"}, "error_tags": {"を": "目的語の格", "の": "連体・所属", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36513, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "物を入れるための袋。体内の袋状の器官もいう。", "primary_collocate": null, "pronunciation": "のう", "ipa": "noɯ", "syllable_count": 2, "sentences": [{"text": "医者は、レントゲンに写った嚢を見て、詳しい検査を勧めた。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、レントゲンに写[うつ]った嚢[のう]を見[み]て、詳[くわ]しい検査[けんさ]を勧[すす]めた。", "sentence_source": "generated"}, {"text": "腎臓に小さな嚢ができたが、特に心配はないと言われた。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "腎臓[じんぞう]に小[ちい]さな嚢[のう]ができたが、特[とく]に心配[しんぱい]はないと言[い]われた。", "sentence_source": "generated"}, {"text": "イカは墨を入れた嚢を持っていて、危ないときに墨を出す。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "イカは墨[すみ]を入[い]れた嚢[のう]を持[も]っていて、危[あぶ]ないときに墨[すみ]を出[だ]す。", "sentence_source": "generated"}, {"text": "嚢の壁が厚くなると、中の液体が出にくくなる。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "嚢[のう]の壁[かべ]が厚[あつ]くなると、中[なか]の液体[えきたい]が出[で]にくくなる。", "sentence_source": "generated"}, {"text": "超音波検査で、膵臓の近くに小さな嚢が見つかった。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "超音波検査[ちょうおんぱけんさ]で、膵臓[すいぞう]の近[ちか]くに小[ちい]さな嚢[のう]が見[み]つかった。", "sentence_source": "generated"}, {"text": "手術で、肝臓にあった嚢を取り除いた。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]で、肝臓[かんぞう]にあった嚢[のう]を取[と]り除[のぞ]いた。", "sentence_source": "generated"}, {"text": "嚢の中に水がたまって、腫れてしまった。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "嚢[のう]の中[なか]に水[みず]がたまって、腫[は]れてしまった。", "sentence_source": "generated"}, {"text": "超音波で見ると、膵臓の横に液体の入った嚢があった。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "超音波[ちょうおんぱ]で見[み]ると、膵臓[すいぞう]の横[よこ]に液体[えきたい]の入[はい]った嚢[のう]があった。", "sentence_source": "generated"}, {"text": "超音波の画像で、胸の近くに丸い嚢が見つかった。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "超音波[ちょうおんぱ]の画像[がぞう]で、胸[むね]の近[ちか]くに丸[まる]い嚢[のう]が見[み]つかった。", "sentence_source": "generated"}, {"text": "医者は嚢の壁を調べて、炎症がないか確かめた。", "target_word": "嚢", "complexity_tier": "T3", "furigana": "医者[いしゃ]は嚢[のう]の壁[かべ]を調[しら]べて、炎症[えんしょう]がないか確[たし]かめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "嚢", "label": "基本形"}], "register": "written", "sense_fingerprint": "物を入れる袋、また体内の袋状の器官や組織", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36513, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嚢", "is_correct": true, "explanation": "文中の〈嚢〉（体内の袋状の器官）が入る。レントゲンに写る器官を指し、医者が見て検査を勧める文脈に合う。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、レントゲンに写る体の器官としては合わない。"}, {"text": "靴", "is_correct": false, "explanation": "靴は履くもので、レントゲンに写る器官ではない。"}, {"text": "切符", "is_correct": false, "explanation": "切符は乗車券で、レントゲンに写る体の一部にはならない。"}], "explanations": {"嚢": "文中の〈嚢〉（体内の袋状の器官）が入る。レントゲンに写る器官を指し、医者が見て検査を勧める文脈に合う。", "天井": "天井は部屋の上の面で、レントゲンに写る体の器官としては合わない。", "靴": "靴は履くもので、レントゲンに写る器官ではない。", "切符": "切符は乗車券で、レントゲンに写る体の一部にはならない。"}, "sentence_index": 0, "correct_answer": "嚢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春になると、嚢が一斉に咲いた。", "explanation": "ここは〈嚢〉（体内の袋状の器官や入れ物）の意味。〈花〉の位置に入れた文で、花は咲くが、嚢は咲くものではない。"}, {"text": "先生は、毎朝嚢を運転して学校へ行った。", "explanation": "〈乗り物〉の位置に入れた文。運転するのは乗り物で、体内の袋状の器官は運転の対象にならないので、この使い方は合わない。"}, {"text": "その子は嚢を奏でて、みんなを感動させた。", "explanation": "〈音楽〉の位置に入れた文。奏でるのは音楽や音色で、袋状の嚢は奏でる対象にならないので、この使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36513, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嚢", "is_correct": true, "explanation": "文中の〈嚢〉が入る。体の中の袋状の器官に液体がたまる文脈に合う。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は錠を開ける道具で、体の中に水がたまる対象にはならない。"}, {"text": "通帳", "is_correct": false, "explanation": "通帳は預金の記録で、水がたまるものではない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の開口部で、体の中に水がたまる場所としては合わない。"}], "explanations": {"嚢": "文中の〈嚢〉が入る。体の中の袋状の器官に液体がたまる文脈に合う。", "鍵": "鍵は錠を開ける道具で、体の中に水がたまる対象にはならない。", "通帳": "通帳は預金の記録で、水がたまるものではない。", "窓": "窓は建物の開口部で、体の中に水がたまる場所としては合わない。"}, "sentence_index": 6, "correct_answer": "嚢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医者は嚢を履いて、炎症がないか確かめた。", "explanation": "〈靴〉の位置に入れた文。靴は履くものだが、体内の袋状の器官は履くことができないので、この使い方はしない。"}, {"text": "医者は嚢に頭を下げて、炎症がないか確かめた。", "explanation": "〈人〉の位置に入れた文。頭を下げるのは人に対してで、体内の袋状の器官には使わない言い方なので、この使い方は合わない。"}, {"text": "医者は嚢の味を確かめて、炎症がないか確かめた。", "explanation": "〈食べ物〉の位置に入れた文。味を確かめるのは食べ物や飲み物で、体内の嚢の味を確かめることはできないので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36513, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "検査で、腎臓に丸い嚢を見つかった。", "corrected_sentence": "検査で、腎臓に丸い嚢が見つかった。", "error_description": "「見つかる」は自動詞で、見つかったものが主語になるため「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36513, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医者は胸の嚢に超音波で調べた。", "corrected_sentence": "医者は胸の嚢を超音波で調べた。", "error_description": "「調べる」は対象を「を」で示す。嚢が調べられる対象なので「を」が正しく、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36514, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷たい", "is_correct": true, "explanation": "温かいの対義語。温度が低い状態を表し、冷めたお茶と対になる。"}, {"text": "熱い", "is_correct": false, "explanation": "熱いは温度が高いことで、温かいの対義語にはならない。"}, {"text": "硬い", "is_correct": false, "explanation": "硬いは触ったときの固さを表し、温度とは関係がない。"}, {"text": "濃い", "is_correct": false, "explanation": "濃いは色や味の強さを表し、温かさの対義語ではない。"}], "correct_answer": "冷たい", "explanations": {"冷たい": "温かいの対義語。温度が低い状態を表し、冷めたお茶と対になる。", "熱い": "熱いは温度が高いことで、温かいの対義語にはならない。", "硬い": "硬いは触ったときの固さを表し、温度とは関係がない。", "濃い": "濃いは色や味の強さを表し、温かさの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36514, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷たい", "is_correct": true, "explanation": "温かいの対義語。冷めた状態のごはんを表し、温かいごはんと対になる。"}, {"text": "甘い", "is_correct": false, "explanation": "甘いは味の種類を表し、温度の対義語ではない。"}, {"text": "軽い", "is_correct": false, "explanation": "軽いは重さを表す語で、温かさの対義語にはならない。"}, {"text": "厚い", "is_correct": false, "explanation": "厚いは物の厚みを表し、温かさとは関係がない。"}], "correct_answer": "冷たい", "explanations": {"冷たい": "温かいの対義語。冷めた状態のごはんを表し、温かいごはんと対になる。", "甘い": "甘いは味の種類を表し、温度の対義語ではない。", "軽い": "軽いは重さを表す語で、温かさの対義語にはならない。", "厚い": "厚いは物の厚みを表し、温かさとは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36514, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "ほどよく熱をもち、さわると気持ちがいいこと。", "primary_collocate": null, "pronunciation": "あたたかい", "ipa": "atatakai", "syllable_count": 5, "sentences": [{"text": "寒い朝は、温かいスープを飲むとほっとする。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]は、温[あたた]かいスープを飲[の]むとほっとする。", "sentence_source": "generated"}, {"text": "母の手は温かくて、さわると安心する。", "target_word": "温かくて", "complexity_tier": "T3", "furigana": "母[はは]の手[て]は温[あたた]かくて、さわると安心[あんしん]する。", "sentence_source": "generated"}, {"text": "温かいお風呂に入ったので、体がぽかぽかになった。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "温[あたた]かいお風呂[ふろ]に入[はい]ったので、体[からだ]がぽかぽかになった。", "sentence_source": "generated"}, {"text": "冷めてしまったから、もう一度温かいお茶を入れてください。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "冷[さ]めてしまったから、もう一度[いちど]温[あたた]かいお茶[ちゃ]を入[い]れてください。", "sentence_source": "generated"}, {"text": "このタオルは乾燥機から出したばかりで、まだ温かい。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "このタオルは乾燥機[かんそうき]から出[だ]したばかりで、まだ温[あたた]かい。", "sentence_source": "generated"}, {"text": "犬をだくと、小さな体が温かかった。", "target_word": "温かかった", "complexity_tier": "T3", "furigana": "犬[いぬ]をだくと、小[ちい]さな体[からだ]が温[あたた]かかった。", "sentence_source": "generated"}, {"text": "このスープは温かいうちに飲んでね。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "このスープは温[あたた]かいうちに飲[の]んでね。", "sentence_source": "generated"}, {"text": "外で遊んだあと、温かい牛乳をもらった。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "外[そと]で遊[あそ]んだあと、温[あたた]かい牛乳[ぎゅうにゅう]をもらった。", "sentence_source": "generated"}, {"text": "手袋をはめた手は温かく、寒くなかった。", "target_word": "温かく", "complexity_tier": "T3", "furigana": "手袋[てぶくろ]をはめた手[て]は温[あたた]かく、寒[さむ]くなかった。", "sentence_source": "generated"}, {"text": "温かいごはんに、卵をかけて食べるのが好きだ。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "温[あたた]かいごはんに、卵[たまご]をかけて食[た]べるのが好[す]きだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "温かい", "label": "終止形"}, {"form": "温かく", "label": "連用形"}, {"form": "温かくて", "label": "て形"}, {"form": "温かかった", "label": "過去形"}, {"form": "温かくない", "label": "否定形"}, {"form": "温かければ", "label": "仮定形"}], "register": "spoken", "sense_fingerprint": "食べ物・飲み物・手などがほどよく熱をもち、ふれると気持ちがよい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36514, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温かい", "is_correct": true, "explanation": "文中の〈温かい〉が入る。スープの温度がほどよく、飲むとほっとする状態を表す。"}, {"text": "痛い", "is_correct": false, "explanation": "痛いは体の痛みを表し、スープの温度の説明には合わない。"}, {"text": "忙しい", "is_correct": false, "explanation": "忙しいは時間の余裕がないことで、スープの温かさには当てはまらない。"}, {"text": "狭い", "is_correct": false, "explanation": "狭いは広さを表す語で、スープの状態を説明できない。"}], "explanations": {"温かい": "文中の〈温かい〉が入る。スープの温度がほどよく、飲むとほっとする状態を表す。", "痛い": "痛いは体の痛みを表し、スープの温度の説明には合わない。", "忙しい": "忙しいは時間の余裕がないことで、スープの温かさには当てはまらない。", "狭い": "狭いは広さを表す語で、スープの状態を説明できない。"}, "sentence_index": 0, "correct_answer": "温かい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の昼、温かいアイスを食べて、少しさっぱりした。", "explanation": "〈冷たい〉の位置に入れた文。アイスは冷たい食べ物で、温かいとは言わないので、この使い方は合わない。"}, {"text": "駅まで、温かい距離を歩いて帰った。", "explanation": "ここは〈温かい〉（ぬくもりや心地よさ）の意味。道のりの長さは「遠い」で表し、温度や心地よさの語は距離には使わないので、この使い方は合わない。"}, {"text": "このお店のお菓子は温かい値段で、とても安かった。", "explanation": "ここは〈温かい〉（ぬくもりや心地よさ）の意味。金額の大きさは温度の語では表せず、金額そのものを示す語を使うので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36514, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温かい", "is_correct": true, "explanation": "文中の〈温かい〉が入る。「温かいうちに」は、まだ温かいあいだに飲んでという意味になる。"}, {"text": "寂しい", "is_correct": false, "explanation": "寂しいは気持ちの状態で、スープの温度には当てはまらない。"}, {"text": "重い", "is_correct": false, "explanation": "重いは重さを表し、「うちに」で飲むタイミングを示す文には続かない。"}, {"text": "遠い", "is_correct": false, "explanation": "遠いは距離を表す語で、スープの状態を説明できない。"}], "explanations": {"温かい": "文中の〈温かい〉が入る。「温かいうちに」は、まだ温かいあいだに飲んでという意味になる。", "寂しい": "寂しいは気持ちの状態で、スープの温度には当てはまらない。", "重い": "重いは重さを表し、「うちに」で飲むタイミングを示す文には続かない。", "遠い": "遠いは距離を表す語で、スープの状態を説明できない。"}, "sentence_index": 6, "correct_answer": "温かい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室には、温かい人数の生徒がいた。", "explanation": "ここは〈温かい〉（ぬくもりや心地よさ）の意味。人の多さは「多い」で表し、温度や心地よさの語は人数には使わないので、この使い方は合わない。"}, {"text": "この電車は温かい形をしている。", "explanation": "ここは〈温かい〉（ぬくもりや心地よさ）の意味。形の特徴は「丸い」「四角い」などで表し、温度や心地よさの語は形には使わないので、この使い方は合わない。"}, {"text": "この試験は温かくて、みんな解けなかった。", "explanation": "〈難しい〉の位置に入れた文。試験の難しさを温度の語で表すことはできないので、この使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36514, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒い夜、温かさお茶を飲むと体がほっとする。", "corrected_sentence": "寒い夜、温かいお茶を飲むと体がほっとする。", "error_description": "「温かい」は形容詞なので、お茶を直接修飾するには「温かい」の形が必要。名詞の「温かさ」にしたため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "温かくて", "is_correct": true, "explanation": "て形で、後の文へつなぐ働きをする。「母の手は温かくて、さわると安心する」と文を続けている。"}, {"text": "温かかった", "is_correct": false, "explanation": "過去形で、過去の状態を表す。現在の状態を述べるこの文には合わない。"}, {"text": "温かくない", "is_correct": false, "explanation": "否定形で、温かさを打ち消す意味になるため、文の内容と逆になる。"}, {"text": "温かいくて", "is_correct": false, "explanation": "「い」形容詞のて形は「温かくて」。「温かいくて」は活用の誤り。"}], "correct_form": "温かくて", "base_form": "温かい", "form_label": "て形", "sentence_index": 1, "explanations": {"温かくて": "て形で、後の文へつなぐ働きをする。「母の手は温かくて、さわると安心する」と文を続けている。", "温かかった": "過去形で、過去の状態を表す。現在の状態を述べるこの文には合わない。", "温かくない": "否定形で、温かさを打ち消す意味になるため、文の内容と逆になる。", "温かいくて": "「い」形容詞のて形は「温かくて」。「温かいくて」は活用の誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36514, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬の夜、温かいココアを飲むと、体が温かいなる。", "corrected_sentence": "冬の夜、温かいココアを飲むと、体が温かくなる。", "error_description": "「なる」には形容詞の連用形「温かく」が必要。「温かい」のままでは文法的に誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "温かい", "is_correct": true, "explanation": "連体形で、「温かい牛乳」のように後ろの名詞を直接修飾する形。文に合う。"}, {"text": "温かく", "is_correct": false, "explanation": "連用形で、名詞を直接修飾できない。「温かく牛乳」とは続かない。"}, {"text": "温かくて", "is_correct": false, "explanation": "て形で、名詞を直接修飾できない。「温かくて牛乳」とは続かない。"}, {"text": "温かいくない", "is_correct": false, "explanation": "「い」形容詞の否定形は「温かくない」。「温かいくない」は活用の誤り。"}], "correct_form": "温かい", "base_form": "温かい", "form_label": "連体形", "sentence_index": 7, "explanations": {"温かい": "連体形で、「温かい牛乳」のように後ろの名詞を直接修飾する形。文に合う。", "温かく": "連用形で、名詞を直接修飾できない。「温かく牛乳」とは続かない。", "温かくて": "て形で、名詞を直接修飾できない。「温かくて牛乳」とは続かない。", "温かいくない": "「い」形容詞の否定形は「温かくない」。「温かいくない」は活用の誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36515, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷たい", "is_correct": true, "explanation": "温度の逆を表す対義語として辞典に載る。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、温度の対義語ではない。"}, {"text": "深い", "is_correct": false, "explanation": "奥行きを表す語で、温度とは関係がない。"}, {"text": "甘い", "is_correct": false, "explanation": "味を表す語で、温度の対義にはならない。"}], "correct_answer": "冷たい", "explanations": {"冷たい": "温度の逆を表す対義語として辞典に載る。", "重い": "重さを表す語で、温度の対義語ではない。", "深い": "奥行きを表す語で、温度とは関係がない。", "甘い": "味を表す語で、温度の対義にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
