INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36515, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "温度が高く、心地よいと感じるさま。", "primary_collocate": null, "pronunciation": "あたたかい", "ipa": "atatakai", "syllable_count": 5, "sentences": [{"text": "窓ぎわは日が当たって、温かい空気に包まれていた。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "窓[まど]ぎわは日[ひ]が当[あ]たって、温[あたた]かい空気[くうき]に包[つつ]まれていた。", "sentence_source": "generated"}, {"text": "温かい飲み物を持って、ベンチに座った。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "温[あたた]かい飲[の]み物[もの]を持[も]って、ベンチに座[すわ]った。", "sentence_source": "generated"}, {"text": "冬の夜、温かい布団に入ると、すぐに眠くなる。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "冬[ふゆ]の夜[よる]、温[あたた]かい布団[ふとん]に入[はい]ると、すぐに眠[ねむ]くなる。", "sentence_source": "generated"}, {"text": "温泉の湯は温かく、冷えた体がゆっくりほぐれた。", "target_word": "温かく", "complexity_tier": "T3", "furigana": "温泉[おんせん]の湯[ゆ]は温[あたた]かく、冷[ひ]えた体[からだ]がゆっくりほぐれた。", "sentence_source": "generated"}, {"text": "焼きたてのパンは温かくて、香りもよかった。", "target_word": "温かくて", "complexity_tier": "T3", "furigana": "焼[や]きたてのパンは温[あたた]かくて、香[かお]りもよかった。", "sentence_source": "generated"}, {"text": "湯たんぽのおかげで、足もとが温かい。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "湯[ゆ]たんぽのおかげで、足[あし]もとが温[あたた]かい。", "sentence_source": "generated"}, {"text": "病院では、温かいおかゆが出された。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "病院[びょういん]では、温[あたた]かいおかゆが出[だ]された。", "sentence_source": "generated"}, {"text": "両手で包むと、カップが温かかった。", "target_word": "温かかった", "complexity_tier": "T3", "furigana": "両手[りょうて]で包[つつ]むと、カップが温[あたた]かかった。", "sentence_source": "generated"}, {"text": "日なたの石はまだ温かく、猫が気持ちよさそうに寝ていた。", "target_word": "温かく", "complexity_tier": "T3", "furigana": "日[ひ]なたの石[いし]はまだ温[あたた]かく、猫[ねこ]が気持[きも]ちよさそうに寝[ね]ていた。", "sentence_source": "generated"}, {"text": "冷たい水より、温かいお湯で顔を洗うほうが心地よい。", "target_word": "温かい", "complexity_tier": "T3", "furigana": "冷[つめ]たい水[みず]より、温[あたた]かいお湯[ゆ]で顔[かお]を洗[あら]うほうが心地[ここち]よい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "温かい", "label": "終止形"}, {"form": "温かく", "label": "連用形"}, {"form": "温かくて", "label": "て形"}, {"form": "温かかった", "label": "過去形"}, {"form": "温かくない", "label": "否定形"}, {"form": "温かければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "物や空気の温度が高く、心地よく感じられる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 窓ぎわ (Zipf 1.61)']::text[], 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36515, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温かい", "is_correct": true, "explanation": "「温かい空気」と合い、日が当たる場面の温度を表す形容詞として自然に入る。"}, {"text": "固い", "is_correct": false, "explanation": "硬さを表す語で、空気の温度の状態を言うには合わない。"}, {"text": "速い", "is_correct": false, "explanation": "速さを表す形容詞で、空気の様子を形容すると意味が通らない。"}, {"text": "細い", "is_correct": false, "explanation": "細さや幅を表す語で、空気には使えず文が成り立たない。"}], "explanations": {"温かい": "「温かい空気」と合い、日が当たる場面の温度を表す形容詞として自然に入る。", "固い": "硬さを表す語で、空気の温度の状態を言うには合わない。", "速い": "速さを表す形容詞で、空気の様子を形容すると意味が通らない。", "細い": "細さや幅を表す語で、空気には使えず文が成り立たない。"}, "sentence_index": 0, "correct_answer": "温かい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火傷しそうなほど温かいお茶を、一気に飲み干した。", "explanation": "ここは〈熱い〉の意味。やけどするほどの高温は「温かい」ではなく「熱い」と言うので、この語では不自然。"}, {"text": "真夏の夜、温かい風がまとわりついて、少しも心地よくない。", "explanation": "ここは〈生ぬるくて不快〉の意味。定義の〈心地よい〉と逆で、不快な蒸し暑さには「生ぬるい」を使うので、この語は合わない。"}, {"text": "真夏の昼は温かくて、外に出るのもつらい。", "explanation": "ここは〈暑い〉の意味。真夏の強い暑さは「温かい」ではなく「暑い」と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36515, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温かい", "is_correct": true, "explanation": "病院で出される食べ物の温度を表し、おかゆに合う。"}, {"text": "鋭い", "is_correct": false, "explanation": "鋭さを表す語で、おかゆの状態には使えない。"}, {"text": "浅い", "is_correct": false, "explanation": "深さを表す語で、食べ物の温度を言う文には合わない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さを表す語で、料理の状態を表せない。"}], "explanations": {"温かい": "病院で出される食べ物の温度を表し、おかゆに合う。", "鋭い": "鋭さを表す語で、おかゆの状態には使えない。", "浅い": "深さを表す語で、食べ物の温度を言う文には合わない。", "遅い": "速さを表す語で、料理の状態を表せない。"}, "sentence_index": 6, "correct_answer": "温かい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は温かい人柄で、誰にでも親切に接する。", "explanation": "ここは〈思いやりがある〉の意味。人柄を表す用法で、温度の心地よさという義項とは別なので合わない。"}, {"text": "やけどしそうなほど温かいラーメンを食べて、舌を痛めた。", "explanation": "ここは〈熱い〉の意味。やけどするほどの高温は「熱い」と言い、「温かい」では合わない。"}, {"text": "真夏のアスファルトは温かく、歩くとサンダルが溶けそうだ。", "explanation": "ここは〈暑い〉の意味。路面の強い熱さは「暑い」や「熱い」で表すので、「温かい」は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36515, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冷たいスープを飲んだら、体が温かいなった。", "corrected_sentence": "冷たいスープを飲んだら、体が温かくなった。", "error_description": "「温かい」は形容詞なので、「なる」に続けるには連用形「温かく」にする必要がある。「温かいなった」は誤りで、正しくは「温かくなった」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "温かい", "is_correct": true, "explanation": "名詞「飲み物」を直接修飾するので連体形が正しい。"}, {"text": "温かく", "is_correct": false, "explanation": "連用形で、名詞を直接修飾できない。"}, {"text": "温かくて", "is_correct": false, "explanation": "て形で、後ろに続く文が必要なので名詞の前には置けない。"}, {"text": "温かかろう", "is_correct": false, "explanation": "推量の形で、名詞を直接修飾できない。"}], "correct_form": "温かい", "base_form": "温かい", "form_label": "連体形", "sentence_index": 1, "explanations": {"温かい": "名詞「飲み物」を直接修飾するので連体形が正しい。", "温かく": "連用形で、名詞を直接修飾できない。", "温かくて": "て形で、後ろに続く文が必要なので名詞の前には置けない。", "温かかろう": "推量の形で、名詞を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36515, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒い朝、温かいにスープを飲むとほっとする。", "corrected_sentence": "寒い朝、温かいスープを飲むとほっとする。", "error_description": "「温かい」の直後に「に」が付いているのが誤り。「温かい」は名詞「スープ」を直接修飾するので、「に」は不要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "温かかった", "is_correct": true, "explanation": "過去の状態を表す文末の形で、「カップが温かかった」と合う。"}, {"text": "温かければ", "is_correct": false, "explanation": "仮定形で、文を言い切れず主節が必要になる。"}, {"text": "温かくて", "is_correct": false, "explanation": "て形で、文を言い切れず「。」で終われない。"}, {"text": "温かくなかった", "is_correct": false, "explanation": "否定の過去形で、肯定の状態を述べる文と合わない。"}], "correct_form": "温かかった", "base_form": "温かい", "form_label": "過去形", "sentence_index": 7, "explanations": {"温かかった": "過去の状態を表す文末の形で、「カップが温かかった」と合う。", "温かければ": "仮定形で、文を言い切れず主節が必要になる。", "温かくて": "て形で、文を言い切れず「。」で終われない。", "温かくなかった": "否定の過去形で、肯定の状態を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36516, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上がる", "is_correct": true, "explanation": "「下がる」の対義語で、上へ動くことを表す。"}, {"text": "回る", "is_correct": false, "explanation": "回転を表す動詞で、上下の対義語ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "移動させる動詞だが、上下の対義にはならない。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作を表し、移動の対義語ではない。"}], "correct_answer": "上がる", "explanations": {"上がる": "「下がる」の対義語で、上へ動くことを表す。", "回る": "回転を表す動詞で、上下の対義語ではない。", "運ぶ": "移動させる動詞だが、上下の対義にはならない。", "眺める": "見る動作を表し、移動の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36516, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ブラインドが」の主語を示す「が」。急に下がる動作の主体なので正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞だが、下がるは目的語を取らない動詞なので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、動きの主体を表す位置には合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や引用を示す助詞で、主語の位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "「ブラインドが」の主語を示す「が」。急に下がる動作の主体なので正しい。", "を": "目的語を示す助詞だが、下がるは目的語を取らない動詞なので合わない。", "で": "手段や場所を示す助詞で、動きの主体を表す位置には合わない。", "と": "相手や引用を示す助詞で、主語の位置には合わない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "と": "相手・引用"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上がる", "is_correct": true, "explanation": "「下がる」の対義語で、上へ動くことを表す。"}, {"text": "叩く", "is_correct": false, "explanation": "打つ動作で、上下の対義語ではない。"}, {"text": "測る", "is_correct": false, "explanation": "量を計る動詞で、対義語ではない。"}, {"text": "包む", "is_correct": false, "explanation": "覆う動作を表し、移動の対義語にはならない。"}], "correct_answer": "上がる", "explanations": {"上がる": "「下がる」の対義語で、上へ動くことを表す。", "叩く": "打つ動作で、上下の対義語ではない。", "測る": "量を計る動詞で、対義語ではない。", "包む": "覆う動作を表し、移動の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36516, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが、うえからしたにうごくこと。", "primary_collocate": null, "pronunciation": "さがる", "ipa": "sagaɾɯ", "syllable_count": 3, "sentences": [{"text": "ボタンを押すと、大きなスクリーンがゆっくり下がった。", "target_word": "下がった", "complexity_tier": "T3", "furigana": "ボタンを 押[お]すと、大[おお]きなスクリーンがゆっくり 下[さ]がった。", "sentence_source": "generated"}, {"text": "エレベーターが、ゆっくり一階まで下がった。", "target_word": "下がった", "complexity_tier": "T3", "furigana": "エレベーターが、ゆっくり一階[いっかい]まで下[さ]がった。", "sentence_source": "generated"}, {"text": "幕が下がると、会場は大きな拍手に包まれた。", "target_word": "下がる", "complexity_tier": "T3", "furigana": "幕[まく]が下[さ]がると、会場[かいじょう]は大[おお]きな拍手[はくしゅ]に包[つつ]まれた。", "sentence_source": "generated"}, {"text": "遮断機が下がったので、車は止まった。", "target_word": "下がった", "complexity_tier": "T3", "furigana": "遮断機[しゃだんき]が下[さ]がったので、車[くるま]は止[と]まった。", "sentence_source": "generated"}, {"text": "クレーンのフックが、ゆっくり下がった。", "target_word": "下がった", "complexity_tier": "T3", "furigana": "クレーンの フックが、ゆっくり 下[さ]がった。", "sentence_source": "generated"}, {"text": "ロープを引くと、旗がするすると下がった。", "target_word": "下がった", "complexity_tier": "T3", "furigana": "ロープを引[ひ]くと、旗[はた]がするすると下[さ]がった。", "sentence_source": "generated"}, {"text": "重いかばんを持つと、肩が下がってしまう。", "target_word": "下がって", "complexity_tier": "T3", "furigana": "重[おも]いかばんを持[も]つと、肩[かた]が下[さ]がってしまう。", "sentence_source": "generated"}, {"text": "窓のブラインドが急に下がって、部屋が暗くなった。", "target_word": "下がって", "complexity_tier": "T3", "furigana": "窓[まど]のブラインドが急[きゅう]に下[さ]がって、部屋[へや]が暗[くら]くなった。", "sentence_source": "generated"}, {"text": "手を放すと、重りがゆっくり下がった。", "target_word": "下がった", "complexity_tier": "T3", "furigana": "手[て]を 放[はな]すと、重[おも]りがゆっくり 下[さ]がった。", "sentence_source": "generated"}, {"text": "跳ね橋が下がると、人々は川を渡り始めた。", "target_word": "下がる", "complexity_tier": "T3", "furigana": "跳[は]ね橋[ばし]が下[さ]がると、人々[ひとびと]は川[かわ]を渡[わた]り始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下がる", "label": "終止形"}, {"form": "下がらない", "label": "否定形"}, {"form": "下がり", "label": "連用形"}, {"form": "下がって", "label": "て形"}, {"form": "下がった", "label": "過去形"}, {"form": "下がれば", "label": "仮定形"}, {"form": "下がろう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "ものが上から下へ移動する、また上から垂れ下がる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36516, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下がった", "is_correct": true, "explanation": "スクリーンが上から下へ動いたことを表し、文脈に合う。"}, {"text": "割れた", "is_correct": false, "explanation": "砕ける意味で、スクリーンがゆっくり動く状況に合わない。"}, {"text": "鳴った", "is_correct": false, "explanation": "音を出す意味で、スクリーンの動きには使えない。"}, {"text": "濡れた", "is_correct": false, "explanation": "水に触れる意味で、ゆっくり動く場面に合わない。"}], "explanations": {"下がった": "スクリーンが上から下へ動いたことを表し、文脈に合う。", "割れた": "砕ける意味で、スクリーンがゆっくり動く状況に合わない。", "鳴った": "音を出す意味で、スクリーンの動きには使えない。", "濡れた": "水に触れる意味で、ゆっくり動く場面に合わない。"}, "sentence_index": 0, "correct_answer": "下がった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テストの点が下がった。", "explanation": "ここは〈数値・程度が低くなる〉の意味。上から下へ動く位置の変化ではないので、この義項の例としては合わない。"}, {"text": "気球が、ゆっくり空へ下がっていった。", "explanation": "ここは〈上へ昇る〉の意味。空へ向かう動きは「上がる」「昇る」で表し、「下がる」では方向が逆になるので合わない。"}, {"text": "ロケットが、ゆっくり宇宙の方へ下がっていった。", "explanation": "ここは〈上へ昇る〉の意味。空の高みへ向かう動きは「上がる」で表し、「下がる」では方向が逆になるので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36516, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下がって", "is_correct": true, "explanation": "肩が落ちる様子を表し、「下がってしまう」と文脈に合う。"}, {"text": "光って", "is_correct": false, "explanation": "光る意味で、肩の状態を表す文には合わない。"}, {"text": "踊って", "is_correct": false, "explanation": "体を動かす意味だが、肩が下がる状況とは合わない。"}, {"text": "眠って", "is_correct": false, "explanation": "眠る意味で、肩の状態を表すことはできない。"}], "explanations": {"下がって": "肩が落ちる様子を表し、「下がってしまう」と文脈に合う。", "光って": "光る意味で、肩の状態を表す文には合わない。", "踊って": "体を動かす意味だが、肩が下がる状況とは合わない。", "眠って": "眠る意味で、肩の状態を表すことはできない。"}, "sentence_index": 6, "correct_answer": "下がって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "たこが、ぐんぐん空へ下がっていった。", "explanation": "ここは〈上へ昇る〉の意味。空へ高く上がる動きは「上がる」で表し、「下がる」では逆になるので合わない。"}, {"text": "ボールは地面にぶつかってから、高く下がった。", "explanation": "ここは〈上へ跳ね返る〉の意味。跳ね上がる動きは「跳ね上がる」「上がる」で表し、「下がる」では方向が逆になるので合わない。"}, {"text": "煙が、夜空の高いところへ下がっていった。", "explanation": "ここは〈上へ昇る〉の意味。高いところへ動く様子は「上がる」「昇る」で表し、「下がる」は逆になるので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36516, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜になると、カーテンがゆっくり下がらった。", "corrected_sentence": "夜になると、カーテンがゆっくり下がった。", "error_description": "「下がる」の過去形は「下がった」。「下がらった」の「ら」は余計で、誤った活用形になっている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下がった", "is_correct": true, "explanation": "過去の動きを表す文末の形で、文脈に合う。"}, {"text": "下がれ", "is_correct": false, "explanation": "命令形で、事実を述べる文末には合わない。"}, {"text": "下がろう", "is_correct": false, "explanation": "意志を表す形で、すでに起きた動きを述べる文には合わない。"}, {"text": "下がれば", "is_correct": false, "explanation": "仮定形で、文を言い切れず主節が必要になる。"}], "correct_form": "下がった", "base_form": "下がる", "form_label": "過去形", "sentence_index": 1, "explanations": {"下がった": "過去の動きを表す文末の形で、文脈に合う。", "下がれ": "命令形で、事実を述べる文末には合わない。", "下がろう": "意志を表す形で、すでに起きた動きを述べる文には合わない。", "下がれば": "仮定形で、文を言い切れず主節が必要になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36516, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "カーテンが音もなく下がるに、部屋が暗くなった。", "corrected_sentence": "カーテンが音もなく下がって、部屋が暗くなった。", "error_description": "「下がる」の直後に「に」が付いているのが誤り。後ろの文につなぐには、て形「下がって」にする必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下がって", "is_correct": true, "explanation": "て形で、後ろの結果を続ける形として文脈に合う。"}, {"text": "下がらない", "is_correct": false, "explanation": "否定形で、ブラインドが暗くした結果の流れと合わない。"}, {"text": "下がります", "is_correct": false, "explanation": "丁寧形で、普通体の文の中では文体が合わない。"}, {"text": "下がるな", "is_correct": false, "explanation": "禁止の形で、結果を述べる文には合わない。"}], "correct_form": "下がって", "base_form": "下がる", "form_label": "て形", "sentence_index": 7, "explanations": {"下がって": "て形で、後ろの結果を続ける形として文脈に合う。", "下がらない": "否定形で、ブラインドが暗くした結果の流れと合わない。", "下がります": "丁寧形で、普通体の文の中では文体が合わない。", "下がるな": "禁止の形で、結果を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36517, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「熱」の主語を示す格助詞で、動きの主体を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「熱」の主語の位置には合わない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す助詞で、主語の位置では不自然。"}, {"text": "と", "is_correct": false, "explanation": "引用や相手を示す助詞で、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「熱」の主語を示す格助詞で、動きの主体を表す。", "を": "目的語を示す助詞で、「熱」の主語の位置には合わない。", "に": "位置や相手を示す助詞で、主語の位置では不自然。", "と": "引用や相手を示す助詞で、主語にはならない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "と": "引用・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上がる", "is_correct": true, "explanation": "「下がる」の対義語で、数値や程度が高くなることを表す。"}, {"text": "煮る", "is_correct": false, "explanation": "熱を通す動詞で、対義語ではない。"}, {"text": "包む", "is_correct": false, "explanation": "覆う動作を表し、対義語とは言えない。"}, {"text": "守る", "is_correct": false, "explanation": "保護する動詞で、対義語にはならない。"}], "correct_answer": "上がる", "explanations": {"上がる": "「下がる」の対義語で、数値や程度が高くなることを表す。", "煮る": "熱を通す動詞で、対義語ではない。", "包む": "覆う動作を表し、対義語とは言えない。", "守る": "保護する動詞で、対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36517, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「下がる」に続けて、条件を示す格助詞として使う。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す助詞で、条件の意味にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「下がる」の後では不自然。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞だが、「下がる」は目的語を取らず、文が成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「下がる」に続けて、条件を示す格助詞として使う。", "で": "手段や場所を示す助詞で、条件の意味にはならない。", "へ": "方向を示す助詞で、「下がる」の後では不自然。", "を": "目的語を示す助詞だが、「下がる」は目的語を取らず、文が成り立たない。"}, "error_tags": {"で": "手段・場所", "へ": "方向", "を": "目的語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上がる", "is_correct": true, "explanation": "「下がる」の対義語で、上へ動くことを表す。"}, {"text": "叩く", "is_correct": false, "explanation": "打つ動作で、上下の対義語ではない。"}, {"text": "測る", "is_correct": false, "explanation": "量を計る動詞で、対義語にはならない。"}, {"text": "結ぶ", "is_correct": false, "explanation": "つなぐ動作で、上下の対義語ではない。"}], "correct_answer": "上がる", "explanations": {"上がる": "「下がる」の対義語で、上へ動くことを表す。", "叩く": "打つ動作で、上下の対義語ではない。", "測る": "量を計る動詞で、対義語にはならない。", "結ぶ": "つなぐ動作で、上下の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36517, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "位置や程度が、高い状態から低い状態に変わること。", "primary_collocate": null, "pronunciation": "さがる", "ipa": "sa̠ɡa̠ɾɯ", "syllable_count": 3, "sentences": [{"text": "夜になると、気温が急に下がります。", "target_word": "下がります", "complexity_tier": "T3", "furigana": "夜[よる]になると、気温[きおん]が急[きゅう]に下[さ]がります。", "sentence_source": "generated"}, {"text": "薬を飲んだら、熱が下がって楽になりました。", "target_word": "下がって", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだら、熱[ねつ]が下[さ]がって楽[らく]になりました。", "sentence_source": "generated"}, {"text": "来月から野菜の値段が下がるそうだ。", "target_word": "下がる", "complexity_tier": "T3", "furigana": "来月[らいげつ]から野菜[やさい]の値段[ねだん]が下[さ]がるそうだ。", "sentence_source": "generated"}, {"text": "川の水位がなかなか下がらないので、心配だ。", "target_word": "下がらない", "complexity_tier": "T3", "furigana": "川[かわ]の水位[すいい]がなかなか下[さ]がらないので、心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "テストの点が下がったのは、勉強しなかったからだ。", "target_word": "下がった", "complexity_tier": "T3", "furigana": "テストの点[てん]が下[さ]がったのは、勉強[べんきょう]しなかったからだ。", "sentence_source": "generated"}, {"text": "雨が降れば、暑さも少しは下がるでしょう。", "target_word": "下がる", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]れば、暑[あつ]さも少[すこ]しは下[さ]がるでしょう。", "sentence_source": "generated"}, {"text": "暖房をつけたので、部屋の温度は下がらなかった。", "target_word": "下がらなかった", "complexity_tier": "T3", "furigana": "暖房[だんぼう]をつけたので、部屋[へや]の温度[おんど]は下[さ]がらなかった。", "sentence_source": "generated"}, {"text": "円の価値が下がると、輸入品は高くなる。", "target_word": "下がる", "complexity_tier": "T4", "furigana": "円[えん]の価値[かち]が下[さ]がると、輸入品[ゆにゅうひん]は高[たか]くなる。", "sentence_source": "generated"}, {"text": "血圧が下がるように、塩を減らしています。", "target_word": "下がる", "complexity_tier": "T4", "furigana": "血圧[けつあつ]が下[さ]がるように、塩[しお]を減[へ]らしています。", "sentence_source": "generated"}, {"text": "夏でも山の上は、夜に気温が下がる。", "target_word": "下がる", "complexity_tier": "T3", "furigana": "夏[なつ]でも山[やま]の上[うえ]は、夜[よる]に気温[きおん]が下[さ]がる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下がる", "label": "終止形・連体形"}, {"form": "下がらない", "label": "否定形"}, {"form": "下がります", "label": "丁寧形"}, {"form": "下がった", "label": "過去形"}, {"form": "下がって", "label": "て形"}, {"form": "下がれば", "label": "仮定形"}, {"form": "下がろう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "位置・温度・値段・数値などの程度が高い状態から低い状態へ変わる(気温が下がる、熱が下がる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36517, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下がります", "is_correct": true, "explanation": "気温が低くなることを表し、「夜になると」と文脈に合う。"}, {"text": "割れます", "is_correct": false, "explanation": "割れる意味で、気温の変化には使えない。"}, {"text": "眠ります", "is_correct": false, "explanation": "眠る意味で、気温の変化を表すことはできない。"}, {"text": "鳴ります", "is_correct": false, "explanation": "音が出る意味で、気温には合わない。"}], "explanations": {"下がります": "気温が低くなることを表し、「夜になると」と文脈に合う。", "割れます": "割れる意味で、気温の変化には使えない。", "眠ります": "眠る意味で、気温の変化を表すことはできない。", "鳴ります": "音が出る意味で、気温には合わない。"}, "sentence_index": 0, "correct_answer": "下がります"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "棚の上の箱が、ゆっくり下がってきた。", "explanation": "ここは〈上から下へ動く〉の意味。位置の移動で、程度が低くなるこの義項とは別の用法なので合わない。"}, {"text": "ごみ袋が、テーブルの横へ下がった。", "explanation": "ここは〈横へ動く〉の意味。下へ動く定義とは合わず、横への移動には「移る」を使うので、「下がる」は不自然。"}, {"text": "夜になると、空気が下がる。", "explanation": "ここは〈冷える〉の意味。温度が低くなる様子は「冷える」と言うので、この語では不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36517, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下がらなかった", "is_correct": true, "explanation": "温度が変わらなかったことを表し、暖房をつけた文脈に合う。"}, {"text": "砕けなかった", "is_correct": false, "explanation": "砕ける意味で、温度には使えない。"}, {"text": "凍らなかった", "is_correct": false, "explanation": "凍る意味で、部屋の温度を表す文には合わない。"}, {"text": "結ばれなかった", "is_correct": false, "explanation": "結ぶ意味で、温度の変化を表すことはできない。"}], "explanations": {"下がらなかった": "温度が変わらなかったことを表し、暖房をつけた文脈に合う。", "砕けなかった": "砕ける意味で、温度には使えない。", "凍らなかった": "凍る意味で、部屋の温度を表す文には合わない。", "結ばれなかった": "結ぶ意味で、温度の変化を表すことはできない。"}, "sentence_index": 6, "correct_answer": "下がらなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ロープに結んだ重りが、ゆっくり下がってきた。", "explanation": "ここは〈上から下へ動く〉の意味。位置の移動で、程度の低下を表すこの義項とは別の用法なので合わない。"}, {"text": "来週から会議の時間が下がるそうだ。", "explanation": "ここは〈短くなる〉の意味。時間の長さの変化には「下がる」を使わないので不自然。"}, {"text": "鳥が雲の上へ下がって、姿が見えなくなった。", "explanation": "ここは〈上へ昇る〉の意味。雲の上へ行く動きは「上がる」で表し、「下がる」は逆になるので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36517, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が降って、気温が下がったを、厚着をします。", "corrected_sentence": "雨が降って、気温が下がったので、厚着をします。", "error_description": "「下がった」の後に「を」が続いているのが誤り。原因を示す「ので」を使うのが正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下がって", "is_correct": true, "explanation": "て形で、後ろの結果を続ける形として文脈に合う。"}, {"text": "下がらない", "is_correct": false, "explanation": "否定形で、薬の効果という文脈と合わない。"}, {"text": "下がろう", "is_correct": false, "explanation": "意志を表す形で、結果を述べる文には合わない。"}, {"text": "下がるな", "is_correct": false, "explanation": "禁止の形で、文が成り立たない。"}], "correct_form": "下がって", "base_form": "下がる", "form_label": "て形", "sentence_index": 1, "explanations": {"下がって": "て形で、後ろの結果を続ける形として文脈に合う。", "下がらない": "否定形で、薬の効果という文脈と合わない。", "下がろう": "意志を表す形で、結果を述べる文には合わない。", "下がるな": "禁止の形で、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36517, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今朝は雨が降って、気温が下がりなかった。", "corrected_sentence": "今朝は雨が降って、気温が下がらなかった。", "error_description": "否定形は「下がらない」で、過去形は「下がらなかった」。「下がりなかった」の「り」が誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下がる", "is_correct": true, "explanation": "終止形・連体形で、文を言い切る形として文脈に合う。"}, {"text": "下がれ", "is_correct": false, "explanation": "命令形で、事実を述べる文には成り立たない。"}, {"text": "下がりたい", "is_correct": false, "explanation": "願望の形で、事実を述べる文と合わない。"}, {"text": "下がらなければ", "is_correct": false, "explanation": "仮定の否定で、結果を述べる文に合わない。"}], "correct_form": "下がる", "base_form": "下がる", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"下がる": "終止形・連体形で、文を言い切る形として文脈に合う。", "下がれ": "命令形で、事実を述べる文には成り立たない。", "下がりたい": "願望の形で、事実を述べる文と合わない。", "下がらなければ": "仮定の否定で、結果を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36518, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「頭に帽子をかぶる」で、かぶる場所を示す〈に〉。"}, {"text": "を", "is_correct": false, "explanation": "〈頭を〉は直接の対象を示すが、ここは場所を示すので合わない。"}, {"text": "で", "is_correct": false, "explanation": "〈頭で〉は手段を示す。頭で帽子をかぶるわけではないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "〈頭が〉は主語を示す。頭が帽子をかぶるわけではないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「頭に帽子をかぶる」で、かぶる場所を示す〈に〉。", "を": "〈頭を〉は直接の対象を示すが、ここは場所を示すので合わない。", "で": "〈頭で〉は手段を示す。頭で帽子をかぶるわけではないので合わない。", "が": "〈頭が〉は主語を示す。頭が帽子をかぶるわけではないので合わない。"}, "error_tags": {"を": "目的格", "で": "手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36518, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「頭の上」で、〈頭〉と〈上〉をつなぐ〈の〉。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は向かう方向を示すが、「頭へ上に」は方向が重なり不自然で、〈頭の上〉の位置関係にならない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並べて示す助詞。「頭と上」では二つのものを並べるだけで、〈頭の上〉の位置関係は表せない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉を入れると「頭に上に」と助詞が重なり、〈頭の上〉の意味にならない。"}], "correct_answer": "の", "explanations": {"の": "「頭の上」で、〈頭〉と〈上〉をつなぐ〈の〉。", "へ": "〈へ〉は向かう方向を示すが、「頭へ上に」は方向が重なり不自然で、〈頭の上〉の位置関係にならない。", "と": "〈と〉は並べて示す助詞。「頭と上」では二つのものを並べるだけで、〈頭の上〉の位置関係は表せない。", "に": "〈に〉を入れると「頭に上に」と助詞が重なり、〈頭の上〉の意味にならない。"}, "error_tags": {"へ": "方向", "と": "並列", "に": "位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36518, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あたまは、体のいちばん上にあって、目や鼻や口があるところです。", "primary_collocate": null, "pronunciation": "あたま", "ipa": "atama", "syllable_count": 3, "sentences": [{"text": "ボールが頭に当たって、少し痛かった。", "target_word": "頭", "complexity_tier": "T3", "furigana": "ボールが頭[あたま]に当[あ]たって、少[すこ]し痛[いた]かった。", "sentence_source": "generated"}, {"text": "寒いので、頭に帽子をかぶって出かけた。", "target_word": "頭", "complexity_tier": "T3", "furigana": "寒[さむ]いので、頭[あたま]に帽子[ぼうし]をかぶって出[で]かけた。", "sentence_source": "generated"}, {"text": "子犬の頭をやさしくなでた。", "target_word": "頭", "complexity_tier": "T3", "furigana": "子犬[こいぬ]の頭[あたま]をやさしくなでた。", "sentence_source": "generated"}, {"text": "髪を洗うとき、頭からお湯をかけます。", "target_word": "頭", "complexity_tier": "T3", "furigana": "髪[かみ]を洗[あら]うとき、頭[あたま]からお湯[ゆ]をかけます。", "sentence_source": "generated"}, {"text": "電車のドアで頭をぶつけてしまった。", "target_word": "頭", "complexity_tier": "T3", "furigana": "電車[でんしゃ]のドアで頭[あたま]をぶつけてしまった。", "sentence_source": "generated"}, {"text": "赤ちゃんの頭は、体に比べて大きい。", "target_word": "頭", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんの頭[あたま]は、体[からだ]に比[くら]べて大[おお]きい。", "sentence_source": "generated"}, {"text": "頭を下げて、先生にあいさつした。", "target_word": "頭", "complexity_tier": "T3", "furigana": "頭[あたま]を下[さ]げて、先生[せんせい]にあいさつした。", "sentence_source": "generated"}, {"text": "雪が頭の上に落ちてきて、冷たかった。", "target_word": "頭", "complexity_tier": "T3", "furigana": "雪[ゆき]が頭[あたま]の上[うえ]に落[お]ちてきて、冷[つめ]たかった。", "sentence_source": "generated"}, {"text": "この帽子は小さすぎて、僕の頭に合わない。", "target_word": "頭", "complexity_tier": "T3", "furigana": "この帽子は小さすぎて、僕の頭[あたま]に合わない。", "sentence_source": "generated"}, {"text": "プールのあと、頭を洗ってからドライヤーで乾かした。", "target_word": "頭", "complexity_tier": "T3", "furigana": "プールのあと、頭[あたま]を洗[あら]ってからドライヤーで乾[かわ]かした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭", "label": "基本形"}, {"form": "頭を", "label": "目的格"}, {"form": "頭に", "label": "位置格"}, {"form": "頭の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "体のいちばん上にある、顔や髪のある部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 子犬 (Zipf 3.68), やさしく (Zipf 3.6), なで (Zipf 3.65)']::text[], '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36518, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頭", "is_correct": true, "explanation": "「ボールが頭に当たる」の頭。体の最上部を指し、文の内容に合う。"}, {"text": "夢", "is_correct": false, "explanation": "夢に物が当たるとは言わず、文が成り立たない。"}, {"text": "息", "is_correct": false, "explanation": "息に物が当たることはなく、体の部位が入る文脈に合わない。"}, {"text": "霧", "is_correct": false, "explanation": "霧に当たるボールは物理的に不自然で、文脈に合わない。"}], "explanations": {"頭": "「ボールが頭に当たる」の頭。体の最上部を指し、文の内容に合う。", "夢": "夢に物が当たるとは言わず、文が成り立たない。", "息": "息に物が当たることはなく、体の部位が入る文脈に合わない。", "霧": "霧に当たるボールは物理的に不自然で、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "頭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犬の頭に首輪をつけて散歩に出た。", "explanation": "ここは〈首〉の位置（首輪は首につける）。〈頭〉につけることはないので、〈首〉と混同している。"}, {"text": "靴を頭にはいて、外に出た。", "explanation": "ここは〈足〉の位置（靴は足にはく）。〈頭〉にはくことはできないので、〈足〉と混同している。"}, {"text": "ドアの取っ手を頭でつかんで開けた。", "explanation": "ここは〈手〉の働き（手でつかむ）。頭ではつかめないので、〈手〉と混同している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36518, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頭", "is_correct": true, "explanation": "「頭を下げる」で、礼をする動作の対象。文の内容に合う。"}, {"text": "朝", "is_correct": false, "explanation": "「朝を下げる」とは言わず、文が成り立たない。"}, {"text": "夢", "is_correct": false, "explanation": "「夢を下げる」とは言わず、文が成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "「雨を下げる」とは言わず、文が成り立たない。"}], "explanations": {"頭": "「頭を下げる」で、礼をする動作の対象。文の内容に合う。", "朝": "「朝を下げる」とは言わず、文が成り立たない。", "夢": "「夢を下げる」とは言わず、文が成り立たない。", "雨": "「雨を下げる」とは言わず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "頭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ボタンを頭でとめた。", "explanation": "ここは〈手〉の働き（手でとめる）。頭ではボタンをとめられないので、〈手〉と混同している。"}, {"text": "ゆびわを頭にはめた。", "explanation": "ここは〈指〉の位置（指輪は指にはめる）。〈頭〉にはめることはないので、〈指〉と混同している。"}, {"text": "椅子に座って、足を組むかわりに頭を組んだ。", "explanation": "ここは〈足〉の動作（足を組む）。〈頭〉を組むことはできないので、〈足〉と混同している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36518, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボールが頭を当たって、ひどく痛かった。", "corrected_sentence": "ボールが頭に当たって、ひどく痛かった。", "error_description": "「当たる」は〈〜に当たる〉で、当たる先に〈に〉を使う。〈頭を〉は誤りで、〈頭に〉が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36518, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "転んで、頭をひどく打ちた。", "corrected_sentence": "転んで、頭をひどく打った。", "error_description": "「打つ」の過去形は〈打った〉。〈打ちた〉は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36519, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「頭がいい」で、〈いい〉の主語を示す〈が〉。"}, {"text": "を", "is_correct": false, "explanation": "「頭をいい」とは言えず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「頭にいい」は脳に良いの意味になり、頭の働きが良いことを表さないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「頭でいい」は成り立たず、文脈に合わない。"}], "correct_answer": "が", "explanations": {"が": "「頭がいい」で、〈いい〉の主語を示す〈が〉。", "を": "「頭をいい」とは言えず、文が成り立たない。", "に": "「頭にいい」は脳に良いの意味になり、頭の働きが良いことを表さないので合わない。", "で": "「頭でいい」は成り立たず、文脈に合わない。"}, "error_tags": {"を": "目的格", "に": "対象", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36519, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「頭から消える」で、起点を示す〈から〉。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は向かう先を示す。「頭へ消える」は消えていく先としてつながらず、文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は並列や引用を示す。「頭と消えてしまった」では起点が表せず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較の基準を示す。「頭より消えてしまった」は比較の文にならず、文脈に合わない。"}], "correct_answer": "から", "explanations": {"から": "「頭から消える」で、起点を示す〈から〉。", "へ": "〈へ〉は向かう先を示す。「頭へ消える」は消えていく先としてつながらず、文脈に合わない。", "と": "〈と〉は並列や引用を示す。「頭と消えてしまった」では起点が表せず、文が成り立たない。", "より": "〈より〉は比較の基準を示す。「頭より消えてしまった」は比較の文にならず、文脈に合わない。"}, "error_tags": {"へ": "方向", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36519, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間や動物の体の最上部にあり、脳を収め、顔面を含む部分。思考や感覚の中枢。", "primary_collocate": null, "pronunciation": "あたま", "ipa": "atama", "syllable_count": 3, "sentences": [{"text": "頭を使う仕事は、夕方になると疲れる。", "target_word": "頭", "complexity_tier": "T3", "furigana": "頭[あたま]を使[つか]う仕事[しごと]は、夕方[ゆうがた]になると疲[つか]れる。", "sentence_source": "generated"}, {"text": "彼は頭がいいので、数学の問題をすぐ解ける。", "target_word": "頭", "complexity_tier": "T3", "furigana": "彼[かれ]は頭[あたま]がいいので、数学[すうがく]の問題[もんだい]をすぐ解[と]ける。", "sentence_source": "generated"}, {"text": "徹夜したせいで、頭がぼんやりしている。", "target_word": "頭", "complexity_tier": "T3", "furigana": "徹夜[てつや]したせいで、頭[あたま]がぼんやりしている。", "sentence_source": "generated"}, {"text": "頭の中で計画を整理してから話し始めた。", "target_word": "頭", "complexity_tier": "T3", "furigana": "頭[あたま]の中[なか]で計画[けいかく]を整理[せいり]してから話[はな]し始[はじ]めた。", "sentence_source": "generated"}, {"text": "熱があって頭が痛く、授業を休んだ。", "target_word": "頭", "complexity_tier": "T3", "furigana": "熱[ねつ]があって頭[あたま]が痛[いた]く、授業[じゅぎょう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "彼女は頭の回転が速く、質問にすぐ答える。", "target_word": "頭", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は頭[あたま]の回転[かいてん]が速[はや]く、質問[しつもん]にすぐ答[こた]える。", "sentence_source": "generated"}, {"text": "頭を冷やしてから、もう一度話し合おう。", "target_word": "頭", "complexity_tier": "T3", "furigana": "頭[あたま]を冷[ひ]やしてから、もう一度[いちど]話[はな]し合[あ]おう。", "sentence_source": "generated"}, {"text": "緊張して、覚えたことが頭から消えてしまった。", "target_word": "頭", "complexity_tier": "T3", "furigana": "緊張[きんちょう]して、覚[おぼ]えたことが頭[あたま]から消[き]えてしまった。", "sentence_source": "generated"}, {"text": "頭が固い人は、新しい方法を受け入れにくい。", "target_word": "頭", "complexity_tier": "T3", "furigana": "頭[あたま]が固[かた]い人[ひと]は、新[あたら]しい方法[ほうほう]を受[う]け入[い]れにくい。", "sentence_source": "generated"}, {"text": "事故の後、頭を強く打ったので病院で検査を受けた。", "target_word": "頭", "complexity_tier": "T3", "furigana": "事故[じこ]の後[あと]、頭[あたま]を強[つよ]く打[う]ったので病院[びょういん]で検査[けんさ]を受[う]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭", "label": "基本形"}, {"form": "頭が", "label": "主格"}, {"form": "頭を", "label": "目的格"}, {"form": "頭の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "脳のある部分、また考える働きや知能の中心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: contains vocabulary far above tier T1: 話し合お (Zipf 2.41)']::text[], '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36519, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頭", "is_correct": true, "explanation": "「頭を使う」で、考える働きを用いる意味。仕事の内容に合う。"}, {"text": "夢", "is_correct": false, "explanation": "「夢を使う仕事」とは言わず、文脈に合わない。"}, {"text": "朝", "is_correct": false, "explanation": "「朝を使う仕事」とは言わず、文が成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "「雨を使う仕事」とは言わず、文が成り立たない。"}], "explanations": {"頭": "「頭を使う」で、考える働きを用いる意味。仕事の内容に合う。", "夢": "「夢を使う仕事」とは言わず、文脈に合わない。", "朝": "「朝を使う仕事」とは言わず、文が成り立たない。", "雨": "「雨を使う仕事」とは言わず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "頭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は頭が広く、誰とでもすぐ打ち解ける。", "explanation": "ここは〈心が広い〉の〈心〉。〈頭が広い〉とは言わず、〈心〉と混同している。"}, {"text": "頭を割って、本当の気持ちを話した。", "explanation": "ここは〈腹〉の意味（腹を割る＝本心を打ち明ける）。〈頭〉を割れば体の損傷になるので、〈腹〉と混同している。"}, {"text": "彼女は頭が明るいので、クラスの人気者だ。", "explanation": "ここは〈性格が明るい〉の〈性格〉。〈頭〉では明るさを表せないので、〈性格〉と混同している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36519, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頭", "is_correct": true, "explanation": "「頭を冷やす」で、気持ちを落ち着ける意味。文の内容に合う。"}, {"text": "眉", "is_correct": false, "explanation": "眉は冷やして気持ちを落ち着けるものではなく、「眉を冷やす」とは言わないので、〈頭を冷やす〉の意味に合わない。"}, {"text": "声", "is_correct": false, "explanation": "「声を冷やす」とは言わず、〈頭を冷やす〉（気持ちを落ち着ける）の比喩にも合わない。"}, {"text": "時計", "is_correct": false, "explanation": "「時計を冷やす」は不自然で、文の意味が通らない。"}], "explanations": {"頭": "「頭を冷やす」で、気持ちを落ち着ける意味。文の内容に合う。", "眉": "眉は冷やして気持ちを落ち着けるものではなく、「眉を冷やす」とは言わないので、〈頭を冷やす〉の意味に合わない。", "声": "「声を冷やす」とは言わず、〈頭を冷やす〉（気持ちを落ち着ける）の比喩にも合わない。", "時計": "「時計を冷やす」は不自然で、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "頭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は頭が深く、人の相談によく乗る。", "explanation": "ここは〈知恵が深い〉の〈知恵〉。〈頭が深い〉とは言わず、〈知恵〉と混同している。"}, {"text": "腕を組むかわりに、頭を組んで考えた。", "explanation": "ここは〈腕〉の動作（腕を組む）。〈頭〉を組むことはできないので、〈腕〉と混同している。"}, {"text": "彼は頭が豊かで、どんな楽器も上手に弾く。", "explanation": "ここは〈才能が豊か〉の〈才能〉。〈頭が豊か〉とは言わず、〈才能〉と混同している。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36519, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は頭を良くて、難しい問題もすぐ解ける。", "corrected_sentence": "彼は頭が良くて、難しい問題もすぐ解ける。", "error_description": "「頭が良い」は〈頭が〉で主語を示す。〈頭を良くて〉は誤りで、〈頭が〉が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36519, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は頭が良くくて、会議をすぐまとめた。", "corrected_sentence": "彼女は頭が良くて、会議をすぐまとめた。", "error_description": "形容詞〈良い〉の接続形は〈良くて〉。〈良くくて〉は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36520, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "騒がしい", "is_correct": true, "explanation": "「静か」の対義語として、音が多く騒がしい意味を表す。"}, {"text": "明るい", "is_correct": false, "explanation": "光の量を表す語で、音の対義語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、音の対義語にはならない。"}, {"text": "細い", "is_correct": false, "explanation": "太さを表す語で、音の状態とは無関係。"}], "correct_answer": "騒がしい", "explanations": {"騒がしい": "「静か」の対義語として、音が多く騒がしい意味を表す。", "明るい": "光の量を表す語で、音の対義語ではない。", "重い": "重さを表す語で、音の対義語にはならない。", "細い": "太さを表す語で、音の状態とは無関係。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
