INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36520, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "音がなくて、落ち着いていること。", "primary_collocate": null, "pronunciation": "しずか", "ipa": "ɕizɯka̠", "syllable_count": 3, "sentences": [{"text": "夜の図書館はとても静かです。", "target_word": "静か", "complexity_tier": "T3", "furigana": "夜[よる]の図書館[としょかん]はとても静[しず]かです。", "sentence_source": "generated"}, {"text": "静かな部屋で本を読むのが好きだ。", "target_word": "静かな", "complexity_tier": "T3", "furigana": "静[しず]かな部屋[へや]で本[ほん]を読[よ]むのが好[す]きだ。", "sentence_source": "generated"}, {"text": "赤ちゃんが寝ているので、静かに歩いてください。", "target_word": "静かに", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんが寝[ね]ているので、静[しず]かに歩[ある]いてください。", "sentence_source": "generated"}, {"text": "雨がやんで、町が急に静かになった。", "target_word": "静か", "complexity_tier": "T3", "furigana": "雨[あめ]がやんで、町[まち]が急[きゅう]に静[しず]かになった。", "sentence_source": "generated"}, {"text": "教室が静かだったから、先生の声がよく聞こえた。", "target_word": "静かだった", "complexity_tier": "T3", "furigana": "教室[きょうしつ]が静[しず]かだったから、先生[せんせい]の声[こえ]がよく聞[き]こえた。", "sentence_source": "generated"}, {"text": "駅の近くはうるさいが、この公園は静かだ。", "target_word": "静か", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くはうるさいが、この公園[こうえん]は静[しず]かだ。", "sentence_source": "generated"}, {"text": "静かな海を見ながら、ゆっくり休んだ。", "target_word": "静かな", "complexity_tier": "T3", "furigana": "静[しず]かな海[うみ]を見[み]ながら、ゆっくり休[やす]んだ。", "sentence_source": "generated"}, {"text": "授業中は静かにしなければならない。", "target_word": "静かに", "complexity_tier": "T3", "furigana": "授業中[じゅぎょうちゅう]は静[しず]かにしなければならない。", "sentence_source": "generated"}, {"text": "子どもたちが帰ると、家の中は静かになった。", "target_word": "静か", "complexity_tier": "T3", "furigana": "子[こ]どもたちが帰[かえ]ると、家[いえ]の中[なか]は静[しず]かになった。", "sentence_source": "generated"}, {"text": "田舎の夜は静かで、虫の声しか聞こえない。", "target_word": "静かで", "complexity_tier": "T4", "furigana": "田舎[いなか]の夜[よる]は静[しず]かで、虫[むし]の声[こえ]しか聞[き]こえない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "静かだ", "label": "終止形"}, {"form": "静かな", "label": "連体形"}, {"form": "静かに", "label": "連用形"}, {"form": "静かで", "label": "て形"}, {"form": "静かなら", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "音や声が少なく、場所や様子が落ち着いている(静かな部屋、静かに歩く)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36520, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "静か", "is_correct": true, "explanation": "図書館の音が少なく落ち着いた様子を表し、「とても」に続く形容として自然。"}, {"text": "鮮やか", "is_correct": false, "explanation": "色や印象が際立つ意味で、図書館の静けさには合わない。"}, {"text": "滑らか", "is_correct": false, "explanation": "表面や動きがなめらかな意味で、場所の様子には使わない。"}, {"text": "健やか", "is_correct": false, "explanation": "心身の健康を表す語で、場所の様子には合わない。"}], "explanations": {"静か": "図書館の音が少なく落ち着いた様子を表し、「とても」に続く形容として自然。", "鮮やか": "色や印象が際立つ意味で、図書館の静けさには合わない。", "滑らか": "表面や動きがなめらかな意味で、場所の様子には使わない。", "健やか": "心身の健康を表す語で、場所の様子には合わない。"}, "sentence_index": 0, "correct_answer": "静か"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "静かな波が、大きくうねって船を揺らした。", "explanation": "ここは〈おだやか〉の意味。大きくうねる波には「荒い」を使うので、この意味では矛盾する。"}, {"text": "この薬は効き目が静かで、すぐに体が楽になる。", "explanation": "ここは〈穏やかな〉の意味。効き目の強さを「静か」とは言わないので不自然。"}, {"text": "この店は静かな色合いの服ばかりを扱っている。", "explanation": "ここは〈地味な〉の意味。色の印象を表す用法で、音の少なさを表す義項とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36520, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "静かな", "is_correct": true, "explanation": "「海」を修飾する連体形で、穏やかな海の様子に合う。"}, {"text": "頑丈な", "is_correct": false, "explanation": "丈夫さを表す語で、海の様子には合わない。"}, {"text": "陽気な", "is_correct": false, "explanation": "人の気分を表す語で、海には使えない。"}, {"text": "器用な", "is_correct": false, "explanation": "人の手際を表す語で、海の状態には合わない。"}], "explanations": {"静かな": "「海」を修飾する連体形で、穏やかな海の様子に合う。", "頑丈な": "丈夫さを表す語で、海の様子には合わない。", "陽気な": "人の気分を表す語で、海には使えない。", "器用な": "人の手際を表す語で、海の状態には合わない。"}, "sentence_index": 6, "correct_answer": "静かな"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このセーターは静かな黄色で、遠くからも見えるほど派手だ。", "explanation": "ここは〈派手で目立つ〉の意味。目立つ色には「派手」を使い、この意味では矛盾するので合わない。"}, {"text": "この料理は味が静かで、香辛料がよく効いている。", "explanation": "ここは味の強さではなく〈おだやか〉の意味。味の強さを「静か」とは言わないので不自然。"}, {"text": "彼女は静かな性格で、大勢の前ではほとんど話さない。", "explanation": "ここは〈性格がおとなしい〉の意味。人の性格を表す用法で、音の少なさを表す義項とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36520, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "午前三時の住宅街は静かにだ。", "corrected_sentence": "午前三時の住宅街は静かだ。", "error_description": "「静か」に「に」を続け、さらに「だ」を付けたのが誤り。断定の「静かだ」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "静かな", "is_correct": true, "explanation": "名詞「部屋」を修飾する連体形で、文脈に合う。"}, {"text": "静かだろう", "is_correct": false, "explanation": "推量の形で、名詞を直接修飾できない。"}, {"text": "静かで", "is_correct": false, "explanation": "て形で、名詞の前には置けない。"}, {"text": "静かなら", "is_correct": false, "explanation": "仮定形で、名詞を修飾する形としては成り立たない。"}], "correct_form": "静かな", "base_form": "静か", "form_label": "連体形", "sentence_index": 1, "explanations": {"静かな": "名詞「部屋」を修飾する連体形で、文脈に合う。", "静かだろう": "推量の形で、名詞を直接修飾できない。", "静かで": "て形で、名詞の前には置けない。", "静かなら": "仮定形で、名詞を修飾する形としては成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36520, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の公園は静かに、人の姿もない。", "corrected_sentence": "夜の公園は静かで、人の姿もない。", "error_description": "後ろに状態を続けるには、て形「静かで」にする必要がある。「静かに」は連用形で、この文では続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "静かに", "is_correct": true, "explanation": "動詞「する」にかかる連用形で、「にしなければならない」と続く。"}, {"text": "静かだ", "is_correct": false, "explanation": "終止形で、動詞「する」に直接続かない。"}, {"text": "静かだろう", "is_correct": false, "explanation": "推量の形で、規則を述べる文には合わない。"}, {"text": "静かだった", "is_correct": false, "explanation": "過去の形で、これから守るべき規則の文と合わない。"}], "correct_form": "静かに", "base_form": "静か", "form_label": "連用形", "sentence_index": 7, "explanations": {"静かに": "動詞「する」にかかる連用形で、「にしなければならない」と続く。", "静かだ": "終止形で、動詞「する」に直接続かない。", "静かだろう": "推量の形で、規則を述べる文には合わない。", "静かだった": "過去の形で、これから守るべき規則の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
