INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36522, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "abstract", "definition": "だいじなことです。かならずしなければならないことです。", "primary_collocate": null, "pronunciation": "だいじ", "ipa": "da̠id͡ʑi", "syllable_count": 3, "sentences": [{"text": "明日は大事な会議があるので、早く寝ます。", "target_word": "大事な", "complexity_tier": "T3", "furigana": "明日[あした]は大事[だいじ]な会議[かいぎ]があるので、早[はや]く寝[ね]ます。", "sentence_source": "generated"}, {"text": "約束を守るのは大事なことです。", "target_word": "大事な", "complexity_tier": "T3", "furigana": "約束[やくそく]を守[まも]るのは大事[だいじ]なことです。", "sentence_source": "generated"}, {"text": "大事な用事があって、今日は先に帰ります。", "target_word": "大事な", "complexity_tier": "T3", "furigana": "大事[だいじ]な用事[ようじ]があって、今日[きょう]は先[さき]に帰[かえ]ります。", "sentence_source": "generated"}, {"text": "試験の前に、体を休めることも大事だ。", "target_word": "大事", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]に、体[からだ]を休[やす]めることも大事[だいじ]だ。", "sentence_source": "generated"}, {"text": "パスポートは大事な書類だから、なくさないでください。", "target_word": "大事な", "complexity_tier": "T3", "furigana": "パスポートは大事[だいじ]な書類[しょるい]だから、なくさないでください。", "sentence_source": "generated"}, {"text": "毎日少しずつ練習することが大事です。", "target_word": "大事", "complexity_tier": "T3", "furigana": "毎日[まいにち]少[すこ]しずつ練習[れんしゅう]することが大事[だいじ]です。", "sentence_source": "generated"}, {"text": "大事な話があるので、あとで時間をください。", "target_word": "大事な", "complexity_tier": "T3", "furigana": "大事[だいじ]な話[はなし]があるので、あとで時間[じかん]をください。", "sentence_source": "generated"}, {"text": "先生は「基本が大事だ」と何度も言った。", "target_word": "大事だ", "complexity_tier": "T4", "furigana": "先生[せんせい]は「基本[きほん]が大事[だいじ]だ」と何度[なんど]も言[い]った。", "sentence_source": "generated"}, {"text": "大事な連絡を忘れて、みんなに迷惑をかけた。", "target_word": "大事な", "complexity_tier": "T4", "furigana": "大事[だいじ]な連絡[れんらく]を忘[わす]れて、みんなに迷惑[めいわく]をかけた。", "sentence_source": "generated"}, {"text": "旅行では、水を持っていくことが大事です。", "target_word": "大事", "complexity_tier": "T3", "furigana": "旅行[りょこう]では、水[みず]を持[も]っていくことが大事[だいじ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大事だ", "label": "終止形"}, {"form": "大事な", "label": "連体形"}, {"form": "大事に", "label": "連用形"}, {"form": "大事で", "label": "て形"}, {"form": "大事なら", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "重要で、必ずしなければならない事柄(大事な用事、基本が大事だ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36522, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大事に", "is_correct": false, "explanation": "連用形は名詞「会議」を直接修飾できず、「大事に会議」は成り立たない。"}, {"text": "大事な", "is_correct": true, "explanation": "連体形で、後ろの名詞「会議」を修飾する正しい形。"}, {"text": "大事だ", "is_correct": false, "explanation": "終止形は名詞の前に置けず、「大事だ会議」は文法的に成り立たない。"}, {"text": "大事さ", "is_correct": false, "explanation": "名詞「大事さ」は「会議」を修飾できず、「大事さの会議」では意味が変わってしまう。"}], "explanations": {"大事に": "連用形は名詞「会議」を直接修飾できず、「大事に会議」は成り立たない。", "大事な": "連体形で、後ろの名詞「会議」を修飾する正しい形。", "大事だ": "終止形は名詞の前に置けず、「大事だ会議」は文法的に成り立たない。", "大事さ": "名詞「大事さ」は「会議」を修飾できず、「大事さの会議」では意味が変わってしまう。"}, "sentence_index": 0, "correct_answer": "大事な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "舞台が終わると、大事な拍手が会場を包んだ。", "explanation": "〈大きな拍手〉の〈大きな〉の意味。〈大事な〉は『重要な』の意味で、拍手の大きさは表せないので合わない。"}, {"text": "作業中は、大事を払って歩きましょう。", "explanation": "〈注意を払う〉の〈注意〉を〈大事〉に置き換えた形で、この言い方は使わない。〈注意〉の意味が必要。"}, {"text": "作業の前に、大事を確かめてください。", "explanation": "〈安全を確かめる〉の〈安全〉を〈大事〉に置き換えた形で、この言い方は使わない。〈安全〉の意味が必要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36522, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大事の", "is_correct": false, "explanation": "「大事」は形容動詞なので、「の」を付けて名詞を修飾する形にはならず、「大事の話」は不自然。"}, {"text": "大事な", "is_correct": true, "explanation": "連体形で、後ろの名詞「話」を修飾する正しい形。"}, {"text": "大事そう", "is_correct": false, "explanation": "様態の形で、名詞を修飾するには「大事そうな」が必要。「大事そう話」は成り立たない。"}, {"text": "大事がる", "is_correct": false, "explanation": "「大事がる」は動詞で、名詞の前に直接置いて修飾することはできない。"}], "explanations": {"大事の": "「大事」は形容動詞なので、「の」を付けて名詞を修飾する形にはならず、「大事の話」は不自然。", "大事な": "連体形で、後ろの名詞「話」を修飾する正しい形。", "大事そう": "様態の形で、名詞を修飾するには「大事そうな」が必要。「大事そう話」は成り立たない。", "大事がる": "「大事がる」は動詞で、名詞の前に直接置いて修飾することはできない。"}, "sentence_index": 6, "correct_answer": "大事な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちの冗談に、大事に笑った。", "explanation": "〈大笑い〉の『大きく笑う』の意味。〈大事に〉は『丁寧に』の意味で、笑い方を表すには使わないので合わない。"}, {"text": "試験が大事に終わって、ほっとした。", "explanation": "ここは〈無事〉(問題なく)の意味。〈大事に終わる〉は『重要に終わる』となり、意味が合わない。"}, {"text": "毎日運動して大事を保っている。", "explanation": "ここは〈健康〉の意味。〈保つ〉の目的語に〈大事〉は使わず、この組み合わせは不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36522, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大事に約束があるので、今日は早く帰ります。", "corrected_sentence": "大事な約束があるので、今日は早く帰ります。", "error_description": "連用形「大事に」は名詞「約束」を修飾できない。名詞の前では連体形「大事な」にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36522, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "結果より過程の大事だと、先生は言った。", "corrected_sentence": "結果より過程が大事だと、先生は言った。", "error_description": "形容動詞「大事だ」は「の」を付けて名詞の前に置けない。ここは「過程が大事だ」の形にする必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36523, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "おろそか", "is_correct": true, "explanation": "「大事に使う」の反対は「おろそかに使う」で、対義語の関係にある。"}, {"text": "丁寧", "is_correct": false, "explanation": "「丁寧」は『念入りで行き届いている』の意味で、「大事」の対義語ではなく類義に近い。"}, {"text": "簡単", "is_correct": false, "explanation": "「簡単」は『手間がかからない』の意味で、「大事」の対義語にはならない。"}, {"text": "平凡", "is_correct": false, "explanation": "「平凡」は『特にすぐれた点がない』の意味で、「大事」の対義語とはならない。"}], "correct_answer": "おろそか", "explanations": {"おろそか": "「大事に使う」の反対は「おろそかに使う」で、対義語の関係にある。", "丁寧": "「丁寧」は『念入りで行き届いている』の意味で、「大事」の対義語ではなく類義に近い。", "簡単": "「簡単」は『手間がかからない』の意味で、「大事」の対義語にはならない。", "平凡": "「平凡」は『特にすぐれた点がない』の意味で、「大事」の対義語とはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36523, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "おろそか", "is_correct": true, "explanation": "「体を大事にする」の反対は「体をおろそかにする」で、対義語の関係にある。"}, {"text": "親切", "is_correct": false, "explanation": "「親切」は『思いやりがある』の意味で、「大事」の対義語ではない。"}, {"text": "確実", "is_correct": false, "explanation": "「確実」は『間違いがない』の意味で、「大事」の対義語にはならない。"}, {"text": "新鮮", "is_correct": false, "explanation": "「新鮮」は『新しく生き生きしている』の意味で、「大事」の対義語ではない。"}], "correct_answer": "おろそか", "explanations": {"おろそか": "「体を大事にする」の反対は「体をおろそかにする」で、対義語の関係にある。", "親切": "「親切」は『思いやりがある』の意味で、「大事」の対義語ではない。", "確実": "「確実」は『間違いがない』の意味で、「大事」の対義語にはならない。", "新鮮": "「新鮮」は『新しく生き生きしている』の意味で、「大事」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36523, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "人や物を大切に思い、手放したくない・傷つけたくないと感じること。", "primary_collocate": null, "pronunciation": "だいじ", "ipa": "da̠id͡ʑi", "syllable_count": 3, "sentences": [{"text": "この時計は祖父にもらった大事なものです。", "target_word": "大事な", "complexity_tier": "T3", "furigana": "この時計[とけい]は祖父[そふ]にもらった大事[だいじ]なものです。", "sentence_source": "generated"}, {"text": "友だちを大事にする人は、みんなに好かれる。", "target_word": "大事に", "complexity_tier": "T3", "furigana": "友[とも]だちを大事[だいじ]にする人[ひと]は、みんなに好[す]かれる。", "sentence_source": "generated"}, {"text": "大事な人を守るために、彼は仕事をがんばっている。", "target_word": "大事な", "complexity_tier": "T3", "furigana": "大事[だいじ]な人[ひと]を守[まも]るために、彼[かれ]は仕事[しごと]をがんばっている。", "sentence_source": "generated"}, {"text": "本を大事に使えば、長く読める。", "target_word": "大事に", "complexity_tier": "T3", "furigana": "本[ほん]を大事[だいじ]に使[つか]えば、長[なが]く読[よ]める。", "sentence_source": "generated"}, {"text": "母は私の大事な宝物を、捨てずにとっておいてくれた。", "target_word": "大事な", "complexity_tier": "T4", "furigana": "母[はは]は私[わたし]の大事[だいじ]な宝物[たからもの]を、捨[す]てずにとっておいてくれた。", "sentence_source": "generated"}, {"text": "古い家具を大事にして、三十年も使っている。", "target_word": "大事に", "complexity_tier": "T3", "furigana": "古[ふる]い家具[かぐ]を大事[だいじ]にして、三十年[さんじゅうねん]も使[つか]っている。", "sentence_source": "generated"}, {"text": "大事な思い出だから、写真を毎日見ています。", "target_word": "大事な", "complexity_tier": "T3", "furigana": "大事[だいじ]な思[おも]い出[で]だから、写真[しゃしん]を毎日[まいにち]見[み]ています。", "sentence_source": "generated"}, {"text": "家族は何より大事だと思う。", "target_word": "大事だ", "complexity_tier": "T3", "furigana": "家族[かぞく]は何[なに]より大事[だいじ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "彼女は大事に育てた花を、隣の人にあげた。", "target_word": "大事に", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は大事[だいじ]に育[そだ]てた花[はな]を、隣[となり]の人[ひと]にあげた。", "sentence_source": "generated"}, {"text": "体を大事にして、無理をしないでください。", "target_word": "大事に", "complexity_tier": "T3", "furigana": "体[からだ]を大事[だいじ]にして、無理[むり]をしないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大事だ", "label": "終止形"}, {"form": "大事な", "label": "連体形"}, {"form": "大事に", "label": "連用形"}, {"form": "大事で", "label": "て形"}, {"form": "大事なら", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "人や物を大切に思い、手放したくない・傷つけたくないと感じる(大事な人、大事にする)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36523, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大事に", "is_correct": false, "explanation": "連用形は名詞「もの」を直接修飾できず、「大事にものです」は成り立たない。"}, {"text": "大事な", "is_correct": true, "explanation": "連体形で、後ろの名詞「もの」を修飾する正しい形。"}, {"text": "大事だ", "is_correct": false, "explanation": "終止形は名詞の前に置けず、「大事だものです」では意味が通らない。"}, {"text": "大事さ", "is_correct": false, "explanation": "名詞「大事さ」は「もの」を修飾できず、「大事さのものです」は不自然。"}], "explanations": {"大事に": "連用形は名詞「もの」を直接修飾できず、「大事にものです」は成り立たない。", "大事な": "連体形で、後ろの名詞「もの」を修飾する正しい形。", "大事だ": "終止形は名詞の前に置けず、「大事だものです」では意味が通らない。", "大事さ": "名詞「大事さ」は「もの」を修飾できず、「大事さのものです」は不自然。"}, "sentence_index": 0, "correct_answer": "大事な"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会場では、大事な拍手が何度も起きた。", "explanation": "ここは〈大きな〉の意味。〈大事な〉は『大切な』の意味で、拍手の大きさは表せないので合わない。"}, {"text": "その選手は大会で大事を更新した。", "explanation": "〈記録を更新する〉の〈記録〉を〈大事〉に置き換えた形で、この言い方は使わない。〈記録〉の意味が必要。"}, {"text": "道路の大事を確かめてから渡る。", "explanation": "ここは〈安全〉の意味。〈大事〉では確かめる対象にならず、この言い方は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36523, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大事の", "is_correct": false, "explanation": "「大事」は形容動詞なので、「の」で名詞を修飾する形にはならず、「大事の思い出」は不自然。"}, {"text": "大事な", "is_correct": true, "explanation": "連体形で、後ろの名詞「思い出」を修飾する正しい形。"}, {"text": "大事そう", "is_correct": false, "explanation": "様態の形で、名詞を修飾するには「大事そうな」が必要。「大事そう思い出」は成り立たない。"}, {"text": "大事がる", "is_correct": false, "explanation": "「大事がる」は動詞で、名詞の前に直接置いて修飾することはできない。"}], "explanations": {"大事の": "「大事」は形容動詞なので、「の」で名詞を修飾する形にはならず、「大事の思い出」は不自然。", "大事な": "連体形で、後ろの名詞「思い出」を修飾する正しい形。", "大事そう": "様態の形で、名詞を修飾するには「大事そうな」が必要。「大事そう思い出」は成り立たない。", "大事がる": "「大事がる」は動詞で、名詞の前に直接置いて修飾することはできない。"}, "sentence_index": 6, "correct_answer": "大事な"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面白い話に、大事に笑い転げた。", "explanation": "〈大笑い〉の『大きく笑う』の意味。〈大事に〉は『丁寧に』の意味で、笑い方を表すには使わないので合わない。"}, {"text": "友達の話に、大事を打ってうなずいた。", "explanation": "〈相槌を打つ〉の〈相槌〉を〈大事〉に置き換えた形で、この言い方は使わない。〈相槌〉の意味が必要。"}, {"text": "毎日運動して大事を保っている。", "explanation": "ここは〈健康〉の意味。〈保つ〉の目的語に〈大事〉は使わず、この組み合わせは不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36523, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父にもらった大事ペンを、なくしてしまった。", "corrected_sentence": "祖父にもらった大事なペンを、なくしてしまった。", "error_description": "名詞「ペン」を修飾するには連体形「大事な」が必要。「な」が抜けていて誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "大事な", "is_correct": false, "explanation": "連体形は後ろに「する」を続けられず、「大事なする」は成り立たない。"}, {"text": "大事で", "is_correct": false, "explanation": "て形は「大事でする」とは続かず、不自然。"}, {"text": "大事なら", "is_correct": false, "explanation": "仮定形は「大事ならする」とは続かず、文法的に成り立たない。"}, {"text": "大事に", "is_correct": true, "explanation": "連用形で、後ろの動詞「する」に続いて「大事にする」となる正しい形。"}], "correct_form": "大事に", "base_form": "大事だ", "form_label": "連用形", "sentence_index": 1, "explanations": {"大事な": "連体形は後ろに「する」を続けられず、「大事なする」は成り立たない。", "大事で": "て形は「大事でする」とは続かず、不自然。", "大事なら": "仮定形は「大事ならする」とは続かず、文法的に成り立たない。", "大事に": "連用形で、後ろの動詞「する」に続いて「大事にする」となる正しい形。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36523, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家族の写真を大事で飾っている。", "corrected_sentence": "家族の写真を大事に飾っている。", "error_description": "動詞「飾る」を修飾するには連用形「大事に」が必要。て形「大事で」は動詞に続かず誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "大事がる", "is_correct": false, "explanation": "「大事がる」は動詞で、「何より大事がると思う」と形容動詞の位置には入らない。"}, {"text": "大事さ", "is_correct": false, "explanation": "名詞「大事さ」は「と思う」の前に述語として置けず、「何より大事さと思う」は不自然。"}, {"text": "大事の", "is_correct": false, "explanation": "「大事」は形容動詞なので「の」で続けられず、「何より大事のと思う」は成り立たない。"}, {"text": "大事だ", "is_correct": true, "explanation": "終止形で『と思う』に続き、断定の意見を表す正しい形。"}], "correct_form": "大事だ", "base_form": "大事だ", "form_label": "終止形", "sentence_index": 7, "explanations": {"大事がる": "「大事がる」は動詞で、「何より大事がると思う」と形容動詞の位置には入らない。", "大事さ": "名詞「大事さ」は「と思う」の前に述語として置けず、「何より大事さと思う」は不自然。", "大事の": "「大事」は形容動詞なので「の」で続けられず、「何より大事のと思う」は成り立たない。", "大事だ": "終止形で『と思う』に続き、断定の意見を表す正しい形。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36524, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "一緒に行動する相手を表す〈と〉。仲間といっしょにラーメンを食べたと自然に続く。"}, {"text": "に", "is_correct": false, "explanation": "相手や方向を示す助詞。〈仲間に ラーメンを食べた〉では一緒に食べた意味にならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。〈仲間へ ラーメンを食べた〉では、人を方向として扱う形になり不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の基準を示す助詞。〈仲間より ラーメンを食べた〉では一緒に食べた意味が通らない。"}], "correct_answer": "と", "explanations": {"と": "一緒に行動する相手を表す〈と〉。仲間といっしょにラーメンを食べたと自然に続く。", "に": "相手や方向を示す助詞。〈仲間に ラーメンを食べた〉では一緒に食べた意味にならないので合わない。", "へ": "方向を示す助詞。〈仲間へ ラーメンを食べた〉では、人を方向として扱う形になり不自然。", "より": "比較の基準を示す助詞。〈仲間より ラーメンを食べた〉では一緒に食べた意味が通らない。"}, "error_tags": {"に": "相手・方向", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36524, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "一緒に行く相手を表す〈と〉。趣味が同じ仲間と釣りに行くと自然に続く。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。〈仲間を 週末に釣りに行く〉では、仲間が目的語になり文の形が合わない。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ助詞。〈仲間の 週末に釣りに行く〉では、一緒に行く相手の意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。〈仲間へ 釣りに行く〉では人を行き先として扱う形になり、不自然。"}], "correct_answer": "と", "explanations": {"と": "一緒に行く相手を表す〈と〉。趣味が同じ仲間と釣りに行くと自然に続く。", "を": "目的語を示す助詞。〈仲間を 週末に釣りに行く〉では、仲間が目的語になり文の形が合わない。", "の": "名詞をつなぐ助詞。〈仲間の 週末に釣りに行く〉では、一緒に行く相手の意味にならない。", "へ": "方向を示す助詞。〈仲間へ 釣りに行く〉では人を行き先として扱う形になり、不自然。"}, "error_tags": {"を": "目的語", "の": "連体", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36524, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "いっしょに なにかを する ひと。", "primary_collocate": null, "pronunciation": "なかま", "ipa": "nakama", "syllable_count": 3, "sentences": [{"text": "公園で、仲間といっしょにサッカーをした。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "公園[こうえん]で、仲間[なかま]といっしょにサッカーをした。", "sentence_source": "generated"}, {"text": "学校の帰りに、仲間とラーメンを食べた。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "学校[がっこう]の帰[かえ]りに、仲間[なかま]とラーメンを食[た]べた。", "sentence_source": "generated"}, {"text": "山登りの仲間が、お弁当を分けてくれた。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "山登[やまのぼ]りの仲間[なかま]が、お弁当[べんとう]を分[わ]けてくれた。", "sentence_source": "generated"}, {"text": "ゲームが好きな仲間と、夜まで遊んだ。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "ゲームが好[す]きな仲間[なかま]と、夜[よる]まで遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "新しい仲間ができて、毎日が楽しい。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "新[あたら]しい仲間[なかま]ができて、毎日[まいにち]が楽[たの]しい。", "sentence_source": "generated"}, {"text": "仲間に入れてもらって、いっしょに歌った。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "仲間[なかま]に入[い]れてもらって、いっしょに歌[うた]った。", "sentence_source": "generated"}, {"text": "仲間がいたから、長い道もさみしくなかった。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "仲間[なかま]がいたから、長[なが]い道[みち]もさみしくなかった。", "sentence_source": "generated"}, {"text": "趣味が同じ仲間と、週末に釣りに行く。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "趣味[しゅみ]が同[おな]じ仲間[なかま]と、週末[しゅうまつ]に釣[つ]りに行[い]く。", "sentence_source": "generated"}, {"text": "私は仲間たちと、文化祭の準備をした。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "私[わたし]は仲間[なかま]たちと、文化祭[ぶんかさい]の準備[じゅんび]をした。", "sentence_source": "generated"}, {"text": "仲間が転んだので、みんなで手を貸した。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "仲間[なかま]が転[ころ]んだので、みんなで手[て]を貸[か]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仲間", "label": "基本形"}, {"form": "仲間たち", "label": "複数形"}], "register": "casual", "sense_fingerprint": "いっしょに遊んだり何かをしたりする身近な人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36524, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仲間", "is_correct": true, "explanation": "いっしょに行動する人を表す〈仲間〉。いっしょにサッカーをする相手として自然に入る。"}, {"text": "教科書", "is_correct": false, "explanation": "授業で使う本。いっしょにサッカーをする相手にはならないので合わない。"}, {"text": "靴下", "is_correct": false, "explanation": "足に履く衣類。サッカーを一緒にする相手としては成り立たないので入らない。"}, {"text": "砂", "is_correct": false, "explanation": "細かい土の粒。いっしょに何かをする相手にはならないので、ここには合わない。"}], "explanations": {"仲間": "いっしょに行動する人を表す〈仲間〉。いっしょにサッカーをする相手として自然に入る。", "教科書": "授業で使う本。いっしょにサッカーをする相手にはならないので合わない。", "靴下": "足に履く衣類。サッカーを一緒にする相手としては成り立たないので入らない。", "砂": "細かい土の粒。いっしょに何かをする相手にはならないので、ここには合わない。"}, "sentence_index": 0, "correct_answer": "仲間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このハサミは仲間が欠けている。", "explanation": "ここは〈刃〉の意味。ハサミの刃が欠けることは〈刃〉で言い、〈仲間〉は人の集まりを指すので物の部分には使わない。"}, {"text": "このカメは、ワニの仲間だ。", "explanation": "ここは〈同類〉の意味。生物の分類で近い種を指す使い方で、いっしょに何かをする人の義項とは違うので誤り。"}, {"text": "最後の大会で、仲間が悪くなり、優勝を逃した。", "explanation": "ここは〈仲〉の意味。人どうしの関係の良し悪しは〈仲〉で言い、〈仲間〉は人を指すので「悪くなる」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36524, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仲間", "is_correct": true, "explanation": "いつも一緒にいる仲間。仲間がいたから寂しくなかったと、理由として自然に続く。"}, {"text": "鍵", "is_correct": false, "explanation": "扉を開けるための道具。長い道の寂しさを和らげる存在にはならないので合わない。"}, {"text": "傘", "is_correct": false, "explanation": "雨を防ぐ道具。寂しさをなくす理由としては意味が通らないので入らない。"}, {"text": "地図", "is_correct": false, "explanation": "道を示す紙。寂しさを和らげる存在を表す文脈には合わないので合わない。"}], "explanations": {"仲間": "いつも一緒にいる仲間。仲間がいたから寂しくなかったと、理由として自然に続く。", "鍵": "扉を開けるための道具。長い道の寂しさを和らげる存在にはならないので合わない。", "傘": "雨を防ぐ道具。寂しさをなくす理由としては意味が通らないので入らない。", "地図": "道を示す紙。寂しさを和らげる存在を表す文脈には合わないので合わない。"}, "sentence_index": 6, "correct_answer": "仲間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "見知らぬ仲間が声をかけてきた。", "explanation": "ここは〈見知らぬ人〉の意味。面識のない人を表すのは〈見知らぬ人〉で、〈仲間〉は普段から一緒にいる人なので両立しない。"}, {"text": "通りすがりの仲間が助けてくれた。", "explanation": "ここは〈通りすがりの人〉の意味。たまたま通りかかった人を表すので、〈仲間〉は合わない。"}, {"text": "このシャツの仲間が破れた。", "explanation": "ここは〈生地〉の意味。服の布の部分は〈生地〉で言い、〈仲間〉は人を指すので布地には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36524, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の仲間を、みんな野球が好きだ。", "corrected_sentence": "私の仲間は、みんな野球が好きだ。", "error_description": "〈仲間〉は主題として〈は〉で示す。〈を〉は目的語を示すが、後ろに動詞がないので文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36524, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい仲間を買って、チームを作った。", "corrected_sentence": "新しい仲間を集めて、チームを作った。", "error_description": "〈仲間〉は〈集める〉で得るもの。〈買う〉は物に使う動詞なので、人に対しては言えない。正しくは〈集めて〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36525, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "一緒に稽古をする相手を表す〈と〉で、仲間に付くのが自然。"}, {"text": "を", "is_correct": false, "explanation": "稽古の対象のように読めてしまい、「仲間を稽古している」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「仲間の、毎日稽古」と所有の形になり、文が続かない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すため、「仲間へ稽古をしている」では一緒に行う意味にならない。"}], "correct_answer": "と", "explanations": {"と": "一緒に稽古をする相手を表す〈と〉で、仲間に付くのが自然。", "を": "稽古の対象のように読めてしまい、「仲間を稽古している」は不自然。", "の": "「仲間の、毎日稽古」と所有の形になり、文が続かない。", "へ": "方向を表すため、「仲間へ稽古をしている」では一緒に行う意味にならない。"}, "error_tags": {"を": "対象", "の": "所有", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36525, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "頼む相手を表す〈に〉で、「仲間に頼んだ」が成り立つ。"}, {"text": "で", "is_correct": false, "explanation": "「仲間で頼んだ」は場所や手段を表し、頼む相手にならない。"}, {"text": "から", "is_correct": false, "explanation": "「仲間から頼んだ」は起点を示し、頼む方向が逆になる。"}, {"text": "の", "is_correct": false, "explanation": "「仲間の、部の仕事を頼んだ」と所有の形になり、依頼の相手が表せず文が続かない。"}], "correct_answer": "に", "explanations": {"に": "頼む相手を表す〈に〉で、「仲間に頼んだ」が成り立つ。", "で": "「仲間で頼んだ」は場所や手段を表し、頼む相手にならない。", "から": "「仲間から頼んだ」は起点を示し、頼む方向が逆になる。", "の": "「仲間の、部の仕事を頼んだ」と所有の形になり、依頼の相手が表せず文が続かない。"}, "error_tags": {"で": "場所・手段", "から": "起点", "の": "所有"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36525, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "同じ目的や活動をともにする人。グループの一員。", "primary_collocate": null, "pronunciation": "なかま", "ipa": "nakama", "syllable_count": 3, "sentences": [{"text": "彼はこの研究チームの大切な仲間だ。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "彼[かれ]はこの研究[けんきゅう]チームの大切[たいせつ]な仲間[なかま]だ。", "sentence_source": "generated"}, {"text": "同じ劇団の仲間と、毎日稽古をしている。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "同[おな]じ劇団[げきだん]の仲間[なかま]と、毎日[まいにち]稽古[けいこ]をしている。", "sentence_source": "generated"}, {"text": "新入社員も、すぐにチームの仲間になった。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "新入社員[しんにゅうしゃいん]も、すぐにチームの仲間[なかま]になった。", "sentence_source": "generated"}, {"text": "仲間と力を合わせて、ボランティア活動を続けている。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "仲間[なかま]と力[ちから]を合[あ]わせて、ボランティア活動[かつどう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "私たちは同じ目標を目指す仲間だ。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "私[わたし]たちは同[おな]じ目標[もくひょう]を目指[めざ]す仲間[なかま]だ。", "sentence_source": "generated"}, {"text": "試合に負けても、仲間を責める人はいなかった。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けても、仲間[なかま]を責[せ]める人[ひと]はいなかった。", "sentence_source": "generated"}, {"text": "登山隊の仲間は、全員無事に山を下りた。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "登山隊[とざんたい]の仲間[なかま]は、全員[ぜんいん]無事[ぶじ]に山[やま]を下[お]りた。", "sentence_source": "generated"}, {"text": "同じサークルの仲間に、部の仕事を頼んだ。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "同[おな]じサークルの仲間[なかま]に、部[ぶ]の仕事[しごと]を頼[たの]んだ。", "sentence_source": "generated"}, {"text": "仲間の一人が病気になったので、練習を休んだ。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "仲間[なかま]の一人[ひとり]が病気[びょうき]になったので、練習[れんしゅう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "会社の仲間と新しい商品を開発した。", "target_word": "仲間", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の仲間[なかま]と新[あたら]しい商品[しょうひん]を開発[かいはつ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "仲間", "label": "基本形"}, {"form": "仲間たち", "label": "複数形"}], "register": "neutral", "sense_fingerprint": "チームや団体で目的を共にする一員", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36525, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仲間", "is_correct": true, "explanation": "研究チームの一員を指す〈仲間〉が入り、「大切な仲間だ」として自然に成り立つ。"}, {"text": "天気", "is_correct": false, "explanation": "「大切な天気だ」では意味が通らず、チームの一員という文脈に合わない。"}, {"text": "砂糖", "is_correct": false, "explanation": "人を表さず、「研究チームの大切な砂糖だ」は成り立たない。"}, {"text": "出口", "is_correct": false, "explanation": "場所を表す語で、研究チームの一員を指すことはできない。"}], "explanations": {"仲間": "研究チームの一員を指す〈仲間〉が入り、「大切な仲間だ」として自然に成り立つ。", "天気": "「大切な天気だ」では意味が通らず、チームの一員という文脈に合わない。", "砂糖": "人を表さず、「研究チームの大切な砂糖だ」は成り立たない。", "出口": "場所を表す語で、研究チームの一員を指すことはできない。"}, "sentence_index": 0, "correct_answer": "仲間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼とは五年付き合っている仲間だ。", "explanation": "ここは〈恋人〉の意味。恋愛の相手を〈仲間〉とは呼ばず、目的を共にする人を指す語義に合わない。"}, {"text": "取引先で少し話したことがあるだけの、ただの仲間だ。", "explanation": "ここは〈知人〉の意味。目的を共にしていない相手を〈仲間〉と呼ぶのは合わない。"}, {"text": "駅で一度すれ違っただけの人は、私にとって仲間だ。", "explanation": "ここは〈他人〉の意味。面識のない相手は目的を共にする仲間ではなく他人なので、この語義には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36525, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仲間", "is_correct": true, "explanation": "登山隊の一員を指す〈仲間〉が入り、全員無事に下山した文として成り立つ。"}, {"text": "鍵", "is_correct": false, "explanation": "人を表さず、「登山隊の鍵は山を下りた」では主語にならない。"}, {"text": "電池", "is_correct": false, "explanation": "物なので、山を下りた人たちの主語として意味が通らない。"}, {"text": "花火", "is_correct": false, "explanation": "人を指せず、「登山隊の花火は山を下りた」は成り立たない。"}], "explanations": {"仲間": "登山隊の一員を指す〈仲間〉が入り、全員無事に下山した文として成り立つ。", "鍵": "人を表さず、「登山隊の鍵は山を下りた」では主語にならない。", "電池": "物なので、山を下りた人たちの主語として意味が通らない。", "花火": "人を指せず、「登山隊の花火は山を下りた」は成り立たない。"}, "sentence_index": 6, "correct_answer": "仲間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "決勝戦の前、仲間と向かい合って互いに礼をした。", "explanation": "ここは〈対戦相手〉の意味。仲間は同じ側の人なので、向かい合って戦う相手には使えない。"}, {"text": "上司は、新人の仲間として厳しく指導した。", "explanation": "ここは〈上下関係にある相手〉の意味。対等に目的を共にする人を指す〈仲間〉とは合わない。"}, {"text": "審判は、選手の仲間として判定を下した。", "explanation": "ここは〈中立の第三者〉の意味。試合の当事者ではない審判は、目的を共にする仲間とは呼ばない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36525, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私たちは同じ目標を目指す仲間に、いつも一緒に活動している。", "corrected_sentence": "私たちは同じ目標を目指す仲間と、いつも一緒に活動している。", "error_description": "「一緒に活動する相手」は「と」で表す。「仲間に」と書くと相手ではなく受け手のような読みになり、一緒に活動する意味が伝わらない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36525, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、同じ部の仲間を、資料の整理を頼んだ。", "corrected_sentence": "昨日、同じ部の仲間に、資料の整理を頼んだ。", "error_description": "頼む相手は「に」で示す。「仲間を」と書くと仲間を頼みごとの対象のように扱うことになり、依頼先が表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36527, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "直接の対象（理由）を示し、『理由を説明する』として正しい。"}, {"text": "が", "is_correct": false, "explanation": "『理由が先生に説明した』と主語にすると、理由が説明する主体になり意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "『遅刻した理由の先生に』と続けると、説明の対象が文の中で成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "『理由と先生に説明した』は並列にも相手にもならず、不自然。"}], "correct_answer": "を", "explanations": {"を": "直接の対象（理由）を示し、『理由を説明する』として正しい。", "が": "『理由が先生に説明した』と主語にすると、理由が説明する主体になり意味が通らない。", "の": "『遅刻した理由の先生に』と続けると、説明の対象が文の中で成り立たない。", "と": "『理由と先生に説明した』は並列にも相手にもならず、不自然。"}, "error_tags": {"を": "対象", "が": "主語", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36527, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『行かない理由を聞かれる』として、理由を対象として示す正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "『行かない理由に聞かれて』と相手や位置を示すと、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、理由には向かわないので不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞で、『理由より聞かれて』は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『行かない理由を聞かれる』として、理由を対象として示す正しい助詞。", "に": "『行かない理由に聞かれて』と相手や位置を示すと、意味が通らない。", "へ": "方向を表す助詞で、理由には向かわないので不自然。", "より": "比較の助詞で、『理由より聞かれて』は文が成り立たない。"}, "error_tags": {"を": "対象", "に": "相手・位置", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36527, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事がそうなる原因や根拠。なぜそうなるのかを説明するための考え。", "primary_collocate": null, "pronunciation": "りゆう", "ipa": "ɾijɯː", "syllable_count": 3, "sentences": [{"text": "彼がこれらを大切に育てる理由は、地域の子供たちに安全な給食を安定的に提供するためだ。", "target_word": "理由", "complexity_tier": "T4", "furigana": "彼[かれ]がこれらを大切[たいせつ]に育[そだ]てる理由[りゆう]は、地域[ちいき]の子供[こども]たちに安全[あんぜん]な給食[きゅうしょく]を安定的[あんていてき]に提供[ていきょう]するためだ。", "sentence_source": "mined"}, {"text": "遅刻した理由を先生に正直に説明した。", "target_word": "理由", "complexity_tier": "T3", "furigana": "遅刻[ちこく]した理由[りゆう]を先生[せんせい]に正直[しょうじき]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "彼女が会社を辞めた理由は、誰にも分からなかった。", "target_word": "理由", "complexity_tier": "T3", "furigana": "彼女[かのじょ]が会社[かいしゃ]を辞[や]めた理由[りゆう]は、誰[だれ]にも分[わ]からなかった。", "sentence_source": "generated"}, {"text": "理由もなく不安になることが、たまにある。", "target_word": "理由", "complexity_tier": "T3", "furigana": "理由[りゆう]もなく不安[ふあん]になることが、たまにある。", "sentence_source": "generated"}, {"text": "雨が降っているという理由で、運動会は中止になった。", "target_word": "理由", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]っているという理由[りゆう]で、運動会[うんどうかい]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "田中さんが怒るのは当然で、彼には十分な理由がある。", "target_word": "理由", "complexity_tier": "T3", "furigana": "田中[たなか]さんが怒[おこ]るのは当然[とうぜん]で、彼[かれ]には十分[じゅうぶん]な理由[りゆう]がある。", "sentence_source": "generated"}, {"text": "電車が遅れた理由は、強風のためだと放送で説明された。", "target_word": "理由", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が遅[おく]れた理由[りゆう]は、強風[きょうふう]のためだと放送[ほうそう]で説明[せつめい]された。", "sentence_source": "generated"}, {"text": "行かない理由を聞かれて、彼は黙ってしまった。", "target_word": "理由", "complexity_tier": "T3", "furigana": "行[い]かない理由[りゆう]を聞[き]かれて、彼[かれ]は黙[だま]ってしまった。", "sentence_source": "generated"}, {"text": "私が日本語を勉強する理由は、日本の小説を原文で読みたいからだ。", "target_word": "理由", "complexity_tier": "T3", "furigana": "私[わたし]が日本語[にほんご]を勉強[べんきょう]する理由[りゆう]は、日本[にほん]の小説[しょうせつ]を原文[げんぶん]で読[よ]みたいからだ。", "sentence_source": "generated"}, {"text": "理由を言わずに断られたので、納得できなかった。", "target_word": "理由", "complexity_tier": "T3", "furigana": "理由[りゆう]を言[い]わずに断[ことわ]られたので、納得[なっとく]できなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "理由", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事が起こる原因・根拠を説明する名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd67c50-7f83-4308-bf88-da37a0518856') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36527, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理由", "is_correct": true, "explanation": "「育てる理由」として、後半の「〜ためだ」で根拠・原因を説明する文になる。"}, {"text": "季節", "is_correct": false, "explanation": "季節は育てる対象にならず、「育てる季節は〜ためだ」では内容が合わない。"}, {"text": "食器", "is_correct": false, "explanation": "食器は育てるものではないので、「育てる食器」は成り立たない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは育てるものではなく、この文の空欄には入らない。"}], "explanations": {"理由": "「育てる理由」として、後半の「〜ためだ」で根拠・原因を説明する文になる。", "季節": "季節は育てる対象にならず、「育てる季節は〜ためだ」では内容が合わない。", "食器": "食器は育てるものではないので、「育てる食器」は成り立たない。", "夕焼け": "夕焼けは育てるものではなく、この文の空欄には入らない。"}, "sentence_index": 0, "correct_answer": "理由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この言葉の理由は、昔の辞書では『役に立つこと』と書かれている。", "explanation": "ここは〈意味〉の意味。理由は物事の原因や根拠で、言葉が表す内容は指さないので合わない。"}, {"text": "この機械の理由は、三つの部品でできている。", "explanation": "ここは〈構成〉の意味。理由は原因や根拠で、機械の部品や組み立ては指さないので合わない。"}, {"text": "今週の理由は、毎日の会議と資料作りで埋まっている。", "explanation": "ここは〈予定〉の意味。理由は原因や根拠で、一定期間に入っている予定は指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36527, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理由", "is_correct": true, "explanation": "「遅れた理由は〜ためだ」と、原因を説明する名詞として文が成り立つ。"}, {"text": "切符", "is_correct": false, "explanation": "切符は遅れるものではないので、「遅れた切符は〜ためだ」が成り立たない。"}, {"text": "窓ガラス", "is_correct": false, "explanation": "窓ガラスが遅れることはなく、この空欄には入らない。"}, {"text": "夕立", "is_correct": false, "explanation": "夕立は『遅れた』の主体にならず、文の内容と合わない。"}], "explanations": {"理由": "「遅れた理由は〜ためだ」と、原因を説明する名詞として文が成り立つ。", "切符": "切符は遅れるものではないので、「遅れた切符は〜ためだ」が成り立たない。", "窓ガラス": "窓ガラスが遅れることはなく、この空欄には入らない。", "夕立": "夕立は『遅れた』の主体にならず、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "理由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の理由は、来月に延期することになった。", "explanation": "ここは〈結論〉の意味。理由は原因や根拠で、議論の末に出した答えは指さないので合わない。"}, {"text": "目的地へ行く理由は電車だ。", "explanation": "ここは〈手段〉の意味。理由は『そうなる原因や根拠』で、目的地へ行く方法は表さないので合わない。"}, {"text": "映画の理由は、二時間を超える長さだった。", "explanation": "ここは〈上映時間〉の意味。理由は原因や根拠で、作品の長さは指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36527, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "欠席した理由が、先生に正直に説明した。", "corrected_sentence": "欠席した理由を、先生に正直に説明した。", "error_description": "「説明する」の対象は『理由を』と『を』で示す。『理由が』と主格にすると『理由が説明した』となり、主語として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36527, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台風が来るという理由に、学校は休みになった。", "corrected_sentence": "台風が来るという理由で、学校は休みになった。", "error_description": "原因を表す『理由で』が正しい。『理由に』は助詞が誤りで、原因の意味にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52fd92db-7a37-4651-bd44-6b237b6641eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36530, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不完全", "is_correct": true, "explanation": "「完全」の反対は「不完全」で、対義語の関係にある。"}, {"text": "簡単", "is_correct": false, "explanation": "「簡単」は『手間がかからない』の意味で、「完全」の対義語ではない。"}, {"text": "平凡", "is_correct": false, "explanation": "「平凡」は『特にすぐれた点がない』の意味で、「完全」の対義語ではない。"}, {"text": "確実", "is_correct": false, "explanation": "「確実」は『間違いがない』の意味で、「完全」の対義語ではない。"}], "correct_answer": "不完全", "explanations": {"不完全": "「完全」の反対は「不完全」で、対義語の関係にある。", "簡単": "「簡単」は『手間がかからない』の意味で、「完全」の対義語ではない。", "平凡": "「平凡」は『特にすぐれた点がない』の意味で、「完全」の対義語ではない。", "確実": "「確実」は『間違いがない』の意味で、「完全」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36530, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不完全", "is_correct": true, "explanation": "「完全」の反対は「不完全」で、対義語の関係にある。"}, {"text": "単純", "is_correct": false, "explanation": "「単純」は『複雑でない』の意味で、「完全」の対義語ではない。"}, {"text": "容易", "is_correct": false, "explanation": "「容易」は『たやすい』の意味で、「完全」の対義語ではない。"}, {"text": "無難", "is_correct": false, "explanation": "「無難」は『問題がない』の意味で、「完全」の対義語ではない。"}], "correct_answer": "不完全", "explanations": {"不完全": "「完全」の反対は「不完全」で、対義語の関係にある。", "単純": "「単純」は『複雑でない』の意味で、「完全」の対義語ではない。", "容易": "「容易」は『たやすい』の意味で、「完全」の対義語ではない。", "無難": "「無難」は『問題がない』の意味で、「完全」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36530, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "全てがそろっていること", "primary_collocate": null, "pronunciation": "かんぜん", "ipa": "ka̠ɰ̃d͡zeɰ̃", "syllable_count": 4, "sentences": [{"text": "この辞書は全十巻が完全にそろっています。", "target_word": "完全に", "complexity_tier": "T3", "furigana": "この辞書[じしょ]は全十巻[ぜんじゅっかん]が完全[かんぜん]にそろっています。", "sentence_source": "generated"}, {"text": "完全な形で残っている古い皿は、とても少ない。", "target_word": "完全な", "complexity_tier": "T4", "furigana": "完全[かんぜん]な形[かたち]で残[のこ]っている古[ふる]い皿[さら]は、とても少[すく]ない。", "sentence_source": "generated"}, {"text": "部品が完全なら、この機械はすぐ動く。", "target_word": "完全なら", "complexity_tier": "T3", "furigana": "部品[ぶひん]が完全[かんぜん]なら、この機械[きかい]はすぐ動[うご]く。", "sentence_source": "generated"}, {"text": "切手のコレクションを、やっと完全にそろえた。", "target_word": "完全に", "complexity_tier": "T3", "furigana": "切手[きって]のコレクションを、やっと完全[かんぜん]にそろえた。", "sentence_source": "generated"}, {"text": "完全なセットで買うと、少し安くなります。", "target_word": "完全な", "complexity_tier": "T3", "furigana": "完全[かんぜん]なセットで買[か]うと、少[すこ]し安[やす]くなります。", "sentence_source": "generated"}, {"text": "資料が完全ではないので、まだ発表できない。", "target_word": "完全", "complexity_tier": "T3", "furigana": "資料[しりょう]が完全[かんぜん]ではないので、まだ発表[はっぴょう]できない。", "sentence_source": "generated"}, {"text": "この全集は一巻から最終巻まで完全にそろっている。", "target_word": "完全に", "complexity_tier": "T4", "furigana": "この全集[ぜんしゅう]は一巻[いっかん]から最終巻[さいしゅうかん]まで完全[かんぜん]にそろっている。", "sentence_source": "generated"}, {"text": "完全な骨が見つかり、研究が進んだ。", "target_word": "完全な", "complexity_tier": "T4", "furigana": "完全[かんぜん]な骨[ほね]が見[み]つかり、研究[けんきゅう]が進[すす]んだ。", "sentence_source": "generated"}, {"text": "名簿が完全にそろってから、会を始めます。", "target_word": "完全に", "complexity_tier": "T3", "furigana": "名簿[めいぼ]が完全[かんぜん]にそろってから、会[かい]を始[はじ]めます。", "sentence_source": "generated"}, {"text": "箱を開けると、部品が完全にそろっていた。", "target_word": "完全", "complexity_tier": "T3", "furigana": "箱[はこ]を開[あ]けると、部品[ぶひん]が完全[かんぜん]にそろっていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "完全だ", "label": "終止形"}, {"form": "完全な", "label": "連体形"}, {"form": "完全に", "label": "連用形"}, {"form": "完全で", "label": "て形"}, {"form": "完全なら", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "必要な部分や数が全部そろっていて、足りないものがない(完全なセット、完全にそろう)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36530, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完全に", "is_correct": true, "explanation": "連用形で、後ろの動詞「そろう」を修飾する正しい形。"}, {"text": "完全な", "is_correct": false, "explanation": "連体形は名詞の前に置くので、「完全なそろっています」は成り立たない。"}, {"text": "完全だ", "is_correct": false, "explanation": "終止形は動詞に直接続けられず、「完全だそろっています」は不自然。"}, {"text": "完全さ", "is_correct": false, "explanation": "名詞「完全さ」は動詞を修飾できず、「完全さそろっています」は意味が通らない。"}], "explanations": {"完全に": "連用形で、後ろの動詞「そろう」を修飾する正しい形。", "完全な": "連体形は名詞の前に置くので、「完全なそろっています」は成り立たない。", "完全だ": "終止形は動詞に直接続けられず、「完全だそろっています」は不自然。", "完全さ": "名詞「完全さ」は動詞を修飾できず、「完全さそろっています」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "完全に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "演奏の完全さに、会場は静まり返った。", "explanation": "〈完全さ〉は『欠点がなく見事』の意味。ここは『全部そろっている』の意味ではないので合わない。"}, {"text": "その店は完全に閉まっていた。", "explanation": "〈完全に〉の『まったく』の意味。『全部そろっている』の意味とは違うので、ここでは合わない。"}, {"text": "彼は完全な人間だと言われている。", "explanation": "〈完全な〉は『欠点がなく立派な』の意味で、『全部そろっている』の意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36530, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完全の", "is_correct": false, "explanation": "「完全」は形容動詞なので、「の」で名詞を修飾する形にはならず、「完全の」は不自然。"}, {"text": "完全に", "is_correct": true, "explanation": "連用形で、後ろの動詞「そろっている」を修飾する正しい形。"}, {"text": "完全だろう", "is_correct": false, "explanation": "推量形は動詞に直接続けられず、「完全だろうそろっている」は不自然。"}, {"text": "完全ではない", "is_correct": false, "explanation": "否定の形は動詞を修飾できず、「完全ではないそろっている」は文法的に誤り。"}], "explanations": {"完全の": "「完全」は形容動詞なので、「の」で名詞を修飾する形にはならず、「完全の」は不自然。", "完全に": "連用形で、後ろの動詞「そろっている」を修飾する正しい形。", "完全だろう": "推量形は動詞に直接続けられず、「完全だろうそろっている」は不自然。", "完全ではない": "否定の形は動詞を修飾できず、「完全ではないそろっている」は文法的に誤り。"}, "sentence_index": 6, "correct_answer": "完全に"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "完全な夕焼けに、みんなが息をのんだ。", "explanation": "〈完全な〉は『欠点がなく見事』の意味。ここは『部品がすべてそろう』の意味ではないので合わない。"}, {"text": "スープは完全に冷めていた。", "explanation": "〈完全に〉の『すっかり』の意味。『全部そろっていた』の意味とは違うので合わない。"}, {"text": "完全さを求めて、何度も練習した。", "explanation": "〈完全さ〉は『欠点がなく見事なこと』。ここは『部品がすべてそろう』の意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
