INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36531, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "欠けるところがなく、十分であること", "primary_collocate": null, "pronunciation": "かんぜん", "ipa": "ka̠ɰ̃d͡zeɰ̃", "syllable_count": 4, "sentences": [{"text": "薬のおかげで、病気は完全に治りました。", "target_word": "完全に", "complexity_tier": "T3", "furigana": "薬[くすり]のおかげで、病気[びょうき]は完全[かんぜん]に治[なお]りました。", "sentence_source": "generated"}, {"text": "彼の計画には、完全な準備が必要だ。", "target_word": "完全な", "complexity_tier": "T3", "furigana": "彼[かれ]の計画[けいかく]には、完全[かんぜん]な準備[じゅんび]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "昨日の試合は、完全に私たちの勝ちだった。", "target_word": "完全に", "complexity_tier": "T3", "furigana": "昨日[きのう]の試合[しあい]は、完全[かんぜん]に私[わたし]たちの勝[か]ちだった。", "sentence_source": "generated"}, {"text": "完全な答えを書いたので、満点をもらった。", "target_word": "完全な", "complexity_tier": "T3", "furigana": "完全[かんぜん]な答[こた]えを書[か]いたので、満点[まんてん]をもらった。", "sentence_source": "generated"}, {"text": "雨で、完全に服がぬれてしまった。", "target_word": "完全に", "complexity_tier": "T3", "furigana": "雨[あめ]で、完全[かんぜん]に服[ふく]がぬれてしまった。", "sentence_source": "generated"}, {"text": "この問題を、完全に理解するまで続けます。", "target_word": "完全に", "complexity_tier": "T3", "furigana": "この問題[もんだい]を、完全[かんぜん]に理解[りかい]するまで続[つづ]けます。", "sentence_source": "generated"}, {"text": "彼の説明は完全で、質問する所がなかった。", "target_word": "完全で", "complexity_tier": "T4", "furigana": "彼[かれ]の説明[せつめい]は完全[かんぜん]で、質問[しつもん]する所[ところ]がなかった。", "sentence_source": "generated"}, {"text": "完全に安全な方法は、なかなかない。", "target_word": "完全に", "complexity_tier": "T4", "furigana": "完全[かんぜん]に安全[あんぜん]な方法[ほうほう]は、なかなかない。", "sentence_source": "generated"}, {"text": "失敗のない完全な仕事を目指している。", "target_word": "完全な", "complexity_tier": "T4", "furigana": "失敗[しっぱい]のない完全[かんぜん]な仕事[しごと]を目指[めざ]している。", "sentence_source": "generated"}, {"text": "事故のあと、道は完全にふさがれた。", "target_word": "完全に", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、道[みち]は完全[かんぜん]にふさがれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "完全だ", "label": "終止形"}, {"form": "完全な", "label": "連体形"}, {"form": "完全に", "label": "連用形"}, {"form": "完全で", "label": "て形"}, {"form": "完全なら", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "欠点や不足がなく、程度が十分で徹底している(完全に治る、完全な準備)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf91980e-aa9f-47fd-89fe-b8e33253bc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36531, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完全に", "is_correct": true, "explanation": "連用形で、後ろの動詞「治りました」を修飾する正しい形。"}, {"text": "完全な", "is_correct": false, "explanation": "連体形は名詞の前に置くので、「病気は完全な治りました」は成り立たない。"}, {"text": "完全だ", "is_correct": false, "explanation": "終止形は動詞に直接続けられず、「完全だ治りました」は不自然。"}, {"text": "完全さ", "is_correct": false, "explanation": "名詞「完全さ」は動詞を修飾できず、「完全さ治りました」は意味が通らない。"}], "explanations": {"完全に": "連用形で、後ろの動詞「治りました」を修飾する正しい形。", "完全な": "連体形は名詞の前に置くので、「病気は完全な治りました」は成り立たない。", "完全だ": "終止形は動詞に直接続けられず、「完全だ治りました」は不自然。", "完全さ": "名詞「完全さ」は動詞を修飾できず、「完全さ治りました」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "完全に"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全十巻のうち、完全なそろいは三巻しかない。", "explanation": "〈完全な〉は『全部そろっている』の意味で、ここは『欠点がなく十分』の意味ではないので合わない。"}, {"text": "骨格は完全なまま、博物館に保存されている。", "explanation": "〈完全な〉は『欠けた部分がない』の意味で、ここは『欠点がなく十分』の意味ではないので合わない。"}, {"text": "箱の中身は、部品が完全なセットだった。", "explanation": "〈完全な〉は『全部そろっている』の意味で、ここは『欠点がなく十分』の意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36531, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完全で", "is_correct": true, "explanation": "て形で、『完全で、質問する所がなかった』と後ろに続く正しい形。"}, {"text": "完全の", "is_correct": false, "explanation": "「完全」は形容動詞なので、「の」で名詞を修飾する形にはならず不自然。"}, {"text": "完全な", "is_correct": false, "explanation": "連体形は名詞の前に置くもので、読点の後に文を続けられず成り立たない。"}, {"text": "完全そう", "is_correct": false, "explanation": "様態の形は「完全そうで」の形で続き、このままでは文が成り立たない。"}], "explanations": {"完全で": "て形で、『完全で、質問する所がなかった』と後ろに続く正しい形。", "完全の": "「完全」は形容動詞なので、「の」で名詞を修飾する形にはならず不自然。", "完全な": "連体形は名詞の前に置くもので、読点の後に文を続けられず成り立たない。", "完全そう": "様態の形は「完全そうで」の形で続き、このままでは文が成り立たない。"}, "sentence_index": 6, "correct_answer": "完全で"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "完全なセットで売られている。", "explanation": "〈完全な〉の『全部そろっている』の意味。ここは『欠点がなく十分』の意味ではないので合わない。"}, {"text": "十巻の全集が完全にそろった棚を、ようやく眺めた。", "explanation": "〈完全に〉の『全部そろう』の意味で、ここは『欠点がなく十分』の意味ではないので合わない。"}, {"text": "部品の完全なそろいを確かめた。", "explanation": "〈完全〉の『全部そろっている』の意味。『欠けるところがなく十分』の意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36531, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事故の後、道は完全通れるようになった。", "corrected_sentence": "事故の後、道は完全に通れるようになった。", "error_description": "「完全」を副詞として動詞「通れる」に続けるには「に」が必要。「に」が抜けていて誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "完全な", "is_correct": true, "explanation": "連体形で、後ろの名詞「準備」を修飾する正しい形。"}, {"text": "完全だ", "is_correct": false, "explanation": "終止形は名詞の前に置けず、「完全だ準備」は不自然。"}, {"text": "完全そう", "is_correct": false, "explanation": "様態の形は名詞を修飾できず、「完全そう準備」は成り立たない。"}, {"text": "完全で", "is_correct": false, "explanation": "て形は名詞を修飾できず、「完全で準備」は文法的に誤り。"}], "correct_form": "完全な", "base_form": "完全だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"完全な": "連体形で、後ろの名詞「準備」を修飾する正しい形。", "完全だ": "終止形は名詞の前に置けず、「完全だ準備」は不自然。", "完全そう": "様態の形は名詞を修飾できず、「完全そう準備」は成り立たない。", "完全で": "て形は名詞を修飾できず、「完全で準備」は文法的に誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36531, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は完全の答えを書いた。", "corrected_sentence": "彼は完全な答えを書いた。", "error_description": "「完全」は形容動詞で、名詞「答え」を修飾するには連体形「完全な」が必要。「完全の」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "完全に", "is_correct": true, "explanation": "連用形で、後ろの形容動詞「安全な」を修飾する正しい形。"}, {"text": "完全の", "is_correct": false, "explanation": "「完全」は形容動詞なので「の」で続けられず、「完全の安全な」は成り立たない。"}, {"text": "完全さ", "is_correct": false, "explanation": "名詞「完全さ」は後ろの形容動詞「安全な」を修飾できず、成り立たない。"}, {"text": "完全だろう", "is_correct": false, "explanation": "推量形は連体修飾に使えず、「完全だろう安全な」は成り立たない。"}], "correct_form": "完全に", "base_form": "完全だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"完全に": "連用形で、後ろの形容動詞「安全な」を修飾する正しい形。", "完全の": "「完全」は形容動詞なので「の」で続けられず、「完全の安全な」は成り立たない。", "完全さ": "名詞「完全さ」は後ろの形容動詞「安全な」を修飾できず、成り立たない。", "完全だろう": "推量形は連体修飾に使えず、「完全だろう安全な」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5d74ac4-a980-483c-822a-fca9110e7599') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36532, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「解明に取り組む」で、取り組む対象を示す〈に〉。"}, {"text": "を", "is_correct": false, "explanation": "「解明を取り組む」は不自然で、〈取り組む〉の対象には〈に〉を使う。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段を示す。「解明で取り組む」は意味が合わない。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示す。「解明が取り組む」は主語が違い不自然。"}], "correct_answer": "に", "explanations": {"に": "「解明に取り組む」で、取り組む対象を示す〈に〉。", "を": "「解明を取り組む」は不自然で、〈取り組む〉の対象には〈に〉を使う。", "で": "〈で〉は手段を示す。「解明で取り組む」は意味が合わない。", "が": "〈が〉は主語を示す。「解明が取り組む」は主語が違い不自然。"}, "error_tags": {"を": "目的格", "で": "手段", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
