INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36532, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "まだわからないことをもっとよくわかるようにすることです。", "primary_collocate": null, "pronunciation": "かいめい", "ipa": "kaimeː", "syllable_count": 4, "sentences": [{"text": "事故の原因の解明には、まだ時間がかかる。", "target_word": "解明", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]の解明[かいめい]には、まだ時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "科学者たちは、宇宙のなぞの解明に取り組んでいる。", "target_word": "解明", "complexity_tier": "T3", "furigana": "科学者[かがくしゃ]たちは、宇宙[うちゅう]のなぞの解明[かいめい]に取[と]り組[く]んでいる。", "sentence_source": "generated"}, {"text": "病気の仕組みが解明され、新しい薬ができた。", "target_word": "解明され", "complexity_tier": "T3", "furigana": "病気[びょうき]の仕組[しく]みが解明[かいめい]され、新[あたら]しい薬[くすり]ができた。", "sentence_source": "generated"}, {"text": "警察は事件の解明を急いでいる。", "target_word": "解明", "complexity_tier": "T3", "furigana": "警察[けいさつ]は事件[じけん]の解明[かいめい]を急[いそ]いでいる。", "sentence_source": "generated"}, {"text": "謎の解明のために、古い資料を読み直した。", "target_word": "解明", "complexity_tier": "T3", "furigana": "謎[なぞ]の解明[かいめい]のために、古[ふる]い資料[しりょう]を読[よ]み直[なお]した。", "sentence_source": "generated"}, {"text": "彼は動物の行動を解明したくて、研究者になった。", "target_word": "解明し", "complexity_tier": "T3", "furigana": "彼[かれ]は動物[どうぶつ]の行動[こうどう]を解明[かいめい]したくて、研究者[けんきゅうしゃ]になった。", "sentence_source": "generated"}, {"text": "解明が進めば、病気の予防もしやすくなる。", "target_word": "解明", "complexity_tier": "T3", "furigana": "解明[かいめい]が進[すす]めば、病気[びょうき]の予防[よぼう]もしやすくなる。", "sentence_source": "generated"}, {"text": "まだ解明されていない言葉の由来が多い。", "target_word": "解明され", "complexity_tier": "T3", "furigana": "まだ解明[かいめい]されていない言葉[ことば]の由来[ゆらい]が多[おお]い。", "sentence_source": "generated"}, {"text": "原因を解明しないと、同じ失敗を繰り返す。", "target_word": "解明し", "complexity_tier": "T3", "furigana": "原因[げんいん]を解明[かいめい]しないと、同[おな]じ失敗[しっぱい]を繰[く]り返[かえ]す。", "sentence_source": "generated"}, {"text": "長年の疑問が解明されて、みんなほっとした。", "target_word": "解明され", "complexity_tier": "T3", "furigana": "長年[ながねん]の疑問[ぎもん]が解明[かいめい]されて、みんなほっとした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解明", "label": "基本形"}, {"form": "解明する", "label": "サ変動詞"}, {"form": "解明され", "label": "受身形"}, {"form": "解明しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "わからなかった原因や謎をはっきりさせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36532, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解明", "is_correct": true, "explanation": "「原因の解明」で、原因をはっきりさせること。文の内容に合う。"}, {"text": "購入", "is_correct": false, "explanation": "「原因の購入」は成り立たず、文脈に合わない。"}, {"text": "出発", "is_correct": false, "explanation": "「原因の出発」は不自然で、文脈に合わない。"}, {"text": "注文", "is_correct": false, "explanation": "「原因の注文」は成り立たず、文脈に合わない。"}], "explanations": {"解明": "「原因の解明」で、原因をはっきりさせること。文の内容に合う。", "購入": "「原因の購入」は成り立たず、文脈に合わない。", "出発": "「原因の出発」は不自然で、文脈に合わない。", "注文": "「原因の注文」は成り立たず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "解明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パスワードのロックを解明した。", "explanation": "ここは〈解除〉の意味（ロックを外す）。解明は謎を明らかにすることなので、ロックには使わない。"}, {"text": "新しい薬を解明した。", "explanation": "ここは〈発見〉の意味（新しく見つける）。解明は謎を明らかにすることで、新しい薬を見つける意味では使わない。"}, {"text": "不正をした社員を解明した。", "explanation": "ここは〈解雇〉の意味（職をやめさせる）。解明は謎を明らかにすることで、人事には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36532, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解明", "is_correct": true, "explanation": "「解明が進む」で、明らかにする作業が進むこと。文の内容に合う。"}, {"text": "宿泊", "is_correct": false, "explanation": "「宿泊が進む」とは言わず、文脈に合わない。"}, {"text": "漁獲", "is_correct": false, "explanation": "「漁獲が進む」は文脈に合わない。"}, {"text": "残業", "is_correct": false, "explanation": "「残業が進む」は文脈に合わない。"}], "explanations": {"解明": "「解明が進む」で、明らかにする作業が進むこと。文の内容に合う。", "宿泊": "「宿泊が進む」とは言わず、文脈に合わない。", "漁獲": "「漁獲が進む」は文脈に合わない。", "残業": "「残業が進む」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "解明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地震の警報を解明した。", "explanation": "ここは〈解除〉の意味（警報を止める）。解明は謎を明らかにする意味で、警報には使わない。"}, {"text": "医師が遺体を解明した。", "explanation": "ここは〈解剖〉の意味（体を切り開いて調べる）。〈解明〉とは言わず、混同している。"}, {"text": "長く捕らわれていた人を解明した。", "explanation": "ここは〈解放〉の意味（自由にする）。解明は謎を明らかにすることで、人を自由にする意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36532, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察は、事件の解明に急ぐ方針を決めた。", "corrected_sentence": "警察は、事件の解明を急ぐ方針を決めた。", "error_description": "「急ぐ」は対象を〈を〉で取る。〈解明に〉は誤りで、〈解明を〉が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36532, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者が仕組みを解明しれば、対策を立てやすい。", "corrected_sentence": "研究者が仕組みを解明すれば、対策を立てやすい。", "error_description": "サ変動詞〈解明する〉の仮定形は〈解明すれば〉。〈解明しれば〉は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36533, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「原因を解明した」で、解明の対象を示す〈を〉。"}, {"text": "に", "is_correct": false, "explanation": "「原因に解明した」は成り立たず、対象を示せない。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示す。「原因が解明した」は主語が変わり意味が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す。「原因へ解明した」は不自然で文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「原因を解明した」で、解明の対象を示す〈を〉。", "に": "「原因に解明した」は成り立たず、対象を示せない。", "が": "〈が〉は主語を示す。「原因が解明した」は主語が変わり意味が合わない。", "へ": "〈へ〉は方向を示す。「原因へ解明した」は不自然で文が成り立たない。"}, "error_tags": {"に": "位置", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36533, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「解明に関する」で、関係する対象を示す〈に〉。"}, {"text": "を", "is_correct": false, "explanation": "「解明を関する」は成り立たず、〈関する〉には〈に〉を使う。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示す。「解明が関する」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す。「解明へ関する」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「解明に関する」で、関係する対象を示す〈に〉。", "を": "「解明を関する」は成り立たず、〈関する〉には〈に〉を使う。", "が": "〈が〉は主語を示す。「解明が関する」は成り立たない。", "へ": "〈へ〉は方向を示す。「解明へ関する」は成り立たない。"}, "error_tags": {"を": "目的格", "が": "主語", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36533, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "不明なことや複雑なことを、調査や研究によって明らかにすること。", "primary_collocate": null, "pronunciation": "かいめい", "ipa": "kaimeː", "syllable_count": 4, "sentences": [{"text": "本研究は、遺伝子の働きの解明を目的としている。", "target_word": "解明", "complexity_tier": "T3", "furigana": "本研究[ほんけんきゅう]は、遺伝子[いでんし]の働[はたら]きの解明[かいめい]を目的[もくてき]としている。", "sentence_source": "generated"}, {"text": "調査委員会は、火災の原因を解明した。", "target_word": "解明した", "complexity_tier": "T3", "furigana": "調査委員会[ちょうさいいんかい]は、火災[かさい]の原因[げんいん]を解明[かいめい]した。", "sentence_source": "generated"}, {"text": "古代文明の滅亡の解明には、さらなる発掘が必要だ。", "target_word": "解明", "complexity_tier": "T3", "furigana": "古代文明[こだいぶんめい]の滅亡[めつぼう]の解明[かいめい]には、さらなる発掘[はっくつ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "データの分析によって、感染経路の解明が進んだ。", "target_word": "解明", "complexity_tier": "T3", "furigana": "データの分析[ぶんせき]によって、感染経路[かんせんけいろ]の解明[かいめい]が進[すす]んだ。", "sentence_source": "generated"}, {"text": "複雑な気候変動のしくみを解明する試みが続く。", "target_word": "解明する", "complexity_tier": "T3", "furigana": "複雑[ふくざつ]な気候変動[きこうへんどう]のしくみを解明[かいめい]する試[こころ]みが続[つづ]く。", "sentence_source": "generated"}, {"text": "事故の真相の解明を求める声が高まっている。", "target_word": "解明", "complexity_tier": "T3", "furigana": "事故[じこ]の真相[しんそう]の解明[かいめい]を求[もと]める声[こえ]が高[たか]まっている。", "sentence_source": "generated"}, {"text": "新しい装置の導入で、物質の構造が解明された。", "target_word": "解明され", "complexity_tier": "T3", "furigana": "新[あたら]しい装置[そうち]の導入[どうにゅう]で、物質[ぶっしつ]の構造[こうぞう]が解明[かいめい]された。", "sentence_source": "generated"}, {"text": "学会では、脳の働きの解明に関する発表が相次いだ。", "target_word": "解明", "complexity_tier": "T3", "furigana": "学会[がっかい]では、脳[のう]の働[はたら]きの解明[かいめい]に関[かん]する発表[はっぴょう]が相次[あいつ]いだ。", "sentence_source": "generated"}, {"text": "彼女の論文は、方言の成り立ちを解明した点で評価された。", "target_word": "解明した", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の論文[ろんぶん]は、方言[ほうげん]の成[な]り立[た]ちを解明[かいめい]した点[てん]で評価[ひょうか]された。", "sentence_source": "generated"}, {"text": "研究費が不足し、病原体の解明は途中で止まった。", "target_word": "解明", "complexity_tier": "T3", "furigana": "研究費[けんきゅうひ]が不足[ふそく]し、病原体[びょうげんたい]の解明[かいめい]は途中[とちゅう]で止[と]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解明", "label": "基本形"}, {"form": "解明する", "label": "サ変動詞"}, {"form": "解明され", "label": "受身形"}, {"form": "解明した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "不明・複雑な事柄を調査や研究で明らかにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58ee37e6-610e-4bcb-85cb-1483a5e28c76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36533, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解明", "is_correct": true, "explanation": "「働きの解明を目的とする」で、仕組みを明らかにすること。文の内容に合う。"}, {"text": "購入", "is_correct": false, "explanation": "「働きの購入」は成り立たず、文脈に合わない。"}, {"text": "出版", "is_correct": false, "explanation": "「働きの出版」は成り立たず、文脈に合わない。"}, {"text": "解約", "is_correct": false, "explanation": "「働きの解約」は成り立たず、文脈に合わない。"}], "explanations": {"解明": "「働きの解明を目的とする」で、仕組みを明らかにすること。文の内容に合う。", "購入": "「働きの購入」は成り立たず、文脈に合わない。", "出版": "「働きの出版」は成り立たず、文脈に合わない。", "解約": "「働きの解約」は成り立たず、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "解明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "契約を解明した。", "explanation": "ここは〈解約〉の意味（契約を終わらせる）。解明とは言わず、混同している。"}, {"text": "そのチームを解明した。", "explanation": "ここは〈解散〉の意味（集団を終わらせる）。解明は謎を明らかにすることで、集団の終了には使わない。"}, {"text": "捕虜を解明した。", "explanation": "ここは〈解放〉の意味（自由にする）。解明は謎を明らかにすることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36533, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解明され", "is_correct": true, "explanation": "「構造が解明され（た）」で、受身の形。文の中で〈た〉に続き、文が成り立つ。"}, {"text": "解明する", "is_correct": false, "explanation": "「構造が解明する」は不自然で、〈た〉に続けても文が成り立たない。"}, {"text": "解明し", "is_correct": false, "explanation": "〈解明し〉＋〈た〉は「構造が解明した」となるが、構造は解明する主体にならず、主語と態が合わないので不自然。"}, {"text": "解明さ", "is_correct": false, "explanation": "〈解明さ〉は受身の未然形で、〈た〉に続けても「解明さた」となり成り立たない。"}], "explanations": {"解明され": "「構造が解明され（た）」で、受身の形。文の中で〈た〉に続き、文が成り立つ。", "解明する": "「構造が解明する」は不自然で、〈た〉に続けても文が成り立たない。", "解明し": "〈解明し〉＋〈た〉は「構造が解明した」となるが、構造は解明する主体にならず、主語と態が合わないので不自然。", "解明さ": "〈解明さ〉は受身の未然形で、〈た〉に続けても「解明さた」となり成り立たない。"}, "sentence_index": 6, "correct_answer": "解明され"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "実験で、カエルを解明した。", "explanation": "ここは〈解剖〉の意味（体を切り開いて調べる）。解明とは言わず、混同している。"}, {"text": "禁止されていた商品の販売を解明した。", "explanation": "ここは〈解禁〉の意味（禁止を解く）。解明は謎を明らかにすることで、禁止を解く意味ではない。"}, {"text": "交通規制を解明した。", "explanation": "ここは〈解除〉の意味（規制をやめる）。解明は謎を明らかにすることで、規制の終了には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66890038-3bf1-4c3d-b617-68ef5ca27123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
