INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36534, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「守る」の目的語を示す格助詞で、生物に直接かかる。"}, {"text": "と", "is_correct": false, "explanation": "「生物と」では守る対象が一つにならず、目的語が欠けて文が成り立たないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「守る」の対象を示す格にはならず、文の意味が通らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す格で、生物は守る手段ではないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「守る」の目的語を示す格助詞で、生物に直接かかる。", "と": "「生物と」では守る対象が一つにならず、目的語が欠けて文が成り立たないので合わない。", "に": "「守る」の対象を示す格にはならず、文の意味が通らないので合わない。", "で": "手段や場所を示す格で、生物は守る手段ではないので合わない。"}, "error_tags": {"と": "共同の格", "に": "対象の格", "で": "手段の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36534, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生きているもののこと。", "primary_collocate": null, "pronunciation": "せいぶつ", "ipa": "seːbɯtsɯ", "syllable_count": 4, "sentences": [{"text": "海には、たくさんの生物がすんでいます。", "target_word": "生物", "complexity_tier": "T3", "furigana": "海(うみ)には、たくさんの生物(せいぶつ)がすんでいます。", "sentence_source": "generated"}, {"text": "生物は水がないと生きられません。", "target_word": "生物", "complexity_tier": "T3", "furigana": "生物(せいぶつ)は水(みず)がないと生(い)きられません。", "sentence_source": "generated"}, {"text": "この池には珍しい生物が見られる。", "target_word": "生物", "complexity_tier": "T3", "furigana": "この池(いけ)には珍(めずら)しい生物(せいぶつ)が見(み)られる。", "sentence_source": "generated"}, {"text": "生物によって、体のしくみはさまざまだ。", "target_word": "生物", "complexity_tier": "T3", "furigana": "生物（せいぶつ）によって、体（からだ）のしくみはさまざまだ。", "sentence_source": "generated"}, {"text": "深い海にも、光を出す生物がいます。", "target_word": "生物", "complexity_tier": "T3", "furigana": "深(ふか)い海(うみ)にも、光(ひかり)を出(だ)す生物(せいぶつ)がいます。", "sentence_source": "generated"}, {"text": "月には生物がいないと考えられています。", "target_word": "生物", "complexity_tier": "T3", "furigana": "月(つき)には生物(せいぶつ)がいないと考(かんが)えられています。", "sentence_source": "generated"}, {"text": "川の水がよごれて、小さな生物が減ってしまった。", "target_word": "生物", "complexity_tier": "T3", "furigana": "川(かわ)の水(みず)がよごれて、小(ちい)さな生物(せいぶつ)が減(へ)ってしまった。", "sentence_source": "generated"}, {"text": "生物を守るために、この森では木を切ってはいけません。", "target_word": "生物", "complexity_tier": "T3", "furigana": "生物(せいぶつ)を守(まも)るために、この森(もり)では木(き)を切(き)ってはいけません。", "sentence_source": "generated"}, {"text": "私は生物の中で、特に昆虫が好きです。", "target_word": "生物", "complexity_tier": "T3", "furigana": "私(わたし)は生物(せいぶつ)の中(なか)で、特(とく)に昆虫(こんちゅう)が好(す)きです。", "sentence_source": "generated"}, {"text": "地球にはさまざまな生物がくらしている。", "target_word": "生物", "complexity_tier": "T3", "furigana": "地球(ちきゅう)にはさまざまな生物(せいぶつ)がくらしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生物", "label": "基本形"}], "register": "中立（標準的な書き言葉・話し言葉）", "sense_fingerprint": "動物・植物など、生きているものの総称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: よごれ (Zipf 2.32)']::text[], 'c807979d-24e5-4686-b553-a0ab630f3395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36534, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生物", "is_correct": true, "explanation": "海にすむ生き物の総称で、「すんでいます」の主語として自然に入る。"}, {"text": "生活", "is_correct": false, "explanation": "暮らし方の意味で、海の中にいる生き物を指さないので合わない。"}, {"text": "文化", "is_correct": false, "explanation": "人間社会の営みを指す語で、海にすむものの主語にはならない。"}, {"text": "建物", "is_correct": false, "explanation": "人が造った建造物で、海にすむものではないので合わない。"}], "explanations": {"生物": "海にすむ生き物の総称で、「すんでいます」の主語として自然に入る。", "生活": "暮らし方の意味で、海の中にいる生き物を指さないので合わない。", "文化": "人間社会の営みを指す語で、海にすむものの主語にはならない。", "建物": "人が造った建造物で、海にすむものではないので合わない。"}, "sentence_index": 0, "correct_answer": "生物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は生物にあふれ、いつもはつらつとしている。", "explanation": "ここは〈生命力〉の意味。生物は生き物そのものを指し、活力の程度には使わないので合わない。"}, {"text": "学校で生物の試験があったので、昨日は遅くまで勉強した。", "explanation": "ここは〈生物学〉の意味。科目名として使う言葉で、生きているもの自体を指す生物とは別の意味なので合わない。"}, {"text": "彼は事故で生物を落とした。", "explanation": "ここは〈生命〉の意味。「命を落とす」は死ぬことで、生物はこの言い方に入らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36534, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生物", "is_correct": true, "explanation": "水中や陸上に生きる生き物の総称で、「減ってしまった」の主語として自然に入る。"}, {"text": "水質", "is_correct": false, "explanation": "水の性質を表す語で、生き物が減るという文の主語にはならない。"}, {"text": "環境", "is_correct": false, "explanation": "まわりの状況を指す語で、数が減る対象としては合わない。"}, {"text": "地形", "is_correct": false, "explanation": "土地の形を指す語で、小さなものが減るという文には合わない。"}], "explanations": {"生物": "水中や陸上に生きる生き物の総称で、「減ってしまった」の主語として自然に入る。", "水質": "水の性質を表す語で、生き物が減るという文の主語にはならない。", "環境": "まわりの状況を指す語で、数が減る対象としては合わない。", "地形": "土地の形を指す語で、小さなものが減るという文には合わない。"}, "sentence_index": 6, "correct_answer": "生物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工場では、生物を毎日点検して、故障を防いでいる。", "explanation": "ここは〈機械〉の意味。点検するのは機械で、生きているもの（生物）は機械の代わりにならないので合わない。"}, {"text": "新しい生物を建てて、家族で住み始めた。", "explanation": "ここは〈建物〉の意味。建てるのは建物で、生物は建てることができない。"}, {"text": "彼は長い生物を、きれいな字で書き上げた。", "explanation": "ここは〈文章〉の意味。書き上げるのは文章や文字で、生物は書けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36534, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池の中には、小さな生物をたくさんいる。", "corrected_sentence": "池の中には、小さな生物がたくさんいる。", "error_description": "助詞の誤り。「いる」の主語を示す「が」を使うべきところを「を」にしている。正しくは「小さな生物が」で、生物を主語にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36534, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森の木を切ると、多くの生物をすむ場所がなくなる。", "corrected_sentence": "森の木を切ると、多くの生物がすむ場所がなくなる。", "error_description": "助詞の誤り。「すむ」の主語を示す「が」が正しく、「を」は他動詞に使うので誤り。正しくは「生物がすむ場所」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36536, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「神経が脳に知らせる」。知らせる主体は「が」で示す。"}, {"text": "の", "is_correct": false, "explanation": "「神経の脳に知らせる」は所属を示すだけで、動詞の主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「神経へ脳に知らせる」は方向を示すが、主語の位置には使えない。"}, {"text": "に", "is_correct": false, "explanation": "「神経に脳に知らせる」は位置を示す形で、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「神経が脳に知らせる」。知らせる主体は「が」で示す。", "の": "「神経の脳に知らせる」は所属を示すだけで、動詞の主語にならない。", "へ": "「神経へ脳に知らせる」は方向を示すが、主語の位置には使えない。", "に": "「神経に脳に知らせる」は位置を示す形で、主語を示せない。"}, "error_tags": {"の": "所属の誤り", "へ": "方向の誤り", "に": "位置の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36536, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「神経が押されて」。押される主語は「が」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「神経を押されて」は受け身の主語を「を」で示せず、誤り。"}, {"text": "に", "is_correct": false, "explanation": "「神経に押されて」は、人以外の物を動作主にする形として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「神経で押されて」は手段の意味になり、受け身の動作主にならない。"}], "correct_answer": "が", "explanations": {"が": "「神経が押されて」。押される主語は「が」で示す。", "を": "「神経を押されて」は受け身の主語を「を」で示せず、誤り。", "に": "「神経に押されて」は、人以外の物を動作主にする形として不自然。", "で": "「神経で押されて」は手段の意味になり、受け身の動作主にならない。"}, "error_tags": {"を": "対象の誤り", "に": "動作主の誤り", "で": "手段の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36536, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体の中にあって、いろいろなところに知らせを伝えるもの。", "primary_collocate": null, "pronunciation": "しんけい", "ipa": "ɕiŋkeː", "syllable_count": 4, "sentences": [{"text": "神経は、体のあちこちに知らせを送っている。", "target_word": "神経", "complexity_tier": "T3", "furigana": "神経[しんけい]は、体[からだ]のあちこちに知[し]らせを送[おく]っている。", "sentence_source": "generated"}, {"text": "熱いものに触ると、神経が脳に知らせるので、すぐ手を引く。", "target_word": "神経", "complexity_tier": "T3", "furigana": "熱[あつ]いものに触[さわ]ると、神経[しんけい]が脳[のう]に知[し]らせるので、すぐ手[て]を引[ひ]く。", "sentence_source": "generated"}, {"text": "足の神経を痛めて、病院で治療を受けている。", "target_word": "神経", "complexity_tier": "T3", "furigana": "足[あし]の神経[しんけい]を痛[いた]めて、病院[びょういん]で治療[ちりょう]を受[う]けている。", "sentence_source": "generated"}, {"text": "歯が痛いのは、虫歯が中の神経まで届いたからだ。", "target_word": "神経", "complexity_tier": "T3", "furigana": "歯[は]が痛[いた]いのは、虫歯[むしば]が中[なか]の神経[しんけい]まで届[とど]いたからだ。", "sentence_source": "generated"}, {"text": "神経がきちんと働くから、私たちは体を動かせる。", "target_word": "神経", "complexity_tier": "T3", "furigana": "神経[しんけい]がきちんと働[はたら]くから、私[わたし]たちは体[からだ]を動[うご]かせる。", "sentence_source": "generated"}, {"text": "先生は、体の神経の絵をかいて見せてくれた。", "target_word": "神経", "complexity_tier": "T3", "furigana": "先生[せんせい]は、体[からだ]の神経[しんけい]の絵[え]をかいて見[み]せてくれた。", "sentence_source": "generated"}, {"text": "指の神経が切れて、触っても何も感じない。", "target_word": "神経", "complexity_tier": "T3", "furigana": "指[ゆび]の神経[しんけい]が切[き]れて、触[さわ]っても何[なに]も感[かん]じない。", "sentence_source": "generated"}, {"text": "医者は、首の神経が押されて腕がしびれると言った。", "target_word": "神経", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、首[くび]の神経[しんけい]が押[お]されて腕[うで]がしびれると言[い]った。", "sentence_source": "generated"}, {"text": "理科の授業で、神経が信号を伝える仕組みを習った。", "target_word": "神経", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、神経[しんけい]が信号[しんごう]を伝[つた]える仕組[しく]みを習[なら]った。", "sentence_source": "generated"}, {"text": "神経のおかげで、冷たさや痛みを感じることができる。", "target_word": "神経", "complexity_tier": "T3", "furigana": "神経[しんけい]のおかげで、冷[つめ]たさや痛[いた]みを感[かん]じることができる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "神経", "label": "基本形"}], "register": "ふつう", "sense_fingerprint": "体の中にあって、痛みや冷たさなどの知らせを脳へ、脳の命令を体へ伝える糸のようなもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d2050e-73d4-41bb-b305-1aad375477d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36536, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神経", "is_correct": true, "explanation": "体のあちこちに知らせを送るものを指す主語として合う。"}, {"text": "体温", "is_correct": false, "explanation": "体温は知らせを送るものではなく、主語として文に合わない。"}, {"text": "呼吸", "is_correct": false, "explanation": "呼吸は知らせを送るものではなく、文の主語に合わない。"}, {"text": "血圧", "is_correct": false, "explanation": "血圧は知らせを送る主体ではなく、文の意味に合わない。"}], "explanations": {"神経": "体のあちこちに知らせを送るものを指す主語として合う。", "体温": "体温は知らせを送るものではなく、主語として文に合わない。", "呼吸": "呼吸は知らせを送るものではなく、文の主語に合わない。", "血圧": "血圧は知らせを送る主体ではなく、文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "神経"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試験の前は神経がどきどき速く打って、眠れなかった。", "explanation": "ここは〈脈〉の話。速く打つのは脈で、神経は打たない。"}, {"text": "けがで腕の神経から血が出た。", "explanation": "ここは〈血管〉の意味。血が流れるのは血管で、神経からは血は出ない。"}, {"text": "試験の準備で神経が凝って、くたくたになった。", "explanation": "ここは〈筋肉〉の話。凝るのは筋肉で、神経は凝らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36536, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神経", "is_correct": true, "explanation": "指の神経を指し、切れて感覚を失う主語として合う。"}, {"text": "血液", "is_correct": false, "explanation": "血液は切れて感覚を失うものとは言わない。"}, {"text": "脈拍", "is_correct": false, "explanation": "脈拍は指の部位ではなく、切れるものでもない。"}, {"text": "関節", "is_correct": false, "explanation": "関節は切れる対象ではなく、感覚の話にも合わない。"}], "explanations": {"神経": "指の神経を指し、切れて感覚を失う主語として合う。", "血液": "血液は切れて感覚を失うものとは言わない。", "脈拍": "脈拍は指の部位ではなく、切れるものでもない。", "関節": "関節は切れる対象ではなく、感覚の話にも合わない。"}, "sentence_index": 6, "correct_answer": "神経"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "神経のおかげで、体のすみずみに酸素が届く。", "explanation": "ここは〈血液〉の意味。酸素を運ぶのは血液で、神経は知らせを伝えるものなので合わない。"}, {"text": "かすかな物音に、神経が耳を傾けた。", "explanation": "ここは〈耳〉の話。耳を傾けるのは人で、神経は聞けない。"}, {"text": "寒い日は神経がひび割れて、手の甲が荒れやすい。", "explanation": "ここは〈皮膚〉の話。ひび割れて荒れるのは皮膚で、神経はひび割れない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36536, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "足の神経に痛んで、歩くとしびれが出る。", "corrected_sentence": "足の神経が痛んで、歩くとしびれが出る。", "error_description": "「痛む」は自動詞なので主語は「が」で示す。「に」は誤りで、正しくは「神経が痛む」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36536, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "指の神経を切れて、感覚がなくなった。", "corrected_sentence": "指の神経が切れて、感覚がなくなった。", "error_description": "「切れる」は自動詞なので主語は「が」で示す。「を」は誤りで、正しくは「神経が切れる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36537, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「神経を傷つける」。傷つける対象は「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「神経に傷つけ」は対象を示す形として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「神経が傷つけ」は主語にも対象にもならず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「神経で傷つけ」は手段の意味になり、文の意味に合わない。"}], "correct_answer": "を", "explanations": {"を": "「神経を傷つける」。傷つける対象は「を」で示す。", "に": "「神経に傷つけ」は対象を示す形として成り立たない。", "が": "「神経が傷つけ」は主語にも対象にもならず不自然。", "で": "「神経で傷つけ」は手段の意味になり、文の意味に合わない。"}, "error_tags": {"に": "対象の誤り", "が": "主語の誤り", "で": "手段の誤り"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36537, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「神経を通る」。通過する対象は「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「神経に通って」は通る場所を示す形として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「神経で通って」は手段の意味になり、経路を表さない。"}, {"text": "へ", "is_correct": false, "explanation": "「神経へ通って」は方向を示すが、通過の動詞には使わない。"}], "correct_answer": "を", "explanations": {"を": "「神経を通る」。通過する対象は「を」で示す。", "に": "「神経に通って」は通る場所を示す形として不自然。", "で": "「神経で通って」は手段の意味になり、経路を表さない。", "へ": "「神経へ通って」は方向を示すが、通過の動詞には使わない。"}, "error_tags": {"に": "到達点の誤り", "で": "手段の誤り", "へ": "方向の誤り"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36537, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "脳や脊髄から体中に情報を伝える、細い繊維の束。", "primary_collocate": null, "pronunciation": "しんけい", "ipa": "ɕiŋkeː", "syllable_count": 4, "sentences": [{"text": "首の神経が傷つくと、腕に力が入らなくなることがある。", "target_word": "神経", "complexity_tier": "T3", "furigana": "首[くび]の神経[しんけい]が傷[きず]つくと、腕[うで]に力[ちから]が入[はい]らなくなることがある。", "sentence_source": "generated"}, {"text": "転んで腕の神経を傷つけ、指が動かなくなった。", "target_word": "神経", "complexity_tier": "T3", "furigana": "転[ころ]んで腕[うで]の神経[しんけい]を傷[きず]つけ、指[ゆび]が動[うご]かなくなった。", "sentence_source": "generated"}, {"text": "神経は、脳からの命令を筋肉に伝える大切な通り道だ。", "target_word": "神経", "complexity_tier": "T3", "furigana": "神経[しんけい]は、脳[のう]からの命令[めいれい]を筋肉[きんにく]に伝[つた]える大切[たいせつ]な通[とお]り道[みち]だ。", "sentence_source": "generated"}, {"text": "脊髄から分かれた神経は、筋肉へ運動の指令を伝える。", "target_word": "神経", "complexity_tier": "T3", "furigana": "脊髄[せきずい]から分[わ]かれた神経[しんけい]は、筋肉[きんにく]へ運動[うんどう]の指令[しれい]を伝[つた]える。", "sentence_source": "generated"}, {"text": "事故のあと、足の神経がまひして歩けなくなった。", "target_word": "神経", "complexity_tier": "T3", "furigana": "事故[じこ]のあと、足[あし]の神経[しんけい]がまひして歩[ある]けなくなった。", "sentence_source": "generated"}, {"text": "医者は、背中の痛みが神経の圧迫によるものだと説明した。", "target_word": "神経", "complexity_tier": "T3", "furigana": "医者[いしゃ]は、背中[せなか]の痛[いた]みが神経[しんけい]の圧迫[あっぱく]によるものだと説明[せつめい]した。", "sentence_source": "generated"}, {"text": "手術では、顔の神経を傷つけないように慎重に進めた。", "target_word": "神経", "complexity_tier": "T3", "furigana": "手術[しゅじゅつ]では、顔[かお]の神経[しんけい]を傷[きず]つけないように慎重[しんちょう]に進[すす]めた。", "sentence_source": "generated"}, {"text": "目で見た光の情報は、神経を通って脳に届く。", "target_word": "神経", "complexity_tier": "T3", "furigana": "目[め]で見[み]た光[ひかり]の情報[じょうほう]は、神経[しんけい]を通[とお]って脳[のう]に届[とど]く。", "sentence_source": "generated"}, {"text": "神経が切れると、触られても何も感じなくなることがある。", "target_word": "神経", "complexity_tier": "T3", "furigana": "神経[しんけい]が切[き]れると、触[さわ]られても何[なに]も感[かん]じなくなることがある。", "sentence_source": "generated"}, {"text": "寒い所に長くいたせいで、指先の神経が鈍ってしまった。", "target_word": "神経", "complexity_tier": "T3", "furigana": "寒[さむ]い所[ところ]に長[なが]くいたせいで、指先[ゆびさき]の神経[しんけい]が鈍[にぶ]ってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "神経", "label": "基本形"}], "register": "専門的", "sense_fingerprint": "脳や脊髄と体の各部をつなぎ、感覚や命令の情報を伝える体内の繊維の束。解剖学・医学でいう神経", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d2050e-73d4-41bb-b305-1aad375477d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36537, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神経", "is_correct": true, "explanation": "首の神経が傷つくと腕の動きに影響するので、神経が主語として合う。"}, {"text": "体温", "is_correct": false, "explanation": "体温は傷つく部位ではなく、腕に力が入らない話とも結びつかない。"}, {"text": "呼吸", "is_correct": false, "explanation": "呼吸は傷つく部位ではなく、腕の力とは関係しない。"}, {"text": "脈拍", "is_correct": false, "explanation": "脈拍は傷つくものではなく、腕の力が入らなくなる文脈に合わない。"}], "explanations": {"神経": "首の神経が傷つくと腕の動きに影響するので、神経が主語として合う。", "体温": "体温は傷つく部位ではなく、腕に力が入らない話とも結びつかない。", "呼吸": "呼吸は傷つく部位ではなく、腕の力とは関係しない。", "脈拍": "脈拍は傷つくものではなく、腕の力が入らなくなる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "神経"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い所に長くいたので、指先の神経がかさついた。", "explanation": "ここは〈皮膚〉の話。かさつくのは皮膚で、神経はかさつかない。"}, {"text": "走ったあと、神経が速く打って息が切れた。", "explanation": "ここは〈脈〉の話。速く打つのは脈で、神経は打たない。"}, {"text": "心臓から送り出された血液は、神経を通って全身に酸素を運ぶ。", "explanation": "ここは〈血管〉の意味。血液や酸素を運ぶのは血管で、神経は情報を伝える組織なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36537, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神経", "is_correct": true, "explanation": "顔の神経を指し、傷つけないよう注意する対象として合う。"}, {"text": "血液", "is_correct": false, "explanation": "血液は傷つけないよう注意する対象にはならない。"}, {"text": "予算", "is_correct": false, "explanation": "予算は体の部位ではなく、顔の対象として傷つけることはできないので文に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は体の部位ではなく、顔の対象として傷つけることはできないので文に合わない。"}], "explanations": {"神経": "顔の神経を指し、傷つけないよう注意する対象として合う。", "血液": "血液は傷つけないよう注意する対象にはならない。", "予算": "予算は体の部位ではなく、顔の対象として傷つけることはできないので文に合わない。", "天気": "天気は体の部位ではなく、顔の対象として傷つけることはできないので文に合わない。"}, "sentence_index": 6, "correct_answer": "神経"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い所に長くいたせいで、指先の神経がこわばってしまった。", "explanation": "ここは〈筋肉〉の話。こわばるのは筋肉で、神経は鈍るもの。"}, {"text": "寒さのせいで、指先の脳が鈍ってしまった。", "explanation": "ここは〈脳〉の話。指先の感覚は神経が伝えるもので、脳が鈍るとは言わない。"}, {"text": "寒さのせいで、指先の神経がまったく分からなくなった。", "explanation": "ここは〈感覚〉の意味。感覚は分かる・なくなるが、神経が分からなくなるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36537, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "転んで腕の神経に痛め、指が動かなくなった。", "corrected_sentence": "転んで腕の神経を痛め、指が動かなくなった。", "error_description": "「痛める」は直接の対象を「を」で示す。「神経に痛め」は誤りで、正しくは「神経を痛め」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df8d83f0-94d6-4ae3-8529-fef4fb327a1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
