INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36538, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「夢中だ」の対象を示す格助詞で、研究に直接かかる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す格で、「夢中だ」の対象にはならないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格だが、「夢中だ」とは結びつかないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す格で、「夢中だ」の対象にはならないので合わない。"}], "correct_answer": "に", "explanations": {"に": "「夢中だ」の対象を示す格助詞で、研究に直接かかる。", "が": "主語を示す格で、「夢中だ」の対象にはならないので合わない。", "を": "目的語を示す格だが、「夢中だ」とは結びつかないので合わない。", "で": "場所や手段を示す格で、「夢中だ」の対象にはならないので合わない。"}, "error_tags": {"が": "主語の格", "を": "目的語の格", "で": "場所・手段の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
