INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36538, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を詳しく調べて、新しいことを見つけることです。", "primary_collocate": null, "pronunciation": "けんきゅう", "ipa": "keɴkʲɯː", "syllable_count": 4, "sentences": [{"text": "夏休みに、町の歴史について研究しました。", "target_word": "研究", "complexity_tier": "T3", "furigana": "夏休(なつやす)みに、町(まち)の歴史(れきし)について研究(けんきゅう)しました。", "sentence_source": "generated"}, {"text": "弟は昆虫の研究に夢中だ。", "target_word": "研究", "complexity_tier": "T3", "furigana": "弟(おとうと)は昆虫(こんちゅう)の研究(けんきゅう)に夢中(むちゅう)だ。", "sentence_source": "generated"}, {"text": "私の趣味は、おいしいパンの作り方を研究することです。", "target_word": "研究", "complexity_tier": "T3", "furigana": "私(わたし)の趣味(しゅみ)は、おいしいパンの作(つく)り方(かた)を研究(けんきゅう)することです。", "sentence_source": "generated"}, {"text": "研究を続けて、新しい方法を見つけた。", "target_word": "研究", "complexity_tier": "T3", "furigana": "研究(けんきゅう)を続(つづ)けて、新(あたら)しい方法(ほうほう)を見(み)つけた。", "sentence_source": "generated"}, {"text": "兄は大学で言葉の研究をしている。", "target_word": "研究", "complexity_tier": "T3", "furigana": "兄(あに)は大学(だいがく)で言葉(ことば)の研究(けんきゅう)をしている。", "sentence_source": "generated"}, {"text": "先生は、昔の地図の研究で有名だ。", "target_word": "研究", "complexity_tier": "T3", "furigana": "先生(せんせい)は、昔(むかし)の地図(ちず)の研究(けんきゅう)で有名(ゆうめい)だ。", "sentence_source": "generated"}, {"text": "研究のために、毎日図書館に通っています。", "target_word": "研究", "complexity_tier": "T3", "furigana": "研究(けんきゅう)のために、毎日(まいにち)図書館(としょかん)に通(かよ)っています。", "sentence_source": "generated"}, {"text": "この町の祭りは、研究する価値がある。", "target_word": "研究", "complexity_tier": "T3", "furigana": "この町(まち)の祭(まつ)りは、研究(けんきゅう)する価値(かち)がある。", "sentence_source": "generated"}, {"text": "研究が進んで、いろいろなことが分かってきた。", "target_word": "研究", "complexity_tier": "T3", "furigana": "研究(けんきゅう)が進(すす)んで、いろいろなことが分(わ)かってきた。", "sentence_source": "generated"}, {"text": "彼女は猫の行動を研究して、本を書いた。", "target_word": "研究", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は猫(ねこ)の行動(こうどう)を研究(けんきゅう)して、本(ほん)を書(か)いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "研究", "label": "基本形"}, {"form": "研究する", "label": "する動詞の形"}], "register": "中立（標準的な書き言葉・話し言葉）", "sense_fingerprint": "身近な物事を詳しく調べ、新しい発見をすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c807979d-24e5-4686-b553-a0ab630f3395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36538, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究", "is_correct": true, "explanation": "物事を詳しく調べる意味で、「町の歴史について〜しました」に入る。"}, {"text": "散歩", "is_correct": false, "explanation": "気晴らしに歩くことで、歴史について行うものではないので合わない。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作ることで、歴史について行う行為ではないので合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "汚れを取り除くことで、歴史について行う行為ではないので合わない。"}], "explanations": {"研究": "物事を詳しく調べる意味で、「町の歴史について〜しました」に入る。", "散歩": "気晴らしに歩くことで、歴史について行うものではないので合わない。", "料理": "食べ物を作ることで、歴史について行う行為ではないので合わない。", "掃除": "汚れを取り除くことで、歴史について行う行為ではないので合わない。"}, "sentence_index": 0, "correct_answer": "研究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新入社員は三日間の研究を受けた。", "explanation": "ここは〈研修〉の意味。研修は受けるものだが、研究は受けるものではないので合わない。"}, {"text": "研究で一等が当たった。", "explanation": "ここは〈抽選〉の意味。当たるのは抽選や賞で、研究は当たらないので合わない。"}, {"text": "旅行先で研究を撮った。", "explanation": "ここは〈写真〉の意味。撮るのは写真などで、研究は撮れないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36538, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究", "is_correct": true, "explanation": "調べて新しい発見をする意味で、「〜のために図書館に通う」の理由として入る。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗うことで、図書館に通う理由にはならないので合わない。"}, {"text": "買い物", "is_correct": false, "explanation": "物を買うことで、図書館に通う理由としては合わない。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠ることで、図書館に通う理由としては合わない。"}], "explanations": {"研究": "調べて新しい発見をする意味で、「〜のために図書館に通う」の理由として入る。", "洗濯": "衣類を洗うことで、図書館に通う理由にはならないので合わない。", "買い物": "物を買うことで、図書館に通う理由としては合わない。", "睡眠": "眠ることで、図書館に通う理由としては合わない。"}, "sentence_index": 6, "correct_answer": "研究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室で使う研究を買った。", "explanation": "ここは〈教材〉の意味。買えるのは教材などの物で、研究は買えないので合わない。"}, {"text": "決勝戦では、研究に勝った。", "explanation": "ここは〈試合〉の意味。勝つのは試合の相手で、研究は勝負の相手にならないので合わない。"}, {"text": "彼女は美しい研究を描いた。", "explanation": "ここは〈絵〉の意味。描くのは絵で、研究は描けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36538, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は古い地図の研究で一生をささげた。", "corrected_sentence": "彼女は古い地図の研究に一生をささげた。", "error_description": "助詞の誤り。「ささげる」は「〜に」で対象を示すため、「研究で」の「で」は誤り。正しくは「研究に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36538, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大学では、昆虫の研究で力を入れている。", "corrected_sentence": "大学では、昆虫の研究に力を入れている。", "error_description": "助詞の誤り。「力を入れる」は「〜に」で対象を示すため、「研究で」の「で」は誤り。正しくは「研究に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36539, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "理由を示す「で」で、「研究によって賞を受けた」の意味に合う。"}, {"text": "に", "is_correct": false, "explanation": "対象を示す格で、「研究に賞を受けた」では意味が通らないので合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す格で、「受けた」の目的語が二つになり文が成り立たないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す格で、賞を受けた理由を表せないので合わない。"}], "correct_answer": "で", "explanations": {"で": "理由を示す「で」で、「研究によって賞を受けた」の意味に合う。", "に": "対象を示す格で、「研究に賞を受けた」では意味が通らないので合わない。", "を": "目的語を示す格で、「受けた」の目的語が二つになり文が成り立たないので合わない。", "へ": "方向を示す格で、賞を受けた理由を表せないので合わない。"}, "error_tags": {"に": "格が合わない", "を": "目的語の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
