INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36539, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あるテーマについて、理論や実験などを使って深く調べ、新しい知識を得ようとする活動。", "primary_collocate": null, "pronunciation": "けんきゅう", "ipa": "keɴkʲɯː", "syllable_count": 4, "sentences": [{"text": "新しい薬の研究には、長い時間と多くの実験が必要だ。", "target_word": "研究", "complexity_tier": "T3", "furigana": "新(あたら)しい薬(くすり)の研究(けんきゅう)には、長(なが)い時間(じかん)と多(おお)くの実験(じっけん)が必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "彼は理論と実験を組み合わせた研究で賞を受けた。", "target_word": "研究", "complexity_tier": "T3", "furigana": "彼(かれ)は理論(りろん)と実験(じっけん)を組(く)み合(あ)わせた研究(けんきゅう)で賞(しょう)を受(う)けた。", "sentence_source": "generated"}, {"text": "地震の研究が進み、予測の精度が上がった。", "target_word": "研究", "complexity_tier": "T3", "furigana": "地震(じしん)の研究(けんきゅう)が進(すす)み、予測(よそく)の精度(せいど)が上(あ)がった。", "sentence_source": "generated"}, {"text": "研究の結果は、来月の学会で発表される。", "target_word": "研究", "complexity_tier": "T3", "furigana": "研究(けんきゅう)の結果(けっか)は、来月(らいげつ)の学会(がっかい)で発表(はっぴょう)される。", "sentence_source": "generated"}, {"text": "太陽の光をエネルギーに変える研究が注目されている。", "target_word": "研究", "complexity_tier": "T3", "furigana": "太陽(たいよう)の光(ひかり)をエネルギーに変(か)える研究(けんきゅう)が注目(ちゅうもく)されている。", "sentence_source": "generated"}, {"text": "失敗が続いても、研究を続けることで新しい発見が生まれる。", "target_word": "研究", "complexity_tier": "T3", "furigana": "失敗(しっぱい)が続(つづ)いても、研究(けんきゅう)を続(つづ)けることで新(あたら)しい発見(はっけん)が生(う)まれる。", "sentence_source": "generated"}, {"text": "彼女は宇宙の起源についての研究に一生をささげた。", "target_word": "研究", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は宇宙(うちゅう)の起源(きげん)についての研究(けんきゅう)に一生(いっしょう)をささげた。", "sentence_source": "generated"}, {"text": "この研究は国から資金を受けて行われている。", "target_word": "研究", "complexity_tier": "T3", "furigana": "この研究(けんきゅう)は国(くに)から資金(しきん)を受(う)けて行(おこな)われている。", "sentence_source": "generated"}, {"text": "実験データを分析して、研究の仮説を確かめた。", "target_word": "研究", "complexity_tier": "T3", "furigana": "実験(じっけん)データを分析(ぶんせき)して、研究(けんきゅう)の仮説(かせつ)を確(たし)かめた。", "sentence_source": "generated"}, {"text": "科学者たちは、病気の原因を明らかにする研究に取り組んでいる。", "target_word": "研究", "complexity_tier": "T3", "furigana": "科学者(かがくしゃ)たちは、病気(びょうき)の原因(げんいん)を明(あき)らかにする研究(けんきゅう)に取(と)り組(く)んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "研究", "label": "基本形"}, {"form": "研究する", "label": "する動詞の形"}], "register": "やや硬い（学術的な書き言葉）", "sense_fingerprint": "理論や実験を用いて行う学術的・科学的な調査活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c807979d-24e5-4686-b553-a0ab630f3395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36539, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究", "is_correct": true, "explanation": "理論や実験を使って深く調べる意味で、「必要だ」の主語になる。"}, {"text": "運動", "is_correct": false, "explanation": "体を動かすことで、薬を新しく作る過程の主語にはならないので合わない。"}, {"text": "旅行", "is_correct": false, "explanation": "遠くへ出かけることで、薬の開発には当てはまらないので合わない。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作ることで、薬の研究の主語にはならないので合わない。"}], "explanations": {"研究": "理論や実験を使って深く調べる意味で、「必要だ」の主語になる。", "運動": "体を動かすことで、薬を新しく作る過程の主語にはならないので合わない。", "旅行": "遠くへ出かけることで、薬の開発には当てはまらないので合わない。", "料理": "食べ物を作ることで、薬の研究の主語にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "研究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週、難しい研究を受ける予定だ。", "explanation": "ここは〈試験〉の意味。試験は受けるものだが、研究は受けるものではないので合わない。"}, {"text": "夏休みに、研究に登って景色を楽しんだ。", "explanation": "ここは〈登山〉の意味。登るのは山や階段で、研究には使わないので合わない。"}, {"text": "レストランで研究を注文した。", "explanation": "ここは〈料理〉の意味。注文するのは料理などで、研究は注文できないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36539, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究", "is_correct": true, "explanation": "深く調べる活動の意味で、「一生をささげた」の対象として入る。"}, {"text": "恋愛", "is_correct": false, "explanation": "人を好きになることで、宇宙の起源を対象にするものではないので合わない。"}, {"text": "睡眠", "is_correct": false, "explanation": "眠ることで、一生をささげる対象にはならないので合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "汚れを取ることで、宇宙の起源についての対象にはならないので合わない。"}], "explanations": {"研究": "深く調べる活動の意味で、「一生をささげた」の対象として入る。", "恋愛": "人を好きになることで、宇宙の起源を対象にするものではないので合わない。", "睡眠": "眠ることで、一生をささげる対象にはならないので合わない。", "掃除": "汚れを取ることで、宇宙の起源についての対象にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "研究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝る前に、研究を敷いた。", "explanation": "ここは〈布団〉の意味。敷くのは布団などの寝具で、研究は敷けないので合わない。"}, {"text": "彼女は指に研究をはめた。", "explanation": "ここは〈指輪〉の意味。はめるのは指輪などの装身具で、研究はできないので合わない。"}, {"text": "駅で研究を買った。", "explanation": "ここは〈切符〉の意味。買うのは切符などの物で、研究は買えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36539, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は三年間、この薬の研究を打ち込んだ。", "corrected_sentence": "彼は三年間、この薬の研究に打ち込んだ。", "error_description": "助詞の誤り。「打ち込む」は「〜に」で対象を示すため、「研究を」の「を」は誤り。正しくは「研究に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36539, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大学院では、細胞の研究で力を入れている。", "corrected_sentence": "大学院では、細胞の研究に力を入れている。", "error_description": "助詞の誤り。「力を入れる」は「〜に」で対象を示すため、「研究で」の「で」は誤り。正しくは「研究に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
