INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36540, 3, 'prompt1_core', '{"pos": "接頭辞", "semantic_class": "function", "definition": "「幾」は、「いくつか」や「どれくらい」という意味で、数がはっきりしないときに使う言葉です。", "primary_collocate": null, "pronunciation": "いく", "ipa": "ikɯ", "syllable_count": 2, "sentences": [{"text": "森の中で、幾人かの子どもが遊んでいた。", "target_word": "幾", "complexity_tier": "T3", "furigana": "森(もり)の中(なか)で、幾人(いくにん)かの子(こ)どもが遊(あそ)んでいた。", "sentence_source": "generated"}, {"text": "机の上には、幾冊かの本が置いてある。", "target_word": "幾", "complexity_tier": "T3", "furigana": "机(つくえ)の上(うえ)には、幾冊(いくさつ)かの本(ほん)が置(お)いてある。", "sentence_source": "generated"}, {"text": "この荷物は、届くまで幾日かかりますか。", "target_word": "幾", "complexity_tier": "T3", "furigana": "この荷物(にもつ)は、届(とど)くまで幾日(いくにち)かかりますか。", "sentence_source": "generated"}, {"text": "今日の会議には幾人来るか、まだ分からない。", "target_word": "幾", "complexity_tier": "T3", "furigana": "今日(きょう)の会議(かいぎ)には幾人(いくにん)来(く)るか、まだ分(わ)からない。", "sentence_source": "generated"}, {"text": "池に幾羽かの白鳥がいた。", "target_word": "幾", "complexity_tier": "T3", "furigana": "池(いけ)に幾羽(いくわ)かの白鳥(はくちょう)がいた。", "sentence_source": "generated"}, {"text": "幾人もの客が、店の前に並んでいる。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾人(いくにん)もの客(きゃく)が、店(みせ)の前(まえ)に並(なら)んでいる。", "sentence_source": "generated"}, {"text": "病気で、幾晩も眠れなかった。", "target_word": "幾", "complexity_tier": "T3", "furigana": "病気(びょうき)で、幾晩(いくばん)も眠(ねむ)れなかった。", "sentence_source": "generated"}, {"text": "幾日か休めば、風邪はなおるでしょう。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾日(いくにち)か休(やす)めば、風邪(かぜ)はなおるでしょう。", "sentence_source": "generated"}, {"text": "幾台かの車が、道のはしにとまっている。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾台(いくだい)かの車(くるま)が、道(みち)のはしにとまっている。", "sentence_source": "generated"}, {"text": "幾枚か写真をとって、母に送った。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾枚(いくまい)か写真(しゃしん)をとって、母(はは)に送(おく)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幾", "label": "基本形"}], "register": "中立（やや改まった書き言葉）", "sense_fingerprint": "数詞や助数詞の前につき、「いくつか」「どれくらい」と不定の数を表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c807979d-24e5-4686-b553-a0ab630f3395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36540, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幾", "is_correct": true, "explanation": "「いくつか」の意味の接頭辞で、「幾人かの」の形で不定の数を表す。"}, {"text": "大", "is_correct": false, "explanation": "「大人」は成人の意味で、数量を表す「かの」の形にはならないので合わない。"}, {"text": "小", "is_correct": false, "explanation": "大きさを表す接頭辞で、「〜人かの」の形で数を表すことはないので合わない。"}, {"text": "新", "is_correct": false, "explanation": "新しさを表す接頭辞で、人数を不定に表す用法はないので合わない。"}], "explanations": {"幾": "「いくつか」の意味の接頭辞で、「幾人かの」の形で不定の数を表す。", "大": "「大人」は成人の意味で、数量を表す「かの」の形にはならないので合わない。", "小": "大きさを表す接頭辞で、「〜人かの」の形で数を表すことはないので合わない。", "新": "新しさを表す接頭辞で、人数を不定に表す用法はないので合わない。"}, "sentence_index": 0, "correct_answer": "幾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "数学の授業で、幾何学の証明を習った。", "explanation": "ここは〈幾何学〉の意味。図形の性質を研究する学問の名前で、「いくつか」の意味の幾とは別の語なので合わない。"}, {"text": "幾重にも重なった雲が、夕焼けで赤く染まった。", "explanation": "ここは〈幾重〉（何枚も重なる）の意味。重なりの多さを表す別の語で、数がはっきりしない「いくつか」の幾とは意味が合わない。"}, {"text": "彼女は幾分疲れた様子で、早めに休んだ。", "explanation": "ここは〈幾分〉（少しは）の意味。程度を表す別の語で、数がはっきりしないものを数える幾とは意味が違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36540, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幾", "is_correct": true, "explanation": "「いくつか」の意味の接頭辞で、「幾晩も」の形で期間の多さを表す。"}, {"text": "元", "is_correct": false, "explanation": "もとの状態を表す語で、「元晩」という形では期間を表さないので合わない。"}, {"text": "初", "is_correct": false, "explanation": "初めての意味で、「初晩も」では多さを表せないので合わない。"}, {"text": "真", "is_correct": false, "explanation": "まことの意味の接頭辞で、「真晩も」では期間の多さを表さないので合わない。"}], "explanations": {"幾": "「いくつか」の意味の接頭辞で、「幾晩も」の形で期間の多さを表す。", "元": "もとの状態を表す語で、「元晩」という形では期間を表さないので合わない。", "初": "初めての意味で、「初晩も」では多さを表せないので合わない。", "真": "まことの意味の接頭辞で、「真晩も」では期間の多さを表さないので合わない。"}, "sentence_index": 6, "correct_answer": "幾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "幾何の問題を、夜遅くまで解いた。", "explanation": "ここは〈幾何〉（図形を扱う学問）の意味。学問の名前で、いくつかの数量を表す幾とは別の意味なので合わない。"}, {"text": "幾多の困難を乗り越えて、彼は成功した。", "explanation": "ここは〈幾多〉（数多くの）の意味。数の多さを表す別の語で、数がはっきりしないことを表す幾の「いくつか」とは違うので合わない。"}, {"text": "幾度も練習して、ようやく成功した。", "explanation": "ここは〈幾度〉（何度も）の意味。回数を表す別の語で、物の数を表す幾の「いくつか」とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36540, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日は幾か人の客が来た。", "corrected_sentence": "昨日は幾人かの客が来た。", "error_description": "語順の誤り。「幾人か」は「幾」＋助数詞＋「か」の順だが、「幾か人」は並びが逆で成り立たない。正しくは「幾人かの」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36540, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公園に幾人の子どもがいた。", "corrected_sentence": "公園に幾人かの子どもがいた。", "error_description": "語形の誤り。「いくつか」の意味で使うには「か」が必要。「幾人」だけでは数を尋ねる形になるため、正しくは「幾人かの」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36541, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
