INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36541, 3, 'prompt1_core', '{"pos": "接頭辞", "semantic_class": "function", "definition": "「幾」は、数量や程度が不確定であることを表す語で、「いくつかの」「どれほどの」という意味を持ちます。", "primary_collocate": null, "pronunciation": "いく", "ipa": "ikɯ", "syllable_count": 2, "sentences": [{"text": "幾千もの星が、夜空にかがやいている。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾千(いくせん)もの星(ほし)が、夜空(よぞら)にかがやいている。", "sentence_source": "generated"}, {"text": "彼は幾度も失敗して、それでもあきらめなかった。", "target_word": "幾", "complexity_tier": "T3", "furigana": "彼(かれ)は幾度(いくど)も失敗(しっぱい)して、それでもあきらめなかった。", "sentence_source": "generated"}, {"text": "幾万という人々が、広場に集まった。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾万(いくまん)という人々(ひとびと)が、広場(ひろば)に集(あつ)まった。", "sentence_source": "generated"}, {"text": "この橋は、幾百年ものあいだ人々の往来を支えてきた。", "target_word": "幾百", "complexity_tier": "T3", "furigana": "この橋(はし)は、幾百年(いくひゃくねん)ものあいだ人々(ひとびと)の往来(おうらい)を支(ささ)えてきた。", "sentence_source": "generated"}, {"text": "幾千の兵士が、その山をこえたと言われる。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾千(いくせん)の兵士(へいし)が、その山(やま)をこえたと言(い)われる。", "sentence_source": "generated"}, {"text": "幾重にも重なる山々が、遠くまで続いている。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾重(いくえ)にも重(かさ)なる山々(やまやま)が、遠(とお)くまで続(つづ)いている。", "sentence_source": "generated"}, {"text": "幾たびの冬をこえて、桜の木は大きくなった。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾(いく)たびの冬(ふゆ)をこえて、桜(さくら)の木(き)は大(おお)きくなった。", "sentence_source": "generated"}, {"text": "母は私のために、幾夜も眠らずに看病してくれた。", "target_word": "幾", "complexity_tier": "T3", "furigana": "母(はは)は私(わたし)のために、幾夜(いくよ)も眠(ねむ)らずに看病(かんびょう)してくれた。", "sentence_source": "generated"}, {"text": "幾多の困難をのりこえて、彼は成功した。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾多(いくた)の困難(こんなん)をのりこえて、彼(かれ)は成功(せいこう)した。", "sentence_source": "generated"}, {"text": "幾百もの鳥が、空をいっせいに飛び立った。", "target_word": "幾", "complexity_tier": "T3", "furigana": "幾百(いくひゃく)もの鳥(とり)が、空(そら)をいっせいに飛(と)び立(た)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幾", "label": "基本形"}], "register": "文語的（改まった書き言葉）", "sense_fingerprint": "数や回数の多さ・程度の大きさを、はっきり示さずに表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c807979d-24e5-4686-b553-a0ab630f3395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36541, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幾", "is_correct": true, "explanation": "「幾千もの」の「幾」。数がはっきりしない多さを表す接頭辞で、この空欄に入る。"}, {"text": "全", "is_correct": false, "explanation": "「全」は「すべての」の意味。「全千もの星」は数の多さを表せず、意味が通らない。"}, {"text": "最", "is_correct": false, "explanation": "「最」は「いちばん」の意味。「最千もの星」とは言わない。"}, {"text": "第", "is_correct": false, "explanation": "「第」は順序を表す接頭辞。「第千もの星」は成り立たない。"}], "explanations": {"幾": "「幾千もの」の「幾」。数がはっきりしない多さを表す接頭辞で、この空欄に入る。", "全": "「全」は「すべての」の意味。「全千もの星」は数の多さを表せず、意味が通らない。", "最": "「最」は「いちばん」の意味。「最千もの星」とは言わない。", "第": "「第」は順序を表す接頭辞。「第千もの星」は成り立たない。"}, "sentence_index": 0, "correct_answer": "幾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レシートには幾千円と、ちょうど三千円が印字されていた。", "explanation": "ここは「幾」の意味（数がはっきりしない）と合わない。「ちょうど三千円」のような正確な金額には「幾」を使わない。"}, {"text": "試験は幾問、きっかり十問出題された。", "explanation": "「幾」は数が不確定なことを表す。「きっかり十問」と数を確定させる文では、この語は使えない。"}, {"text": "大会は幾度、ちょうど三回だけ開かれた。", "explanation": "「幾度」は「何度も」の意味で回数の多さを表す。「ちょうど三回だけ」と回数を限定する文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36541, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幾", "is_correct": true, "explanation": "「幾たびの冬」の「幾」。回数の多さを、はっきり数えずに表す接頭辞。"}, {"text": "各", "is_correct": false, "explanation": "「各」は「それぞれの」の意味で、回数の多さを表さない。「各たびの冬」とは言わない。"}, {"text": "真", "is_correct": false, "explanation": "「真」は「本当の」などの意味の接頭辞で、「真たびの冬」は意味が通らない。"}, {"text": "副", "is_correct": false, "explanation": "「副」は「補助の」などの意味で、回数の多さには使わない。"}], "explanations": {"幾": "「幾たびの冬」の「幾」。回数の多さを、はっきり数えずに表す接頭辞。", "各": "「各」は「それぞれの」の意味で、回数の多さを表さない。「各たびの冬」とは言わない。", "真": "「真」は「本当の」などの意味の接頭辞で、「真たびの冬」は意味が通らない。", "副": "「副」は「補助の」などの意味で、回数の多さには使わない。"}, "sentence_index": 6, "correct_answer": "幾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ケーキは幾切れ、ちょうど八切れに切り分けられた。", "explanation": "ここは「幾」の意味（数がはっきりしない）と合わない。「ちょうど八切れ」と数を決める文には使えない。"}, {"text": "試験の日程は幾日、正確に十日間と決まっていた。", "explanation": "「幾日」は日数が不確定な表現。「正確に十日間」と確定させる文では、この語は合わない。"}, {"text": "この缶詰は幾本、ちょうど六本入りだ。", "explanation": "「幾」は多さがはっきりしないことを示す。「ちょうど六本入り」と数を固定する文には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36541, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "幾度に挑戦して、彼はついに合格した。", "corrected_sentence": "幾度も挑戦して、彼はついに合格した。", "error_description": "「幾度」には「も」を付けて「何度も」の意味にする。「に」は不自然で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36541, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幾夜に待ち続けて、彼女はついに戻った。", "corrected_sentence": "幾夜も待ち続けて、彼女はついに戻った。", "error_description": "「幾夜」には「も」を付けて「何夜も」の意味にする。「に」は不自然で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36542, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「説を唱えました」と目的語を示し、唱える対象として文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「説が唱えました」だと説が主語になり、「唱える」の対象にならないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「説で唱えました」は手段にならず、「唱える」の対象として不自然。"}, {"text": "の", "is_correct": false, "explanation": "「説の唱えました」は名詞と動詞が続かず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「説を唱えました」と目的語を示し、唱える対象として文が成り立つ。", "が": "「説が唱えました」だと説が主語になり、「唱える」の対象にならないので合わない。", "で": "「説で唱えました」は手段にならず、「唱える」の対象として不自然。", "の": "「説の唱えました」は名詞と動詞が続かず、文が成り立たない。"}, "error_tags": {"が": "主語", "で": "手段", "の": "修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36542, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36542, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることについて、人々が考える考え。", "primary_collocate": null, "pronunciation": "せつ", "ipa": "setsɯ", "syllable_count": 2, "sentences": [{"text": "恐竜は大きな隕石で滅びたという説が、いちばん有力です。", "target_word": "説", "complexity_tier": "T3", "furigana": "恐竜[きょうりゅう]は大[おお]きな隕石[いんせき]で滅[ほろ]びたという説[せつ]が、いちばん有力[ゆうりょく]です。", "sentence_source": "generated"}, {"text": "その学者は、月は地球の一部だったという説を唱えました。", "target_word": "説", "complexity_tier": "T3", "furigana": "その学者[がくしゃ]は、月[つき]は地球[ちきゅう]の一部[いちぶ]だったという説[せつ]を唱[とな]えました。", "sentence_source": "generated"}, {"text": "この説は、新しい調査の結果によって、正しいと分かりました。", "target_word": "説", "complexity_tier": "T3", "furigana": "この説[せつ]は、新[あたら]しい調査[ちょうさ]の結果[けっか]によって、正[ただ]しいと分[わ]かりました。", "sentence_source": "generated"}, {"text": "先生の説によると、昔の人は星を見て季節を知っていたそうです。", "target_word": "説", "complexity_tier": "T3", "furigana": "先生[せんせい]の説[せつ]によると、昔[むかし]の人[ひと]は星[ほし]を見[み]て季節[きせつ]を知[し]っていたそうです。", "sentence_source": "generated"}, {"text": "説は一つではなく、研究者の間でも意見が分かれています。", "target_word": "説", "complexity_tier": "T3", "furigana": "説[せつ]は一[ひと]つではなく、研究者[けんきゅうしゃ]の間[あいだ]でも意見[いけん]が分[わ]かれています。", "sentence_source": "generated"}, {"text": "私は、この町の名前は川から来たという説を信じています。", "target_word": "説", "complexity_tier": "T3", "furigana": "私[わたし]は、この町[まち]の名前[なまえ]は川[かわ]から来[き]たという説[せつ]を信[しん]じています。", "sentence_source": "generated"}, {"text": "古い説は、新しい証拠が出ると、だんだん支持されなくなりました。", "target_word": "説", "complexity_tier": "T3", "furigana": "古[ふる]い説[せつ]は、新[あたら]しい証拠[しょうこ]が出[で]ると、だんだん支持[しじ]されなくなりました。", "sentence_source": "generated"}, {"text": "その説には、まだ証拠が足りないので、多くの人が疑っています。", "target_word": "説", "complexity_tier": "T3", "furigana": "その説[せつ]には、まだ証拠[しょうこ]が足[た]りないので、多[おお]くの人[ひと]が疑[うたが]っています。", "sentence_source": "generated"}, {"text": "地球の未来について、友達は自分の説を述べました。", "target_word": "説", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の未来[みらい]について、友達[ともだち]は自分[じぶん]の説[せつ]を述[の]べました。", "sentence_source": "generated"}, {"text": "彼女は有名な説に反対して、新しい説を発表しました。", "target_word": "説", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は有名[ゆうめい]な説[せつ]に反対[はんたい]して、新[あたら]しい説[せつ]を発表[はっぴょう]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "説", "label": "基本形"}, {"form": "説を", "label": "を格"}, {"form": "説は", "label": "は提題"}], "register": "neutral", "sense_fingerprint": "説(せつ): ある事柄について学者や人々が唱える考え・主張(学説・言い伝えなど。説明の意味ではない)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ac41b1-bf6a-4b52-9986-43adaca85130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36542, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "説", "is_correct": true, "explanation": "正解。「という説が、いちばん有力」と続き、ある事柄についての考えを表す。"}, {"text": "価格", "is_correct": false, "explanation": "価格は値段を表し、「という価格が有力」とは言えないので文が成り立たない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は芸術の一種で、「という音楽が有力」とは言えないので合わない。"}, {"text": "疲労", "is_correct": false, "explanation": "疲労は体や心の状態を表し、考えの有力さを述べる文には入らない。"}], "explanations": {"説": "正解。「という説が、いちばん有力」と続き、ある事柄についての考えを表す。", "価格": "価格は値段を表し、「という価格が有力」とは言えないので文が成り立たない。", "音楽": "音楽は芸術の一種で、「という音楽が有力」とは言えないので合わない。", "疲労": "疲労は体や心の状態を表し、考えの有力さを述べる文には入らない。"}, "sentence_index": 0, "correct_answer": "説"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上の説を片付けました。", "explanation": "ここは〈書類〉の意味。説は考えや主張で、片付けられる物ではないので合わない。"}, {"text": "説が治るまで、ゆっくり休みます。", "explanation": "ここは〈病気〉の意味。説は考えのことで、治る対象にはならないので合わない。"}, {"text": "スープの説が薄いので、塩を足しました。", "explanation": "ここは〈味〉の意味。説は考えや主張で、味のように薄くなるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36542, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "説", "is_correct": true, "explanation": "正解。「古い説は、新しい証拠が出ると支持されなくなった」と続き、考えを主語にできる。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建物の部分で、証拠の出方によって支持されなくなる対象にはならない。"}, {"text": "犬", "is_correct": false, "explanation": "犬は動物で、支持されなくなるという文の主語としては成り立たない。"}, {"text": "靴", "is_correct": false, "explanation": "靴は身につける物で、支持される・されないという文の主語にはならないので合わない。"}], "explanations": {"説": "正解。「古い説は、新しい証拠が出ると支持されなくなった」と続き、考えを主語にできる。", "窓": "窓は建物の部分で、証拠の出方によって支持されなくなる対象にはならない。", "犬": "犬は動物で、支持されなくなるという文の主語としては成り立たない。", "靴": "靴は身につける物で、支持される・されないという文の主語にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "説"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "旅行の前に、説で道を確認しました。", "explanation": "ここは〈地図〉の意味。説は考えや主張で、道を確かめる道具にはならないので合わない。"}, {"text": "鳴っている説を、すぐに取りました。", "explanation": "ここは〈電話〉の意味。説は考えのことで、鳴っている物を取って応対する対象にはならないので合わない。"}, {"text": "庭の説に水をやりました。", "explanation": "ここは〈花〉の意味。説は考えや主張で、水をやって育てる対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36542, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この説に証明するために、実験を繰り返しました。", "corrected_sentence": "この説を証明するために、実験を繰り返しました。", "error_description": "正しくは「説を証明する」。「証明する」は目的語に「を」を取るので、「説に」では合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36542, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多くの学者が、その説が支持しています。", "corrected_sentence": "多くの学者が、その説を支持しています。", "error_description": "正しくは「その説を支持しています」。「支持する」は対象に「を」を取るので、「説が」では支持する対象として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c21758-8fdb-43ec-9247-fa4a2941cf7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36543, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「説を確かめる」で、確かめる対象として説を「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、確かめるは対象を取るので、説が主語では文が成り立たない"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すが、確かめる対象ではない"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、確かめる対象にはならない"}], "correct_answer": "を", "explanations": {"を": "正解。「説を確かめる」で、確かめる対象として説を「を」で示す。", "が": "主語を示すが、確かめるは対象を取るので、説が主語では文が成り立たない", "に": "相手や場所を示すが、確かめる対象ではない", "へ": "方向を示すが、確かめる対象にはならない"}, "error_tags": {"が": "主語を示すが、確かめるは対象を取るので、説が主語では文が成り立たない", "に": "相手や場所を示すが、確かめる対象ではない", "へ": "方向を示すが、確かめる対象にはならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36543, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「彼女の説は」の「は」は説を主題として示し、実験の結果と合っているという述語に続く。"}, {"text": "を", "is_correct": false, "explanation": "対象を示すが、ここは説が主題になる位置なので、文の組み立てが合わない"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、合う相手として文法的でない"}, {"text": "の", "is_correct": false, "explanation": "連体修飾だが、彼女の説の直後に続けると文が成り立たない"}], "correct_answer": "は", "explanations": {"は": "正解。「彼女の説は」の「は」は説を主題として示し、実験の結果と合っているという述語に続く。", "を": "対象を示すが、ここは説が主題になる位置なので、文の組み立てが合わない", "へ": "方向を示すが、合う相手として文法的でない", "の": "連体修飾だが、彼女の説の直後に続けると文が成り立たない"}, "error_tags": {"を": "対象を示すが、ここは説が主題になる位置なので、文の組み立てが合わない", "の": "連体修飾だが、彼女の説の直後に続けると文が成り立たない", "へ": "方向を示すが、合う相手として文法的でない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36543, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄について、複数の人や研究によって立てられた意見や仮説。", "primary_collocate": null, "pronunciation": "せつ", "ipa": "setsɯ", "syllable_count": 2, "sentences": [{"text": "学者たちは、恐竜は鳥に進化したという説を発表した。", "target_word": "説", "complexity_tier": "T3", "furigana": "学者[がくしゃ]たちは、恐竜[きょうりゅう]は鳥[とり]に進化[しんか]したという説[せつ]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "その説を確かめるために、実験を何度も行った。", "target_word": "説", "complexity_tier": "T3", "furigana": "その説[せつ]を確[たし]かめるために、実験[じっけん]を何度[なんど]も行[おこな]った。", "sentence_source": "generated"}, {"text": "新しい調査で、古い説が正しくないとわかった。", "target_word": "説", "complexity_tier": "T3", "furigana": "新[あたら]しい調査[ちょうさ]で、古[ふる]い説[せつ]が正[ただ]しくないとわかった。", "sentence_source": "generated"}, {"text": "この説は多くの研究者に支持されている。", "target_word": "説", "complexity_tier": "T3", "furigana": "この説[せつ]は多[おお]くの研究者[けんきゅうしゃ]に支持[しじ]されている。", "sentence_source": "generated"}, {"text": "彼の説は、まだ証拠が足りないと言われている。", "target_word": "説", "complexity_tier": "T3", "furigana": "彼[かれ]の説[せつ]は、まだ証拠[しょうこ]が足[た]りないと言[い]われている。", "sentence_source": "generated"}, {"text": "二つの説のうち、どちらが正しいかは決まっていない。", "target_word": "説", "complexity_tier": "T3", "furigana": "二[ふた]つの説[せつ]のうち、どちらが正[ただ]しいかは決[き]まっていない。", "sentence_source": "generated"}, {"text": "研究チームは、病気の原因について新しい説を立てた。", "target_word": "説", "complexity_tier": "T3", "furigana": "研究[けんきゅう]チームは、病気[びょうき]の原因[げんいん]について新[あたら]しい説[せつ]を立[た]てた。", "sentence_source": "generated"}, {"text": "彼女の説は、実験の結果とよく合っている。", "target_word": "説", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の説[せつ]は、実験[じっけん]の結果[けっか]とよく合[あ]っている。", "sentence_source": "generated"}, {"text": "その説が正しければ、星の動きも理解できる。", "target_word": "説", "complexity_tier": "T3", "furigana": "その説[せつ]が正[ただ]しければ、星[ほし]の動[うご]きも理解[りかい]できる。", "sentence_source": "generated"}, {"text": "学会では、その説をめぐって議論が続いた。", "target_word": "説", "complexity_tier": "T3", "furigana": "学会[がっかい]では、その説[せつ]をめぐって議論[ぎろん]が続[つづ]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "説", "label": "基本形"}], "register": "普通体", "sense_fingerprint": "研究者などが立てる仮説・学問上の主張", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df666cf-660e-4a65-8685-1c7e60c94a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36543, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "説", "is_correct": true, "explanation": "正解。「発表する」は学者が立てた説を公にする意味で、説と結びつく。"}, {"text": "時間", "is_correct": false, "explanation": "時間は発表する対象にならず、文が成り立たない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は発表されるものではないので合わない。"}, {"text": "味", "is_correct": false, "explanation": "味を発表するとは言えない。"}], "explanations": {"説": "正解。「発表する」は学者が立てた説を公にする意味で、説と結びつく。", "時間": "時間は発表する対象にならず、文が成り立たない。", "季節": "季節は発表されるものではないので合わない。", "味": "味を発表するとは言えない。"}, "sentence_index": 0, "correct_answer": "説"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その説は小さすぎて、足が入らなかった。", "explanation": "ここは〈靴〉の意味。説は立てられた仮説を指すので、足に履く物の代わりには使えない。"}, {"text": "その説は、今朝から降り続いている。", "explanation": "ここは〈雨〉の意味。説は仮説を指す語で、降り続く天気の代わりにはならない。"}, {"text": "この説は、朝から三時間も続いた。", "explanation": "ここは〈議論〉の意味。説は立てられた仮説を指すので、話し合いが三時間続く使い方は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36543, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "説", "is_correct": true, "explanation": "正解。「立てる」は仮説や説を組み立てる意味で、説と結びつく。"}, {"text": "天気", "is_correct": false, "explanation": "天気は仮説として立てられないので、文が成り立たない。"}, {"text": "色", "is_correct": false, "explanation": "色は仮説を立てる対象にならない。"}, {"text": "景色", "is_correct": false, "explanation": "景色は仮説の対象にならず、文が意味をなさない。"}], "explanations": {"説": "正解。「立てる」は仮説や説を組み立てる意味で、説と結びつく。", "天気": "天気は仮説として立てられないので、文が成り立たない。", "色": "色は仮説を立てる対象にならない。", "景色": "景色は仮説の対象にならず、文が意味をなさない。"}, "sentence_index": 6, "correct_answer": "説"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その説は、大きく切って皆で分けて食べた。", "explanation": "ここは〈パン〉の意味。説は仮説を指す語で、切って分けて食べるものの代わりには使えない。"}, {"text": "その説は、川の上に架かって車が渡った。", "explanation": "ここは〈橋〉の意味。説は仮説を指す語で、川に架かって車が渡る構造物の代わりにはならない。"}, {"text": "学会では、その説の味をめぐって議論が続いた。", "explanation": "ここは〈料理の味〉の意味。説は仮説を指す語で、味覚で論じるものではないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36543, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学者たちは、鳥は恐竜から進化したという説に発表した。", "corrected_sentence": "学者たちは、鳥は恐竜から進化したという説を発表した。", "error_description": "発表するは対象を「を」で取る動詞。「に」は誤りで、正しくは「説を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36543, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究チームは、病気の治療について新しい説が立てた。", "corrected_sentence": "研究チームは、病気の治療について新しい説を立てた。", "error_description": "立てるは対象を「を」で取る動詞。「が」は誤りで、正しくは「説を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36544, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「脳に届く」の「に」。栄養の到着点を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「届く」は目的語を取らず、「脳を」では文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「脳が」では脳が届く主語になり、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、到着点には「に」が必要。"}], "correct_answer": "に", "explanations": {"に": "「脳に届く」の「に」。栄養の到着点を示す格助詞。", "を": "「届く」は目的語を取らず、「脳を」では文が成り立たない。", "が": "「脳が」では脳が届く主語になり、意味が通らない。", "で": "「で」は場所や手段を示すため、到着点には「に」が必要。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36544, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「脳を守る」の「を」。守る対象を示す目的語。"}, {"text": "と", "is_correct": false, "explanation": "「脳と守る」は文が成り立たず、並列の意味にもならない。"}, {"text": "の", "is_correct": false, "explanation": "「脳の守る」は名詞修飾にならず、誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、守る対象には「を」が必要。"}], "correct_answer": "を", "explanations": {"を": "「脳を守る」の「を」。守る対象を示す目的語。", "と": "「脳と守る」は文が成り立たず、並列の意味にもならない。", "の": "「脳の守る」は名詞修飾にならず、誤り。", "へ": "「へ」は方向を示すため、守る対象には「を」が必要。"}, "error_tags": {"と": "並列・相手", "の": "連体修飾", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36544, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "頭の中にある、考えるための大事な部分です。", "primary_collocate": null, "pronunciation": "のう", "ipa": "noː", "syllable_count": 2, "sentences": [{"text": "勉強しすぎて、脳が疲れてしまいました。", "target_word": "脳", "complexity_tier": "T3", "furigana": "勉強(べんきょう)しすぎて、脳(のう)が疲(つか)れてしまいました。", "sentence_source": "generated"}, {"text": "朝ごはんを食べると、脳によい栄養が届きます。", "target_word": "脳", "complexity_tier": "T3", "furigana": "朝(あさ)ごはんを食(た)べると、脳(のう)によい栄養(えいよう)が届(とど)きます。", "sentence_source": "generated"}, {"text": "十分に眠らないと、脳はうまく働きません。", "target_word": "脳", "complexity_tier": "T3", "furigana": "十分(じゅうぶん)に眠(ねむ)らないと、脳(のう)はうまく働(はたら)きません。", "sentence_source": "generated"}, {"text": "散歩をして、脳を休ませることにした。", "target_word": "脳", "complexity_tier": "T3", "furigana": "散歩(さんぽ)をして、脳(のう)を休(やす)ませることにした。", "sentence_source": "generated"}, {"text": "運動すると、脳がすっきりする気がします。", "target_word": "脳", "complexity_tier": "T3", "furigana": "運動(うんどう)すると、脳(のう)がすっきりする気(き)がします。", "sentence_source": "generated"}, {"text": "赤ちゃんの脳は、新しいことを覚えるたびに育ちます。", "target_word": "脳", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんの脳(のう)は、新(あたら)しいことを覚(おぼ)えるたびに育(そだ)ちます。", "sentence_source": "generated"}, {"text": "難しい計算をすると、脳をたくさん使います。", "target_word": "脳", "complexity_tier": "T3", "furigana": "難(むずか)しい計算(けいさん)をすると、脳(のう)をたくさん使(つか)います。", "sentence_source": "generated"}, {"text": "脳を守るために、自転車に乗るときはヘルメットをかぶりましょう。", "target_word": "脳", "complexity_tier": "T3", "furigana": "脳(のう)を守(まも)るために、自転車(じてんしゃ)に乗(の)るときはヘルメットをかぶりましょう。", "sentence_source": "generated"}, {"text": "音楽を聞くと、脳が楽しい気持ちになると言われています。", "target_word": "脳", "complexity_tier": "T3", "furigana": "音楽(おんがく)を聞(き)くと、脳(のう)が楽(たの)しい気持(きも)ちになると言(い)われています。", "sentence_source": "generated"}, {"text": "目で見たものは、脳が考えて意味を決めています。", "target_word": "脳", "complexity_tier": "T3", "furigana": "目(め)で見(み)たものは、脳(のう)が考(かんが)えて意味(いみ)を決(き)めています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脳", "label": "基本形"}, {"form": "脳が", "label": "が格"}, {"form": "脳を", "label": "を格"}, {"form": "脳の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "のう(脳): 頭の中の、考えるための大事な部分。日常的な説明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc97b34b-9f79-4981-aac7-2a1064bb0242') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36544, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脳", "is_correct": true, "explanation": "勉強で疲れるのは頭の中の脳なので正解。"}, {"text": "雨", "is_correct": false, "explanation": "雨は勉強で疲れる主体にならず、文が成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は疲れる器官ではなく、文の意味が通らない。"}, {"text": "財布", "is_correct": false, "explanation": "財布が勉強で疲れることはなく、不自然な文になる。"}], "explanations": {"脳": "勉強で疲れるのは頭の中の脳なので正解。", "雨": "雨は勉強で疲れる主体にならず、文が成り立たない。", "窓": "窓は疲れる器官ではなく、文の意味が通らない。", "財布": "財布が勉強で疲れることはなく、不自然な文になる。"}, "sentence_index": 0, "correct_answer": "脳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "久しぶりに友人に会えて、脳がはずんだ。", "explanation": "ここは〈心〉の意味。気持ちの弾みは「心がはずむ」で表し、脳では言わない。"}, {"text": "彼は脳が固く、新しいやり方を受け入れない。", "explanation": "ここは〈頭〉の意味。「頭が固い」は頑固さを表す慣用句で、脳とは言わない。"}, {"text": "あの店は脳が肥えていて、料理の味にうるさい。", "explanation": "ここは〈目〉の意味。「目が肥えている」で審美眼を表し、脳は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36544, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脳", "is_correct": true, "explanation": "計算で使うのは頭の中の脳で、「脳を使う」が自然。"}, {"text": "空", "is_correct": false, "explanation": "空は計算で使うものではなく、文が成り立たない。"}, {"text": "波", "is_correct": false, "explanation": "波を計算で使うことはなく、不自然な文になる。"}, {"text": "天気", "is_correct": false, "explanation": "天気を使うとは言わず、文脈に合わない。"}], "explanations": {"脳": "計算で使うのは頭の中の脳で、「脳を使う」が自然。", "空": "空は計算で使うものではなく、文が成り立たない。", "波": "波を計算で使うことはなく、不自然な文になる。", "天気": "天気を使うとは言わず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "脳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は脳を発揮して、難しい課題を解決した。", "explanation": "ここは〈能力〉の意味。「能力を発揮する」と言い、脳は合わない。"}, {"text": "議論を通して、脳をさらに深めることができた。", "explanation": "ここは〈思考〉の意味。「思考を深める」と言い、脳では言わない。"}, {"text": "彼女は脳が明るく、いつも周りを笑顔にする。", "explanation": "ここは〈性格〉の意味。「性格が明るい」と言い、脳で人柄は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36544, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中まで本を読んだので、脳を疲れてしまいました。", "corrected_sentence": "夜中まで本を読んだので、脳が疲れてしまいました。", "error_description": "助詞の誤り。「疲れる」は主語に「が」を取る動詞なので「脳が」が正しく、「脳を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36544, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "長いレポートを書くと、脳をたくさん使いた。", "corrected_sentence": "長いレポートを書くと、脳をたくさん使います。", "error_description": "活用の誤り。「使う」は「使います」と活用させる必要があり、「使いた」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36545, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36545, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「脳から出る」の「から」。信号の出どころを示す起点の格助詞。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、出どころには「から」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「脳を出た」は文法上は成り立つが、信号の出どころは「から」で表すのが自然で、脳を出る信号という表現は不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点を示すため、出どころを表すには「から」が必要。"}], "correct_answer": "から", "explanations": {"から": "「脳から出る」の「から」。信号の出どころを示す起点の格助詞。", "で": "「で」は場所や手段を示すため、出どころには「から」が必要。", "を": "「脳を出た」は文法上は成り立つが、信号の出どころは「から」で表すのが自然で、脳を出る信号という表現は不自然。", "に": "「に」は到達点を示すため、出どころを表すには「から」が必要。"}, "error_tags": {"で": "手段・場所", "を": "出発点", "に": "方向・位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36545, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間や動物の頭蓋骨の中にある器官で、思考や記憶、感情などを司る。", "primary_collocate": null, "pronunciation": "のう", "ipa": "noː", "syllable_count": 2, "sentences": [{"text": "脳は、思考や記憶をつかさどる器官である。", "target_word": "脳", "complexity_tier": "T3", "furigana": "脳(のう)は、思考(しこう)や記憶(きおく)をつかさどる器官(きかん)である。", "sentence_source": "generated"}, {"text": "人間の脳は、頭蓋骨によって守られている。", "target_word": "脳", "complexity_tier": "T3", "furigana": "人間(にんげん)の脳(のう)は、頭蓋骨(ずがいこつ)によって守(まも)られている。", "sentence_source": "generated"}, {"text": "事故で脳に強い衝撃を受け、記憶を失った患者がいる。", "target_word": "脳", "complexity_tier": "T3", "furigana": "事故(じこ)で脳(のう)に強(つよ)い衝撃(しょうげき)を受(う)け、記憶(きおく)を失(うしな)った患者(かんじゃ)がいる。", "sentence_source": "generated"}, {"text": "脳の働きを調べるため、研究者は画像検査を行った。", "target_word": "脳", "complexity_tier": "T3", "furigana": "脳(のう)の働(はたら)きを調(しら)べるため、研究者(けんきゅうしゃ)は画像検査(がぞうけんさ)を行(おこな)った。", "sentence_source": "generated"}, {"text": "睡眠中も、脳は記憶を整理していると考えられている。", "target_word": "脳", "complexity_tier": "T3", "furigana": "睡眠中(すいみんちゅう)も、脳(のう)は記憶(きおく)を整理(せいり)していると考(かんが)えられている。", "sentence_source": "generated"}, {"text": "感情をつかさどる脳の部分が、研究で明らかになった。", "target_word": "脳", "complexity_tier": "T3", "furigana": "感情(かんじょう)をつかさどる脳(のう)の部分(ぶぶん)が、研究(けんきゅう)で明(あき)らかになった。", "sentence_source": "generated"}, {"text": "イルカなどの動物の脳も、人間と似た構造をもつ。", "target_word": "脳", "complexity_tier": "T3", "furigana": "イルカなどの動物(どうぶつ)の脳(のう)も、人間(にんげん)と似(に)た構造(こうぞう)をもつ。", "sentence_source": "generated"}, {"text": "脳から出た信号が神経を通って、全身の筋肉に伝わる。", "target_word": "脳", "complexity_tier": "T3", "furigana": "脳(のう)から出(で)た信号(しんごう)が神経(しんけい)を通(とお)って、全身(ぜんしん)の筋肉(きんにく)に伝(つた)わる。", "sentence_source": "generated"}, {"text": "医師はMRIで脳の断面を確認した。", "target_word": "脳", "complexity_tier": "T3", "furigana": "医師(いし)はMRIで脳(のう)の断面(だんめん)を確認(かくにん)した。", "sentence_source": "generated"}, {"text": "加齢とともに、脳の神経細胞は少しずつ減っていく。", "target_word": "脳", "complexity_tier": "T3", "furigana": "加齢(かれい)とともに、脳(のう)の神経細胞(しんけいさいぼう)は少(すこ)しずつ減(へ)っていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脳", "label": "基本形"}, {"form": "脳は", "label": "は提題"}, {"form": "脳に", "label": "に格"}, {"form": "脳の", "label": "連体形"}], "register": "formal-written", "sense_fingerprint": "のう(脳): 頭蓋骨の中にある器官。思考・記憶・感情をつかさどる。解剖学・科学的説明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc97b34b-9f79-4981-aac7-2a1064bb0242') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36545, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脳", "is_correct": true, "explanation": "思考や記憶をつかさどる器官は脳なので正解。"}, {"text": "雨", "is_correct": false, "explanation": "雨は器官ではなく、定義文が成り立たない。"}, {"text": "机", "is_correct": false, "explanation": "机は器官ではなく、思考や記憶を司らない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "眼鏡は器官ではなく、この説明に当てはまらない。"}], "explanations": {"脳": "思考や記憶をつかさどる器官は脳なので正解。", "雨": "雨は器官ではなく、定義文が成り立たない。", "机": "机は器官ではなく、思考や記憶を司らない。", "眼鏡": "眼鏡は器官ではなく、この説明に当てはまらない。"}, "sentence_index": 0, "correct_answer": "脳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重い箱を脳で持ち上げた。", "explanation": "ここは〈手〉の意味。物を持つ動作は手で行い、脳では言わない。"}, {"text": "この犬は脳が高く、芸をすぐ覚える。", "explanation": "ここは〈知能〉の意味。「知能が高い」と言い、脳の高さという言い方はしない。"}, {"text": "固いせんべいを脳でかみ砕いた。", "explanation": "ここは〈歯〉の意味。かむ動作は歯で行い、脳では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36545, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脳", "is_correct": true, "explanation": "「動物の脳」が文の主語で、人間の脳と似た構造を持つという内容に合う。"}, {"text": "夢", "is_correct": false, "explanation": "夢は構造をもつ器官ではなく、文が成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は構造をもつものではなく、文脈に合わない。"}, {"text": "波", "is_correct": false, "explanation": "波は動物の器官ではなく、文の意味が通らない。"}], "explanations": {"脳": "「動物の脳」が文の主語で、人間の脳と似た構造を持つという内容に合う。", "夢": "夢は構造をもつ器官ではなく、文が成り立たない。", "天気": "天気は構造をもつものではなく、文脈に合わない。", "波": "波は動物の器官ではなく、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "脳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は脳が立つので、現場で頼りにされている。", "explanation": "ここは〈腕〉の意味。「腕が立つ」は技量の高さを表し、脳では言わない。"}, {"text": "彼女は脳が細かく、相手の気持ちを察する。", "explanation": "ここは〈神経〉の意味。「神経が細かい」は繊細さを表し、脳では言わない。"}, {"text": "遠くの声を聞こうと、脳をすました。", "explanation": "ここは〈耳〉の意味。「耳をすます」で聞き耳を立てることを表し、脳は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36545, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その研究では、脳を働きを詳しく調べた。", "corrected_sentence": "その研究では、脳の働きを詳しく調べた。", "error_description": "助詞の誤り。「脳の働き」の所有を示す「の」が正しく、「脳を働き」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36545, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "強いストレスは、脳を傷つけことがある。", "corrected_sentence": "強いストレスは、脳を傷つけることがある。", "error_description": "接続の誤り。動詞を名詞化する「〜こと」の前は辞書形「傷つける」が必要で、「傷つけこと」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36548, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上げる", "is_correct": true, "explanation": "「下げる」の対義語。低くする動作と反対に、高くする動きを表す。"}, {"text": "近づける", "is_correct": false, "explanation": "位置を寄せる意味で、低くする動作の反対語ではない。"}, {"text": "置く", "is_correct": false, "explanation": "場所に据える意味で、「下げる」の反対語ではない。"}, {"text": "撮る", "is_correct": false, "explanation": "写真を撮る意味で、位置の上下とは関係がない。"}], "correct_answer": "上げる", "explanations": {"上げる": "「下げる」の対義語。低くする動作と反対に、高くする動きを表す。", "近づける": "位置を寄せる意味で、低くする動作の反対語ではない。", "置く": "場所に据える意味で、「下げる」の反対語ではない。", "撮る": "写真を撮る意味で、位置の上下とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36548, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上げる", "is_correct": true, "explanation": "「下げる」の対義語。低くする動作と反対に、高くする動きを表す。"}, {"text": "寄せる", "is_correct": false, "explanation": "近くに移動させる意味で、上下の反対語ではない。"}, {"text": "合わせる", "is_correct": false, "explanation": "高さを揃える意味で、「下げる」の反対語ではない。"}, {"text": "話す", "is_correct": false, "explanation": "言葉を発する意味で、位置の上下とは関係がない。"}], "correct_answer": "上げる", "explanations": {"上げる": "「下げる」の対義語。低くする動作と反対に、高くする動きを表す。", "寄せる": "近くに移動させる意味で、上下の反対語ではない。", "合わせる": "高さを揃える意味で、「下げる」の反対語ではない。", "話す": "言葉を発する意味で、位置の上下とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36548, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを低くする。", "primary_collocate": null, "pronunciation": "さげる", "ipa": "saɡeɾɯ", "syllable_count": 3, "sentences": [{"text": "天井の照明が高すぎたので、少し下げました。", "target_word": "下げました", "complexity_tier": "T3", "furigana": "天井(てんじょう)の照明(しょうめい)が高(たか)すぎたので、少(すこ)し下(さ)げました。", "sentence_source": "generated"}, {"text": "授業が終わったので、上げていた手を下げた。", "target_word": "下げた", "complexity_tier": "T3", "furigana": "授業(じゅぎょう)が終(お)わったので、上(あ)げていた手(て)を下(さ)げた。", "sentence_source": "generated"}, {"text": "見せ終わったので、高く掲げたトロフィーをゆっくり下げた。", "target_word": "下げた", "complexity_tier": "T3", "furigana": "見(み)せ終(お)わったので、高(たか)く掲(かか)げたトロフィーをゆっくり下(さ)げた。", "sentence_source": "generated"}, {"text": "低い花を撮るため、カメラを下げて地面に近づけた。", "target_word": "下げて", "complexity_tier": "T3", "furigana": "低(ひく)い花(はな)を撮(と)るため、カメラを下(さ)げて地面(じめん)に近(ちか)づけた。", "sentence_source": "generated"}, {"text": "肩の力を抜いて、腕をゆっくり下げてください。", "target_word": "下げて", "complexity_tier": "T3", "furigana": "肩(かた)の力(ちから)を抜(ぬ)いて、腕(うで)をゆっくり下(さ)げてください。", "sentence_source": "generated"}, {"text": "写真を撮るとき、目線を下げて犬と同じ高さにした。", "target_word": "下げて", "complexity_tier": "T3", "furigana": "写真(しゃしん)を撮(と)るとき、目線(めせん)を下(さ)げて犬(いぬ)と同(おな)じ高(たか)さにした。", "sentence_source": "generated"}, {"text": "悲しい知らせを聞いて、旗を半分まで下げた。", "target_word": "下げた", "complexity_tier": "T3", "furigana": "悲(かな)しい知(し)らせを聞(き)いて、旗(はた)を半分(はんぶん)まで下(さ)げた。", "sentence_source": "generated"}, {"text": "後ろの人が見えるように、掲げていた看板を下げた。", "target_word": "下げた", "complexity_tier": "T3", "furigana": "後(うし)ろの人(ひと)が見(み)えるように、掲(かか)げていた看板(かんばん)を下(さ)げた。", "sentence_source": "generated"}, {"text": "釣り竿の先を水面まで下げて、魚を待った。", "target_word": "下げて", "complexity_tier": "T3", "furigana": "釣(つ)り竿(ざお)の先(さき)を水面(すいめん)まで下(さ)げて、魚(さかな)を待(ま)った。", "sentence_source": "generated"}, {"text": "マイクが高すぎたので、口の高さまで下げて話しました。", "target_word": "下げて", "complexity_tier": "T3", "furigana": "マイクが高(たか)すぎたので、口(くち)の高(たか)さまで下(さ)げて話(はな)しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下げる", "label": "辞書形"}, {"form": "下げます", "label": "丁寧形"}, {"form": "下げた", "label": "タ形"}, {"form": "下げて", "label": "テ形"}, {"form": "下げない", "label": "ナイ形"}, {"form": "下げれば", "label": "仮定形"}, {"form": "下げられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "さげる(下げる): 頭・手・旗・カメラなど、具体的なものを低い位置へ動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc97b34b-9f79-4981-aac7-2a1064bb0242') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36548, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下げました", "is_correct": true, "explanation": "照明が高すぎたので低くしたという文脈に合う、「下げる」の丁寧な過去形。"}, {"text": "歌いました", "is_correct": false, "explanation": "照明を歌うことはできず、文脈に合わない。"}, {"text": "泳ぎました", "is_correct": false, "explanation": "照明が泳ぐことはなく、文が成り立たない。"}, {"text": "叫びました", "is_correct": false, "explanation": "照明が叫ぶことはなく、文脈に合わない。"}], "explanations": {"下げました": "照明が高すぎたので低くしたという文脈に合う、「下げる」の丁寧な過去形。", "歌いました": "照明を歌うことはできず、文脈に合わない。", "泳ぎました": "照明が泳ぐことはなく、文が成り立たない。", "叫びました": "照明が叫ぶことはなく、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "下げました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "読書の途中で、眼鏡を耳に下げた。", "explanation": "ここは〈かける〉の意味。眼鏡は耳にかけるもので、下げるとは言わないので合わない。"}, {"text": "仕事が終わって、ネクタイを下げて楽にした。", "explanation": "ここは〈緩める〉の意味。ネクタイは緩めて楽にするもので、下げるとは言わないので合わない。"}, {"text": "バス停で、乗客をバスから下げた。", "explanation": "ここは〈下ろす〉の意味。人を乗り物から移すときは「下ろす」を使い、「下げる」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36548, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下げた", "is_correct": true, "explanation": "旗を半分まで低くしたという文脈に合う、「下げる」のタ形。"}, {"text": "読んだ", "is_correct": false, "explanation": "旗を読むことはできず、文が成り立たない。"}, {"text": "食べた", "is_correct": false, "explanation": "旗を食べることはなく、不自然な文になる。"}, {"text": "笑った", "is_correct": false, "explanation": "旗が笑うことはなく、文脈に合わない。"}], "explanations": {"下げた": "旗を半分まで低くしたという文脈に合う、「下げる」のタ形。", "読んだ": "旗を読むことはできず、文が成り立たない。", "食べた": "旗を食べることはなく、不自然な文になる。", "笑った": "旗が笑うことはなく、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "下げた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷たいものを飲みすぎて、お腹を下げた。", "explanation": "ここは〈お腹を下す（腹をこわす）〉の意味。腹痛の意味で「下す」は使うが、「下げる」は合わない。"}, {"text": "髪を肩に下げて、風に揺らしていた。", "explanation": "ここは〈垂らす〉の意味。髪が垂れる様子には「垂らす」を使い、「下げる」は合わない。"}, {"text": "彼は訴えを下げて、話し合いで解決することにした。", "explanation": "ここは〈取り下げる〉の意味。訴えを撤回する意味で、高さを変える「下げる」では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36548, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "椅子が高すぎたので、座面に下げた。", "corrected_sentence": "椅子が高すぎたので、座面を下げた。", "error_description": "助詞の誤り。「下げる」の対象は目的語なので「を」が必要で、「座面に」の「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下げた", "is_correct": true, "explanation": "「下げる」のタ形で、動作が終わったことを表し、文末に合う。"}, {"text": "下げて", "is_correct": false, "explanation": "テ形は文を言い切れず、文末に置けない。"}, {"text": "下げれば", "is_correct": false, "explanation": "仮定形で、言い切りの文末にならない。"}, {"text": "下げない", "is_correct": false, "explanation": "ナイ形になると否定の意味になり、文の意味が逆になる。"}], "correct_form": "下げた", "base_form": "下げる", "form_label": "タ形", "sentence_index": 1, "explanations": {"下げた": "「下げる」のタ形で、動作が終わったことを表し、文末に合う。", "下げて": "テ形は文を言い切れず、文末に置けない。", "下げれば": "仮定形で、言い切りの文末にならない。", "下げない": "ナイ形になると否定の意味になり、文の意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36548, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "撮影のあと、カメラを下げ休んだ。", "corrected_sentence": "撮影のあと、カメラを下げて休んだ。", "error_description": "接続の誤り。「下げ」と「休んだ」をつなぐには「下げて」（テ形）が必要で、「下げ休んだ」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下げた", "is_correct": true, "explanation": "「下げる」のタ形で、看板を下げたという過去の動作に合う。"}, {"text": "下げよう", "is_correct": false, "explanation": "意志形で、既に行われた動作を表す文と合わない。"}, {"text": "下げられた", "is_correct": false, "explanation": "受身形になり、動作の主体が変わって文の意味が変わる。"}, {"text": "下げます", "is_correct": false, "explanation": "丁寧形で、地の文の普通体と文体が合わない。"}], "correct_form": "下げた", "base_form": "下げる", "form_label": "タ形", "sentence_index": 7, "explanations": {"下げた": "「下げる」のタ形で、看板を下げたという過去の動作に合う。", "下げよう": "意志形で、既に行われた動作を表す文と合わない。", "下げられた": "受身形になり、動作の主体が変わって文の意味が変わる。", "下げます": "丁寧形で、地の文の普通体と文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36549, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上げる", "is_correct": true, "explanation": "「下げる」の対義語。数量や程度を低くする動作と反対に、高くする動きを表す。"}, {"text": "数える", "is_correct": false, "explanation": "数量を数える意味で、程度を低くする動作の反対語ではない。"}, {"text": "重ねる", "is_correct": false, "explanation": "積み上げる意味で、程度や数量の反対語ではない。"}, {"text": "冷やす", "is_correct": false, "explanation": "温度を低くする意味で、「下げる」の反対語ではなく近い動作。"}], "correct_answer": "上げる", "explanations": {"上げる": "「下げる」の対義語。数量や程度を低くする動作と反対に、高くする動きを表す。", "数える": "数量を数える意味で、程度を低くする動作の反対語ではない。", "重ねる": "積み上げる意味で、程度や数量の反対語ではない。", "冷やす": "温度を低くする意味で、「下げる」の反対語ではなく近い動作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36549, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上げる", "is_correct": true, "explanation": "「下げる」の対義語。数量や程度を低くする動作と反対に、高くする動きを表す。"}, {"text": "数える", "is_correct": false, "explanation": "数量を数える意味で、明るさの反対語ではない。"}, {"text": "並べる", "is_correct": false, "explanation": "順に置く意味で、明るさを低くする動作の反対語ではない。"}, {"text": "固める", "is_correct": false, "explanation": "硬くする意味で、程度や数量の反対語ではない。"}], "correct_answer": "上げる", "explanations": {"上げる": "「下げる」の対義語。数量や程度を低くする動作と反対に、高くする動きを表す。", "数える": "数量を数える意味で、明るさの反対語ではない。", "並べる": "順に置く意味で、明るさを低くする動作の反対語ではない。", "固める": "硬くする意味で、程度や数量の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36549, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "位置や程度、数量などを低くする。", "primary_collocate": null, "pronunciation": "さげる", "ipa": "saɡeɾɯ", "syllable_count": 3, "sentences": [{"text": "暑いので、エアコンの温度を二度下げました。", "target_word": "下げ", "complexity_tier": "T3", "furigana": "暑(あつ)いので、エアコンの温度(おんど)を二度(にど)下(さ)げました。", "sentence_source": "generated"}, {"text": "店は客を増やすため、商品の値段を下げた。", "target_word": "下げた", "complexity_tier": "T3", "furigana": "店(みせ)は客(きゃく)を増(ふ)やすため、商品(しょうひん)の値段(ねだん)を下(さ)げた。", "sentence_source": "generated"}, {"text": "先生は試験のレベルを下げて、全員が解けるようにした。", "target_word": "下げて", "complexity_tier": "T3", "furigana": "先生(せんせい)は試験(しけん)のレベルを下(さ)げて、全員(ぜんいん)が解(と)けるようにした。", "sentence_source": "generated"}, {"text": "母は、風邪で寝ている私の熱を下げようと、冷たいタオルを当てた。", "target_word": "下げよう", "complexity_tier": "T3", "furigana": "母(はは)は、風邪(かぜ)で寝(ね)ている私(わたし)の熱(ねつ)を下(さ)げようと、冷(つめ)たいタオルを当(あ)てた。", "sentence_source": "generated"}, {"text": "音がうるさいので、テレビの音量を下げてください。", "target_word": "下げて", "complexity_tier": "T3", "furigana": "音(おと)がうるさいので、テレビの音量(おんりょう)を下(さ)げてください。", "sentence_source": "generated"}, {"text": "会社は、費用を下げるために、会議の回数を減らした。", "target_word": "下げる", "complexity_tier": "T3", "furigana": "会社(かいしゃ)は、費用(ひよう)を下(さ)げるために、会議(かいぎ)の回数(かいすう)を減(へ)らした。", "sentence_source": "generated"}, {"text": "薬を飲んで、血圧を下げるようにしています。", "target_word": "下げる", "complexity_tier": "T3", "furigana": "薬(くすり)を飲(の)んで、血圧(けつあつ)を下(さ)げるようにしています。", "sentence_source": "generated"}, {"text": "目標を下げれば楽だが、それでは成長しない。", "target_word": "下げれ", "complexity_tier": "T3", "furigana": "目標(もくひょう)を下(さ)げれば楽(らく)だが、それでは成長(せいちょう)しない。", "sentence_source": "generated"}, {"text": "成績が落ちたので、志望校のランクを下げた。", "target_word": "下げた", "complexity_tier": "T3", "furigana": "成績(せいせき)が落(お)ちたので、志望校(しぼうこう)のランクを下(さ)げた。", "sentence_source": "generated"}, {"text": "夜は部屋の明るさを下げると、よく眠れます。", "target_word": "下げる", "complexity_tier": "T3", "furigana": "夜(よる)は部屋(へや)の明(あか)るさを下(さ)げると、よく眠(ねむ)れます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下げる", "label": "辞書形"}, {"form": "下げます", "label": "丁寧形"}, {"form": "下げた", "label": "タ形"}, {"form": "下げて", "label": "テ形"}, {"form": "下げない", "label": "ナイ形"}, {"form": "下げれば", "label": "仮定形"}, {"form": "下げよう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "さげる(下げる): 温度・値段・音量・水準など、程度や数量を小さくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc97b34b-9f79-4981-aac7-2a1064bb0242') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36549, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下げ", "is_correct": true, "explanation": "温度を低くする文脈に合い、「下げ」＋「ました」で温度を下げたことを表す。"}, {"text": "読み", "is_correct": false, "explanation": "温度を読むことはなく、文が成り立たない。"}, {"text": "食べ", "is_correct": false, "explanation": "温度を食べることはなく、不自然な文になる。"}, {"text": "洗い", "is_correct": false, "explanation": "温度を洗うことはなく、文脈に合わない。"}], "explanations": {"下げ": "温度を低くする文脈に合い、「下げ」＋「ました」で温度を下げたことを表す。", "読み": "温度を読むことはなく、文が成り立たない。", "食べ": "温度を食べることはなく、不自然な文になる。", "洗い": "温度を洗うことはなく、文脈に合わない。"}, "sentence_index": 0, "correct_answer": "下げ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敵に見つからないように、息を下げて隠れた。", "explanation": "ここは〈殺す〉の意味（息を殺す）。息は殺すもので、下げるとは言わないので合わない。"}, {"text": "風邪をひいて、鼻水を下げて寝込んだ。", "explanation": "ここは〈垂らす〉の意味。鼻水は垂らすもので、下げるとは言わないので合わない。"}, {"text": "来客の前に、散らかった部屋を下げた。", "explanation": "ここは〈片付ける〉の意味。部屋は片付けるもので、下げるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36549, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下げる", "is_correct": true, "explanation": "血圧を低くする文脈に合い、「血圧を下げるようにしています」が自然。"}, {"text": "歌う", "is_correct": false, "explanation": "血圧を歌うことはなく、文が成り立たない。"}, {"text": "眠る", "is_correct": false, "explanation": "血圧を眠らせることはなく、不自然な文になる。"}, {"text": "磨く", "is_correct": false, "explanation": "血圧を磨くことはなく、文脈に合わない。"}], "explanations": {"下げる": "血圧を低くする文脈に合い、「血圧を下げるようにしています」が自然。", "歌う": "血圧を歌うことはなく、文が成り立たない。", "眠る": "血圧を眠らせることはなく、不自然な文になる。", "磨く": "血圧を磨くことはなく、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "下げる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜中に食べすぎて、お腹を下げた。", "explanation": "ここは〈お腹を下す（腹をこわす）〉の意味。腹痛は「お腹を下す」と言い、「下げる」は合わない。"}, {"text": "申し出を下げて、話を白紙に戻した。", "explanation": "ここは〈取り下げる〉の意味。申し出を撤回する意味で、程度や数量を低くする「下げる」の使い方ではない。"}, {"text": "山道を登る前に、ペットボトルのふたを下げた。", "explanation": "ここは〈閉める〉の意味。ふたは閉めるもので、下げるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36549, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "室温が二度下げると、体がすっきりする。", "corrected_sentence": "室温を二度下げると、体がすっきりする。", "error_description": "助詞の誤り。「下げる」の対象は目的語なので「を」が必要で、「室温が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下げた", "is_correct": true, "explanation": "「下げる」のタ形で、値段を下げたという過去の動作に合う。"}, {"text": "下げます", "is_correct": false, "explanation": "丁寧形で、地の文の普通体と文体が合わない。"}, {"text": "下げれば", "is_correct": false, "explanation": "仮定形で、言い切りの文末にならない。"}, {"text": "下げられない", "is_correct": false, "explanation": "可能形の否定になり、値段を下げたという事実と意味が違う。"}], "correct_form": "下げた", "base_form": "下げる", "form_label": "タ形", "sentence_index": 1, "explanations": {"下げた": "「下げる」のタ形で、値段を下げたという過去の動作に合う。", "下げます": "丁寧形で、地の文の普通体と文体が合わない。", "下げれば": "仮定形で、言い切りの文末にならない。", "下げられない": "可能形の否定になり、値段を下げたという事実と意味が違う。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36549, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝る前に画面の明るさを下げるた、目が疲れにくい。", "corrected_sentence": "寝る前に画面の明るさを下げると、目が疲れにくい。", "error_description": "接続の誤り。「下げる」に「た」は続かず、条件を表す「と」が必要。「下げると」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下げれ", "is_correct": true, "explanation": "仮定形「下げれば」の一部で、「〜ば」に続く形として正しい。"}, {"text": "下げろ", "is_correct": false, "explanation": "命令形で、条件を表す文の中では使えない。"}, {"text": "下げた", "is_correct": false, "explanation": "タ形は「〜ば」と接続せず、条件の文に合わない。"}, {"text": "下げない", "is_correct": false, "explanation": "ナイ形は意味が逆になり、「〜ば」にも続かない。"}], "correct_form": "下げれ", "base_form": "下げる", "form_label": "仮定形", "sentence_index": 7, "explanations": {"下げれ": "仮定形「下げれば」の一部で、「〜ば」に続く形として正しい。", "下げろ": "命令形で、条件を表す文の中では使えない。", "下げた": "タ形は「〜ば」と接続せず、条件の文に合わない。", "下げない": "ナイ形は意味が逆になり、「〜ば」にも続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fde80e6-589b-455a-bdee-b0788df4977e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
