INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36550, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "眠りたい気持ちを表す言葉です。", "primary_collocate": null, "pronunciation": "ねむたい", "ipa": "nemɯtai", "syllable_count": 4, "sentences": [{"text": "昼ご飯を食べたあとは、どうしても眠たい。", "target_word": "眠たい", "complexity_tier": "T2", "furigana": "昼[ひる]ご飯[はん]を食[た]べたあとは、どうしても眠[ねむ]たい。", "sentence_source": "generated"}, {"text": "昨日は夜中まで勉強したので、朝から眠たくて仕方がない。", "target_word": "眠たくて", "complexity_tier": "T3", "furigana": "昨日[きのう]は夜中[よなか]まで勉強[べんきょう]したので、朝[あさ]から眠[ねむ]たくて仕方[しかた]がない。", "sentence_source": "generated"}, {"text": "授業がつまらなくて、だんだん眠たくなってきた。", "target_word": "眠たく", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]がつまらなくて、だんだん眠[ねむ]たくなってきた。", "sentence_source": "generated"}, {"text": "子どもは眠たいとき、よく目をこする。", "target_word": "眠たい", "complexity_tier": "T2", "furigana": "子[こ]どもは眠[ねむ]たいとき、よく目[め]をこする。", "sentence_source": "generated"}, {"text": "眠たかったので、会議のあいだずっとコーヒーを飲んでいた。", "target_word": "眠たかった", "complexity_tier": "T3", "furigana": "眠[ねむ]たかったので、会議[かいぎ]のあいだずっとコーヒーを飲[の]んでいた。", "sentence_source": "generated"}, {"text": "まだ眠たくないから、もう少し本を読むつもりだ。", "target_word": "眠たくない", "complexity_tier": "T3", "furigana": "まだ眠[ねむ]たくないから、もう少[すこ]し本[ほん]を読[よ]むつもりだ。", "sentence_source": "generated"}, {"text": "眠たければ、無理をしないで先に寝ていいよ。", "target_word": "眠たければ", "complexity_tier": "T3", "furigana": "眠[ねむ]たければ、無理[むり]をしないで先[さき]に寝[ね]ていいよ。", "sentence_source": "generated"}, {"text": "薬を飲んだせいか、午後はずっと眠たい。", "target_word": "眠たい", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだせいか、午後[ごご]はずっと眠[ねむ]たい。", "sentence_source": "generated"}, {"text": "電車の揺れが心地よくて、すぐに眠たくなってしまった。", "target_word": "眠たく", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の揺れ[ゆれ]が心地[ここち]よくて、すぐに眠[ねむ]たくなってしまった。", "sentence_source": "generated"}, {"text": "彼は眠たい声で「おはよう」と言った。", "target_word": "眠たい", "complexity_tier": "T3", "furigana": "彼[かれ]は眠[ねむ]たい声[こえ]で「おはよう」と言[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眠たい", "label": "終止形"}, {"form": "眠たく", "label": "連用形"}, {"form": "眠たくて", "label": "て形"}, {"form": "眠たかった", "label": "過去形"}, {"form": "眠たくない", "label": "否定形"}, {"form": "眠たければ", "label": "仮定形"}], "register": "口語（常体）", "sense_fingerprint": "眠りたいという気持ちや状態を表す形容詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36550, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眠たい", "is_correct": true, "explanation": "終止形で文末に置かれ、「どうしても眠たい」と状態を言い切る述語になる。"}, {"text": "眠たく", "is_correct": false, "explanation": "連用形は文を終えられないので、「どうしても眠たく。」では文が成立しない。"}, {"text": "眠たくて", "is_correct": false, "explanation": "て形は後ろに続く文が必要なので、ここで文を終えると不完全になる。"}, {"text": "眠たければ", "is_correct": false, "explanation": "仮定形は「もし眠ければ」という条件節になり、文末の述語にならない。"}], "explanations": {"眠たい": "終止形で文末に置かれ、「どうしても眠たい」と状態を言い切る述語になる。", "眠たく": "連用形は文を終えられないので、「どうしても眠たく。」では文が成立しない。", "眠たくて": "て形は後ろに続く文が必要なので、ここで文を終えると不完全になる。", "眠たければ": "仮定形は「もし眠ければ」という条件節になり、文末の述語にならない。"}, "sentence_index": 0, "correct_answer": "眠たい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風邪をひいて、体中がずっと眠たい。", "explanation": "ここは〈だるい〉の意味。眠たいは眠りたい気持ちを表すので、体全体のだるさには使わない。"}, {"text": "一日中重い荷物を運んで、腕が眠たくなった。", "explanation": "ここは〈疲れた〉の意味。眠たいは眠気を表すので、腕の疲労を表す言葉としては使わない。"}, {"text": "このお茶は、なんだか眠たい味がする。", "explanation": "ここは〈渋い〉などの味の意味。眠たいは人の眠りたい状態を表すので、味の説明には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36550, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眠たければ", "is_correct": true, "explanation": "仮定形で「もし眠たければ」と条件を示し、後ろの「寝ていいよ」につながる。"}, {"text": "眠たくない", "is_correct": false, "explanation": "否定形では条件にならず、「眠たくない、無理をしないで先に寝ていいよ」は意味が通らない。"}, {"text": "眠たそう", "is_correct": false, "explanation": "様子を表す形は条件節にならず、「眠たそう、寝ていいよ」は続かない。"}, {"text": "眠たくなる", "is_correct": false, "explanation": "変化を表す形なので、「眠たくなる、無理をしないで」は条件として成り立たない。"}], "explanations": {"眠たければ": "仮定形で「もし眠たければ」と条件を示し、後ろの「寝ていいよ」につながる。", "眠たくない": "否定形では条件にならず、「眠たくない、無理をしないで先に寝ていいよ」は意味が通らない。", "眠たそう": "様子を表す形は条件節にならず、「眠たそう、寝ていいよ」は続かない。", "眠たくなる": "変化を表す形なので、「眠たくなる、無理をしないで」は条件として成り立たない。"}, "sentence_index": 6, "correct_answer": "眠たければ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新幹線が眠たいほど速く走って、景色が一瞬で消えた。", "explanation": "ここは〈速い〉の意味。眠たいは眠気の状態を表すので、速度の形容には使わない。"}, {"text": "この店のケーキが眠たくて、一つ買ってしまった。", "explanation": "ここは〈食べたい〉の意味。眠たいは眠りたい気持ちを表すので、食べたい気持ちには使わない。"}, {"text": "彼は怒りで眠たくなり、大声を出した。", "explanation": "ここは〈かっとなる〉といった感情の意味。眠たいは眠気の状態なので、感情が高ぶることは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36550, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜中に目が覚めてしまって、今日はずっと眠たくて。", "corrected_sentence": "夜中に目が覚めてしまって、今日はずっと眠たい。", "error_description": "文末に「眠たくて」を置いているが、て形は後ろに続く文が必要で、ここでは文が終わってしまう。正しくは終止形の「眠たい」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "眠たくて", "is_correct": true, "explanation": "て形で「仕方がない」の原因を述べる形になり、後ろの文とつながる。"}, {"text": "眠たく", "is_correct": false, "explanation": "連用形のままでは「仕方がない」へ続かず、「て」が必要になる。"}, {"text": "眠たかった", "is_correct": false, "explanation": "過去形なので、今も続いている状態を述べる「仕方がない」と時制が合わず、て形にもならない。"}, {"text": "眠たくない", "is_correct": false, "explanation": "否定形では「朝から眠たくない」と眠くない状態になり、文の意味が逆になる。"}], "correct_form": "眠たくて", "base_form": "眠たい", "form_label": "て形", "sentence_index": 1, "explanations": {"眠たくて": "て形で「仕方がない」の原因を述べる形になり、後ろの文とつながる。", "眠たく": "連用形のままでは「仕方がない」へ続かず、「て」が必要になる。", "眠たかった": "過去形なので、今も続いている状態を述べる「仕方がない」と時制が合わず、て形にもならない。", "眠たくない": "否定形では「朝から眠たくない」と眠くない状態になり、文の意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36550, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜ふかしのあとは、いつも朝から眠たく。", "corrected_sentence": "夜ふかしのあとは、いつも朝から眠たい。", "error_description": "「眠たく」は連用形で、文を言い切れない。文末の述語には終止形の「眠たい」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "眠たい", "is_correct": true, "explanation": "終止形で「午後はずっと眠たい」と状態を言い切る述語になる。"}, {"text": "眠たくなる", "is_correct": false, "explanation": "変化を表す形で、「ずっと〜だ」という持続の文と合わない。"}, {"text": "眠たそう", "is_correct": false, "explanation": "様子の推量を表す形で、事実として言い切る文にならない。"}, {"text": "眠たくなかった", "is_correct": false, "explanation": "否定の過去形なので、「午後はずっと」の今の状態と時制と意味が合わない。"}], "correct_form": "眠たい", "base_form": "眠たい", "form_label": "終止形", "sentence_index": 7, "explanations": {"眠たい": "終止形で「午後はずっと眠たい」と状態を言い切る述語になる。", "眠たくなる": "変化を表す形で、「ずっと〜だ」という持続の文と合わない。", "眠たそう": "様子の推量を表す形で、事実として言い切る文にならない。", "眠たくなかった": "否定の過去形なので、「午後はずっと」の今の状態と時制と意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
