INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36551, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "眠くて、寝たいと感じる様子。形容詞「眠い」のややくだけた言い方。", "primary_collocate": null, "pronunciation": "ねむたい", "ipa": "nemɯtai", "syllable_count": 4, "sentences": [{"text": "ねえ、ちょっと眠たいから、少し寝てもいい？", "target_word": "眠たい", "complexity_tier": "T2", "furigana": "ねえ、ちょっと眠[ねむ]たいから、少[すこ]し寝[ね]てもいい？", "sentence_source": "generated"}, {"text": "昨日あまり寝てないから、今日はめっちゃ眠たい。", "target_word": "眠たい", "complexity_tier": "T2", "furigana": "昨日[きのう]あまり寝[ね]てないから、今日[きょう]はめっちゃ眠[ねむ]たい。", "sentence_source": "generated"}, {"text": "眠たいなら、コーヒーでも買ってこようか。", "target_word": "眠たい", "complexity_tier": "T2", "furigana": "眠[ねむ]たいなら、コーヒーでも買[か]ってこようか。", "sentence_source": "generated"}, {"text": "映画の途中で眠たくなって、結末を見逃した。", "target_word": "眠たく", "complexity_tier": "T3", "furigana": "映画[えいが]の途中[とちゅう]で眠[ねむ]たくなって、結末[けつまつ]を見逃[みのが]した。", "sentence_source": "generated"}, {"text": "夜更かしした翌日は、いつも一日中眠たい。", "target_word": "眠たい", "complexity_tier": "T3", "furigana": "夜更[よふ]かしした翌日[よくじつ]は、いつも一日中[いちにちじゅう]眠[ねむ]たい。", "sentence_source": "generated"}, {"text": "眠たくなる前に、宿題を終わらせてしまおう。", "target_word": "眠たく", "complexity_tier": "T3", "furigana": "眠[ねむ]たくなる前[まえ]に、宿題[しゅくだい]を終[お]わらせてしまおう。", "sentence_source": "generated"}, {"text": "今日は暖かくて、窓際にいると眠たくなる。", "target_word": "眠たく", "complexity_tier": "T3", "furigana": "今日[きょう]は暖[あたた]かくて、窓際[まどぎわ]にいると眠[ねむ]たくなる。", "sentence_source": "generated"}, {"text": "眠たいのを我慢して、最後まで友だちの話を聞いた。", "target_word": "眠たい", "complexity_tier": "T4", "furigana": "眠[ねむ]たいのを我慢[がまん]して、最後[さいご]まで友[とも]だちの話[はなし]を聞[き]いた。", "sentence_source": "generated"}, {"text": "さっきまで眠たかったのに、シャワーを浴びたら目が覚めた。", "target_word": "眠たかった", "complexity_tier": "T3", "furigana": "さっきまで眠[ねむ]たかったのに、シャワーを浴[あ]びたら目[め]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "弟は眠たいと、すぐ機嫌が悪くなる。", "target_word": "眠たい", "complexity_tier": "T3", "furigana": "弟[おとうと]は眠[ねむ]たいと、すぐ機嫌[きげん]が悪[わる]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眠たい", "label": "終止形"}, {"form": "眠たく", "label": "連用形"}, {"form": "眠たかった", "label": "過去形"}, {"form": "眠たくなる", "label": "変化表現"}], "register": "口語（くだけた会話）", "sense_fingerprint": "「眠い」のややくだけた言い方で、眠くて寝たい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36551, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眠たい", "is_correct": true, "explanation": "終止形で「ちょっと眠たいから」と理由を述べられる。"}, {"text": "眠たくない", "is_correct": false, "explanation": "否定形では「ちょっと眠たくないから寝たい」と理由が矛盾し、文が成り立たない。"}, {"text": "眠たければ", "is_correct": false, "explanation": "仮定形は「もし眠ければ」という条件になり、理由を示す「から」と合わない。"}, {"text": "眠たそう", "is_correct": false, "explanation": "様子を表す形は「眠たそうから」とは続かず、不自然になる。"}], "explanations": {"眠たい": "終止形で「ちょっと眠たいから」と理由を述べられる。", "眠たくない": "否定形では「ちょっと眠たくないから寝たい」と理由が矛盾し、文が成り立たない。", "眠たければ": "仮定形は「もし眠ければ」という条件になり、理由を示す「から」と合わない。", "眠たそう": "様子を表す形は「眠たそうから」とは続かず、不自然になる。"}, "sentence_index": 0, "correct_answer": "眠たい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このお風呂は眠たいので、もう少し沸かそう。", "explanation": "ここは〈ぬるい〉の意味。眠たいは眠気の状態を表すので、お湯の温度には使わない。"}, {"text": "昼ご飯を抜いたので、お腹が眠たくなった。", "explanation": "ここは〈空腹〉の意味。眠たいは眠気を表すので、お腹が空いた感覚には使わない。"}, {"text": "夜になって、部屋が眠たくなってきた。", "explanation": "ここは〈寒い〉の意味。眠たいは人の眠気なので、部屋の温度の変化には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36551, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眠たく", "is_correct": true, "explanation": "連用形で後ろの「なる」に続き、「窓際にいると眠たくなる」と変化を表す。"}, {"text": "眠たい", "is_correct": false, "explanation": "終止形のままでは「眠たいなる」となり、「なる」に続けられない。"}, {"text": "眠たかった", "is_correct": false, "explanation": "過去形のままでは「眠たかったなる」となり、「なる」と続かない。"}, {"text": "眠たくない", "is_correct": false, "explanation": "否定形では「眠たくないなる」となり、成り立たない。"}], "explanations": {"眠たく": "連用形で後ろの「なる」に続き、「窓際にいると眠たくなる」と変化を表す。", "眠たい": "終止形のままでは「眠たいなる」となり、「なる」に続けられない。", "眠たかった": "過去形のままでは「眠たかったなる」となり、「なる」と続かない。", "眠たくない": "否定形では「眠たくないなる」となり、成り立たない。"}, "sentence_index": 6, "correct_answer": "眠たく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暑い日は、喉が眠たくてたまらない。", "explanation": "ここは〈渇く〉の意味。眠たいは眠気を表すので、喉の渇きには使わない。"}, {"text": "歯が眠たくて、食事がつらい。", "explanation": "ここは〈痛い〉の意味。眠たいは眠りたい状態で、歯の痛みには使わない。"}, {"text": "彼は悔しさで眠たくなり、机を叩いた。", "explanation": "ここは〈苛立ち〉の意味。眠たいは眠気の状態で、苛立ちの感情は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36551, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨夜は寝られなくて、今日は朝からずっと眠たくい。", "corrected_sentence": "昨夜は寝られなくて、今日は朝からずっと眠たい。", "error_description": "「眠たくい」は活用として存在しない誤った形。正しくは終止形の「眠たい」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "眠たい", "is_correct": true, "explanation": "終止形で「今日はめっちゃ眠たい」と言い切る述語になる。"}, {"text": "眠たく", "is_correct": false, "explanation": "連用形では文を言い切れず、「めっちゃ眠たく。」は成立しない。"}, {"text": "眠たくて", "is_correct": false, "explanation": "て形は後ろに続く文が必要で、ここでは文が途中で切れてしまう。"}, {"text": "眠たければ", "is_correct": false, "explanation": "仮定形は条件節になり、言い切りの文にならない。"}], "correct_form": "眠たい", "base_form": "眠たい", "form_label": "終止形", "sentence_index": 1, "explanations": {"眠たい": "終止形で「今日はめっちゃ眠たい」と言い切る述語になる。", "眠たく": "連用形では文を言い切れず、「めっちゃ眠たく。」は成立しない。", "眠たくて": "て形は後ろに続く文が必要で、ここでは文が途中で切れてしまう。", "眠たければ": "仮定形は条件節になり、言い切りの文にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36551, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "本を読んでいると、だんだん眠たいなってきた。", "corrected_sentence": "本を読んでいると、だんだん眠たくなってきた。", "error_description": "「なる」の前では「眠たい」を連用形「眠たく」にする必要がある。「眠たいなって」は活用の誤りで、正しくは「眠たくなって」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "眠たい", "is_correct": true, "explanation": "終止形と同じ形で「眠たいのを我慢して」と、眠い状態を名詞のように示す。"}, {"text": "眠たかった", "is_correct": false, "explanation": "過去形なので、今まさに我慢している場面の状態と時制が合わない。"}, {"text": "眠たくて", "is_correct": false, "explanation": "て形は「眠たくてのを」と名詞に続けられず、文が成り立たない。"}, {"text": "眠たくない", "is_correct": false, "explanation": "否定形では「眠くないのを我慢する」となり、意味が逆になる。"}], "correct_form": "眠たい", "base_form": "眠たい", "form_label": "終止形", "sentence_index": 7, "explanations": {"眠たい": "終止形と同じ形で「眠たいのを我慢して」と、眠い状態を名詞のように示す。", "眠たかった": "過去形なので、今まさに我慢している場面の状態と時制が合わない。", "眠たくて": "て形は「眠たくてのを」と名詞に続けられず、文が成り立たない。", "眠たくない": "否定形では「眠くないのを我慢する」となり、意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36552, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「火の熱で」の「で」は、部屋があたたかくなる原因・手段を示す。"}, {"text": "を", "is_correct": false, "explanation": "対象を示すが、ここは原因や手段を表す位置なので、文の組み立てに合わない"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、原因を表す語にはならない"}, {"text": "の", "is_correct": false, "explanation": "連体修飾だが、続く動詞がなく文の組み立てが合わない"}], "correct_answer": "で", "explanations": {"で": "正解。「火の熱で」の「で」は、部屋があたたかくなる原因・手段を示す。", "を": "対象を示すが、ここは原因や手段を表す位置なので、文の組み立てに合わない", "へ": "方向を示すが、原因を表す語にはならない", "の": "連体修飾だが、続く動詞がなく文の組み立てが合わない"}, "error_tags": {"を": "対象を示すが、ここは原因や手段を表す位置なので、文の組み立てに合わない", "へ": "方向を示すが、原因を表す語にはならない", "の": "連体修飾だが、続く動詞がなく文の組み立てが合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36552, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「周りの熱を奪って」で、奪う対象として熱を「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、奪うは対象を取る動詞なので合わない"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を示すが、奪う対象は直接「を」で取る"}, {"text": "と", "is_correct": false, "explanation": "並列や引用を示すが、奪う対象を表さない"}], "correct_answer": "を", "explanations": {"を": "正解。「周りの熱を奪って」で、奪う対象として熱を「を」で示す。", "が": "主語を示すが、奪うは対象を取る動詞なので合わない", "に": "相手や場所を示すが、奪う対象は直接「を」で取る", "と": "並列や引用を示すが、奪う対象を表さない"}, "error_tags": {"が": "主語を示すが、奪うは対象を取る動詞なので合わない", "に": "相手や場所を示すが、奪う対象は直接「を」で取る", "と": "並列や引用を示すが、奪う対象を表さない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36552, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものがとてもあたたかいこと。", "primary_collocate": null, "pronunciation": "ねつ", "ipa": "netsɯ", "syllable_count": 2, "sentences": [{"text": "鍋に熱が伝わるまで、少し待った。", "target_word": "熱", "complexity_tier": "T3", "furigana": "鍋[なべ]に熱[ねつ]が伝[つた]わるまで、少[すこ]し待[ま]った。", "sentence_source": "generated"}, {"text": "火の熱で、部屋がだんだんあたたかくなった。", "target_word": "熱", "complexity_tier": "T3", "furigana": "火[ひ]の熱[ねつ]で、部屋[へや]がだんだんあたたかくなった。", "sentence_source": "generated"}, {"text": "金属は熱をよく通す。", "target_word": "熱", "complexity_tier": "T3", "furigana": "金属[きんぞく]は熱[ねつ]をよく通[とお]す。", "sentence_source": "generated"}, {"text": "太陽の熱で、地面がとても熱くなった。", "target_word": "熱", "complexity_tier": "T3", "furigana": "太陽[たいよう]の熱[ねつ]で、地面[じめん]がとても熱[あつ]くなった。", "sentence_source": "generated"}, {"text": "彼は鉄に熱を加えて、やわらかくした。", "target_word": "熱", "complexity_tier": "T3", "furigana": "彼[かれ]は鉄[てつ]に熱[ねつ]を加[くわ]えて、やわらかくした。", "sentence_source": "generated"}, {"text": "この服は熱を逃がさないので、冬でも暖かい。", "target_word": "熱", "complexity_tier": "T3", "furigana": "この服[ふく]は熱[ねつ]を逃[に]がさないので、冬[ふゆ]でも暖[あたた]かい。", "sentence_source": "generated"}, {"text": "湯の熱が冷めないうちに、お茶を飲んだ。", "target_word": "熱", "complexity_tier": "T3", "furigana": "湯[ゆ]の熱[ねつ]が冷[さ]めないうちに、お茶[ちゃ]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "氷は周りの熱を奪って、とけていく。", "target_word": "熱", "complexity_tier": "T3", "furigana": "氷[こおり]は周[まわ]りの熱[ねつ]を奪[うば]って、とけていく。", "sentence_source": "generated"}, {"text": "厚い壁は、外の熱を中に入れにくい。", "target_word": "熱", "complexity_tier": "T3", "furigana": "厚[あつ]い壁[かべ]は、外[そと]の熱[ねつ]を中[なか]に入[い]れにくい。", "sentence_source": "generated"}, {"text": "ストーブの熱が、冷えた手をあたためてくれた。", "target_word": "熱", "complexity_tier": "T3", "furigana": "ストーブの熱[ねつ]が、冷[ひ]えた手[て]をあたためてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱", "label": "基本形"}], "register": "普通体", "sense_fingerprint": "物が持つ温かさ・エネルギーとしての熱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df666cf-660e-4a65-8685-1c7e60c94a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36552, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熱", "is_correct": true, "explanation": "正解。鍋に伝わって中を温める文脈で、熱が伝わるという意味に合う。"}, {"text": "色", "is_correct": false, "explanation": "色は鍋に伝わって温めることがなく、文が成り立たない。"}, {"text": "形", "is_correct": false, "explanation": "形は伝わって温まるものではないので合わない。"}, {"text": "本", "is_correct": false, "explanation": "本が鍋に伝わるとは言えない。"}], "explanations": {"熱": "正解。鍋に伝わって中を温める文脈で、熱が伝わるという意味に合う。", "色": "色は鍋に伝わって温めることがなく、文が成り立たない。", "形": "形は伝わって温まるものではないので合わない。", "本": "本が鍋に伝わるとは言えない。"}, "sentence_index": 0, "correct_answer": "熱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ラジオの熱が大きくて、近所に響いた。", "explanation": "ここは〈音〉の意味。熱は温かさを指すので、大きくて近所に響くものの代わりには使えない。"}, {"text": "この花の熱が強くて、部屋中に広がった。", "explanation": "ここは〈香り〉の意味。熱は温かさを指すので、部屋中に広がる匂いの代わりにはならない。"}, {"text": "雨が降ったので、川の熱が増えた。", "explanation": "ここは〈水量〉の意味。熱は温かさを指すので、川で増える水の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36552, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熱", "is_correct": true, "explanation": "正解。湯が冷めないうちにという文脈で、湯の温かさを指す熱に合う。"}, {"text": "天気", "is_correct": false, "explanation": "湯の天気が冷めるとは言えず、文が成り立たない。"}, {"text": "景色", "is_correct": false, "explanation": "景色は冷めることがないので合わない。"}, {"text": "名前", "is_correct": false, "explanation": "名前が冷めるとは言えない。"}], "explanations": {"熱": "正解。湯が冷めないうちにという文脈で、湯の温かさを指す熱に合う。", "天気": "湯の天気が冷めるとは言えず、文が成り立たない。", "景色": "景色は冷めることがないので合わない。", "名前": "名前が冷めるとは言えない。"}, "sentence_index": 6, "correct_answer": "熱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨の熱が指先を冷やした。", "explanation": "冷たさの代わりに熱を置くと、冷やす原因が温かさになり矛盾する。熱は冷やすものではない。"}, {"text": "寒さで手がかじかんだのは、熱のせいだ。", "explanation": "熱は温かさを指す語で、寒さで手がかじかむ原因として「熱のせい」と言うのは文脈に合わない。"}, {"text": "太陽の熱で、部屋がまぶしくなった。", "explanation": "ここは〈光〉の意味。熱は温かさを指すので、部屋をまぶしく照らす明るさの代わりには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36552, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "お湯に熱を伝わるまで、少し待った。", "corrected_sentence": "お湯に熱が伝わるまで、少し待った。", "error_description": "伝わるは主語を「が」で取る動詞。「を」は誤りで、正しくは「熱が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36552, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湯の熱を冷めないうちに、菓子を食べた。", "corrected_sentence": "湯の熱が冷めないうちに、菓子を食べた。", "error_description": "冷めるは主語を「が」で取る動詞。「を」は誤りで、正しくは「熱が」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36554, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「口に入れる」の「に」。入れる先（口の中）を示す格助詞で、この文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「口を入れる」とは言わない。「入れる」の目的語は「食べ物」なので、「口」に「を」は付かない。"}, {"text": "で", "is_correct": false, "explanation": "「口で入れる」は手段として不自然で、「口に入れる」の意味にならない。"}, {"text": "の", "is_correct": false, "explanation": "「口の入れたまま」では「入れる」が名詞を修飾できず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「口に入れる」の「に」。入れる先（口の中）を示す格助詞で、この文に合う。", "を": "「口を入れる」とは言わない。「入れる」の目的語は「食べ物」なので、「口」に「を」は付かない。", "で": "「口で入れる」は手段として不自然で、「口に入れる」の意味にならない。", "の": "「口の入れたまま」では「入れる」が名詞を修飾できず、文が成り立たない。"}, "error_tags": {"を": "object", "で": "means", "の": "possessive"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36554, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「口を開ける」の「を」。開ける対象（口）を示す目的語の格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「口が開けて」は「開ける」の主語に「口」を置くことになり、他動詞の用法に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「口と開けて」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「口へ開けて」は方向を表す語として意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「口を開ける」の「を」。開ける対象（口）を示す目的語の格助詞。", "が": "「口が開けて」は「開ける」の主語に「口」を置くことになり、他動詞の用法に合わない。", "と": "「口と開けて」は文が成り立たない。", "へ": "「口へ開けて」は方向を表す語として意味が通らない。"}, "error_tags": {"が": "subject", "と": "with", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36554, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "食べ物を食べたり、話したりするときに使う、顔のあなです。", "primary_collocate": null, "pronunciation": "くち", "ipa": "kɯtɕi", "syllable_count": 2, "sentences": [{"text": "大きな口を開けて、あくびをした。", "target_word": "口", "complexity_tier": "T3", "furigana": "大(おお)きな口(くち)を開(あ)けて、あくびをした。", "sentence_source": "generated"}, {"text": "食べ物を口に入れたまま話してはいけない。", "target_word": "口", "complexity_tier": "T3", "furigana": "食(た)べ物(もの)を口(くち)に入(い)れたまま話(はな)してはいけない。", "sentence_source": "generated"}, {"text": "寒いので、口から白い息が出る。", "target_word": "口", "complexity_tier": "T3", "furigana": "寒(さむ)いので、口(くち)から白(しろ)い息(いき)が出(で)る。", "sentence_source": "generated"}, {"text": "歯をみがいたあとは、水で口をすすぎます。", "target_word": "口", "complexity_tier": "T3", "furigana": "歯(は)をみがいたあとは、水(みず)で口(くち)をすすぎます。", "sentence_source": "generated"}, {"text": "赤ちゃんは何でも口に入れたがる。", "target_word": "口", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんは何(なん)でも口(くち)に入(い)れたがる。", "sentence_source": "generated"}, {"text": "口を大きく動かすと、言葉がはっきり聞こえる。", "target_word": "口", "complexity_tier": "T3", "furigana": "口(くち)を大(おお)きく動(うご)かすと、言葉(ことば)がはっきり聞(き)こえる。", "sentence_source": "generated"}, {"text": "犬は口にボールをくわえて走ってきた。", "target_word": "口", "complexity_tier": "T3", "furigana": "犬(いぬ)は口(くち)にボールをくわえて走(はし)ってきた。", "sentence_source": "generated"}, {"text": "医者に言われて、口を開けて喉を見せた。", "target_word": "口", "complexity_tier": "T3", "furigana": "医者(いしゃ)に言(い)われて、口(くち)を開(あ)けて喉(のど)を見(み)せた。", "sentence_source": "generated"}, {"text": "びっくりして、口がぽかんと開いたままだった。", "target_word": "口", "complexity_tier": "T3", "furigana": "びっくりして、口(くち)がぽかんと開(あ)いたままだった。", "sentence_source": "generated"}, {"text": "熱いスープで口をやけどしてしまった。", "target_word": "口", "complexity_tier": "T3", "furigana": "熱(あつ)いスープで口(くち)をやけどしてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "口", "label": "基本形"}], "register": "中立（日常語）", "sense_fingerprint": "顔にあり、食べる・話す・息をするときに使う体の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: contains vocabulary far above tier T1: みがい (Zipf 1.96), すすぎ (Zipf 2.42)','sentence 8 above tier T1: contains vocabulary far above tier T1: ぽかんと (Zipf 1.86)']::text[], 'c807979d-24e5-4686-b553-a0ab630f3395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36554, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口", "is_correct": true, "explanation": "「大きな口を開けて」の「口」。顔のあなで、あくびの動作に合う。"}, {"text": "腹", "is_correct": false, "explanation": "「腹」は胴体の部位で、「大きな腹を開けて」とは言わない。"}, {"text": "腕", "is_correct": false, "explanation": "「腕」は手足の一部で、口を開ける動作には合わない。"}, {"text": "耳", "is_correct": false, "explanation": "「耳」は聞くための器官で、「大きな耳を開けて」は意味が通らない。"}], "explanations": {"口": "「大きな口を開けて」の「口」。顔のあなで、あくびの動作に合う。", "腹": "「腹」は胴体の部位で、「大きな腹を開けて」とは言わない。", "腕": "「腕」は手足の一部で、口を開ける動作には合わない。", "耳": "「耳」は聞くための器官で、「大きな耳を開けて」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "悔しくて、口をかんでこらえた。", "explanation": "ここは「唇」の意味。「唇をかむ」は唇を使う慣用表現で、「口をかむ」とは言わないので合わない。"}, {"text": "朝、口をそってから出かけた。", "explanation": "ここは「ひげ」の意味。ひげはそるものだが、口はそらないので、この文では合わない。"}, {"text": "朝、口をとかしてから家を出た。", "explanation": "ここは「髪」の意味。髪はとかすものだが、口はとかさないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36554, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口", "is_correct": true, "explanation": "「犬は口にボールをくわえて」の「口」。ボールをくわえるための器官。"}, {"text": "手", "is_correct": false, "explanation": "「手」にボールをくわえるとは言わない。"}, {"text": "足", "is_correct": false, "explanation": "「足」は移動のための器官で、くわえる動作には使わない。"}, {"text": "背中", "is_correct": false, "explanation": "「背中」にボールをくわえる動作はできない。"}], "explanations": {"口": "「犬は口にボールをくわえて」の「口」。ボールをくわえるための器官。", "手": "「手」にボールをくわえるとは言わない。", "足": "「足」は移動のための器官で、くわえる動作には使わない。", "背中": "「背中」にボールをくわえる動作はできない。"}, "sentence_index": 6, "correct_answer": "口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "口をひそめて、話を聞いていた。", "explanation": "ここは「まゆ」の意味。まゆはひそめるものだが、口はひそめないので合わない。"}, {"text": "転んで口が折れてしまった。", "explanation": "ここは「歯」の話として自然。口は折れない器官なので、この文では「口」は合わない。"}, {"text": "毎晩、口をけずって、すべすべにしている。", "explanation": "ここは「かかと」の意味。かかとはけずるものだが、口はけずらないので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36554, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熱いお茶を口が含んで、少し待つ。", "corrected_sentence": "熱いお茶を口に含んで、少し待つ。", "error_description": "「口に含む」の「に」が正しい。「口が含む」とすると「口」が主語になり、不自然で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36554, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "薬を口を入れて、水で飲みます。", "corrected_sentence": "薬を口に入れて、水で飲みます。", "error_description": "「口に入れる」の「に」が正しい。「口を入れる」は「口」を目的語にするため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36556, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「押し入れを開ける」の目的語を示す助詞で、開ける対象として自然。"}, {"text": "が", "is_correct": false, "explanation": "「押し入れが開けて」は押し入れを動作主にする形になり、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「押し入れに開けて」は位置を示すが、開ける対象を示す形にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「押し入れへ開けて」は方向を示す助詞で、開ける動作の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「押し入れを開ける」の目的語を示す助詞で、開ける対象として自然。", "が": "「押し入れが開けて」は押し入れを動作主にする形になり、不自然。", "に": "「押し入れに開けて」は位置を示すが、開ける対象を示す形にはならない。", "へ": "「押し入れへ開けて」は方向を示す助詞で、開ける動作の対象を示せない。"}, "error_tags": {"が": "主語", "に": "位置", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閉める", "is_correct": true, "explanation": "「開ける」の対義語。金庫の扉などを閉じて中を見えない状態にする動詞。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる動作で、開けることの反対の関係にはない。"}, {"text": "置く", "is_correct": false, "explanation": "物を据える動作で、開けることの反対の関係にはない。"}, {"text": "洗う", "is_correct": false, "explanation": "汚れを落とす動作で、開けることの対義語にはならない。"}], "correct_answer": "閉める", "explanations": {"閉める": "「開ける」の対義語。金庫の扉などを閉じて中を見えない状態にする動詞。", "運ぶ": "物を移動させる動作で、開けることの反対の関係にはない。", "置く": "物を据える動作で、開けることの反対の関係にはない。", "洗う": "汚れを落とす動作で、開けることの対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36556, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「倉庫を開ける」の目的語を示す助詞で、開ける対象として自然。"}, {"text": "と", "is_correct": false, "explanation": "「倉庫と開けて」は並列を示すが、開ける動作の対象にはならず不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す助詞で、「倉庫より開けて」は文の関係が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「倉庫の開けて」は連体修飾として続かず、動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「倉庫を開ける」の目的語を示す助詞で、開ける対象として自然。", "と": "「倉庫と開けて」は並列を示すが、開ける動作の対象にはならず不自然。", "より": "比較を示す助詞で、「倉庫より開けて」は文の関係が成り立たない。", "の": "「倉庫の開けて」は連体修飾として続かず、動詞の目的語にならない。"}, "error_tags": {"と": "並列", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閉める", "is_correct": true, "explanation": "「開ける」の対義語。郵便受けなどを閉じて中を見えない状態にする動詞。"}, {"text": "包む", "is_correct": false, "explanation": "物を覆う動作で、開けることの反対の関係にはない。"}, {"text": "届ける", "is_correct": false, "explanation": "相手に運ぶ動作で、開けることの反対の関係にはない。"}, {"text": "測る", "is_correct": false, "explanation": "長さや量をはかる動作で、開けることの対義語にはならない。"}], "correct_answer": "閉める", "explanations": {"閉める": "「開ける」の対義語。郵便受けなどを閉じて中を見えない状態にする動詞。", "包む": "物を覆う動作で、開けることの反対の関係にはない。", "届ける": "相手に運ぶ動作で、開けることの反対の関係にはない。", "測る": "長さや量をはかる動作で、開けることの対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36556, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "しまってあるものを、あけること", "primary_collocate": null, "pronunciation": "あける", "ipa": "akeɾɯ", "syllable_count": 3, "sentences": [{"text": "冷蔵庫を開けたが、中は空っぽだった。", "target_word": "開けた", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]を開[あ]けたが、中[なか]は空[から]っぽだった。", "sentence_source": "generated"}, {"text": "押し入れを開けて、冬用の布団を出した。", "target_word": "開けて", "complexity_tier": "T3", "furigana": "押[お]し入[い]れを開[あ]けて、冬用[ふゆよう]の布団[ふとん]を出[だ]した。", "sentence_source": "generated"}, {"text": "母は箪笥の引き出しを開けて、古い着物を取り出した。", "target_word": "開けて", "complexity_tier": "T3", "furigana": "母[はは]は箪笥[たんす]の引[ひ]き出[だ]しを開[あ]けて、古[ふる]い着物[きもの]を取[と]り出[だ]した。", "sentence_source": "generated"}, {"text": "金庫を開けるには、四桁の番号が必要だ。", "target_word": "開ける", "complexity_tier": "T3", "furigana": "金庫[きんこ]を開[あ]けるには、四桁[よんけた]の番号[ばんごう]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "プレゼントの箱を開けて、弟は大声で喜んだ。", "target_word": "開けて", "complexity_tier": "T3", "furigana": "プレゼントの箱[はこ]を開[あ]けて、弟[おとうと]は大声[おおごえ]で喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "戸棚を開けると、お菓子の缶が三つ並んでいた。", "target_word": "開ける", "complexity_tier": "T3", "furigana": "戸棚[とだな]を開[あ]けると、お菓子[かし]の缶[かん]が三[みっ]つ並[なら]んでいた。", "sentence_source": "generated"}, {"text": "宝箱を開けた瞬間、子どもたちは声を上げた。", "target_word": "開けた", "complexity_tier": "T3", "furigana": "宝箱[たからばこ]を開[あ]けた瞬間[しゅんかん]、子[こ]どもたちは声[こえ]を上[あ]げた。", "sentence_source": "generated"}, {"text": "倉庫を開けて、使っていない道具を運び出した。", "target_word": "開けて", "complexity_tier": "T3", "furigana": "倉庫[そうこ]を開[あ]けて、使[つか]っていない道具[どうぐ]を運[はこ]び出[だ]した。", "sentence_source": "generated"}, {"text": "机の引き出しを開けて、大切な書類を確認した。", "target_word": "開けて", "complexity_tier": "T3", "furigana": "机[つくえ]の引[ひ]き出[だ]しを開[あ]けて、大切[たいせつ]な書類[しょるい]を確認[かくにん]した。", "sentence_source": "generated"}, {"text": "郵便受けを開けると、新聞が入っていた。", "target_word": "開ける", "complexity_tier": "T3", "furigana": "郵便受[ゆうびんう]けを開[あ]けると、新聞[しんぶん]が入[はい]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "開ける", "label": "終止形"}, {"form": "開けない", "label": "否定形"}, {"form": "開けます", "label": "丁寧形"}, {"form": "開け", "label": "連用形"}, {"form": "開けて", "label": "て形"}, {"form": "開けた", "label": "過去形"}, {"form": "開ければ", "label": "仮定形"}], "register": "普通体の日常語", "sense_fingerprint": "しまってある物の入れ物や戸を開く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36556, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "開けた", "is_correct": true, "explanation": "「冷蔵庫を開けた」で、しまってあるものの戸を開く意味に合う正解。"}, {"text": "眠った", "is_correct": false, "explanation": "眠るは自動詞なので、「冷蔵庫を眠った」とは言えない。"}, {"text": "咲いた", "is_correct": false, "explanation": "咲くは自動詞で、冷蔵庫を目的語にできず文が成り立たない。"}, {"text": "歌った", "is_correct": false, "explanation": "歌うは冷蔵庫を目的語にできないので、「冷蔵庫を歌った」は意味が通らない。"}], "explanations": {"開けた": "「冷蔵庫を開けた」で、しまってあるものの戸を開く意味に合う正解。", "眠った": "眠るは自動詞なので、「冷蔵庫を眠った」とは言えない。", "咲いた": "咲くは自動詞で、冷蔵庫を目的語にできず文が成り立たない。", "歌った": "歌うは冷蔵庫を目的語にできないので、「冷蔵庫を歌った」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "開けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜が開けて、鳥が一斉に鳴き始めた。", "explanation": "ここは〈明ける〉（夜が終わり朝になる）の意味。夜は明けるもので、〈開ける〉とは言わない。"}, {"text": "問題を開けるのに、三十分かかった。", "explanation": "ここは〈解く〉（答えを出す）の意味。問題は解くもので、閉じたものを開ける〈開ける〉とは合わない。"}, {"text": "来月、新しい展示会を開ける予定だ。", "explanation": "ここは〈開く〉（催しを行う）の意味。展示会は開くもので、〈開ける〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36556, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "開けた", "is_correct": true, "explanation": "「宝箱を開けた瞬間」で、ふたを開く意味に合う正解。"}, {"text": "鳴いた", "is_correct": false, "explanation": "鳴くは自動詞なので、「宝箱を鳴いた」とは言えない。"}, {"text": "生えた", "is_correct": false, "explanation": "草木が生じる意味の自動詞で、宝箱を目的語にできない。"}, {"text": "光った", "is_correct": false, "explanation": "光るは自動詞なので、「宝箱を光った」は文として成り立たない。"}], "explanations": {"開けた": "「宝箱を開けた瞬間」で、ふたを開く意味に合う正解。", "鳴いた": "鳴くは自動詞なので、「宝箱を鳴いた」とは言えない。", "生えた": "草木が生じる意味の自動詞で、宝箱を目的語にできない。", "光った": "光るは自動詞なので、「宝箱を光った」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "開けた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "席を開けておいたので、友達がすぐ座れた。", "explanation": "ここは〈空ける〉（ふさがずにおく）の意味。席は空けておくもので、〈開ける〉とは合わない。"}, {"text": "りんごの皮を開けて、切り分けた。", "explanation": "ここは〈剥く〉（皮をむく）の意味。皮はむくもので、閉じたものを開ける〈開ける〉とは言わない。"}, {"text": "玄関で靴を開けて、家に上がった。", "explanation": "ここは〈脱ぐ〉（身につけたものをとる）の意味。靴は脱ぐもので、〈開ける〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36556, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "金庫に開けたが、中は空っぽだった。", "corrected_sentence": "金庫を開けたが、中は空っぽだった。", "error_description": "「開けた」の目的語を示す助詞が「に」になっている。対象を取る「開ける」には「を」が必要で、「金庫を開けた」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "開けて", "is_correct": true, "explanation": "て形で「押し入れを開けて、布団を出した」と続く中間形。この文の形として正しい。"}, {"text": "開けろ", "is_correct": false, "explanation": "命令形で、「押し入れを開けろ、布団を出した」と続けると文が成り立たない。"}, {"text": "開けない", "is_correct": false, "explanation": "否定形で押し入れを開けない意味になり、布団を出したという内容と矛盾する。"}, {"text": "開けます", "is_correct": false, "explanation": "丁寧形で、普通体の過去の文の流れに合わない。"}], "correct_form": "開けて", "base_form": "開ける", "form_label": "て形", "sentence_index": 1, "explanations": {"開けて": "て形で「押し入れを開けて、布団を出した」と続く中間形。この文の形として正しい。", "開けろ": "命令形で、「押し入れを開けろ、布団を出した」と続けると文が成り立たない。", "開けない": "否定形で押し入れを開けない意味になり、布団を出したという内容と矛盾する。", "開けます": "丁寧形で、普通体の過去の文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36556, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "棚を開けたたら、古い茶碗が出てきた。", "corrected_sentence": "棚を開けたら、古い茶碗が出てきた。", "error_description": "「開けた」の後に「た」が重なっている。条件の「たら」は「開けたら」と続けるのが正しく、「開けたたら」は不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "開けて", "is_correct": true, "explanation": "て形で「倉庫を開けて、道具を運び出した」と続く中間形。この文の形として正しい。"}, {"text": "開けなかった", "is_correct": false, "explanation": "否定過去なので、「倉庫を開けなかった、道具を運び出した」と続けると矛盾する。"}, {"text": "開けよう", "is_correct": false, "explanation": "意志形で、実際に開けた結果を述べる文には合わない。"}, {"text": "開けろ", "is_correct": false, "explanation": "命令形で、「倉庫を開けろて」と続けられず、文が成り立たない。"}], "correct_form": "開けて", "base_form": "開ける", "form_label": "て形", "sentence_index": 7, "explanations": {"開けて": "て形で「倉庫を開けて、道具を運び出した」と続く中間形。この文の形として正しい。", "開けなかった": "否定過去なので、「倉庫を開けなかった、道具を運び出した」と続けると矛盾する。", "開けよう": "意志形で、実際に開けた結果を述べる文には合わない。", "開けろ": "命令形で、「倉庫を開けろて」と続けられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36557, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「窓を開ける」の目的語を示す助詞で、動作の対象として自然。"}, {"text": "が", "is_correct": false, "explanation": "「窓が開ける」は窓を動作主にする形になり、開ける動作の主体として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「窓に開ける」は位置や相手を示すが、開ける動作の対象を示す形にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「窓へ開ける」は方向を示す助詞で、開ける動作の対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「窓を開ける」の目的語を示す助詞で、動作の対象として自然。", "が": "「窓が開ける」は窓を動作主にする形になり、開ける動作の主体として不自然。", "に": "「窓に開ける」は位置や相手を示すが、開ける動作の対象を示す形にはならない。", "へ": "「窓へ開ける」は方向を示す助詞で、開ける動作の対象を示せない。"}, "error_tags": {"が": "主語", "に": "位置", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閉める", "is_correct": true, "explanation": "「開ける」の対義語。扉を閉じて通れない・見えない状態にする動詞。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移動させる動作で、開けることの反対の関係にはない。"}, {"text": "置く", "is_correct": false, "explanation": "物を据える動作で、開けることの反対の関係にはない。"}, {"text": "洗う", "is_correct": false, "explanation": "汚れを落とす動作で、開けることの対義語にはならない。"}], "correct_answer": "閉める", "explanations": {"閉める": "「開ける」の対義語。扉を閉じて通れない・見えない状態にする動詞。", "運ぶ": "物を移動させる動作で、開けることの反対の関係にはない。", "置く": "物を据える動作で、開けることの反対の関係にはない。", "洗う": "汚れを落とす動作で、開けることの対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36557, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閉める", "is_correct": true, "explanation": "「開ける」の対義語。袋や箱の口を閉じて中を見えないようにする動詞。"}, {"text": "包む", "is_correct": false, "explanation": "物を覆う動作で、開けることの反対の関係にはない。"}, {"text": "届ける", "is_correct": false, "explanation": "相手に運ぶ動作で、開けることの反対の関係にはない。"}, {"text": "測る", "is_correct": false, "explanation": "長さや量をはかる動作で、開けることの対義語にはならない。"}], "correct_answer": "閉める", "explanations": {"閉める": "「開ける」の対義語。袋や箱の口を閉じて中を見えないようにする動詞。", "包む": "物を覆う動作で、開けることの反対の関係にはない。", "届ける": "相手に運ぶ動作で、開けることの反対の関係にはない。", "測る": "長さや量をはかる動作で、開けることの対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36557, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "閉じたりふさいだりしているものを、中や向こう側が見えるようにしたり、使えるようにしたりする。", "primary_collocate": null, "pronunciation": "あける", "ipa": "akeɾɯ", "syllable_count": 3, "sentences": [{"text": "私は遺産整理のために錆びついたドアノブに手をかけ、ゆっくりとそれを開けた。", "target_word": "開けた", "complexity_tier": "T4", "furigana": "私[わたし]は遺産[いさん]整理[せいり]のために錆[さ]びついたドアノブに手[て]をかけ、ゆっくりとそれを開[あ]けた。", "sentence_source": "mined"}, {"text": "朝起きて、まず部屋の窓を開けると、冷たい空気が入ってきた。", "target_word": "開ける", "complexity_tier": "T3", "furigana": "朝[あさ]起[お]きて、まず部屋[へや]の窓[まど]を開[あ]けると、冷[つめ]たい空気[くうき]が入[はい]ってきた。", "sentence_source": "generated"}, {"text": "荷物が届いたので、さっそく箱を開けた。", "target_word": "開けた", "complexity_tier": "T3", "furigana": "荷物[にもつ]が届[とど]いたので、さっそく箱[はこ]を開[あ]けた。", "sentence_source": "generated"}, {"text": "暑いので、ドアを少し開けておく。", "target_word": "開けて", "complexity_tier": "T3", "furigana": "暑[あつ]いので、ドアを少[すこ]し開[あ]けておく。", "sentence_source": "generated"}, {"text": "鍵を回して重い扉を開けると、中は暗かった。", "target_word": "開ける", "complexity_tier": "T3", "furigana": "鍵[かぎ]を回[まわ]して重[おも]い扉[とびら]を開[あ]けると、中[なか]は暗[くら]かった。", "sentence_source": "generated"}, {"text": "彼は驚いて、部屋のドアを勢いよく開けた。", "target_word": "開けた", "complexity_tier": "T3", "furigana": "彼[かれ]は驚[おどろ]いて、部屋[へや]のドアを勢[いきお]いよく開[あ]けた。", "sentence_source": "generated"}, {"text": "あの店は毎朝九時に入口を開ける。", "target_word": "開ける", "complexity_tier": "T3", "furigana": "あの店[みせ]は毎朝[まいあさ]九時[くじ]に入口[いりぐち]を開[あ]ける。", "sentence_source": "generated"}, {"text": "缶を開けようとしたが、固くて開けられなかった。", "target_word": "開けられなかった", "complexity_tier": "T3", "furigana": "缶[かん]を開[あ]けようとしたが、固[かた]くて開[あ]けられなかった。", "sentence_source": "generated"}, {"text": "引き出しを開けると、古い手紙が出てきた。", "target_word": "開ける", "complexity_tier": "T3", "furigana": "引[ひ]き出[だ]しを開[あ]けると、古[ふる]い手紙[てがみ]が出[で]てきた。", "sentence_source": "generated"}, {"text": "お菓子の袋を開けると、いい匂いがした。", "target_word": "開ける", "complexity_tier": "T3", "furigana": "お菓子[かし]の袋[ふくろ]を開[あ]けると、いい匂[にお]いがした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "開ける", "label": "終止形"}, {"form": "開けない", "label": "否定形"}, {"form": "開けます", "label": "丁寧形"}, {"form": "開け", "label": "連用形"}, {"form": "開けて", "label": "て形"}, {"form": "開けた", "label": "過去形"}, {"form": "開ければ", "label": "仮定形"}], "register": "普通体の日常語", "sense_fingerprint": "閉じているものを開いて中や向こうを見えるようにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87117ea3-631e-4c9b-ab6c-2ee2502a2798') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36557, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "開けた", "is_correct": true, "explanation": "「それを開けた」で、ドアを開く動作として文脈に合う正解。"}, {"text": "食べた", "is_correct": false, "explanation": "扉は食べられないので、「それを食べた」は意味が通らない。"}, {"text": "咲いた", "is_correct": false, "explanation": "咲くは自動詞なので「それを」を目的語にとれず、扉を対象とする文に入らない。"}, {"text": "歌った", "is_correct": false, "explanation": "歌うは扉を目的語にできないので、「それを歌った」は文として成り立たない。"}], "explanations": {"開けた": "「それを開けた」で、ドアを開く動作として文脈に合う正解。", "食べた": "扉は食べられないので、「それを食べた」は意味が通らない。", "咲いた": "咲くは自動詞なので「それを」を目的語にとれず、扉を対象とする文に入らない。", "歌った": "歌うは扉を目的語にできないので、「それを歌った」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "開けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "席を開けておいてくれたので、すぐに座れた。", "explanation": "ここは〈空ける〉（ふさがずにおく）の意味。席は空けておくもので、閉じたものを開く〈開ける〉とは合わない。"}, {"text": "靴ひもを開けてから、靴を脱いだ。", "explanation": "ここは〈解く〉（結び目をほどく）の意味。結んだひもはほどくもので、〈開ける〉とは言わない。"}, {"text": "来週、会議を開けるので、準備しておいてください。", "explanation": "ここは〈開く〉（会議などを催す）の意味。会議は開くもので、閉じたものを開ける〈開ける〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36557, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "開ける", "is_correct": true, "explanation": "「入口を開ける」で、店が入口を使える状態にする意味として文脈に合う正解。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは自動詞なので、「入口を眠る」とは言えない。"}, {"text": "生える", "is_correct": false, "explanation": "草木が生じる意味の自動詞で、入口を目的語にできない。"}, {"text": "光る", "is_correct": false, "explanation": "光るは自動詞なので、「入口を光る」は文として成り立たない。"}], "explanations": {"開ける": "「入口を開ける」で、店が入口を使える状態にする意味として文脈に合う正解。", "眠る": "眠るは自動詞なので、「入口を眠る」とは言えない。", "生える": "草木が生じる意味の自動詞で、入口を目的語にできない。", "光る": "光るは自動詞なので、「入口を光る」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "開ける"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "みかんの皮を開けてから、食べた。", "explanation": "ここは〈剥く〉（皮をむく）の意味。皮はむくもので、閉じたものを開く〈開ける〉とは言わない。"}, {"text": "玄関で靴を開けて、家に上がった。", "explanation": "ここは〈脱ぐ〉（身につけたものをとる）の意味。靴は脱ぐもので、開けるとは言わない。"}, {"text": "梅雨が開けて、ようやく夏らしくなった。", "explanation": "ここは〈明ける〉（季節の区切りが終わる）の意味。梅雨は明けるもので、〈開ける〉では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36557, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "荷物が届いたので、すぐに包みに開けた。", "corrected_sentence": "荷物が届いたので、すぐに包みを開けた。", "error_description": "「開けた」の目的語を示す助詞が「に」になっている。対象を取る「開ける」には「を」が必要で、「包みを開けた」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "開ける", "is_correct": true, "explanation": "「窓を開けると」の基本形（終止形）で、「〜と」に続く形としてこの文に合う。"}, {"text": "開けろ", "is_correct": false, "explanation": "命令形で、「〜と」の前に置くと条件節として成り立たない。"}, {"text": "開けるな", "is_correct": false, "explanation": "禁止の形で、「窓を開けるな、冷たい空気が入ってきた」は文として成り立たない。"}, {"text": "開けて", "is_correct": false, "explanation": "て形で続く「〜て」の中間形。「〜と」に続く条件の形としては使えない。"}], "correct_form": "開ける", "base_form": "開ける", "form_label": "終止形", "sentence_index": 1, "explanations": {"開ける": "「窓を開けると」の基本形（終止形）で、「〜と」に続く形としてこの文に合う。", "開けろ": "命令形で、「〜と」の前に置くと条件節として成り立たない。", "開けるな": "禁止の形で、「窓を開けるな、冷たい空気が入ってきた」は文として成り立たない。", "開けて": "て形で続く「〜て」の中間形。「〜と」に続く条件の形としては使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36557, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "箱を開けたたら、中から手紙が出てきた。", "corrected_sentence": "箱を開けたら、中から手紙が出てきた。", "error_description": "「開けた」の後に「た」が重なっている。条件の「たら」は「開けたら」と続けるのが正しく、「開けたたら」は日本語として不自然。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "開けられなかった", "is_correct": true, "explanation": "可能形の過去否定。「固くて〜できなかった」の意味にあたり、この文に合う。"}, {"text": "開けるな", "is_correct": false, "explanation": "禁止の形で、「固くて開けるな」と続けると文が成り立たない。"}, {"text": "開けよう", "is_correct": false, "explanation": "意志形で、結果として開かなかったという過去の文には入らない。"}, {"text": "開けさせ", "is_correct": false, "explanation": "使役の連用形で、「固くて開けさせ」と文を終えられない。"}], "correct_form": "開けられなかった", "base_form": "開ける", "form_label": "可能形・過去否定形", "sentence_index": 7, "explanations": {"開けられなかった": "可能形の過去否定。「固くて〜できなかった」の意味にあたり、この文に合う。", "開けるな": "禁止の形で、「固くて開けるな」と続けると文が成り立たない。", "開けよう": "意志形で、結果として開かなかったという過去の文には入らない。", "開けさせ": "使役の連用形で、「固くて開けさせ」と文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9ea5fb-2ea9-460b-859a-731cc75a25b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36558, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温かい", "is_correct": true, "explanation": "温度が低いの反対で、温度が高く心地よい感じを表すので、対義語として合う。"}, {"text": "硬い", "is_correct": false, "explanation": "硬さを表す語で、温度の反対にはならないので不可。"}, {"text": "細かい", "is_correct": false, "explanation": "粒や大きさの細かさを表す語で、温度の反対ではないので不可。"}, {"text": "広い", "is_correct": false, "explanation": "面積や範囲を表す語で、温度とは関係しないので不可。"}], "correct_answer": "温かい", "explanations": {"温かい": "温度が低いの反対で、温度が高く心地よい感じを表すので、対義語として合う。", "硬い": "硬さを表す語で、温度の反対にはならないので不可。", "細かい": "粒や大きさの細かさを表す語で、温度の反対ではないので不可。", "広い": "面積や範囲を表す語で、温度とは関係しないので不可。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
