INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36558, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "温度が低くて、体が気持ちよくない感じのこと。", "primary_collocate": null, "pronunciation": "つめたい", "ipa": "tsɯmetai", "syllable_count": 4, "sentences": [{"text": "冷たい水に手を入れたら、痛いほどだった。", "target_word": "冷たい", "complexity_tier": "T3", "furigana": "冷[つめ]たい水[みず]に手[て]を入[い]れたら、痛[いた]いほどだった。", "sentence_source": "generated"}, {"text": "冬の朝は、風が冷たくて外に出たくない。", "target_word": "冷たく", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]は、風[かぜ]が冷[つめ]たくて外[そと]に出[で]たくない。", "sentence_source": "generated"}, {"text": "手が冷たいので、ポケットに入れた。", "target_word": "冷たい", "complexity_tier": "T3", "furigana": "手[て]が冷[つめ]たいので、ポケットに入[い]れた。", "sentence_source": "generated"}, {"text": "川の水が冷たかったので、足だけ入れた。", "target_word": "冷たかった", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が冷[つめ]たかったので、足[あし]だけ入[い]れた。", "sentence_source": "generated"}, {"text": "冷たいアイスを食べすぎて、おなかが痛くなった。", "target_word": "冷たい", "complexity_tier": "T3", "furigana": "冷[つめ]たいアイスを食[た]べすぎて、おなかが痛[いた]くなった。", "sentence_source": "generated"}, {"text": "冷たくなったスープを、もう一度温めた。", "target_word": "冷たく", "complexity_tier": "T3", "furigana": "冷[つめ]たくなったスープを、もう一度[いちど]温[あたた]めた。", "sentence_source": "generated"}, {"text": "雨にぬれて、服が冷たく感じられた。", "target_word": "冷たく", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれて、服[ふく]が冷[つめ]たく感[かん]じられた。", "sentence_source": "generated"}, {"text": "冷たい床の上に座っていたら、足が冷えた。", "target_word": "冷たい", "complexity_tier": "T3", "furigana": "冷[つめ]たい床[ゆか]の上[うえ]に座[すわ]っていたら、足[あし]が冷[ひ]えた。", "sentence_source": "generated"}, {"text": "冷たい風が吹いて、帽子が飛ばされた。", "target_word": "冷たい", "complexity_tier": "T3", "furigana": "冷[つめ]たい風[かぜ]が吹[ふ]いて、帽子[ぼうし]が飛[と]ばされた。", "sentence_source": "generated"}, {"text": "このお茶は冷たくないので、氷を入れよう。", "target_word": "冷たく", "complexity_tier": "T3", "furigana": "このお茶[ちゃ]は冷[つめ]たくないので、氷[こおり]を入[い]れよう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷たい", "label": "終止形"}, {"form": "冷たく", "label": "連用形"}, {"form": "冷たかった", "label": "過去形"}, {"form": "冷たくない", "label": "否定形"}, {"form": "冷たければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "触れたときの温度が低く不快に感じられる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36558, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷たい", "is_correct": true, "explanation": "水の温度が低く、触れると不快に感じる意味で「冷たい水」と合う。"}, {"text": "遠い", "is_correct": false, "explanation": "「遠い水」は距離を表すので、温度の話には合わないので不可。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、水の温度を説明する文には入らないので不可。"}, {"text": "短い", "is_correct": false, "explanation": "長さを表す語で、温度を表す「冷たい水」とは意味が合わないので不可。"}], "explanations": {"冷たい": "水の温度が低く、触れると不快に感じる意味で「冷たい水」と合う。", "遠い": "「遠い水」は距離を表すので、温度の話には合わないので不可。", "重い": "重さを表す語で、水の温度を説明する文には入らないので不可。", "短い": "長さを表す語で、温度を表す「冷たい水」とは意味が合わないので不可。"}, "sentence_index": 0, "correct_answer": "冷たい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お小遣いが冷たくて、本が一冊も買えなかった。", "explanation": "ここは〈少ない〉の意味。金額の少なさは冷たいでは言えないので合わない。"}, {"text": "この布は冷たくて、光が透けて見える。", "explanation": "ここは〈薄い〉の意味。布の薄さを言うので、温度の定義には合わない。"}, {"text": "この問題は冷たくて、むずかしい。", "explanation": "ここは〈難しい〉の意味。問題の難しさは冷たいでは言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36558, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷たく", "is_correct": true, "explanation": "「服が冷たく感じられた」で、触れた感じの低い温度を表すので合う。"}, {"text": "忙しく", "is_correct": false, "explanation": "忙しさを表す語で、服の感触には合わないので不可。"}, {"text": "眠く", "is_correct": false, "explanation": "眠気を表す語で、服が眠いとは感じられないので不可。"}, {"text": "騒がしく", "is_correct": false, "explanation": "音の状態を表す語で、服の感触を説明できないので不可。"}], "explanations": {"冷たく": "「服が冷たく感じられた」で、触れた感じの低い温度を表すので合う。", "忙しく": "忙しさを表す語で、服の感触には合わないので不可。", "眠く": "眠気を表す語で、服が眠いとは感じられないので不可。", "騒がしく": "音の状態を表す語で、服の感触を説明できないので不可。"}, "sentence_index": 6, "correct_answer": "冷たく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "かばんが冷たくて、学校まで持ち歩けなかった。", "explanation": "ここは〈重い〉の意味。かばんの重さを言うので、温度の定義では合わない。"}, {"text": "電車が冷たくて、会議に間に合わなかった。", "explanation": "ここは〈遅い〉の意味。進みの遅さを言うので、温度の定義では合わない。"}, {"text": "この箱は冷たくて、部屋に入らない。", "explanation": "ここは〈大きい〉の意味。箱の大きさを言うので、温度の定義では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36558, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今朝の風は冷たいくて、外に出たくなかった。", "corrected_sentence": "今朝の風は冷たくて、外に出たくなかった。", "error_description": "形容詞の連用形（て形の前）は「冷たく」。「冷たいくて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "冷たく", "is_correct": true, "explanation": "「冷たくて」の連用形。「て」に続く形として文中の形と一致する。"}, {"text": "冷たかった", "is_correct": false, "explanation": "過去形なので、「風が冷たくて」の連用形とは合わない。"}, {"text": "冷たそう", "is_correct": false, "explanation": "様態の形で、「て」に続けると文が成り立たない。"}, {"text": "冷たければ", "is_correct": false, "explanation": "仮定形なので、文中の「冷たくて」とは合わない。"}], "correct_form": "冷たく", "base_form": "冷たい", "form_label": "連用形", "sentence_index": 1, "explanations": {"冷たく": "「冷たくて」の連用形。「て」に続く形として文中の形と一致する。", "冷たかった": "過去形なので、「風が冷たくて」の連用形とは合わない。", "冷たそう": "様態の形で、「て」に続けると文が成り立たない。", "冷たければ": "仮定形なので、文中の「冷たくて」とは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36558, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このスープは冷たいないので、すぐに飲める。", "corrected_sentence": "このスープは冷たくないので、すぐに飲める。", "error_description": "形容詞の否定は「冷たくない」。「冷たいない」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "冷たい", "is_correct": true, "explanation": "連体形で、後ろの「床」を修飾する形として文中と一致する。"}, {"text": "冷たいだろう", "is_correct": false, "explanation": "推量の形なので、名詞「床」を直接修飾できず、文が成り立たない。"}, {"text": "冷たいから", "is_correct": false, "explanation": "理由を表す接続形なので、名詞「床」を直接修飾できず、文が成り立たない。"}, {"text": "冷たさ", "is_correct": false, "explanation": "名詞なので、「冷たさ床」と形容詞の連体形として続かず成り立たない。"}], "correct_form": "冷たい", "base_form": "冷たい", "form_label": "連体形", "sentence_index": 7, "explanations": {"冷たい": "連体形で、後ろの「床」を修飾する形として文中と一致する。", "冷たいだろう": "推量の形なので、名詞「床」を直接修飾できず、文が成り立たない。", "冷たいから": "理由を表す接続形なので、名詞「床」を直接修飾できず、文が成り立たない。", "冷たさ": "名詞なので、「冷たさ床」と形容詞の連体形として続かず成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36560, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「粘膜が弱くなる」の「が」。「弱くなる」の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「粘膜を弱くなる」は、自動詞「弱くなる」が目的語を取れないため誤り。"}, {"text": "で", "is_correct": false, "explanation": "「粘膜で弱くなる」は手段や原因の「で」として文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「粘膜の弱くなると」は「粘膜」が主語として成り立たず、文が不自然になる。"}], "correct_answer": "が", "explanations": {"が": "「粘膜が弱くなる」の「が」。「弱くなる」の主語を示す格助詞。", "を": "「粘膜を弱くなる」は、自動詞「弱くなる」が目的語を取れないため誤り。", "で": "「粘膜で弱くなる」は手段や原因の「で」として文が成り立たない。", "の": "「粘膜の弱くなると」は「粘膜」が主語として成り立たず、文が不自然になる。"}, "error_tags": {"を": "object", "で": "means", "の": "possessive"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36560, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「口の粘膜にぬって使う」の「に」。ぬる先（粘膜）を示す格助詞。"}, {"text": "が", "is_correct": false, "explanation": "「粘膜がぬって使う」は粘膜が主語になり、「ぬる」の対象として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「粘膜とぬって」は文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「粘膜からぬって」は起点を示すことになり、ぬる先を表せないので不自然。"}], "correct_answer": "に", "explanations": {"に": "「口の粘膜にぬって使う」の「に」。ぬる先（粘膜）を示す格助詞。", "が": "「粘膜がぬって使う」は粘膜が主語になり、「ぬる」の対象として成り立たない。", "と": "「粘膜とぬって」は文が成り立たない。", "から": "「粘膜からぬって」は起点を示すことになり、ぬる先を表せないので不自然。"}, "error_tags": {"が": "subject", "と": "with", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36560, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "体の内側の表面をおおい、粘液を出す薄い組織。", "primary_collocate": null, "pronunciation": "ねんまく", "ipa": "nemmakɯ", "syllable_count": 4, "sentences": [{"text": "胃の内側は、やわらかい粘膜でおおわれている。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "胃[い]の内側[うちがわ]は、やわらかい粘膜[ねんまく]でおおわれている。", "sentence_source": "generated"}, {"text": "鼻の粘膜が弱くなると、くしゃみが出やすくなる。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "鼻(はな)の粘膜(ねんまく)が弱(よわ)くなると、くしゃみが出(で)やすくなる。", "sentence_source": "generated"}, {"text": "辛すぎる食べ物は、胃の粘膜を傷つけることがある。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "辛(から)すぎる食(た)べ物(もの)は、胃(い)の粘膜(ねんまく)を傷(きず)つけることがある。", "sentence_source": "generated"}, {"text": "医者はカメラで、のどの粘膜の色を調べた。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "医者(いしゃ)はカメラで、のどの粘膜(ねんまく)の色(いろ)を調(しら)べた。", "sentence_source": "generated"}, {"text": "粘膜は皮膚よりもうすく、傷つきやすい。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "粘膜(ねんまく)は皮膚(ひふ)よりもうすく、傷(きず)つきやすい。", "sentence_source": "generated"}, {"text": "乾いた空気のせいで、鼻の粘膜が荒れてしまった。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "乾(かわ)いた空気(くうき)のせいで、鼻(はな)の粘膜(ねんまく)が荒(あ)れてしまった。", "sentence_source": "generated"}, {"text": "目の粘膜が赤くなっていたので、眼科に行った。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "目(め)の粘膜(ねんまく)が赤(あか)くなっていたので、眼科(がんか)に行(い)った。", "sentence_source": "generated"}, {"text": "この薬は、口の粘膜にぬって使います。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "この薬(くすり)は、口(くち)の粘膜(ねんまく)にぬって使(つか)います。", "sentence_source": "generated"}, {"text": "強いお酒を飲みすぎると、胃の粘膜が荒れる。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "強(つよ)いお酒(さけ)を飲(の)みすぎると、胃(い)の粘膜(ねんまく)が荒(あ)れる。", "sentence_source": "generated"}, {"text": "腸の粘膜から、体は栄養を吸収する。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "腸(ちょう)の粘膜(ねんまく)から、体(からだ)は栄養(えいよう)を吸収(きゅうしゅう)する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "粘膜", "label": "基本形"}], "register": "中立", "sense_fingerprint": "胃・鼻・のどなど体の内側の表面をおおう薄い層（粘膜）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c807979d-24e5-4686-b553-a0ab630f3395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36560, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粘膜", "is_correct": true, "explanation": "「やわらかい粘膜でおおわれている」の「粘膜」。体の内側の表面をおおう薄い層。"}, {"text": "骨", "is_correct": false, "explanation": "「骨」は硬い組織で、「やわらかい骨でおおわれている」とは言わない。"}, {"text": "血管", "is_correct": false, "explanation": "「血管」は血液が流れる管で、胃の内側をおおう層ではない。"}, {"text": "爪", "is_correct": false, "explanation": "「爪」は指先の硬い部分で、胃の内側をおおうものではない。"}], "explanations": {"粘膜": "「やわらかい粘膜でおおわれている」の「粘膜」。体の内側の表面をおおう薄い層。", "骨": "「骨」は硬い組織で、「やわらかい骨でおおわれている」とは言わない。", "血管": "「血管」は血液が流れる管で、胃の内側をおおう層ではない。", "爪": "「爪」は指先の硬い部分で、胃の内側をおおうものではない。"}, "sentence_index": 0, "correct_answer": "粘膜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の強い日差しで、粘膜が焼けて赤くなった。", "explanation": "ここは「皮膚」の話として自然。粘膜は体の内側の層なので、日焼けする文には合わない。"}, {"text": "鼻から透明な粘膜が出てきた。", "explanation": "ここは「粘液」の話として自然。粘膜は組織そのものなので、外に出てくるものではない。"}, {"text": "食事の前に、粘膜がたくさん出てくる。", "explanation": "ここは「唾液」の話として自然。粘膜は分泌される物ではないので、この文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36560, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粘膜", "is_correct": true, "explanation": "「目の粘膜が赤くなっていた」の「粘膜」。目の表面の内側をおおう層。"}, {"text": "軟骨", "is_correct": false, "explanation": "「軟骨」は関節などにある組織で、目の表面が赤くなる話には合わない。"}, {"text": "脂肪", "is_correct": false, "explanation": "「脂肪」は脂の組織で、赤くなるものとしては不自然。"}, {"text": "骨", "is_correct": false, "explanation": "「骨」は硬い組織で、目の表面が赤くなるものではない。"}], "explanations": {"粘膜": "「目の粘膜が赤くなっていた」の「粘膜」。目の表面の内側をおおう層。", "軟骨": "「軟骨」は関節などにある組織で、目の表面が赤くなる話には合わない。", "脂肪": "「脂肪」は脂の組織で、赤くなるものとしては不自然。", "骨": "「骨」は硬い組織で、目の表面が赤くなるものではない。"}, "sentence_index": 6, "correct_answer": "粘膜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "かかとの粘膜をけずると、すべすべになる。", "explanation": "ここは「角質」の話として自然。粘膜は体の内側の層なので、かかとをけずる文には合わない。"}, {"text": "皮脂が毛穴をふさぐと、粘膜がふえてニキビになる。", "explanation": "ここは「皮脂」の話として自然。粘膜は毛穴をふさぐ物ではないので、この文では合わない。"}, {"text": "粘膜で人形を作った。", "explanation": "ここは「粘土」の意味。粘膜は体の内側の組織で、人形を作る材料にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36560, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "胃の粘膜で荒れると、痛みを感じやすい。", "corrected_sentence": "胃の粘膜が荒れると、痛みを感じやすい。", "error_description": "「粘膜が荒れる」の「が」が正しい。「で」は手段を表し、主語の位置には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36560, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "喉の粘膜を、乾燥すると傷つきやすい。", "corrected_sentence": "喉の粘膜は、乾燥すると傷つきやすい。", "error_description": "「粘膜は」と主題を示す「は」が正しい。「粘膜を」は目的語になり、文の述語と合わないため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36561, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『乾きにくくなる』の主語を示す『が』。『粘膜が乾きにくくなる』で文が成り立つ。"}, {"text": "に", "is_correct": false, "explanation": "位置や方向を示すが、『粘膜に乾きにくくなる』は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示すが、『粘膜と乾きにくくなる』では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、『粘膜へ乾きにくくなる』は誤りで、この文の形に合わない。"}], "correct_answer": "が", "explanations": {"が": "『乾きにくくなる』の主語を示す『が』。『粘膜が乾きにくくなる』で文が成り立つ。", "に": "位置や方向を示すが、『粘膜に乾きにくくなる』は文として成り立たない。", "と": "並列や相手を示すが、『粘膜と乾きにくくなる』では意味が通らない。", "へ": "方向を示すが、『粘膜へ乾きにくくなる』は誤りで、この文の形に合わない。"}, "error_tags": {"に": "dative_locative", "と": "comitative", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36561, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『粘膜には』の『に』。ここでは粘膜に役割があることを示し、文の形に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、『粘膜が は』と後続の『は』が続かず、文の形が合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、『役割を』では『ある』の目的語にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、ここは比べる文ではないので合わない。"}], "correct_answer": "に", "explanations": {"に": "『粘膜には』の『に』。ここでは粘膜に役割があることを示し、文の形に合う。", "が": "主語を示すが、『粘膜が は』と後続の『は』が続かず、文の形が合わない。", "を": "目的語を示すが、『役割を』では『ある』の目的語にならず、文が成り立たない。", "より": "比較を示すが、ここは比べる文ではないので合わない。"}, "error_tags": {"が": "subject_case", "を": "object_case", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36561, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "口や鼻、胃など、体の中の表面を覆っている薄い膜のこと。つねに湿っていて、細菌やウイルスから体を守る役割もある。", "primary_collocate": null, "pronunciation": "ねんまく", "ipa": "nemmakɯ", "syllable_count": 4, "sentences": [{"text": "粘膜はいつも湿っていて、細菌が体に入るのを防いでくれる。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "粘膜(ねんまく)はいつも湿(しめ)っていて、細菌(さいきん)が体(からだ)に入(はい)るのを防(ふせ)いでくれる。", "sentence_source": "generated"}, {"text": "マスクをすると、のどの粘膜が乾きにくくなる。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "マスクをすると、のどの粘膜(ねんまく)が乾(かわ)きにくくなる。", "sentence_source": "generated"}, {"text": "ウイルスは、鼻や口の粘膜から体に入りやすい。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "ウイルスは、鼻(はな)や口(くち)の粘膜(ねんまく)から体(からだ)に入(はい)りやすい。", "sentence_source": "generated"}, {"text": "粘膜が乾くと、守る力が弱まって風邪をひきやすくなる。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "粘膜(ねんまく)が乾(かわ)くと、守(まも)る力(ちから)が弱(よわ)まって風邪(かぜ)をひきやすくなる。", "sentence_source": "generated"}, {"text": "鼻の粘膜を守るために、部屋の湿度を保つようにしている。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "鼻(はな)の粘膜(ねんまく)を守(まも)るために、部屋(へや)の湿度(しつど)を保(たも)つようにしている。", "sentence_source": "generated"}, {"text": "口の中の粘膜にできた傷は、熱いものがしみて痛い。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "口(くち)の中(なか)の粘膜(ねんまく)にできた傷(きず)は、熱(あつ)いものがしみて痛(いた)い。", "sentence_source": "generated"}, {"text": "手を洗わずに目をこすると、粘膜からウイルスが入ることがある。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "手(て)を洗(あら)わずに目(め)をこすると、粘膜(ねんまく)からウイルスが入(はい)ることがある。", "sentence_source": "generated"}, {"text": "粘膜には体を守る役割があると、授業で習った。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "粘膜(ねんまく)には体(からだ)を守(まも)る役割(やくわり)があると、授業(じゅぎょう)で習(なら)った。", "sentence_source": "generated"}, {"text": "うがいをして、のどの粘膜についた汚れを洗い流す。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "うがいをして、のどの粘膜(ねんまく)についた汚(よご)れを洗(あら)い流(なが)す。", "sentence_source": "generated"}, {"text": "胃の粘膜は、胃液から胃そのものを守っている。", "target_word": "粘膜", "complexity_tier": "T3", "furigana": "胃(い)の粘膜(ねんまく)は、胃液(いえき)から胃(い)そのものを守(まも)っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "粘膜", "label": "基本形"}], "register": "中立", "sense_fingerprint": "つねに湿っていて、細菌やウイルスから体を守る、口・鼻・胃などの薄い膜（粘膜）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c807979d-24e5-4686-b553-a0ab630f3395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36561, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粘膜", "is_correct": true, "explanation": "体の内側を覆う湿った膜で、細菌の侵入を防ぐ役割を持つ。文の『いつも湿っていて』『体に入るのを防いで』と一致する。"}, {"text": "血液", "is_correct": false, "explanation": "血管の中を流れる液体で、体を覆う膜ではない。『細菌が体に入るのを防ぐ』膜の働きは持たないので合わない。"}, {"text": "軟骨", "is_correct": false, "explanation": "関節などにある弾力のある組織で、湿った膜ではない。『いつも湿っていて』に合わない。"}, {"text": "骨格", "is_correct": false, "explanation": "体を支える骨の組み合わせのことで、湿っている膜ではない。細菌を防ぐ役割の説明に合わない。"}], "explanations": {"粘膜": "体の内側を覆う湿った膜で、細菌の侵入を防ぐ役割を持つ。文の『いつも湿っていて』『体に入るのを防いで』と一致する。", "血液": "血管の中を流れる液体で、体を覆う膜ではない。『細菌が体に入るのを防ぐ』膜の働きは持たないので合わない。", "軟骨": "関節などにある弾力のある組織で、湿った膜ではない。『いつも湿っていて』に合わない。", "骨格": "体を支える骨の組み合わせのことで、湿っている膜ではない。細菌を防ぐ役割の説明に合わない。"}, "sentence_index": 0, "correct_answer": "粘膜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "粘膜をこねて、小さな器を作った。", "explanation": "粘膜は体の内側の膜で、こねて器を作る材料ではないので合わない。"}, {"text": "ひじの粘膜を毎晩こすって落とした。", "explanation": "ここは〈角質〉の意味。古くなった皮膚の角質を落とす話で、粘膜は口や鼻など体の内側の膜なので、ひじにはないものとして合わない。"}, {"text": "体の外側で日光を浴びる部分を、粘膜が覆っている。", "explanation": "ここは〈皮膚〉の意味。体の外側を覆うのは皮膚で、粘膜は口・鼻など内側の湿った膜を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36561, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粘膜", "is_correct": true, "explanation": "目や鼻・口の内側の膜で、ここからウイルスが体に入る。文の『目をこすると』と合う。"}, {"text": "神経", "is_correct": false, "explanation": "体の情報を伝える器官で、ウイルスの侵入経路にはならない。『からウイルスが入る』に合わない。"}, {"text": "筋肉", "is_correct": false, "explanation": "体を動かす組織で、ウイルスが入る場所ではない。文の意味に合わない。"}, {"text": "髪", "is_correct": false, "explanation": "頭から生える毛で、ウイルスの侵入経路ではない。『目をこすると』からは続かない。"}], "explanations": {"粘膜": "目や鼻・口の内側の膜で、ここからウイルスが体に入る。文の『目をこすると』と合う。", "神経": "体の情報を伝える器官で、ウイルスの侵入経路にはならない。『からウイルスが入る』に合わない。", "筋肉": "体を動かす組織で、ウイルスが入る場所ではない。文の意味に合わない。", "髪": "頭から生える毛で、ウイルスの侵入経路ではない。『目をこすると』からは続かない。"}, "sentence_index": 6, "correct_answer": "粘膜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この粘膜は強くくっつくので、壁の掲示物を留めるのに向いている。", "explanation": "粘膜は体の内側を覆う組織で、物を留める材料ではないので合わない。"}, {"text": "風邪をひくと、鼻から出た粘膜をティッシュで拭く。", "explanation": "ここは〈粘液〉の意味。鼻から出てくるねばつく液を指し、膜そのものが出てくるわけではないので合わない。"}, {"text": "寝ている間は粘膜が減るので、朝に口の中がねばつく。", "explanation": "ここは〈唾液〉の意味。口の中の量が減ってねばつくのは唾液で、粘膜は量が増減するものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36561, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鼻の粘膜に守るために、加湿器を使っている。", "corrected_sentence": "鼻の粘膜を守るために、加湿器を使っている。", "error_description": "『守る』は目的語を『を』で取る。『粘膜に』は誤りで、正しくは『粘膜を守る』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36561, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "喉の粘膜を傷つくと、風邪をひきやすくなる。", "corrected_sentence": "喉の粘膜が傷つくと、風邪をひきやすくなる。", "error_description": "『傷つく』は主語を『が』で示す自動詞。『粘膜を傷つく』は誤りで、正しくは『粘膜が傷つく』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
