INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36562, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "病気や気持ちが、人から他の人へうつること。", "primary_collocate": null, "pronunciation": "でんせん", "ipa": "deɴseɴ", "syllable_count": 4, "sentences": [{"text": "風邪は人から人へ伝染することがある。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "風邪[かぜ]は人[ひと]から人[ひと]へ伝染[でんせん]することがある。", "sentence_source": "generated"}, {"text": "マスクをして、病気の伝染を防いだ。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "マスクをして、病気[びょうき]の伝染[でんせん]を防[ふせ]いだ。", "sentence_source": "generated"}, {"text": "あくびが友達に伝染して、みんな眠くなった。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "あくびが友達[ともだち]に伝染[でんせん]して、みんな眠[ねむ]くなった。", "sentence_source": "generated"}, {"text": "子どもの病気が、家族に伝染した。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "子[こ]どもの病気[びょうき]が、家族[かぞく]に伝染[でんせん]した。", "sentence_source": "generated"}, {"text": "咳をする人の近くにいると、伝染しやすい。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "咳[せき]をする人[ひと]の近[ちか]くにいると、伝染[でんせん]しやすい。", "sentence_source": "generated"}, {"text": "伝染を心配して、彼は学校を休んだ。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "伝染[でんせん]を心配[しんぱい]して、彼[かれ]は学校[がっこう]を休[やす]んだ。", "sentence_source": "generated"}, {"text": "彼女の笑いは周りに伝染して、教室が明るくなった。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の笑[わら]いは周[まわ]りに伝染[でんせん]して、教室[きょうしつ]が明[あか]るくなった。", "sentence_source": "generated"}, {"text": "手を洗えば、病気の伝染を減らせる。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "手[て]を洗[あら]えば、病気[びょうき]の伝染[でんせん]を減[へ]らせる。", "sentence_source": "generated"}, {"text": "動物から人に伝染する病気もある。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "動物[どうぶつ]から人[ひと]に伝染[でんせん]する病気[びょうき]もある。", "sentence_source": "generated"}, {"text": "先生の緊張が生徒に伝染してしまった。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "先生[せんせい]の緊張[きんちょう]が生徒[せいと]に伝染[でんせん]してしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝染する", "label": "終止形"}, {"form": "伝染した", "label": "過去形"}, {"form": "伝染して", "label": "て形"}, {"form": "伝染しない", "label": "否定形"}], "register": "普通体", "sense_fingerprint": "病気や気持ちが人から人へうつること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df666cf-660e-4a65-8685-1c7e60c94a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36562, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伝染", "is_correct": true, "explanation": "正解。風邪が人から人へうつるという文脈に合い、伝染することがあると続く。"}, {"text": "運転", "is_correct": false, "explanation": "風邪が人から人へ運転するとは言えず、文が成り立たない。"}, {"text": "散歩", "is_correct": false, "explanation": "風邪は散歩しないので、この文脈では合わない。"}, {"text": "料理", "is_correct": false, "explanation": "風邪が料理することはないので文が成り立たない。"}], "explanations": {"伝染": "正解。風邪が人から人へうつるという文脈に合い、伝染することがあると続く。", "運転": "風邪が人から人へ運転するとは言えず、文が成り立たない。", "散歩": "風邪は散歩しないので、この文脈では合わない。", "料理": "風邪が料理することはないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "伝染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は明日の予定を伝染でみんなに伝えた。", "explanation": "ここは情報を届ける意味。伝染は病気や気持ちが人にうつることで、伝言の意味では使わない。"}, {"text": "金属は熱をよく伝染する。", "explanation": "熱を伝える意味は〈伝導〉。伝染は病気や気持ちがうつることに使うので、この定義と合わない。"}, {"text": "音が壁を伝染して、隣の部屋に聞こえた。", "explanation": "音が伝わる意味で使っている。人や病気がうつるという伝染の定義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36562, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伝染", "is_correct": true, "explanation": "正解。笑いが周りにうつるという文脈で、伝染して教室が明るくなったと続く。"}, {"text": "反省", "is_correct": false, "explanation": "反省が周りに広がるとは言えず、文が成り立たない。"}, {"text": "録音", "is_correct": false, "explanation": "録音は周りに広がるものではないので合わない。"}, {"text": "清掃", "is_correct": false, "explanation": "清掃が周りにうつるとは言えない。"}], "explanations": {"伝染": "正解。笑いが周りにうつるという文脈で、伝染して教室が明るくなったと続く。", "反省": "反省が周りに広がるとは言えず、文が成り立たない。", "録音": "録音は周りに広がるものではないので合わない。", "清掃": "清掃が周りにうつるとは言えない。"}, "sentence_index": 6, "correct_answer": "伝染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "荷物は昨日、伝染された。", "explanation": "配達の代わりに伝染を置くと、物を届ける意味になる。伝染は人や病気がうつる意味で、物には使わない。"}, {"text": "私は切符を伝染した。", "explanation": "ここは〈渡す〉の意味。伝染は病気や気持ちがうつることで、物を人に渡す意味では使わない。"}, {"text": "この祭りは伝染を守ってきた。", "explanation": "伝統は受け継がれる習わしで守る対象になる。伝染は病気や気持ちのうつることなので、守る対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36562, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風邪は子どもから大人を伝染することがある。", "corrected_sentence": "風邪は子どもから大人に伝染することがある。", "error_description": "伝染するは相手を「に」で取る。「を」は誤りで、正しくは「大人に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36562, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の笑いは周りに伝染する、教室が明るくなった。", "corrected_sentence": "彼の笑いは周りに伝染して、教室が明るくなった。", "error_description": "「伝染して」と続けるべき所を終止形の「伝染する」にしている。て形で文をつなぐ必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
