INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36563, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "病気や行動・反応などが、あるものから他のものへと広がる現象。", "primary_collocate": null, "pronunciation": "でんせん", "ipa": "deɴseɴ", "syllable_count": 4, "sentences": [{"text": "町の中で病気の伝染が急に進んだ。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "町[まち]の中[なか]で病気[びょうき]の伝染[でんせん]が急[きゅう]に進[すす]んだ。", "sentence_source": "generated"}, {"text": "不安は伝染するので、落ち着いて話した方がいい。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "不安[ふあん]は伝染[でんせん]するので、落[お]ち着[つ]いて話[はな]した方[ほう]がいい。", "sentence_source": "generated"}, {"text": "笑いの伝染は、人を元気にする力がある。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "笑[わら]いの伝染[でんせん]は、人[ひと]を元気[げんき]にする力[ちから]がある。", "sentence_source": "generated"}, {"text": "研究者は、ウイルスの伝染の速さを調べた。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]は、ウイルスの伝染[でんせん]の速[はや]さを調[しら]べた。", "sentence_source": "generated"}, {"text": "学校では、伝染を防ぐために窓を開けている。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "学校[がっこう]では、伝染[でんせん]を防[ふせ]ぐために窓[まど]を開[あ]けている。", "sentence_source": "generated"}, {"text": "一人の泣き声が伝染して、赤ちゃん全員が泣き出した。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "一人[ひとり]の泣[な]き声[ごえ]が伝染[でんせん]して、赤[あか]ちゃん全員[ぜんいん]が泣[な]き出[だ]した。", "sentence_source": "generated"}, {"text": "恐怖の伝染を止めるには、正しい情報が必要だ。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "恐怖[きょうふ]の伝染[でんせん]を止[と]めるには、正[ただ]しい情報[じょうほう]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "あくびの伝染は、人間だけでなく犬にも見られる。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "あくびの伝染[でんせん]は、人間[にんげん]だけでなく犬[いぬ]にも見[み]られる。", "sentence_source": "generated"}, {"text": "病気が動物から別の動物へ伝染する経路を調べる。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "病気[びょうき]が動物[どうぶつ]から別[べつ]の動物[どうぶつ]へ伝染[でんせん]する経路[けいろ]を調[しら]べる。", "sentence_source": "generated"}, {"text": "彼のやる気がチーム全体に伝染して、成績が上がった。", "target_word": "伝染", "complexity_tier": "T3", "furigana": "彼[かれ]のやる気[き]がチーム全体[ぜんたい]に伝染[でんせん]して、成績[せいせき]が上[あ]がった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝染する", "label": "終止形"}, {"form": "伝染した", "label": "過去形"}, {"form": "伝染して", "label": "て形"}, {"form": "伝染しない", "label": "否定形"}], "register": "普通体", "sense_fingerprint": "病気・行動・反応が次々に広がる現象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df666cf-660e-4a65-8685-1c7e60c94a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36563, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伝染", "is_correct": true, "explanation": "病気が人から人へ広がる意味で、「急に進んだ」広がりを表すので文に合う。"}, {"text": "発酵", "is_correct": false, "explanation": "微生物が糖などを分解する現象で、病気が広がる文脈には合わない。"}, {"text": "伝記", "is_correct": false, "explanation": "ある人の生涯を書いた本のことで、病気の進み方とは結びつかない。"}, {"text": "売買", "is_correct": false, "explanation": "品物や権利を売り買いすることで、病気の広がりには当てはまらない。"}], "explanations": {"伝染": "病気が人から人へ広がる意味で、「急に進んだ」広がりを表すので文に合う。", "発酵": "微生物が糖などを分解する現象で、病気が広がる文脈には合わない。", "伝記": "ある人の生涯を書いた本のことで、病気の進み方とは結びつかない。", "売買": "品物や権利を売り買いすることで、病気の広がりには当てはまらない。"}, "sentence_index": 0, "correct_answer": "伝染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風で電線が伝染して、町が停電した。", "explanation": "ここは〈通電〉（電気が流れて伝わること）の意味。伝染は病気や行動などが広がることを指すので、電気の流れには使わない。"}, {"text": "音は空気の振動として周囲に伝染する。", "explanation": "ここは〈伝播〉（波や影響が広がって伝わること）の意味。音の広がりには伝染を使わず、伝播や伝わるを使う。"}, {"text": "金属は熱が伝染しやすいので、調理器具に使われる。", "explanation": "ここは〈伝導〉（熱や電気が物質の中を伝わること）の意味。伝染は病気などの広がりを表すので、熱の移動には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36563, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伝染", "is_correct": true, "explanation": "恐怖が人から人へ広がる意味で、「止める」対象として文に合う。"}, {"text": "採掘", "is_correct": false, "explanation": "地下の資源を掘り出すことで、恐怖の広がりには使わず合わない。"}, {"text": "製粉", "is_correct": false, "explanation": "穀物などを粉にすることで、恐怖の文脈には当てはまらない。"}, {"text": "解剖", "is_correct": false, "explanation": "生物の体を切り開いて調べることで、恐怖を止める文脈には合わない。"}], "explanations": {"伝染": "恐怖が人から人へ広がる意味で、「止める」対象として文に合う。", "採掘": "地下の資源を掘り出すことで、恐怖の広がりには使わず合わない。", "製粉": "穀物などを粉にすることで、恐怖の文脈には当てはまらない。", "解剖": "生物の体を切り開いて調べることで、恐怖を止める文脈には合わない。"}, "sentence_index": 6, "correct_answer": "伝染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "歩いていたら、ストッキングが伝染した。", "explanation": "ここは〈伝線〉（ストッキングの編み目がほどけて線状に裂けること）の意味。伝染は病気などの広がりなので、ストッキングには合わない。"}, {"text": "その製法は祖父から孫へ伝染してきた。", "explanation": "ここは〈伝承〉（技術や習慣を次の世代へ受け継ぐこと）の意味。伝染は病気や行動が広がることで、製法の受け継ぎには使わない。"}, {"text": "映像は衛星から地上へ伝染する。", "explanation": "ここは〈伝送〉（電波や信号を送ること）の意味。映像の送信には伝染を使わず、伝送を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36563, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風邪は、マスクをしないと人を伝染しやすい。", "corrected_sentence": "風邪は、マスクをしないと人に伝染しやすい。", "error_description": "「伝染する」は「人に伝染する」と相手に「に」を付ける。「人を伝染」の「を」は誤りで、「に」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36563, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもの間で水ぼうそうが伝染しで、クラス全体が休んだ。", "corrected_sentence": "子どもの間で水ぼうそうが伝染して、クラス全体が休んだ。", "error_description": "て形は「伝染して」が正しい。「伝染しで」は濁音の誤りで、活用形として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
