INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36564, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ものがいつも持っている、特別なようすのこと。", "primary_collocate": null, "pronunciation": "せいしつ", "ipa": "seːɕitsɯ", "syllable_count": 4, "sentences": [{"text": "水の性質を学んだ。", "target_word": "性質", "complexity_tier": "T1", "furigana": "水[みず]の性質[せいしつ]を学[まな]んだ。", "sentence_source": "generated"}, {"text": "この石は柔らかい性質がある。", "target_word": "性質", "complexity_tier": "T3", "furigana": "この石[いし]は柔[やわ]らかい性質[せいしつ]がある。", "sentence_source": "generated"}, {"text": "ゴムは伸びる性質を持っています。", "target_word": "性質", "complexity_tier": "T3", "furigana": "ゴムは伸[の]びる性質[せいしつ]を持[も]っています。", "sentence_source": "generated"}, {"text": "犬は人になつく性質がある。", "target_word": "性質", "complexity_tier": "T3", "furigana": "犬[いぬ]は人[ひと]になつく性質[せいしつ]がある。", "sentence_source": "generated"}, {"text": "性質が違うので、混ぜられない。", "target_word": "性質", "complexity_tier": "T3", "furigana": "性質[せいしつ]が違[ちが]うので、混[ま]ぜられない。", "sentence_source": "generated"}, {"text": "氷は水に浮く性質がある。", "target_word": "性質", "complexity_tier": "T2", "furigana": "氷[こおり]は水[みず]に浮[う]く性質[せいしつ]がある。", "sentence_source": "generated"}, {"text": "鉄はさびやすい性質です。", "target_word": "性質", "complexity_tier": "T2", "furigana": "鉄[てつ]はさびやすい性質[せいしつ]です。", "sentence_source": "generated"}, {"text": "油の性質を調べます。", "target_word": "性質", "complexity_tier": "T2", "furigana": "油[あぶら]の性質[せいしつ]を調[しら]べます。", "sentence_source": "generated"}, {"text": "性質の違いを見つけた。", "target_word": "性質", "complexity_tier": "T3", "furigana": "性質[せいしつ]の違[ちが]いを見[み]つけた。", "sentence_source": "generated"}, {"text": "熱で変わる性質もあります。", "target_word": "性質", "complexity_tier": "T3", "furigana": "熱[ねつ]で変[か]わる性質[せいしつ]もあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "性質上", "label": "派生"}, {"form": "性質的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ものがいつも持つ特別なようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb16110-7121-4281-9462-fbd42844389b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36564, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "性質", "is_correct": true, "explanation": "見出し語「せいしつ」そのもの。"}, {"text": "誠実", "is_correct": false, "explanation": "「せいじつ」で、し→じの一拍だけ違う。"}, {"text": "正式", "is_correct": false, "explanation": "「せいしき」で、つ→きの一拍だけ違う。"}, {"text": "精神", "is_correct": false, "explanation": "「せいしん」で、つ→んの一拍だけ違う。"}, {"text": "体質", "is_correct": false, "explanation": "「たいしつ」で、せ→たの一拍だけ違う。"}, {"text": "水質", "is_correct": false, "explanation": "「すいしつ」で、せ→すの一拍だけ違う。"}], "explanations": {"性質": "見出し語「せいしつ」そのもの。", "誠実": "「せいじつ」で、し→じの一拍だけ違う。", "正式": "「せいしき」で、つ→きの一拍だけ違う。", "精神": "「せいしん」で、つ→んの一拍だけ違う。", "体質": "「たいしつ」で、せ→たの一拍だけ違う。", "水質": "「すいしつ」で、せ→すの一拍だけ違う。"}, "sentence_index": null, "correct_answer": "性質"}, "level_3": {"options": [{"text": "性質", "is_correct": true, "explanation": "水が持つ特別なようすを学ぶ意味に合う。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、水の約束を学ぶのは意味が合わない。"}, {"text": "機嫌", "is_correct": false, "explanation": "形は合うが、水の機嫌を学ぶのは意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、水の天気を学ぶのは意味が合わない。"}], "explanations": {"性質": "水が持つ特別なようすを学ぶ意味に合う。", "約束": "形は合うが、水の約束を学ぶのは意味が合わない。", "機嫌": "形は合うが、水の機嫌を学ぶのは意味が合わない。", "天気": "形は合うが、水の天気を学ぶのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "性質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犬は性質を食べて元気になった。", "explanation": "「性質」は食べ物ではないので、食べる対象にならない。"}, {"text": "性質は駅の前で私を待っている。", "explanation": "「性質」は人のように待つ主体にならない。"}, {"text": "毎朝、性質に乗って学校へ行く。", "explanation": "「性質」は乗り物ではないので、乗る対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
