INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36565, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "物事が本来備えている、他と区別される特徴や傾向。", "primary_collocate": null, "pronunciation": "せいしつ", "ipa": "seːɕitsɯ", "syllable_count": 4, "sentences": [{"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "性質", "complexity_tier": "T6", "furigana": "再生可能[さいせいかのう]エネルギーの導入[どうにゅう]加速[かそく]にもかかわらず、製造[せいぞう]プロセスの性質上[せいしつじょう]、炭素[たんそ]発生[はっせい]をゼロ化[か]し得[え]ない領域[りょういき]において、CCUSは極[きわ]めて重要[じゅうよう]な役割[やくわり]を担[にな]う。", "sentence_source": "mined"}, {"text": "この金属は熱を通しやすい性質がある。", "target_word": "性質", "complexity_tier": "T3", "furigana": "この金属[きんぞく]は熱[ねつ]を通[とお]しやすい性質[せいしつ]がある。", "sentence_source": "generated"}, {"text": "水には、温度で形が変わる性質がある。", "target_word": "性質", "complexity_tier": "T3", "furigana": "水[みず]には、温度[おんど]で形[かたち]が変[か]わる性質[せいしつ]がある。", "sentence_source": "generated"}, {"text": "金はさびにくい性質の金属だ。", "target_word": "性質", "complexity_tier": "T3", "furigana": "金[きん]はさびにくい性質[せいしつ]の金属[きんぞく]だ。", "sentence_source": "generated"}, {"text": "性質が違う二つの薬を混ぜてはいけない。", "target_word": "性質", "complexity_tier": "T4", "furigana": "性質[せいしつ]が違[ちが]う二[ふた]つの薬[くすり]を混[ま]ぜてはいけない。", "sentence_source": "generated"}, {"text": "油と水は性質が異なる。", "target_word": "性質", "complexity_tier": "T3", "furigana": "油[あぶら]と水[みず]は性質[せいしつ]が異[こと]なる。", "sentence_source": "generated"}, {"text": "物の性質を調べる実験をした。", "target_word": "性質", "complexity_tier": "T3", "furigana": "物[もの]の性質[せいしつ]を調[しら]べる実験[じっけん]をした。", "sentence_source": "generated"}, {"text": "この布は水をはじく性質を持っている。", "target_word": "性質", "complexity_tier": "T3", "furigana": "この布[ぬの]は水[みず]をはじく性質[せいしつ]を持[も]っている。", "sentence_source": "generated"}, {"text": "性質を変えると、使い道も変わる。", "target_word": "性質", "complexity_tier": "T4", "furigana": "性質[せいしつ]を変[か]えると、使[つか]い道[みち]も変[か]わる。", "sentence_source": "generated"}, {"text": "性質の似た植物を集めた。", "target_word": "性質", "complexity_tier": "T3", "furigana": "性質[せいしつ]の似[に]た植物[しょくぶつ]を集[あつ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "性質上", "label": "派生"}, {"form": "性質的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が本来備える特徴や傾向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb16110-7121-4281-9462-fbd42844389b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
