INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36567, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『隣りの友だち』の所属を示す『の』。隣りにいる友だちという意味で文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、『隣りが友だち』は意味が通らず文の形に合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、『隣りを友だち』は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、『隣りへ友だち』は文の中で意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "『隣りの友だち』の所属を示す『の』。隣りにいる友だちという意味で文が成り立つ。", "が": "主語を示すが、『隣りが友だち』は意味が通らず文の形に合わない。", "を": "目的語を示すが、『隣りを友だち』は文として成り立たない。", "へ": "方向を示すが、『隣りへ友だち』は文の中で意味が通らない。"}, "error_tags": {"が": "subject_case", "を": "object_case", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36567, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "座る位置を示す『に』。『隣りに座ってもいいですか』で文が成り立つ。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示すが、『隣りと座る』は位置の文として意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示すが、ここは比べる文ではないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、『隣りから座る』は座る位置を表せず、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "座る位置を示す『に』。『隣りに座ってもいいですか』で文が成り立つ。", "と": "相手や並列を示すが、『隣りと座る』は位置の文として意味が通らない。", "より": "比較を示すが、ここは比べる文ではないので合わない。", "から": "起点を示すが、『隣りから座る』は座る位置を表せず、意味が通らない。"}, "error_tags": {"と": "comitative", "より": "comparison", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36567, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あるもののすぐ横の位置。", "primary_collocate": null, "pronunciation": "となり", "ipa": "tonaɾi", "syllable_count": 3, "sentences": [{"text": "電車で、知らない人が私の隣りに座った。", "target_word": "隣り", "complexity_tier": "T3", "furigana": "電車(でんしゃ)で、知(し)らない人(ひと)が私(わたし)の隣(とな)りに座(すわ)った。", "sentence_source": "generated"}, {"text": "授業中、隣りの友だちが小さな声で話しかけてきた。", "target_word": "隣り", "complexity_tier": "T3", "furigana": "授業中(じゅぎょうちゅう)、隣(とな)りの友(とも)だちが小(ちい)さな声(こえ)で話(はな)しかけてきた。", "sentence_source": "generated"}, {"text": "私の隣りの席は、今日は空いています。", "target_word": "隣り", "complexity_tier": "T3", "furigana": "私(わたし)の隣(とな)りの席(せき)は、今日(きょう)は空(あ)いています。", "sentence_source": "generated"}, {"text": "写真では、母の隣りに立っているのが私です。", "target_word": "隣り", "complexity_tier": "T3", "furigana": "写真(しゃしん)では、母(はは)の隣(とな)りに立(た)っているのが私(わたし)です。", "sentence_source": "generated"}, {"text": "映画館で、恋人の隣りに座って映画を見た。", "target_word": "隣り", "complexity_tier": "T3", "furigana": "映画館(えいがかん)で、恋人(こいびと)の隣(とな)りに座(すわ)って映画(えいが)を見(み)た。", "sentence_source": "generated"}, {"text": "緊張していたとき、先生が隣りにいてくれて安心した。", "target_word": "隣り", "complexity_tier": "T3", "furigana": "緊張(きんちょう)していたとき、先生(せんせい)が隣(とな)りにいてくれて安心(あんしん)した。", "sentence_source": "generated"}, {"text": "姉の隣りで寝ると、いつもあたたかい。", "target_word": "隣り", "complexity_tier": "T3", "furigana": "姉(あね)の隣(とな)りで寝(ね)ると、いつもあたたかい。", "sentence_source": "generated"}, {"text": "ここはあいていますか。隣りに座ってもいいですか。", "target_word": "隣り", "complexity_tier": "T3", "furigana": "ここはあいていますか。隣(とな)りに座(すわ)ってもいいですか。", "sentence_source": "generated"}, {"text": "隣りの人にペンを借りて、名前を書いた。", "target_word": "隣り", "complexity_tier": "T3", "furigana": "隣(とな)りの人(ひと)にペンを借(か)りて、名前(なまえ)を書(か)いた。", "sentence_source": "generated"}, {"text": "会議では、部長の隣りに新入社員が座ることになった。", "target_word": "隣り", "complexity_tier": "T3", "furigana": "会議(かいぎ)では、部長(ぶちょう)の隣(とな)りに新入社員(しんにゅうしゃいん)が座(すわ)ることになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "隣り", "label": "基本形"}, {"form": "隣", "label": "送り仮名を省いた表記"}], "register": "中立", "sense_fingerprint": "人や物のすぐ横の位置、席のとなり（隣り）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c807979d-24e5-4686-b553-a0ab630f3395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36567, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隣り", "is_correct": true, "explanation": "『私の隣りに座った』と座る位置を表し、文に合う。"}, {"text": "頭", "is_correct": false, "explanation": "体の部位で、人が座る位置にはならない。『私の頭に座った』は意味が通らない。"}, {"text": "床", "is_correct": false, "explanation": "座る面ではあるが、『私の床』は持ち主の所有を示すだけで、座る位置の文に合わない。"}, {"text": "手", "is_correct": false, "explanation": "体の部位で、『私の手に座った』は不自然で、座る位置として成り立たない。"}], "explanations": {"隣り": "『私の隣りに座った』と座る位置を表し、文に合う。", "頭": "体の部位で、人が座る位置にはならない。『私の頭に座った』は意味が通らない。", "床": "座る面ではあるが、『私の床』は持ち主の所有を示すだけで、座る位置の文に合わない。", "手": "体の部位で、『私の手に座った』は不自然で、座る位置として成り立たない。"}, "sentence_index": 0, "correct_answer": "隣り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱の隣りに、お菓子がぎっしり入っている。", "explanation": "ここは〈中〉の意味。隣りは横の位置を表し、入れ物の中は指さないので合わない。"}, {"text": "夕食の隣りに、食器を洗った。", "explanation": "ここは〈後〉の意味（時間のあと）。隣りは場所の位置で、時間の前後は表さないので合わない。"}, {"text": "テーブルの隣りに向かい合って座った。", "explanation": "ここは〈向かい〉の意味（正面で向き合う）。隣りは横に並ぶ位置で、向き合う位置とは両立しないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36567, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隣り", "is_correct": true, "explanation": "『姉の隣りで寝る』と寝る位置を表し、文の意味に合う。"}, {"text": "窓", "is_correct": false, "explanation": "寝る場所として成り立たない。『姉の窓で寝る』は意味が通らない。"}, {"text": "鏡", "is_correct": false, "explanation": "寝る場所にはならない。『姉の鏡で寝る』は文として意味が通らない。"}, {"text": "時計", "is_correct": false, "explanation": "寝る場所にはならない。『姉の時計で寝る』は意味が通らない。"}], "explanations": {"隣り": "『姉の隣りで寝る』と寝る位置を表し、文の意味に合う。", "窓": "寝る場所として成り立たない。『姉の窓で寝る』は意味が通らない。", "鏡": "寝る場所にはならない。『姉の鏡で寝る』は文として意味が通らない。", "時計": "寝る場所にはならない。『姉の時計で寝る』は意味が通らない。"}, "sentence_index": 6, "correct_answer": "隣り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この計画の隣りは、とても大きい。", "explanation": "ここは〈規模〉の意味（全体の大きさ）。隣りは位置を表す語で、計画の大きさは表さないので合わない。"}, {"text": "新人が選ばれる隣りは、かなり高い。", "explanation": "ここは〈確率〉の意味（起こる見込み）。隣りは位置を表す語で、見込みの高さは表さないので合わない。"}, {"text": "会議の隣りを、みんなに伝えた。", "explanation": "ここは〈内容〉の意味（話の中身）。隣りは場所の位置で、話す中身は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36567, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私の隣りを、弟が座った。", "corrected_sentence": "私の隣りに、弟が座った。", "error_description": "『座る』の位置は『に』で示す。『を』は目的語を表すので、座る場所には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36567, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は、私の隣りを座っていた。", "corrected_sentence": "母は、私の隣りに座っていた。", "error_description": "『座る』の場所は『に』で示す。『を』は目的語を表すので、ここには合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342ff00c-c9b4-4d79-b171-325fd90c6e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
