INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36568, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "じぶんの気もちとは別に、知らないうちにそうしてしまうこと。", "primary_collocate": null, "pronunciation": "つい", "ipa": "tsɯi", "syllable_count": 2, "sentences": [{"text": "ダイエット中なのに、ケーキを見るとつい食べてしまう。", "target_word": "つい", "complexity_tier": "T3", "furigana": "ダイエット中[ちゅう]なのに、ケーキを見[み]るとつい食[た]べてしまう。", "sentence_source": "generated"}, {"text": "話が面白くて、つい時間を忘れてしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "話[はなし]が面白[おもしろ]くて、つい時間[じかん]を忘[わす]れてしまった。", "sentence_source": "generated"}, {"text": "悪いと思いながら、つい友達の悪口を言ってしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "悪[わる]いと思[おも]いながら、つい友達[ともだち]の悪口[わるぐち]を言[い]ってしまった。", "sentence_source": "generated"}, {"text": "弟があまりにしつこいので、つい大きな声を出してしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "弟[おとうと]があまりにしつこいので、つい大[おお]きな声[こえ]を出[だ]してしまった。", "sentence_source": "generated"}, {"text": "安売りの文字を見ると、つい店に入ってしまう。", "target_word": "つい", "complexity_tier": "T3", "furigana": "安売[やすう]りの文字[もじ]を見[み]ると、つい店[みせ]に入[はい]ってしまう。", "sentence_source": "generated"}, {"text": "秘密にするはずだったのに、つい口がすべって話してしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "秘密[ひみつ]にするはずだったのに、つい口[くち]がすべって話[はな]してしまった。", "sentence_source": "generated"}, {"text": "面白い本なので、眠いのについ夜中まで読んでしまう。", "target_word": "つい", "complexity_tier": "T3", "furigana": "面白[おもしろ]い本[ほん]なので、眠[ねむ]いのについ夜中[よなか]まで読[よ]んでしまう。", "sentence_source": "generated"}, {"text": "彼女の笑顔を見て、つい私も笑ってしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の笑顔[えがお]を見[み]て、つい私[わたし]も笑[わら]ってしまった。", "sentence_source": "generated"}, {"text": "先生の前なのに、つい友達のような話し方をしてしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "先生[せんせい]の前[まえ]なのに、つい友達[ともだち]のような話[はな]し方[かた]をしてしまった。", "sentence_source": "generated"}, {"text": "禁煙を始めたのに、疲れているとつい一本吸ってしまう。", "target_word": "つい", "complexity_tier": "T3", "furigana": "禁煙[きんえん]を始[はじ]めたのに、疲[つか]れているとつい一本[いっぽん]吸[す]ってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "つい", "label": "基本形"}], "register": "口語", "sense_fingerprint": "やめようと思っていても、気持ちに反して思わずしてしまう（〜てしまうと呼応する）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36568, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "つい", "is_correct": true, "explanation": "「つい」は自分の気持ちに反して無意識に〜してしまう意味で、「〜てしまう」と呼応するのでここに入る。"}, {"text": "ぜひ", "is_correct": false, "explanation": "「ぜひ」は強く望む気持ちを表すので、無意識に食べてしまうという文脈には合わない。"}, {"text": "きちんと", "is_correct": false, "explanation": "「きちんと」は整った様子を表すので、無意識の行動を修飾する副詞としては合わない。"}, {"text": "まったく", "is_correct": false, "explanation": "「まったく」は打ち消しと呼応するので、肯定の「〜てしまう」文には入らない。"}], "explanations": {"つい": "「つい」は自分の気持ちに反して無意識に〜してしまう意味で、「〜てしまう」と呼応するのでここに入る。", "ぜひ": "「ぜひ」は強く望む気持ちを表すので、無意識に食べてしまうという文脈には合わない。", "きちんと": "「きちんと」は整った様子を表すので、無意識の行動を修飾する副詞としては合わない。", "まったく": "「まったく」は打ち消しと呼応するので、肯定の「〜てしまう」文には入らない。"}, "sentence_index": 0, "correct_answer": "つい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来客に備えようと、つい大掃除を始めた。", "explanation": "もとは「あらかじめ計画して」（前もって準備する）の文。「つい」は意図せず起こるので、準備を計画して行う行動とは合わない。"}, {"text": "嫌がらせをしようと、つい相手の名前を間違えて書いた。", "explanation": "もとは「わざと」の文。「つい」は自分の意思に反して起こることなので、「嫌がらせをしようと」という意図とは合わない。"}, {"text": "周りの反対を押し切って、つい新しい方法を試した。", "explanation": "もとは「あえて」（わざわざ選んで）の文。「つい」は意図に反した行動なので、「押し切って」と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36568, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "つい", "is_correct": true, "explanation": "「つい」は眠いのに夜中まで読んでしまう無意識の行動を表し、「〜てしまう」と呼応するのでここに入る。"}, {"text": "はっきり", "is_correct": false, "explanation": "「はっきり」は明瞭さを表すので、無意識に読んでしまう文脈には合わない。"}, {"text": "ぴったり", "is_correct": false, "explanation": "「ぴったり」はちょうど合う様子を表すので、ここでは意味が通らない。"}, {"text": "きっぱり", "is_correct": false, "explanation": "「きっぱり」は決断して断ち切る様子なので、夜中まで読んでしまうという流れと合わない。"}], "explanations": {"つい": "「つい」は眠いのに夜中まで読んでしまう無意識の行動を表し、「〜てしまう」と呼応するのでここに入る。", "はっきり": "「はっきり」は明瞭さを表すので、無意識に読んでしまう文脈には合わない。", "ぴったり": "「ぴったり」はちょうど合う様子を表すので、ここでは意味が通らない。", "きっぱり": "「きっぱり」は決断して断ち切る様子なので、夜中まで読んでしまうという流れと合わない。"}, "sentence_index": 6, "correct_answer": "つい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "相手の反応を見たくて、つい意地悪な質問をした。", "explanation": "もとは「意図的に」の文。「つい」は本人の意思に反して起こるので、「反応を見たくて」という目的と合わない。"}, {"text": "慎重に確認したうえで、つい契約書にサインした。", "explanation": "「つい」は注意せずに起こることなので、入念に確かめたという注意深さとは合わない。"}, {"text": "故意に相手の機嫌をそこねようと、つい皮肉を言った。", "explanation": "「つい」は本人の意思に反して起こることなので、「機嫌をそこねよう」という意図的な目的とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36568, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寒くなると、つい布団の中で二度寝をしてみる。", "corrected_sentence": "寒くなると、つい布団の中で二度寝をしてしまう。", "error_description": "「つい」は「〜てしまう」と呼応し、無意識の結果を表す。誤りは「してみる」（試しにやってみる）で、意図的な試みになり「つい」と矛盾する。正しくは「してしまう」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36568, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験前なのに、ついに漫画を読みふけってしまう。", "corrected_sentence": "試験前なのに、つい漫画を読みふけってしまう。", "error_description": "「つい」を「ついに」に替えている。「ついに」は長い経過の末にとうとう、の意味で、無意識に行ってしまう「つい」とは別の語。ここでは「ついに」が意味的に合わない。正しくは「つい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
