INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36569, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "意識せずに、ある行動をしてしまうさま。無意識に。", "primary_collocate": null, "pronunciation": "つい", "ipa": "tsɯi", "syllable_count": 2, "sentences": [{"text": "考えごとをしていたので、つい駅を乗り過ごしてしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "考[かんが]えごとをしていたので、つい駅[えき]を乗[の]り過[す]ごしてしまった。", "sentence_source": "generated"}, {"text": "子どもがかわいくて、つい頭をなでてしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "子[こ]どもがかわいくて、つい頭[あたま]をなでてしまった。", "sentence_source": "generated"}, {"text": "暑い日は、コンビニでつい冷たい飲み物を買ってしまう。", "target_word": "つい", "complexity_tier": "T3", "furigana": "暑[あつ]い日[ひ]は、コンビニでつい冷[つめ]たい飲[の]み物[もの]を買[か]ってしまう。", "sentence_source": "generated"}, {"text": "隣の人の画面が気になって、つい見てしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "隣[となり]の人[ひと]の画面[がめん]が気[き]になって、つい見[み]てしまった。", "sentence_source": "generated"}, {"text": "授業中なのに、つい携帯電話を手に取ってしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "授業中[じゅぎょうちゅう]なのに、つい携帯電話[けいたいでんわ]を手[て]に取[と]ってしまった。", "sentence_source": "generated"}, {"text": "昔の癖で、つい古い住所を書いてしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "昔[むかし]の癖[くせ]で、つい古[ふる]い住所[じゅうしょ]を書[か]いてしまった。", "sentence_source": "generated"}, {"text": "久しぶりに母の料理を食べて、つい三杯もおかわりした。", "target_word": "つい", "complexity_tier": "T3", "furigana": "久[ひさ]しぶりに母[はは]の料理[りょうり]を食[た]べて、つい三杯[さんばい]もおかわりした。", "sentence_source": "generated"}, {"text": "電話が鳴ると、運転中でもつい携帯に手を伸ばしてしまう。", "target_word": "つい", "complexity_tier": "T3", "furigana": "電話[でんわ]が鳴[な]ると、運転中[うんてんちゅう]でもつい携帯[けいたい]に手[て]を伸[の]ばしてしまう。", "sentence_source": "generated"}, {"text": "友達の話に共感して、つい涙が出てしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "友達[ともだち]の話[はなし]に共感[きょうかん]して、つい涙[なみだ]が出[で]てしまった。", "sentence_source": "generated"}, {"text": "旅行先で珍しいお菓子を見つけて、つい全部買ってしまった。", "target_word": "つい", "complexity_tier": "T3", "furigana": "旅行先[りょこうさき]で珍[めずら]しいお菓子[かし]を見[み]つけて、つい全部[ぜんぶ]買[か]ってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "つい", "label": "基本形"}], "register": "口語", "sense_fingerprint": "深く考えず、無意識のうちに動作をしてしまうさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 考えごと (Zipf 2.06), 乗り過ごし (Zipf 2.09)']::text[], '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36569, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "つい", "is_correct": true, "explanation": "「つい」は意識せずに駅を乗り過ごしてしまうことを表し、「〜てしまった」と呼応するのでここに入る。"}, {"text": "ぜんぜん", "is_correct": false, "explanation": "「ぜんぜん」は打ち消しと呼応するので、肯定の「乗り過ごしてしまった」には入らない。"}, {"text": "なかなか", "is_correct": false, "explanation": "「なかなか」は否定表現と結びつくことが多く、ここでは文の意味が通らない。"}, {"text": "ぴったり", "is_correct": false, "explanation": "「ぴったり」はちょうど合う様子を表すので、乗り過ごしの行為を修飾すると不自然になる。"}], "explanations": {"つい": "「つい」は意識せずに駅を乗り過ごしてしまうことを表し、「〜てしまった」と呼応するのでここに入る。", "ぜんぜん": "「ぜんぜん」は打ち消しと呼応するので、肯定の「乗り過ごしてしまった」には入らない。", "なかなか": "「なかなか」は否定表現と結びつくことが多く、ここでは文の意味が通らない。", "ぴったり": "「ぴったり」はちょうど合う様子を表すので、乗り過ごしの行為を修飾すると不自然になる。"}, "sentence_index": 0, "correct_answer": "つい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "慎重に言葉を選ぼうと、つい余計なことを口にした。", "explanation": "「つい」は注意せずに起こることなので、言葉を注意深く選ぼうとする意図とは合わない。"}, {"text": "隣の人の画面を確かめようと、つい覗いた。", "explanation": "もとは「わざと」の文。「つい」は意図せず起こるので、「確かめようと」という目的とは合わない。"}, {"text": "相手の秘密を知ろうと、つい人の画面を覗き込んだ。", "explanation": "もとは「あえて」の文。「つい」は意図しない行動なので、「秘密を知ろうと」という意図と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36569, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "つい", "is_correct": true, "explanation": "「つい」は無意識に三杯もおかわりしてしまう行動を表し、「〜てしまう」の流れに合うのでここに入る。"}, {"text": "あらかじめ", "is_correct": false, "explanation": "「あらかじめ」は前もって準備する意味なので、食べすぎの結果を表す文には合わない。"}, {"text": "ずらり", "is_correct": false, "explanation": "「ずらり」は物が並ぶ様子を表すので、おかわりの動作を修飾すると意味が通らない。"}, {"text": "きっぱり", "is_correct": false, "explanation": "「きっぱり」は断る決意を表すので、三杯もおかわりする行動とは合わない。"}], "explanations": {"つい": "「つい」は無意識に三杯もおかわりしてしまう行動を表し、「〜てしまう」の流れに合うのでここに入る。", "あらかじめ": "「あらかじめ」は前もって準備する意味なので、食べすぎの結果を表す文には合わない。", "ずらり": "「ずらり」は物が並ぶ様子を表すので、おかわりの動作を修飾すると意味が通らない。", "きっぱり": "「きっぱり」は断る決意を表すので、三杯もおかわりする行動とは合わない。"}, "sentence_index": 6, "correct_answer": "つい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の人の勧めを断ろうと、つい箱ごと買ってしまった。", "explanation": "「つい」は意図せず起こるので、意志をもって勧めを退けようとする行動とは合わない。"}, {"text": "母への土産にしようと、つい全部買ってしまった。", "explanation": "もとは「わざわざ」の文。「つい」は意図せず起こるので、「母への土産にしようと」という目的とは合わない。"}, {"text": "予算内に収めようと、つい高価なものを選んでしまった。", "explanation": "「つい」は意図せず起こるので、予算に合わせる計画性（節約）とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36569, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "考えごとをしていると、ついに足元の段差を見落としてしまう。", "corrected_sentence": "考えごとをしていると、つい足元の段差を見落としてしまう。", "error_description": "「つい」を「ついに」に替えている。「ついに」は長い経過の末にとうとう、の意味で、無意識の見落としを表す「つい」とは意味が違う。正しくは「つい」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36569, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ゲームに夢中で、つい夕食を忘れてみる。", "corrected_sentence": "ゲームに夢中で、つい夕食を忘れてしまう。", "error_description": "「つい」は「〜てしまう」と呼応し、無意識の結果を表す。誤りは「忘れてみる」で、「〜てみる」は試しに行う意味になり、無意識に忘れる「つい」と矛盾する。正しくは「忘れてしまう」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36570, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題の「仕事」を取り上げる「は」が合います。"}, {"text": "の", "is_correct": false, "explanation": "「仕事のもう」は文として成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「仕事へもう」は文として成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「仕事ともう」は文として成り立ちません。"}], "correct_answer": "は", "explanations": {"は": "主題の「仕事」を取り上げる「は」が合います。", "の": "「仕事のもう」は文として成り立ちません。", "へ": "「仕事へもう」は文として成り立ちません。", "と": "「仕事ともう」は文として成り立ちません。"}, "error_tags": {"の": "ungrammatical", "へ": "direction", "と": "ungrammatical"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "開ける", "is_correct": true, "explanation": "店を閉めるの反対で、開店するという意味です。"}, {"text": "閉める", "is_correct": false, "explanation": "店を閉める意味で、類義語です。"}, {"text": "終える", "is_correct": false, "explanation": "物事を終わりにする意味で、類義語です。"}, {"text": "休む", "is_correct": false, "explanation": "営業しない意味はあるが、反対語ではありません。"}], "correct_answer": "開ける", "explanations": {"開ける": "店を閉めるの反対で、開店するという意味です。", "閉める": "店を閉める意味で、類義語です。", "終える": "物事を終わりにする意味で、類義語です。", "休む": "営業しない意味はあるが、反対語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36570, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "閉めて終える対象の「店」を示す「を」が合います。"}, {"text": "の", "is_correct": false, "explanation": "「店のしまいました」は文として成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「早めに店としまいました」は文として成り立ちません。"}, {"text": "か", "is_correct": false, "explanation": "「店かしまいました」は文として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "閉めて終える対象の「店」を示す「を」が合います。", "の": "「店のしまいました」は文として成り立ちません。", "と": "「早めに店としまいました」は文として成り立ちません。", "か": "「店かしまいました」は文として成り立ちません。"}, "error_tags": {"の": "ungrammatical", "と": "ungrammatical", "か": "ungrammatical"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始める", "is_correct": true, "explanation": "終わりにするの反対で、始めるという意味です。"}, {"text": "終える", "is_correct": false, "explanation": "終わりにする意味で、類義語です。"}, {"text": "閉める", "is_correct": false, "explanation": "店を閉める意味で、類義語です。"}, {"text": "やめる", "is_correct": false, "explanation": "続けていることを終える意味で、類義語です。"}], "correct_answer": "始める", "explanations": {"始める": "終わりにするの反対で、始めるという意味です。", "終える": "終わりにする意味で、類義語です。", "閉める": "店を閉める意味で、類義語です。", "やめる": "続けていることを終える意味で、類義語です。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36570, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "仕事や店などをおしまいにする。片づけて終える。", "primary_collocate": null, "pronunciation": "しまう", "ipa": "ɕimaɯ", "syllable_count": 3, "sentences": [{"text": "店をしまう。", "target_word": "しまう", "complexity_tier": "T1", "furigana": "", "sentence_source": "generated"}, {"text": "今日の仕事はもうしまいます。", "target_word": "しまい", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "六時に仕事をしまいました。", "target_word": "しまい", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "今日の商売はこれでしまうことにした。", "target_word": "しまう", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "お祭りが終わって、屋台をしまっている。", "target_word": "しまっ", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "客が来ないので、今日はもう店をしまおう。", "target_word": "しまお", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "雨が降ってきたので、商売を早めにしまった。", "target_word": "しまっ", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "今日は早めに店をしまいました。", "target_word": "しまい", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "店をしまわれる前に、急いで買い物をすませた。", "target_word": "しまわ", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "父は毎晩、九時に店をしまっている。", "target_word": "しまっ", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "しまった", "label": "活用"}, {"form": "しまって", "label": "活用"}, {"form": "しまわない", "label": "活用"}, {"form": "しまえる", "label": "活用"}, {"form": "店じまい", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 店や仕事をおしまいにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ebd0380-b377-40c1-83ac-2402ca991c8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36570, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仕舞う", "is_correct": true, "explanation": "見出し語「しまう」そのものです。"}, {"text": "構う", "is_correct": false, "explanation": "「かまう」は最初の一拍が違います。"}, {"text": "住まう", "is_correct": false, "explanation": "「すまう」は最初の一拍だけが違います。"}, {"text": "給う", "is_correct": false, "explanation": "「たまう」は最初の一拍だけが違います。"}, {"text": "撓う", "is_correct": false, "explanation": "「しなう」は二拍目だけが違います。"}, {"text": "締まる", "is_correct": false, "explanation": "「しまる」は最後の一拍だけが違います。"}], "explanations": {"仕舞う": "見出し語「しまう」そのものです。", "構う": "「かまう」は最初の一拍が違います。", "住まう": "「すまう」は最初の一拍だけが違います。", "給う": "「たまう」は最初の一拍だけが違います。", "撓う": "「しなう」は二拍目だけが違います。", "締まる": "「しまる」は最後の一拍だけが違います。"}, "sentence_index": null, "correct_answer": "仕舞う"}, "level_3": {"options": [{"text": "しまう", "is_correct": true, "explanation": "「店をしまう」で、店を閉めて終える意味が合います。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが意味が合わない。店を食べることはできません。"}, {"text": "読む", "is_correct": false, "explanation": "形は合うが意味が合わない。「店を読む」は意味が通りません。"}, {"text": "歌う", "is_correct": false, "explanation": "形は合うが意味が合わない。「店を歌う」は意味が通りません。"}], "explanations": {"しまう": "「店をしまう」で、店を閉めて終える意味が合います。", "食べる": "形は合うが意味が合わない。店を食べることはできません。", "読む": "形は合うが意味が合わない。「店を読む」は意味が通りません。", "歌う": "形は合うが意味が合わない。「店を歌う」は意味が通りません。"}, "sentence_index": 0, "correct_answer": "しまう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝九時に店をしまって、お客さんを迎えた。", "explanation": "「しまう」は営業を終える意味なので、開店して客を迎える文脈と矛盾します。"}, {"text": "新しい店を駅前にしまうことにした。", "explanation": "「しまう」を「開店する」の意味で誤用しています。"}, {"text": "新しい仕事を明日からしまうつもりだ。", "explanation": "「しまう」を「始める」の意味で誤用しています。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36570, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "しまっ", "is_correct": true, "explanation": "「商売を早めにしまった」で、営業を終える意味が合います。"}, {"text": "食べ", "is_correct": false, "explanation": "形は合うが意味が合わない。商売を食べることはできません。"}, {"text": "洗っ", "is_correct": false, "explanation": "形は合うが意味が合わない。「商売を洗った」は意味が通りません。"}, {"text": "歌っ", "is_correct": false, "explanation": "形は合うが意味が合わない。「商売を歌った」は文意に合いません。"}], "explanations": {"しまっ": "「商売を早めにしまった」で、営業を終える意味が合います。", "食べ": "形は合うが意味が合わない。商売を食べることはできません。", "洗っ": "形は合うが意味が合わない。「商売を洗った」は意味が通りません。", "歌っ": "形は合うが意味が合わない。「商売を歌った」は文意に合いません。"}, "sentence_index": 6, "correct_answer": "しまっ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は毎朝、九時に店をしまって、営業を始めている。", "explanation": "「しまう」は営業を終える意味なので、営業を始める文脈と矛盾します。"}, {"text": "父は毎晩、九時に電車をしまっている。", "explanation": "「電車をしまう」は成り立たず、「しまう」と結びつかない対象です。"}, {"text": "父は毎晩、九時にお客さんをしまっている。", "explanation": "「しまう」の対象は店や仕事で、人をしまうことはできません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
