INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36571, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "物を収める場所を示す「に」が合います。"}, {"text": "で", "is_correct": false, "explanation": "「箱でしまう」は収める場所の表し方として不自然です。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、収める先にはなりません。"}, {"text": "と", "is_correct": false, "explanation": "「箱としまう」は文として成り立ちません。"}], "correct_answer": "に", "explanations": {"に": "物を収める場所を示す「に」が合います。", "で": "「箱でしまう」は収める場所の表し方として不自然です。", "から": "「から」は起点を表し、収める先にはなりません。", "と": "「箱としまう」は文として成り立ちません。"}, "error_tags": {"で": "location_confusion", "から": "source_vs_goal", "と": "ungrammatical"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出す", "is_correct": true, "explanation": "物を収めるの反対で、取り出すという意味です。"}, {"text": "収める", "is_correct": false, "explanation": "「しまう」とほぼ同じ意味の類義語です。"}, {"text": "片づける", "is_correct": false, "explanation": "物を元の場所に戻す意味で、類義語です。"}, {"text": "隠す", "is_correct": false, "explanation": "見えないようにする意味で、反対語ではありません。"}], "correct_answer": "出す", "explanations": {"出す": "物を収めるの反対で、取り出すという意味です。", "収める": "「しまう」とほぼ同じ意味の類義語です。", "片づける": "物を元の場所に戻す意味で、類義語です。", "隠す": "見えないようにする意味で、反対語ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
