INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36571, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物を決まった場所に収める。片づけて入れておく。", "primary_collocate": null, "pronunciation": "しまう", "ipa": "ɕimaɯ", "syllable_count": 3, "sentences": [{"text": "しかし、抽出された液は未だ不安定な色彩に過ぎず、そのままでは時間と共に退色してしまう。", "target_word": "しまう", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "おもちゃを箱にしまいました。", "target_word": "しまい", "complexity_tier": "T2", "furigana": "", "sentence_source": "generated"}, {"text": "使ったお皿は、棚にしまってください。", "target_word": "しまっ", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "本をしまう。", "target_word": "しまう", "complexity_tier": "T1", "furigana": "", "sentence_source": "generated"}, {"text": "冬になる前に、扇風機を押し入れにしまった。", "target_word": "しまっ", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "大切な書類は、金庫にしまっておくべきだ。", "target_word": "しまっ", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "しまっていた手紙を、久しぶりに読んだ。", "target_word": "しまっ", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}, {"text": "傘をしまうと、雨はもう止んでいた。", "target_word": "しまう", "complexity_tier": "T4", "furigana": "", "sentence_source": "generated"}, {"text": "祖母がしまった着物は、今も箪笥の奥で眠っている。", "target_word": "しまっ", "complexity_tier": "T5", "furigana": "", "sentence_source": "generated"}, {"text": "使わない道具は、倉庫にしまうことにした。", "target_word": "しまう", "complexity_tier": "T3", "furigana": "", "sentence_source": "generated"}], "morphological_forms": [{"form": "しまった", "label": "活用"}, {"form": "しまって", "label": "活用"}, {"form": "しまわない", "label": "活用"}, {"form": "しまえる", "label": "活用"}, {"form": "しまい込む", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物を所定の場所に収める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ebd0380-b377-40c1-83ac-2402ca991c8f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36571, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仕舞う", "is_correct": true, "explanation": "見出し語「しまう」そのものです。"}, {"text": "構う", "is_correct": false, "explanation": "「かまう」は最初の一拍が違います。"}, {"text": "住まう", "is_correct": false, "explanation": "「すまう」は最初の一拍だけが違います。"}, {"text": "給う", "is_correct": false, "explanation": "「たまう」は最初の一拍だけが違います。"}, {"text": "撓う", "is_correct": false, "explanation": "「しなう」は二拍目だけが違います。"}, {"text": "締まる", "is_correct": false, "explanation": "「しまる」は最後の一拍だけが違います。"}], "explanations": {"仕舞う": "見出し語「しまう」そのものです。", "構う": "「かまう」は最初の一拍が違います。", "住まう": "「すまう」は最初の一拍だけが違います。", "給う": "「たまう」は最初の一拍だけが違います。", "撓う": "「しなう」は二拍目だけが違います。", "締まる": "「しまる」は最後の一拍だけが違います。"}, "sentence_index": null, "correct_answer": "仕舞う"}, "level_3": {"options": [{"text": "しまう", "is_correct": true, "explanation": "「退色してしまう」で、望ましくない結果になる意味が合います。"}, {"text": "あげる", "is_correct": false, "explanation": "形は合うが意味が合わない。「退色してあげる」は文意に合いません。"}, {"text": "おく", "is_correct": false, "explanation": "形は合うが意味が合わない。「退色しておく」は液が自然に変わる文意に合いません。"}, {"text": "みる", "is_correct": false, "explanation": "形は合うが意味が合わない。「退色してみる」は意味が通りません。"}], "explanations": {"しまう": "「退色してしまう」で、望ましくない結果になる意味が合います。", "あげる": "形は合うが意味が合わない。「退色してあげる」は文意に合いません。", "おく": "形は合うが意味が合わない。「退色しておく」は液が自然に変わる文意に合いません。", "みる": "形は合うが意味が合わない。「退色してみる」は意味が通りません。"}, "sentence_index": 0, "correct_answer": "しまう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宿題を先生にしまう。", "explanation": "「しまう」を「提出する」の意味で使っており、物を収める意味とは違います。"}, {"text": "犬を散歩にしまう。", "explanation": "「しまう」を「連れて行く」の意味で誤用しています。"}, {"text": "電車の中で大きな声をしまう。", "explanation": "「声をしまう」は「声を出す」の意味で誤用しており、収める意味に合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36571, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "しまっ", "is_correct": true, "explanation": "「しまっていた手紙」で、収めてあった手紙という意味が合います。"}, {"text": "走っ", "is_correct": false, "explanation": "形は合うが意味が合わない。「走っていた手紙」は意味が通りません。"}, {"text": "笑っ", "is_correct": false, "explanation": "形は合うが意味が合わない。手紙が笑うことはありません。"}, {"text": "燃え", "is_correct": false, "explanation": "形は合うが意味が合わない。燃えていた手紙を読むことはできません。"}], "explanations": {"しまっ": "「しまっていた手紙」で、収めてあった手紙という意味が合います。", "走っ": "形は合うが意味が合わない。「走っていた手紙」は意味が通りません。", "笑っ": "形は合うが意味が合わない。手紙が笑うことはありません。", "燃え": "形は合うが意味が合わない。燃えていた手紙を読むことはできません。"}, "sentence_index": 6, "correct_answer": "しまっ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、顔をしまってから学校へ行く。", "explanation": "「しまう」を「洗う」の意味で誤用しています。"}, {"text": "使わない道具は、大きな声で歌をしまうことにした。", "explanation": "歌は収める物ではなく、「しまう」と結びつきません。"}, {"text": "使わない道具は、友達にしまうことにした。", "explanation": "「しまう」を「あげる」の意味で誤用しています。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36571, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毛布を押し入れをしまった。", "corrected_sentence": "毛布を押し入れにしまった。", "error_description": "収める場所は「を」ではなく「に」で示します。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "しまい", "is_correct": true, "explanation": "「ました」に続く連用形で、この空欄に合います。"}, {"text": "しまっ", "is_correct": false, "explanation": "促音便の形で、「ました」には続きません。"}, {"text": "しまわ", "is_correct": false, "explanation": "未然形で、「ました」には続きません。"}, {"text": "しまう", "is_correct": false, "explanation": "終止形で、「ました」には続きません。"}], "correct_form": "しまい", "base_form": "しまう", "form_label": "連用形(ます形)", "sentence_index": 1, "explanations": {"しまい": "「ました」に続く連用形で、この空欄に合います。", "しまっ": "促音便の形で、「ました」には続きません。", "しまわ": "未然形で、「ました」には続きません。", "しまう": "終止形で、「ました」には続きません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36571, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い手紙を引き出しからしまった。", "corrected_sentence": "古い手紙を引き出しにしまった。", "error_description": "収める先を示す助詞は「から」ではなく「に」です。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "しまう", "is_correct": true, "explanation": "「と」に続く終止形が合います。"}, {"text": "しまい", "is_correct": false, "explanation": "連用形で、「と」には続きません。"}, {"text": "しまっ", "is_correct": false, "explanation": "促音便の形で、「と」には続きません。"}, {"text": "しまわ", "is_correct": false, "explanation": "未然形で、「と」には続きません。"}], "correct_form": "しまう", "base_form": "しまう", "form_label": "終止形(辞書形)", "sentence_index": 7, "explanations": {"しまう": "「と」に続く終止形が合います。", "しまい": "連用形で、「と」には続きません。", "しまっ": "促音便の形で、「と」には続きません。", "しまわ": "未然形で、「と」には続きません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21fb93de-e236-43a5-ad70-8ce44f35beeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36572, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「他人の気持ち」と名詞をつなぐ「の」が正しい。持ち主を示す。"}, {"text": "に", "is_correct": false, "explanation": "「他人に気持ち」は名詞を直接つなげられず、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「他人で気持ち」とは続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、名詞をつなぐ位置には入らない。"}], "correct_answer": "の", "explanations": {"の": "「他人の気持ち」と名詞をつなぐ「の」が正しい。持ち主を示す。", "に": "「他人に気持ち」は名詞を直接つなげられず、文として成り立たない。", "で": "「で」は場所や手段を示すので、「他人で気持ち」とは続かない。", "へ": "「へ」は方向を示すので、名詞をつなぐ位置には入らない。"}, "error_tags": {"に": "相手・対象", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36572, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「迷惑をかける」の相手を示す「に」が正しい。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、迷惑をかける相手にはならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」を続けると「迷惑をかける」の目的語が二つになり、不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「他人で迷惑をかける」とは続かず不自然になる。"}], "correct_answer": "に", "explanations": {"に": "「迷惑をかける」の相手を示す「に」が正しい。", "から": "「から」は起点を示すので、迷惑をかける相手にはならない。", "を": "「を」を続けると「迷惑をかける」の目的語が二つになり、不自然になる。", "で": "「で」は場所や手段を示すので、「他人で迷惑をかける」とは続かず不自然になる。"}, "error_tags": {"から": "起点", "を": "対象", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36572, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "じぶんいがいのひと", "primary_collocate": null, "pronunciation": "たにん", "ipa": "taɲiɴ", "syllable_count": 3, "sentences": [{"text": "他人の物を勝手に使ってはいけない。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]の物[もの]を勝手[かって]に使[つか]ってはいけない。", "sentence_source": "generated"}, {"text": "他人の気持ちを考えて話すことは大切だ。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]の気持[きも]ちを考[かんが]えて話[はな]すことは大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "電車の中で他人にぶつかってしまい、すぐに謝った。", "target_word": "他人", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の中[なか]で他人[たにん]にぶつかってしまい、すぐに謝[あやま]った。", "sentence_source": "generated"}, {"text": "彼女は他人に頼らず、自分で問題を解決した。", "target_word": "他人", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は他人[たにん]に頼[たよ]らず、自分[じぶん]で問題[もんだい]を解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "他人の失敗を笑うのは、よくないことだ。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]の失敗[しっぱい]を笑[わら]うのは、よくないことだ。", "sentence_source": "generated"}, {"text": "他人から見れば小さなことでも、本人には大問題だ。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]から見[み]れば小[ちい]さなことでも、本人[ほんにん]には大問題[だいもんだい]だ。", "sentence_source": "generated"}, {"text": "初めて会った他人と、すぐに仲良くなるのは難しい。", "target_word": "他人", "complexity_tier": "T3", "furigana": "初[はじ]めて会[あ]った他人[たにん]と、すぐに仲良[なかよ]くなるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "他人に迷惑をかけないように、静かに歩いた。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]に迷惑[めいわく]をかけないように、静[しず]かに歩[ある]いた。", "sentence_source": "generated"}, {"text": "他人の意見ばかり気にして、自分で決められない。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]の意見[いけん]ばかり気[き]にして、自分[じぶん]で決[き]められない。", "sentence_source": "generated"}, {"text": "他人の家に入るときは、必ず声をかけるべきだ。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]の家[いえ]に入[はい]るときは、必[かなら]ず声[こえ]をかけるべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "他人", "label": "基本形"}, {"form": "他人の", "label": "助詞「の」を伴う形"}], "register": "中立", "sense_fingerprint": "自分以外の人（家族や身内でない人も含む、一般的な「ほかの人」）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36572, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他人", "is_correct": true, "explanation": "「他人」は自分以外の人を指し、「他人の物」の持ち主として文が成り立つのでここに入る。"}, {"text": "世間", "is_correct": false, "explanation": "「世間」は社会全体を表すので、個人の物の持ち主を示す語としては合わない。"}, {"text": "社会", "is_correct": false, "explanation": "「社会」は集団全体を指すので、「〜の物」の持ち主としては不自然になる。"}, {"text": "時間", "is_correct": false, "explanation": "「時間」は持ち物になりえないので、「〜の物」の持ち主には入らない。"}], "explanations": {"他人": "「他人」は自分以外の人を指し、「他人の物」の持ち主として文が成り立つのでここに入る。", "世間": "「世間」は社会全体を表すので、個人の物の持ち主を示す語としては合わない。", "社会": "「社会」は集団全体を指すので、「〜の物」の持ち主としては不自然になる。", "時間": "「時間」は持ち物になりえないので、「〜の物」の持ち主には入らない。"}, "sentence_index": 0, "correct_answer": "他人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "隣の町は他人なので、電車で行くことにした。", "explanation": "「他人」は人を指す語で、町のような場所には使えない。場所を指すなら「よそ」（別の場所）と言う。"}, {"text": "家族の他人の私が、いつも家事を引き受けている。", "explanation": "「他人」を身内の意味で使った誤り。「他人」は身内以外の人を指すので、身内の関係とは両立しない。"}, {"text": "この古い机は、長年使っているのに他人だ。", "explanation": "「他人」は人を指す語で、机のような物には使えない。物を指すなら「もの」などの語を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36572, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他人", "is_correct": true, "explanation": "「他人」は血縁や面識のない人を指し、「初めて会った」人と仲良くなる文脈に合うのでここに入る。"}, {"text": "家族", "is_correct": false, "explanation": "「家族」は初めて会う相手ではないので、「初めて会った〜と」と矛盾する。"}, {"text": "母親", "is_correct": false, "explanation": "「母親」は生まれたときから身近な人なので、「初めて会った」とは合わない。"}, {"text": "幼なじみ", "is_correct": false, "explanation": "「幼なじみ」は子どもの頃からの知り合いなので、「初めて会った」と矛盾する。"}], "explanations": {"他人": "「他人」は血縁や面識のない人を指し、「初めて会った」人と仲良くなる文脈に合うのでここに入る。", "家族": "「家族」は初めて会う相手ではないので、「初めて会った〜と」と矛盾する。", "母親": "「母親」は生まれたときから身近な人なので、「初めて会った」とは合わない。", "幼なじみ": "「幼なじみ」は子どもの頃からの知り合いなので、「初めて会った」と矛盾する。"}, "sentence_index": 6, "correct_answer": "他人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鳥は他人なので、毎朝えさをあげている。", "explanation": "「他人」は人を指す語で、動物には使えない。動物を指すなら「ペット」などと言う。"}, {"text": "双子の他人の兄は、とても背が高い。", "explanation": "「他人」を血縁のある関係の意味で使った誤り。「他人」は血縁のない人を指すので、血縁のある関係とは両立しない。"}, {"text": "このコーヒーは他人だから、毎朝飲んでいる。", "explanation": "「他人」は人を指す語で、飲み物には使えない。飲み物を指すなら「飲み物」などの語を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36572, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他人に気持ちを思いやることが、人間関係の基本だ。", "corrected_sentence": "他人の気持ちを思いやることが、人間関係の基本だ。", "error_description": "「他人の気持ち」の「の」が正しい（持ち主を示す）。「の」を「に」にすると「他人に気持ち」となり、持ち主が示せず不自然になる。正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36572, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "見知らぬ他人で、声をかけてもらった。", "corrected_sentence": "見知らぬ他人に、声をかけてもらった。", "error_description": "「他人に声をかけてもらう」の「に」（相手）を「で」に替えている。「で」は場所や手段を示すので、声をかける相手にはならない。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36573, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「他人に丁寧に話す」の相手を示す「に」が正しい（「には」の「に」）。"}, {"text": "や", "is_correct": false, "explanation": "「や」は名詞を並べる助詞で、「他人やは丁寧に話す」とは続かないので不自然になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は話す対象の物を示すので、人を相手にする文では不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐので、「話す」の相手を表すことはできない。"}], "correct_answer": "に", "explanations": {"に": "「他人に丁寧に話す」の相手を示す「に」が正しい（「には」の「に」）。", "や": "「や」は名詞を並べる助詞で、「他人やは丁寧に話す」とは続かないので不自然になる。", "を": "「を」は話す対象の物を示すので、人を相手にする文では不自然になる。", "の": "「の」は名詞をつなぐので、「話す」の相手を表すことはできない。"}, "error_tags": {"を": "対象", "の": "連体修飾", "や": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36573, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「他人の荷物」と名詞をつなぐ「の」が正しい。持ち主を示す。"}, {"text": "を", "is_correct": false, "explanation": "「他人を荷物を預かる」は目的語が重なり、不自然になる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「他人より荷物」とは続かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「他人で荷物」とは続かない。"}], "correct_answer": "の", "explanations": {"の": "「他人の荷物」と名詞をつなぐ「の」が正しい。持ち主を示す。", "を": "「他人を荷物を預かる」は目的語が重なり、不自然になる。", "より": "「より」は比較を示すので、「他人より荷物」とは続かない。", "で": "「で」は場所や手段を示すので、「他人で荷物」とは続かない。"}, "error_tags": {"を": "対象", "より": "比較", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36573, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分以外の人。ほかの人。", "primary_collocate": null, "pronunciation": "たにん", "ipa": "taɲiɴ", "syllable_count": 3, "sentences": [{"text": "他人の悪口を言うと、自分も嫌な気持ちになる。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]の悪口[わるぐち]を言[い]うと、自分[じぶん]も嫌[いや]な気持[きも]ちになる。", "sentence_source": "generated"}, {"text": "家族なら遠慮しないが、他人には丁寧に話す。", "target_word": "他人", "complexity_tier": "T3", "furigana": "家族[かぞく]なら遠慮[えんりょ]しないが、他人[たにん]には丁寧[ていねい]に話[はな]す。", "sentence_source": "generated"}, {"text": "他人の目を気にしすぎると、疲れてしまう。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]の目[め]を気[き]にしすぎると、疲[つか]れてしまう。", "sentence_source": "generated"}, {"text": "この秘密は他人に話さないでほしい。", "target_word": "他人", "complexity_tier": "T3", "furigana": "この秘密[ひみつ]は他人[たにん]に話[はな]さないでほしい。", "sentence_source": "generated"}, {"text": "他人のせいにしても、問題は解決しない。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]のせいにしても、問題[もんだい]は解決[かいけつ]しない。", "sentence_source": "generated"}, {"text": "同じ建物に住んでいても、他人とはほとんど話さない。", "target_word": "他人", "complexity_tier": "T3", "furigana": "同[おな]じ建物[たてもの]に住[す]んでいても、他人[たにん]とはほとんど話[はな]さない。", "sentence_source": "generated"}, {"text": "困っていたとき、他人が黙って傘を貸してくれた。", "target_word": "他人", "complexity_tier": "T3", "furigana": "困[こま]っていたとき、他人[たにん]が黙[だま]って傘[かさ]を貸[か]してくれた。", "sentence_source": "generated"}, {"text": "他人の荷物を預かるときは、中身を確認しておく。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]の荷物[にもつ]を預[あず]かるときは、中身[なかみ]を確認[かくにん]しておく。", "sentence_source": "generated"}, {"text": "他人に親切にされると、心があたたかくなる。", "target_word": "他人", "complexity_tier": "T3", "furigana": "他人[たにん]に親切[しんせつ]にされると、心[こころ]があたたかくなる。", "sentence_source": "generated"}, {"text": "子どもの頃は、他人の前で話すのが苦手だった。", "target_word": "他人", "complexity_tier": "T3", "furigana": "子[こ]どもの頃[ころ]は、他人[たにん]の前[まえ]で話[はな]すのが苦手[にがて]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "他人", "label": "基本形"}, {"form": "他人に", "label": "助詞「に」を伴う形"}], "register": "中立", "sense_fingerprint": "自分以外の人。家族・身内に対して、関係のないほかの人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36573, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他人", "is_correct": true, "explanation": "「他人の悪口」は、身内でない人に対する悪口を表し、文の意味が通るのでここに入る。"}, {"text": "階段", "is_correct": false, "explanation": "「階段」は物で、悪口を言う相手としては不自然になり、文の意味が通らない。"}, {"text": "景色", "is_correct": false, "explanation": "「景色」は悪口を言う相手として通じず、文の意味が成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓」は物で、人の悪口の対象にはならないので、文の意味が通らない。"}], "explanations": {"他人": "「他人の悪口」は、身内でない人に対する悪口を表し、文の意味が通るのでここに入る。", "階段": "「階段」は物で、悪口を言う相手としては不自然になり、文の意味が通らない。", "景色": "「景色」は悪口を言う相手として通じず、文の意味が成り立たない。", "窓": "「窓」は物で、人の悪口の対象にはならないので、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "他人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この秘密は身内の他人にだけ話した。", "explanation": "「他人」を親族の意味で使った誤り。「他人」は親族以外の人を指すので、親族の関係とは両立しない。"}, {"text": "この秘密は家族の他人の前で、こっそり話し合った。", "explanation": "「他人」を身内の意味で使った誤り。「他人」は身内以外の人を指すので、身内の関係とは両立しない。"}, {"text": "親友の他人には、この秘密を話せない。", "explanation": "「他人」を親しい間柄の意味で使った誤り。「他人」は親しい関係のない人を指すので、親しい間柄とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36573, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他人", "is_correct": true, "explanation": "「他人」は面識のない人を指し、困っているときに黙って傘を貸してくれる人として文が成り立つのでここに入る。"}, {"text": "警報", "is_correct": false, "explanation": "「警報」は傘を貸すことができないので、「黙って傘を貸してくれた」の主語にはならない。"}, {"text": "台風", "is_correct": false, "explanation": "「台風」は傘を貸す主体にならないので、文の主語として成り立たない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「夕焼け」は人のように行動できないので、傘を貸す主語としては合わない。"}], "explanations": {"他人": "「他人」は面識のない人を指し、困っているときに黙って傘を貸してくれる人として文が成り立つのでここに入る。", "警報": "「警報」は傘を貸すことができないので、「黙って傘を貸してくれた」の主語にはならない。", "台風": "「台風」は傘を貸す主体にならないので、文の主語として成り立たない。", "夕焼け": "「夕焼け」は人のように行動できないので、傘を貸す主語としては合わない。"}, "sentence_index": 6, "correct_answer": "他人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもの頃は、兄弟の他人と遊ぶのが大好きだった。", "explanation": "「他人」を血縁のある人の意味で使った誤り。「他人」は血縁のない人を指すので、血縁のある関係とは両立しない。"}, {"text": "子どもの頃は、親戚の他人の家に泊まるのが楽しみだった。", "explanation": "「他人」を血縁のある人の意味で使った誤り。「他人」は血縁のない人を指すので、血縁の関係とは両立しない。"}, {"text": "子どもの頃は、恋人の他人と話すのが苦手だった。", "explanation": "「他人」を親しい間柄の意味で使った誤り。「他人」は親しい関係のない人を指すので、特別な関係とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36573, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他人に評価に振り回されず、自分らしく生きる。", "corrected_sentence": "他人の評価に振り回されず、自分らしく生きる。", "error_description": "「他人の評価」の「の」（持ち主）を「に」に替えている。「他人に評価」では持ち主が示されず不自然になる。正しくは「の」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36573, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "見知らぬ他人で、声をかけてもらった。", "corrected_sentence": "見知らぬ他人に、声をかけてもらった。", "error_description": "「他人に声をかけてもらう」の「に」（相手）を「で」に替えている。「で」は場所や手段を示すので、声をかける相手にはならない。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36574, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「気持ちを考える」の形で、考える対象を直接示すので「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「考えて」の主語にはならず、「気持ちが考えて」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「気持ちに考える」という言い方はなく、考える対象には使わない。"}, {"text": "と", "is_correct": false, "explanation": "「〜と考える」は「〜だと思う」の意味で、「気持ちと考えて」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「気持ちを考える」の形で、考える対象を直接示すので「を」が正しい。", "が": "「考えて」の主語にはならず、「気持ちが考えて」では文が成り立たない。", "に": "「気持ちに考える」という言い方はなく、考える対象には使わない。", "と": "「〜と考える」は「〜だと思う」の意味で、「気持ちと考えて」は成り立たない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "と": "引用・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36574, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「わかった」の対象を示し、「母の気持ちがわかる」の形で文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「わかる」の対象は「が」で示し、「気持ちにわかった」のように「に」で対象を示す言い方はなく、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、わかる対象を表すには使わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「気持ちからわかった」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「わかった」の対象を示し、「母の気持ちがわかる」の形で文に合う。", "に": "「わかる」の対象は「が」で示し、「気持ちにわかった」のように「に」で対象を示す言い方はなく、文が成り立たない。", "へ": "方向を示す助詞で、わかる対象を表すには使わない。", "から": "起点を示す助詞で、「気持ちからわかった」は成り立たない。"}, "error_tags": {"に": "相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36574, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "心の中で感じること。", "primary_collocate": null, "pronunciation": "きもち", "ipa": "kimot͡ɕi", "syllable_count": 3, "sentences": [{"text": "手紙を読んで、うれしい気持ちになった。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "手紙[てがみ]を読[よ]んで、うれしい気持[きも]ちになった。", "sentence_source": "generated"}, {"text": "彼女の気持ちを考えて、何も言わなかった。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の気持[きも]ちを考[かんが]えて、何[なに]も言[い]わなかった。", "sentence_source": "generated"}, {"text": "負けて悔しい気持ちが、なかなか消えない。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "負[ま]けて悔[くや]しい気持[きも]ちが、なかなか消[き]えない。", "sentence_source": "generated"}, {"text": "自分の気持ちを言葉にするのは難しい。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "自分[じぶん]の気持[きも]ちを言葉[ことば]にするのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "朝の散歩をすると、気持ちが落ち着く。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "朝[あさ]の散歩[さんぽ]をすると、気持[きも]ちが落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "感謝の気持ちを込めて、花を贈った。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "感謝[かんしゃ]の気持[きも]ちを込[こ]めて、花[はな]を贈[おく]った。", "sentence_source": "generated"}, {"text": "試合の前は、不安な気持ちでいっぱいだった。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]は、不安[ふあん]な気持[きも]ちでいっぱいだった。", "sentence_source": "generated"}, {"text": "母の気持ちがやっとわかった。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "母[はは]の気持[きも]ちがやっとわかった。", "sentence_source": "generated"}, {"text": "気持ちを切りかえて、もう一度がんばった。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "気持[きも]ちを切[き]りかえて、もう一度[いちど]がんばった。", "sentence_source": "generated"}, {"text": "友達に謝りたい気持ちはあるが、勇気が出ない。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "友達[ともだち]に謝[あやま]りたい気持[きも]ちはあるが、勇気[ゆうき]が出[で]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気持ち", "label": "基本形"}], "register": "普通体", "sense_fingerprint": "心の中で感じる思い・感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: contains vocabulary far above tier T1: 切りかえ (Zipf 1.88)']::text[], '0df666cf-660e-4a65-8685-1c7e60c94a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36574, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気持ち", "is_correct": true, "explanation": "心の中で感じるものを表し、「うれしい気持ちになった」という文に合う。"}, {"text": "座席", "is_correct": false, "explanation": "座る場所のことで、うれしい状態を表す文脈には合わない。"}, {"text": "手順", "is_correct": false, "explanation": "物事を進める順序のことで、うれしい状態には当てはまらない。"}, {"text": "本棚", "is_correct": false, "explanation": "本を並べる家具のことで、心の状態を表す文脈には合わない。"}], "explanations": {"気持ち": "心の中で感じるものを表し、「うれしい気持ちになった」という文に合う。", "座席": "座る場所のことで、うれしい状態を表す文脈には合わない。", "手順": "物事を進める順序のことで、うれしい状態には当てはまらない。", "本棚": "本を並べる家具のことで、心の状態を表す文脈には合わない。"}, "sentence_index": 0, "correct_answer": "気持ち"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今朝は気持ちが低く、冷え込んだ。", "explanation": "ここは〈気温〉（空気の温度）の意味。気温の高低は気温で表し、気持ちを温度の高さ低さとして使うことはない。"}, {"text": "指先にかすかな気持ちが残った。", "explanation": "ここは〈感覚〉（体で感じる刺激）の意味。指先に残る感じは身体の感覚で、心の状態の気持ちとは言わない。"}, {"text": "布の気持ちがやわらかい。", "explanation": "ここは〈感触〉（手で触れたときの感じ）の意味。布のやわらかさは感触で表し、気持ちとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36574, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気持ち", "is_correct": true, "explanation": "不安という心の状態が「いっぱい」になるという文脈に合う。"}, {"text": "玄関", "is_correct": false, "explanation": "家の出入り口のことで、不安でいっぱいという状態には合わない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便料金を示す小さな紙で、心の状態を表す文脈には使わない。"}, {"text": "乾電池", "is_correct": false, "explanation": "機器に入れる電源のことで、心の状態を表す文脈には合わない。"}], "explanations": {"気持ち": "不安という心の状態が「いっぱい」になるという文脈に合う。", "玄関": "家の出入り口のことで、不安でいっぱいという状態には合わない。", "切手": "郵便料金を示す小さな紙で、心の状態を表す文脈には使わない。", "乾電池": "機器に入れる電源のことで、心の状態を表す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "気持ち"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台風の気持ちが近づいている。", "explanation": "ここは〈気配〉（何かが近づく様子）の意味。台風が近づく様子は気配で表し、気持ちとは言わない。"}, {"text": "彼の気持ちは論理的だ。", "explanation": "ここは〈思考〉（考えを筋道立てて進めること）の意味。論理の筋道は思考で表し、気持ちには当てはまらない。"}, {"text": "この料理は気持ちが濃い。", "explanation": "ここは〈味〉の意味。料理の濃さは味で表し、気持ちの濃さとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36574, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "相手の気持ちに察して、静かに席を譲った。", "corrected_sentence": "相手の気持ちを察して、静かに席を譲った。", "error_description": "「察する」は「〜を察する」と目的語に「を」を取る。「気持ちに」の「に」は誤りで、「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36574, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父の言葉を聞いて、気持ちが晴れだ。", "corrected_sentence": "父の言葉を聞いて、気持ちが晴れた。", "error_description": "過去形は「晴れた」が正しい。「晴れだ」は「た」が「だ」になった誤りで、動詞の過去形として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
