INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36575, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が何かを感じたり考えたりする、心の状態や感情。", "primary_collocate": null, "pronunciation": "きもち", "ipa": "kimot͡ɕi", "syllable_count": 3, "sentences": [{"text": "彼は人の気持ちを大切にする、優しい人だと思う。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "彼は人[ひと]の 気持[きも]ちを 大切[たいせつ]にする、優しい人[ひと]だと思う。", "sentence_source": "generated"}, {"text": "相手の気持ちが変わらないうちに、返事をした。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "相手[あいて]の気持[きも]ちが変[か]わらないうちに、返事[へんじ]をした。", "sentence_source": "generated"}, {"text": "旅行の前は、毎回気持ちが高まる。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "旅行[りょこう]の前[まえ]は、毎回[まいかい]気持[きも]ちが高[たか]まる。", "sentence_source": "generated"}, {"text": "雨の日は、なんとなく気持ちが重くなる。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、なんとなく気持[きも]ちが重[おも]くなる。", "sentence_source": "generated"}, {"text": "二人の気持ちがすれ違って、会話が減った。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "二人[ふたり]の気持[きも]ちがすれ違[ちが]って、会話[かいわ]が減[へ]った。", "sentence_source": "generated"}, {"text": "試験が終わって、気持ちが軽くなった。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "試験[しけん]が終[お]わって、気持[きも]ちが軽[かる]くなった。", "sentence_source": "generated"}, {"text": "彼女は気持ちをおさえて、静かに話した。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は気持[きも]ちをおさえて、静[しず]かに話[はな]した。", "sentence_source": "generated"}, {"text": "その知らせを聞いて、複雑な気持ちになった。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "その知[し]らせを聞[き]いて、複雑[ふくざつ]な気持[きも]ちになった。", "sentence_source": "generated"}, {"text": "長い間、同じ気持ちで彼を待っていた。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]、同[おな]じ気持[きも]ちで彼[かれ]を待[ま]っていた。", "sentence_source": "generated"}, {"text": "気持ちが沈んでいる友達を、そっと見守った。", "target_word": "気持ち", "complexity_tier": "T3", "furigana": "気持[きも]ちが沈[しず]んでいる友達[ともだち]を、そっと見守[みまも]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気持ち", "label": "基本形"}], "register": "普通体", "sense_fingerprint": "その時々の心の状態・感情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df666cf-660e-4a65-8685-1c7e60c94a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36575, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気持ち", "is_correct": true, "explanation": "人の心の状態や感情を表し、「大切にする」対象として文に合う。"}, {"text": "雑草", "is_correct": false, "explanation": "庭などに生える草のことで、人を大切にするという文脈には当てはまらない。"}, {"text": "公式", "is_correct": false, "explanation": "決まった形の数式や定型の言い方のことで、人を大切にする対象ではない。"}, {"text": "窓口", "is_correct": false, "explanation": "手続きを受け付ける場所のことで、人を大切にするという文脈には合わない。"}], "explanations": {"気持ち": "人の心の状態や感情を表し、「大切にする」対象として文に合う。", "雑草": "庭などに生える草のことで、人を大切にするという文脈には当てはまらない。", "公式": "決まった形の数式や定型の言い方のことで、人を大切にする対象ではない。", "窓口": "手続きを受け付ける場所のことで、人を大切にするという文脈には合わない。"}, "sentence_index": 0, "correct_answer": "気持ち"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この秤で、小麦粉の気持ちを百グラムで量った。", "explanation": "ここは〈重さ〉（目方）の意味。目方は量れるが、気持ちは重さとして量れないので、百グラムという重さの単位とは合わない。"}, {"text": "指先の気持ちが鈍くなる。", "explanation": "ここは〈感覚〉（体で感じる力）の意味。指先の鈍さは身体の感覚で、心の状態の気持ちとは言わない。"}, {"text": "その山は気持ちが高く、登るのが大変だ。", "explanation": "ここは〈標高〉（海面からの高さ）の意味。山の高さは標高で表し、気持ちが高いとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36575, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気持ち", "is_correct": true, "explanation": "心の中の感情を表し、「おさえる」対象として文に合う。"}, {"text": "土鍋", "is_correct": false, "explanation": "煮物などに使う鍋のことで、感情をおさえるという文脈には当てはまらない。"}, {"text": "模型", "is_correct": false, "explanation": "実物を小さく作ったもので、感情をおさえる対象ではない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "食品を冷やす家電のことで、感情をおさえるという文脈には合わない。"}], "explanations": {"気持ち": "心の中の感情を表し、「おさえる」対象として文に合う。", "土鍋": "煮物などに使う鍋のことで、感情をおさえるという文脈には当てはまらない。", "模型": "実物を小さく作ったもので、感情をおさえる対象ではない。", "冷蔵庫": "食品を冷やす家電のことで、感情をおさえるという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "気持ち"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その紙の気持ちを測る。", "explanation": "ここは〈厚さ〉の意味。紙の厚さは測るものだが、気持ちは測れないので合わない。"}, {"text": "車の気持ちが上がった。", "explanation": "ここは〈速度〉の意味。車の速さは速度で表し、車の気持ちが上がるとは言わない。"}, {"text": "風邪をこじらせて気持ちを崩した友達を、そっと見守った。", "explanation": "ここは〈体調〉（体の状態）の意味。体の調子は崩すものだが、気持ちを崩すとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36575, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの気持ちに確かめてから、話を進めた。", "corrected_sentence": "子どもの気持ちを確かめてから、話を進めた。", "error_description": "「確かめる」は「〜を確かめる」と目的語に「を」を取る。「気持ちに」の「に」は誤りで、「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36575, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その連絡で、気持ちが落ち着いく。", "corrected_sentence": "その連絡で、気持ちが落ち着いた。", "error_description": "過去形は「落ち着いた」が正しい。「落ち着いく」は語尾の誤りで、動詞の活用として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36576, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反感", "is_correct": true, "explanation": "相手への嫌な感情や反発を表し、他人の気持ちがわかる共感の反対にあたる。"}, {"text": "食欲", "is_correct": false, "explanation": "食べたいという欲求で、共感の対義語ではない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のことで、人の気持ちとは関係がない。"}, {"text": "計画", "is_correct": false, "explanation": "将来の予定のことで、共感の対義語ではない。"}], "correct_answer": "反感", "explanations": {"反感": "相手への嫌な感情や反発を表し、他人の気持ちがわかる共感の反対にあたる。", "食欲": "食べたいという欲求で、共感の対義語ではない。", "天気": "空模様のことで、人の気持ちとは関係がない。", "計画": "将来の予定のことで、共感の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36576, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反感", "is_correct": true, "explanation": "相手に対する反発や嫌な感情で、他人の気持ちをわかる共感の反対にあたる。"}, {"text": "旅行", "is_correct": false, "explanation": "出かけて楽しむことで、共感の対義語ではない。"}, {"text": "季節", "is_correct": false, "explanation": "春夏秋冬などの時期のことで、共感とは関係がない。"}, {"text": "電池", "is_correct": false, "explanation": "電気を蓄える部品で、共感の対義語ではない。"}], "correct_answer": "反感", "explanations": {"反感": "相手に対する反発や嫌な感情で、他人の気持ちをわかる共感の反対にあたる。", "旅行": "出かけて楽しむことで、共感の対義語ではない。", "季節": "春夏秋冬などの時期のことで、共感とは関係がない。", "電池": "電気を蓄える部品で、共感の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36576, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他の人の気持ちがわかること。", "primary_collocate": null, "pronunciation": "きょうかん", "ipa": "kʲoːkaɴ", "syllable_count": 4, "sentences": [{"text": "友だちの悩みを聞いて、強く共感した。", "target_word": "共感", "complexity_tier": "T3", "furigana": "友[とも]だちの悩[なや]みを聞[き]いて、強[つよ]く共感[きょうかん]した。", "sentence_source": "generated"}, {"text": "彼女の話には共感できる部分が多かった。", "target_word": "共感", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の話[はなし]には共感[きょうかん]できる部分[ぶぶん]が多[おお]かった。", "sentence_source": "generated"}, {"text": "この映画の主人公に共感して、思わず涙が出た。", "target_word": "共感", "complexity_tier": "T3", "furigana": "この映画[えいが]の主人公[しゅじんこう]に共感[きょうかん]して、思[おも]わず涙[なみだ]が出[で]た。", "sentence_source": "generated"}, {"text": "相手に共感することが、よい聞き手になる第一歩だ。", "target_word": "共感", "complexity_tier": "T4", "furigana": "相手[あいて]に共感[きょうかん]することが、よい聞[き]き手[て]になる第一歩[だいいっぽ]だ。", "sentence_source": "generated"}, {"text": "同じ経験をした人だから、彼の苦しみに共感できるのだろう。", "target_word": "共感", "complexity_tier": "T4", "furigana": "同[おな]じ経験[けいけん]をした人[ひと]だから、彼[かれ]の苦[くる]しみに共感[きょうかん]できるのだろう。", "sentence_source": "generated"}, {"text": "先生は生徒の失敗に共感を示し、優しく声をかけた。", "target_word": "共感", "complexity_tier": "T4", "furigana": "先生[せんせい]は生徒[せいと]の失敗[しっぱい]に共感[きょうかん]を示[しめ]し、優[やさ]しく声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "その歌詞は多くの若者の共感を呼んだ。", "target_word": "共感", "complexity_tier": "T4", "furigana": "その歌詞[かし]は多[おお]くの若者[わかもの]の共感[きょうかん]を呼[よ]んだ。", "sentence_source": "generated"}, {"text": "彼の悔しい気持ちには共感できたが、責める態度には賛成できなかった。", "target_word": "共感", "complexity_tier": "T3", "furigana": "彼[かれ]の悔[くや]しい気持[きも]ちには共感[きょうかん]できたが、責[せ]める態度[たいど]には賛成[さんせい]できなかった。", "sentence_source": "generated"}, {"text": "話をただ聞いて共感してくれるだけで、気持ちが楽になる。", "target_word": "共感", "complexity_tier": "T3", "furigana": "話[はなし]をただ聞[き]いて共感[きょうかん]してくれるだけで、気持[きも]ちが楽[らく]になる。", "sentence_source": "generated"}, {"text": "母は私の失敗を叱らず、まず共感の言葉をかけてくれた。", "target_word": "共感", "complexity_tier": "T4", "furigana": "母[はは]は私[わたし]の失敗[しっぱい]を叱[しか]らず、まず共感[きょうかん]の言葉[ことば]をかけてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共感", "label": "基本形"}, {"form": "共感する", "label": "サ変動詞"}, {"form": "共感した", "label": "過去形"}, {"form": "共感して", "label": "て形"}, {"form": "共感できる", "label": "可能形"}], "register": "中立（常体）", "sense_fingerprint": "他人の気持ちがわかり、そうだなと思うこと（サ変名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36576, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共感", "is_correct": true, "explanation": "サ変名詞で、「強く共感した」と相手の気持ちがわかったことを表す。"}, {"text": "悲しみ", "is_correct": false, "explanation": "名詞だが「強く悲しみした」とは言わず、ここでは文が成り立たない。"}, {"text": "眠気", "is_correct": false, "explanation": "「強く眠気した」は言えず、眠気は動詞「する」と結びつかない。"}, {"text": "友情", "is_correct": false, "explanation": "「強く友情した」とは言えず、この文脈では意味も成り立たない。"}], "explanations": {"共感": "サ変名詞で、「強く共感した」と相手の気持ちがわかったことを表す。", "悲しみ": "名詞だが「強く悲しみした」とは言わず、ここでは文が成り立たない。", "眠気": "「強く眠気した」は言えず、眠気は動詞「する」と結びつかない。", "友情": "「強く友情した」とは言えず、この文脈では意味も成り立たない。"}, "sentence_index": 0, "correct_answer": "共感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このギターは、低い音に共感して弦が大きく震えた。", "explanation": "ここは〈共鳴〉の意味。音の振動が響き合う現象で、人の気持ちをわかる共感とは違う。"}, {"text": "この数式の意味に共感できるまで、何度も読み返した。", "explanation": "ここは〈理解〉の意味。共感は人の気持ちを分かち合う言葉で、数式の内容には使わない。"}, {"text": "この二つのデータには、強い共感がある。", "explanation": "ここは〈相関〉の意味。共感は人の気持ちがわかることで、データ同士の関係には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36576, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共感", "is_correct": true, "explanation": "「多くの若者の共感を呼んだ」と、人々の心に響いたことを表す。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔を呼んだ」とは言えず、呼ぶ対象として成り立たない。"}, {"text": "健康", "is_correct": false, "explanation": "「健康を呼んだ」は不自然で、この文脈では成立しない。"}, {"text": "公平", "is_correct": false, "explanation": "「公平を呼んだ」とは言えず、文の意味が通らない。"}], "explanations": {"共感": "「多くの若者の共感を呼んだ」と、人々の心に響いたことを表す。", "清潔": "「清潔を呼んだ」とは言えず、呼ぶ対象として成り立たない。", "健康": "「健康を呼んだ」は不自然で、この文脈では成立しない。", "公平": "「公平を呼んだ」とは言えず、文の意味が通らない。"}, "sentence_index": 6, "correct_answer": "共感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お礼の電話で、彼に共感を三回言ってから切った。", "explanation": "ここは〈感謝〉の意味。共感は相手の気持ちを分かることで、お礼の言葉としては使わない。"}, {"text": "二つの会社が共感で新商品を開発した。", "explanation": "ここは〈共同〉の意味。協力して何かを作る意味はなく、共感は気持ちを分かり合うことを表す。"}, {"text": "その旅の共感を、友だちと夜中まで話し合った。", "explanation": "ここは〈感想〉の意味。共感は気持ちが分かることで、感じたことを語る内容としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36576, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この小説の主人公を共感して、最後まで読み続けた。", "corrected_sentence": "この小説の主人公に共感して、最後まで読み続けた。", "error_description": "「共感する」は相手に「に」を付ける。「を」は誤りで、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36576, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生の言葉に共感て、もう一度頑張ろうと思った。", "corrected_sentence": "先生の言葉に共感して、もう一度頑張ろうと思った。", "error_description": "「共感する」のて形は「共感して」。「共感て」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36577, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反感", "is_correct": true, "explanation": "相手に対する反発の気持ちで、他人の気持ちをわかる共感の反対にあたる。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面のことで、共感とは関係がない。"}, {"text": "電車", "is_correct": false, "explanation": "乗り物のことで、共感の対義語ではない。"}, {"text": "手紙", "is_correct": false, "explanation": "文字で伝える通信のことで、共感の対義語ではない。"}], "correct_answer": "反感", "explanations": {"反感": "相手に対する反発の気持ちで、他人の気持ちをわかる共感の反対にあたる。", "天井": "部屋の上の面のことで、共感とは関係がない。", "電車": "乗り物のことで、共感の対義語ではない。", "手紙": "文字で伝える通信のことで、共感の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
