INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36577, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他人の感情や立場を理解し、同じように感じること。", "primary_collocate": null, "pronunciation": "きょうかん", "ipa": "kʲoːkaɴ", "syllable_count": 4, "sentences": [{"text": "共感は、相手の立場に立って考えるところから生まれる。", "target_word": "共感", "complexity_tier": "T4", "furigana": "共感[きょうかん]は、相手[あいて]の立場[たちば]に立[た]って考[かんが]えるところから生[う]まれる。", "sentence_source": "generated"}, {"text": "医師には、患者の不安に共感する姿勢が求められる。", "target_word": "共感", "complexity_tier": "T4", "furigana": "医師[いし]には、患者[かんじゃ]の不安[ふあん]に共感[きょうかん]する姿勢[しせい]が求[もと]められる。", "sentence_source": "generated"}, {"text": "彼のスピーチは、聞く人の共感を得て拍手に包まれた。", "target_word": "共感", "complexity_tier": "T4", "furigana": "彼[かれ]のスピーチは、聞[き]く人[ひと]の共感[きょうかん]を得[え]て拍手[はくしゅ]に包[つつ]まれた。", "sentence_source": "generated"}, {"text": "登場人物の悲しみに共感し、最後まで読み進めた。", "target_word": "共感", "complexity_tier": "T4", "furigana": "登場人物[とうじょうじんぶつ]の悲[かな]しみに共感[きょうかん]し、最後[さいご]まで読[よ]み進[すす]めた。", "sentence_source": "generated"}, {"text": "共感と同情は似ているが、共感は相手と同じ目線で感じることだ。", "target_word": "共感", "complexity_tier": "T4", "furigana": "共感[きょうかん]と同情[どうじょう]は似[に]ているが、共感[きょうかん]は相手[あいて]と同[おな]じ目線[めせん]で感[かん]じることだ。", "sentence_source": "generated"}, {"text": "広告は消費者の共感を得られなければ、商品は売れない。", "target_word": "共感", "complexity_tier": "T4", "furigana": "広告[こうこく]は消費者[しょうひしゃ]の共感[きょうかん]を得[え]られなければ、商品[しょうひん]は売[う]れない。", "sentence_source": "generated"}, {"text": "被災した人々への共感が、全国から支援の輪を広げた。", "target_word": "共感", "complexity_tier": "T4", "furigana": "被災[ひさい]した人々[ひとびと]への共感[きょうかん]が、全国[ぜんこく]から支援[しえん]の輪[わ]を広[ひろ]げた。", "sentence_source": "generated"}, {"text": "相手の痛みに共感しようとする努力が、対立を和らげた。", "target_word": "共感", "complexity_tier": "T3", "furigana": "相手[あいて]の痛[いた]みに共感[きょうかん]しようとする努力[どりょく]が、対立[たいりつ]を和[やわ]らげた。", "sentence_source": "generated"}, {"text": "小説の魅力は、読者が登場人物に共感できるかどうかで決まる。", "target_word": "共感", "complexity_tier": "T4", "furigana": "小説[しょうせつ]の魅力[みりょく]は、読者[どくしゃ]が登場人物[とうじょうじんぶつ]に共感[きょうかん]できるかどうかで決[き]まる。", "sentence_source": "generated"}, {"text": "共感しながら話を聞くと、相手は心を開いてくれる。", "target_word": "共感", "complexity_tier": "T3", "furigana": "共感[きょうかん]しながら話[はなし]を聞[き]くと、相手[あいて]は心[こころ]を開[ひら]いてくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "共感", "label": "基本形"}, {"form": "共感する", "label": "サ変動詞"}, {"form": "共感し", "label": "連用形"}, {"form": "共感できる", "label": "可能形"}], "register": "書き言葉・やや硬い（常体）", "sense_fingerprint": "他人の感情や立場を理解し、自分も同じように感じること（サ変名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36577, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共感", "is_correct": true, "explanation": "「共感は、相手の立場に立って考える」と、主題として成り立つ名詞になる。"}, {"text": "砂糖", "is_correct": false, "explanation": "相手の立場に立って考えることから生まれるとは言えず、主語として不自然。"}, {"text": "駐車場", "is_correct": false, "explanation": "場所を表す名詞で、考える姿勢から生まれるという文の主語にならない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は身体の状態で、相手の立場に立つことから生まれるとは言えない。"}], "explanations": {"共感": "「共感は、相手の立場に立って考える」と、主題として成り立つ名詞になる。", "砂糖": "相手の立場に立って考えることから生まれるとは言えず、主語として不自然。", "駐車場": "場所を表す名詞で、考える姿勢から生まれるという文の主語にならない。", "眠気": "眠気は身体の状態で、相手の立場に立つことから生まれるとは言えない。"}, "sentence_index": 0, "correct_answer": "共感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "音叉を鳴らすと、隣の音叉が共感して震え出した。", "explanation": "ここは〈共鳴〉の意味。振動が響き合う現象で、人の気持ちには使わない。"}, {"text": "二つの研究所が共感で新しい薬を開発した。", "explanation": "ここは〈共同〉の意味。協力して開発する意味で、共感は気持ちを分かり合うことを表す。"}, {"text": "長年の支えに深く共感して、手紙を書いた。", "explanation": "ここは〈感謝〉の意味。共感は相手の気持ちを分かることで、お礼の気持ちは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36577, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共感", "is_correct": true, "explanation": "「被災した人々への共感が、支援の輪を広げた」と、心を寄せる気持ちを表す。"}, {"text": "信号", "is_correct": false, "explanation": "交通の合図で、「被災した人々への信号」とは言えず文が成り立たない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "筆記具のことで、支援の輪を広げる主語にはならない。"}, {"text": "座布団", "is_correct": false, "explanation": "敷物のことで、「被災した人々への座布団」は意味をなさない。"}], "explanations": {"共感": "「被災した人々への共感が、支援の輪を広げた」と、心を寄せる気持ちを表す。", "信号": "交通の合図で、「被災した人々への信号」とは言えず文が成り立たない。", "鉛筆": "筆記具のことで、支援の輪を広げる主語にはならない。", "座布団": "敷物のことで、「被災した人々への座布団」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "共感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この定理の証明に共感できるまで、ノートを何度も見直した。", "explanation": "ここは〈理解〉の意味。共感は人の気持ちを分かり合うことで、数学の証明には使わない。"}, {"text": "その旅の共感を、友だちと夜中まで話し合った。", "explanation": "ここは〈感想〉の意味。共感は気持ちが分かることで、感じたことを語る内容としては使わない。"}, {"text": "気温と売り上げの間には、強い共感がある。", "explanation": "ここは〈相関〉の意味。共感は人の気持ちの理解で、数値同士の関係には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36577, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看護師には、患者の痛みに共感ない力が必要だ。", "corrected_sentence": "看護師には、患者の痛みに共感する力が必要だ。", "error_description": "サ変動詞の連体形は「共感する」。「共感ない」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36577, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の苦しみに共感ながら、ゆっくり話を聞いた。", "corrected_sentence": "彼の苦しみに共感しながら、ゆっくり話を聞いた。", "error_description": "「共感しながら」の「し」が必要。「共感ながら」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
