INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36578, 3, 'prompt1_core', '{"pos": "接続詞", "semantic_class": "function", "definition": "違う言葉で同じことを言うときに使う接続詞。", "primary_collocate": null, "pronunciation": "つまり", "ipa": "tsɯmaɾi", "syllable_count": 3, "sentences": [{"text": "私の父の弟、つまりおじが遊びに来た。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "私[わたし]の父[ちち]の弟[おとうと]、つまりおじが遊[あそ]びに来[き]た。", "sentence_source": "generated"}, {"text": "彼は毎日練習している。つまり、本気で勝つつもりだ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "彼[かれ]は毎日[まいにち]練習[れんしゅう]している。つまり、本気[ほんき]で勝[か]つつもりだ。", "sentence_source": "generated"}, {"text": "明日は休みだ。つまり、一日中ゆっくり寝られる。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "明日[あした]は休[やす]みだ。つまり、一日中[いちにちじゅう]ゆっくり寝[ね]られる。", "sentence_source": "generated"}, {"text": "彼女は「考えておく」と言った。つまり、断るという意味だ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は「考[かんが]えておく」と言[い]った。つまり、断[ことわ]るという意味[いみ]だ。", "sentence_source": "generated"}, {"text": "彼は一人っ子、つまり兄弟がいない。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "彼は一人[ひとり]っ子[こ]、つまり兄弟[きょうだい]がいない。", "sentence_source": "generated"}, {"text": "このカードは、つまり、お金の代わりになるものだ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "このカードは、つまり、お金[かね]の代[か]わりになるものだ。", "sentence_source": "generated"}, {"text": "弟は何も食べなかった。つまり、具合が悪かったのだ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "弟[おとうと]は何[なに]も食[た]べなかった。つまり、具合[ぐあい]が悪[わる]かったのだ。", "sentence_source": "generated"}, {"text": "百円の十倍、つまり千円だ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "百円[ひゃくえん]の十倍[じゅうばい]、つまり千円[せんえん]だ。", "sentence_source": "generated"}, {"text": "私は犬が好きではない。つまり、飼うつもりはない。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "私[わたし]は犬[いぬ]が好[す]きではない。つまり、飼[か]うつもりはない。", "sentence_source": "generated"}, {"text": "彼は何度も遅れた。つまり、約束を守らない人だ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "彼[かれ]は何度[なんど]も遅[おく]れた。つまり、約束[やくそく]を守[まも]らない人[ひと]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "つまり", "label": "基本形"}], "register": "普通体", "sense_fingerprint": "別の言葉で言い換えるときの接続語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df666cf-660e-4a65-8685-1c7e60c94a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36578, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "つまり", "is_correct": true, "explanation": "前の「おじ」を「父の弟」と言い換えて説明しているので、言い換えの接続詞が入る。"}, {"text": "しかし", "is_correct": false, "explanation": "逆接を表し、言い換えの文脈には合わない。"}, {"text": "だから", "is_correct": false, "explanation": "原因から結果へつなぐ語で、ここは言い換えなので合わない。"}, {"text": "なぜなら", "is_correct": false, "explanation": "理由を後から述べる語で、言い換えの文脈には合わない。"}], "explanations": {"つまり": "前の「おじ」を「父の弟」と言い換えて説明しているので、言い換えの接続詞が入る。", "しかし": "逆接を表し、言い換えの文脈には合わない。", "だから": "原因から結果へつなぐ語で、ここは言い換えなので合わない。", "なぜなら": "理由を後から述べる語で、言い換えの文脈には合わない。"}, "sentence_index": 0, "correct_answer": "つまり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議は五時に始まる。つまり、来週の予定は未定だ。", "explanation": "ここは〈ところで〉（話題を変える言葉）の意味。つまりは前の内容を言い換えるときに使うので、話題を変える場面には合わない。"}, {"text": "彼は毎日練習した。つまり、試合に負けた。", "explanation": "ここは〈しかし〉（逆接）の意味。つまりは言い換えに使うので、毎日の練習と負けたことが言い換えの関係にない対立の文脈では使わない。"}, {"text": "食事をして、つまり散歩に行った。", "explanation": "ここは〈それから〉（次の動作へ移る順序）の意味。つまりは言い換えなので、動作の順序を表す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36578, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "つまり", "is_correct": true, "explanation": "前の「何も食べなかった」を「具合が悪かった」と言い換えて説明している。"}, {"text": "それから", "is_correct": false, "explanation": "時間の流れや順番を表し、言い換えとは合わない。"}, {"text": "例えば", "is_correct": false, "explanation": "具体例を挙げる語で、ここは言い換えなので合わない。"}, {"text": "次に", "is_correct": false, "explanation": "話の順番を示す語で、説明の言い換えには当てはまらない。"}], "explanations": {"つまり": "前の「何も食べなかった」を「具合が悪かった」と言い換えて説明している。", "それから": "時間の流れや順番を表し、言い換えとは合わない。", "例えば": "具体例を挙げる語で、ここは言い換えなので合わない。", "次に": "話の順番を示す語で、説明の言い換えには当てはまらない。"}, "sentence_index": 6, "correct_answer": "つまり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒かった。つまり、暖房をつけた。", "explanation": "ここは〈だから〉（原因から結果へ）の意味。つまりは言い換えなので、原因と結果をつなぐ場面には使わない。"}, {"text": "兄は背が高い。つまり、弟は小さい。", "explanation": "ここは〈一方〉（対比）の意味。つまりは言い換えなので、二つを対比する文脈では使わない。"}, {"text": "雨の予報だった。つまり、晴れた。", "explanation": "ここは〈ところが〉（予想と反対の結果）の意味。つまりは言い換えなので、予想に反する結果を述べる場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36578, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は毎日、海外のドラマを見ている。つまりです、英語に慣れている。", "corrected_sentence": "彼は毎日、海外のドラマを見ている。つまり、英語に慣れている。", "error_description": "接続詞「つまり」に丁寧な断定の「です」を付けている。「つまり」は接続の働きを持つ語で、「です」を付けて述語にすることはできない。正しくは「つまり、」と続ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36578, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は三日続けて休んだ。つまりが、体調が悪いようだ。", "corrected_sentence": "彼は三日続けて休んだ。つまり、体調が悪いようだ。", "error_description": "接続詞「つまり」に助詞「が」は付かない。正しくは「つまり、」で、「つまりが」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
