INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36579, 3, 'prompt1_core', '{"pos": "接続詞", "semantic_class": "function", "definition": "物事を要約したり、言い換えたりするときに使う接続詞です。話の要点を整理して、聞き手が理解しやすいようにまとめます。", "primary_collocate": null, "pronunciation": "つまり", "ipa": "tsɯmaɾi", "syllable_count": 3, "sentences": [{"text": "話が長くなったが、つまり、反対だということだ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "話[はなし]が長[なが]くなったが、つまり、反対[はんたい]だということだ。", "sentence_source": "generated"}, {"text": "家賃が高く、駅も遠い。つまり、この部屋は住みにくい。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "家賃[やちん]が高[たか]く、駅[えき]も遠[とお]い。つまり、この部屋[へや]は住[す]みにくい。", "sentence_source": "generated"}, {"text": "売り上げは半分になった。つまり、大きな問題だ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げは半分[はんぶん]になった。つまり、大[おお]きな問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "彼は何も言わずに帰った。つまり、怒っているのだろう。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "彼[かれ]は何[なに]も言[い]わずに帰[かえ]った。つまり、怒[おこ]っているのだろう。", "sentence_source": "generated"}, {"text": "毎日運動して、よく眠る。つまり、健康的な生活だ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "毎日[まいにち]運動[うんどう]して、よく眠[ねむ]る。つまり、健康的[けんこうてき]な生活[せいかつ]だ。", "sentence_source": "generated"}, {"text": "計画は遅れ、お金も足りない。つまり、続けるのは難しい。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "計画[けいかく]は遅[おく]れ、お金[かね]も足[た]りない。つまり、続[つづ]けるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼女は走るのも泳ぐのも得意だ。つまり、運動が全部できる。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は走[はし]るのも泳[およ]ぐのも得意[とくい]だ。つまり、運動[うんどう]が全部[ぜんぶ]できる。", "sentence_source": "generated"}, {"text": "返事がない。つまり、まだ読んでいないということだ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "返事[へんじ]がない。つまり、まだ読[よ]んでいないということだ。", "sentence_source": "generated"}, {"text": "宿題が多く、試験も近い。つまり、今週は忙しい。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]が多[おお]く、試験[しけん]も近[ちか]い。つまり、今週[こんしゅう]は忙[いそが]しい。", "sentence_source": "generated"}, {"text": "彼の話は長かったが、つまり、もう少し待ってほしいということだ。", "target_word": "つまり", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は長[なが]かったが、つまり、もう少[すこ]し待[ま]ってほしいということだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "つまり", "label": "基本形"}], "register": "普通体", "sense_fingerprint": "前の内容を要約して結論を示す接続語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df666cf-660e-4a65-8685-1c7e60c94a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36579, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "つまり", "is_correct": true, "explanation": "前の内容を要約して結論を示す語。「長い話の結論は反対だ」という流れに合う。"}, {"text": "ところで", "is_correct": false, "explanation": "話題を変える語で、前の内容をまとめる働きはないため、ここでは合わない。"}, {"text": "ちなみに", "is_correct": false, "explanation": "補足を付け加える語。結論を示す位置には入らない。"}, {"text": "なぜなら", "is_correct": false, "explanation": "理由を後ろから示す語。「反対だということだ」は理由ではないので合わない。"}], "explanations": {"つまり": "前の内容を要約して結論を示す語。「長い話の結論は反対だ」という流れに合う。", "ところで": "話題を変える語で、前の内容をまとめる働きはないため、ここでは合わない。", "ちなみに": "補足を付け加える語。結論を示す位置には入らない。", "なぜなら": "理由を後ろから示す語。「反対だということだ」は理由ではないので合わない。"}, "sentence_index": 0, "correct_answer": "つまり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日は雨だった。つまり、明日の天気はどうだろうか。", "explanation": "ここは〈ちなみに〉（話題に関係する補足を添える）の意味。〈つまり〉は前の内容をまとめたり言い換えたりする語なので、補足を加えて話題を移す場面には合わない。"}, {"text": "朝ご飯を食べた。つまり、学校へ行った。", "explanation": "ここは〈それから〉（出来事の順番を続ける）の意味。〈つまり〉は要約の語なので、起きたことを時間の順に並べる場面には合わない。"}, {"text": "彼は色々な国に行った。つまり、タイには三回も行っている。", "explanation": "ここは例を挙げる場面なので〈例えば〉が必要。〈つまり〉は前の内容を言い換えるだけで、例を示す役割はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36579, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "つまり", "is_correct": true, "explanation": "前の内容を要約して言い換える語。「走るのも泳ぐのも得意」を「運動が全部できる」とまとめる流れに合う。"}, {"text": "ただし", "is_correct": false, "explanation": "条件や例外を付け加える語。ここでは前の内容をまとめる流れにならず合わない。"}, {"text": "それとも", "is_correct": false, "explanation": "選択肢を並べて問いかける時に使う語。要約の文には入らない。"}, {"text": "さて", "is_correct": false, "explanation": "話題を切り替える語。前の内容を言い換える働きはないので合わない。"}], "explanations": {"つまり": "前の内容を要約して言い換える語。「走るのも泳ぐのも得意」を「運動が全部できる」とまとめる流れに合う。", "ただし": "条件や例外を付け加える語。ここでは前の内容をまとめる流れにならず合わない。", "それとも": "選択肢を並べて問いかける時に使う語。要約の文には入らない。", "さて": "話題を切り替える語。前の内容を言い換える働きはないので合わない。"}, "sentence_index": 6, "correct_answer": "つまり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が降っている。つまり、風も強い。", "explanation": "ここは〈しかも〉（さらに付け加える）の意味が必要な場面。〈つまり〉は言い換えや要約の語で、付け加えの代わりにはならない。"}, {"text": "この牛乳は毎朝届く。つまり、日曜日は休みだ。", "explanation": "ここは〈ただし〉（条件や例外を添える）の意味。〈つまり〉は前の内容を言い換えたり要約したりする語なので、例外を示す場面には合わない。"}, {"text": "明日行くか、つまり来週にするか。", "explanation": "ここは〈それとも〉（選択肢を並べる）の意味。〈つまり〉は言い換えの語で、二つの選択肢を示す役割はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36579, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日も休まず練習した。つまりです、努力を続けたということだ。", "corrected_sentence": "雨の日も休まず練習した。つまり、努力を続けたということだ。", "error_description": "接続詞「つまり」に丁寧な断定の「です」を付けている。「つまり」は接続の働きを持つ語で、「です」を付けて述語にすることはできない。正しくは「つまり、」と続ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36579, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "野菜を毎日食べ、週に三回は歩く。つまりに、健康的な暮らしだ。", "corrected_sentence": "野菜を毎日食べ、週に三回は歩く。つまり、健康的な暮らしだ。", "error_description": "接続詞「つまり」に助詞「に」は付かない。正しくは「つまり、」で、「つまりに」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36580, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『眠気が覚める』の主語を示す『が』。覚めるは自動詞。"}, {"text": "を", "is_correct": false, "explanation": "覚めるは自動詞なので、目的語の『を』は合わない。"}, {"text": "に", "is_correct": false, "explanation": "『眠気に覚めた』とは言わず、『に』は文に入らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を表す『と』で、ここでは文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『眠気が覚める』の主語を示す『が』。覚めるは自動詞。", "を": "覚めるは自動詞なので、目的語の『を』は合わない。", "に": "『眠気に覚めた』とは言わず、『に』は文に入らない。", "と": "並列や相手を表す『と』で、ここでは文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "方向・対象", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36580, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36580, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ねむくなること", "primary_collocate": null, "pronunciation": "ねむけ", "ipa": "nemɯke", "syllable_count": 3, "sentences": [{"text": "昼ごはんを食べたあとは、眠気が来て仕事が進まない。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "昼[ひる]ごはんを食[た]べたあとは、眠気[ねむけ]が来[き]て仕事[しごと]が進[すす]まない。", "sentence_source": "generated"}, {"text": "コーヒーを飲んだら、眠気が覚めた。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "コーヒーを飲[の]んだら、眠気[ねむけ]が覚[さ]めた。", "sentence_source": "generated"}, {"text": "この薬を飲むと眠気が出ることがあるので、運転してはいけない。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "この薬[くすり]を飲[の]むと眠気[ねむけ]が出[で]ることがあるので、運転[うんてん]してはいけない。", "sentence_source": "generated"}, {"text": "授業が退屈で、強い眠気に負けそうになった。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]が退屈[たいくつ]で、強[つよ]い眠気[ねむけ]に負[ま]けそうになった。", "sentence_source": "generated"}, {"text": "眠気を我慢して、夜遅くまで宿題をした。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "眠気[ねむけ]を我慢[がまん]して、夜遅[よるおそ]くまで宿題[しゅくだい]をした。", "sentence_source": "generated"}, {"text": "春は暖かくて、一日中眠気が取れない。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "春[はる]は暖[あたた]かくて、一日中[いちにちじゅう]眠気[ねむけ]が取[と]れない。", "sentence_source": "generated"}, {"text": "運転中に眠気を感じたら、すぐ休むべきだ。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "運転中[うんてんちゅう]に眠気[ねむけ]を感[かん]じたら、すぐ休[やす]むべきだ。", "sentence_source": "generated"}, {"text": "顔を洗って、眠気を吹き飛ばした。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "顔[かお]を洗[あら]って、眠気[ねむけ]を吹[ふ]き飛[と]ばした。", "sentence_source": "generated"}, {"text": "遅くまで起きていたので、朝から眠気がひどい。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "遅[おそ]くまで起[お]きていたので、朝[あさ]から眠気[ねむけ]がひどい。", "sentence_source": "generated"}, {"text": "長い会議の途中で、急に眠気が襲ってきた。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "長[なが]い会議[かいぎ]の途中[とちゅう]で、急[きゅう]に眠気[ねむけ]が襲[おそ]ってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眠気", "label": "基本形"}, {"form": "眠気が", "label": "主格（が）"}], "register": "中立", "sense_fingerprint": "ねむくなる感覚が起こること（眠気が来る・覚める・襲う）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36580, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眠気", "is_correct": true, "explanation": "「来る」と合い、仕事を進みにくくする体の感覚を指す。ここでの正解。"}, {"text": "割引", "is_correct": false, "explanation": "値引きの意味で、体に来る感覚ではないため「来て仕事が進まない」の主語にならない。"}, {"text": "絵画", "is_correct": false, "explanation": "作品を指す名詞で、食後に来て仕事を妨げるという文脈に合わない。"}, {"text": "接着剤", "is_correct": false, "explanation": "物質を指す名詞で、食後に来て仕事が進まなくなる話にはならない。"}], "explanations": {"眠気": "「来る」と合い、仕事を進みにくくする体の感覚を指す。ここでの正解。", "割引": "値引きの意味で、体に来る感覚ではないため「来て仕事が進まない」の主語にならない。", "絵画": "作品を指す名詞で、食後に来て仕事を妨げるという文脈に合わない。", "接着剤": "物質を指す名詞で、食後に来て仕事が進まなくなる話にはならない。"}, "sentence_index": 0, "correct_answer": "眠気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜中に何度も目が覚めるのは、眠気が浅いからだ。", "explanation": "ここは〈眠り〉の意味。『眠りが浅い』とは言うが、眠気に深さ・浅さを言う使い方はない。"}, {"text": "寝室の照明を暗くすると、眠気の質が高まる。", "explanation": "ここは〈睡眠〉の意味。『睡眠の質』とは言うが、眠気の質が高まるとは言わない。"}, {"text": "薬を飲んだので、眠気がすっかり下がった。", "explanation": "ここは〈熱〉の場面。熱は『下がる』と言うが、眠気は『引く・覚める』で、『下がる』とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36580, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眠気", "is_correct": true, "explanation": "運転中に感じると危険な体の感覚を指す。ここでの正解。"}, {"text": "保険証", "is_correct": false, "explanation": "身分を証明する書類で、感じる対象にはならない。"}, {"text": "窓ガラス", "is_correct": false, "explanation": "車の部品で、感じて休むという文に合わない。"}, {"text": "乾電池", "is_correct": false, "explanation": "電気を供給する物品で、感じる対象にならない。"}], "explanations": {"眠気": "運転中に感じると危険な体の感覚を指す。ここでの正解。", "保険証": "身分を証明する書類で、感じる対象にはならない。", "窓ガラス": "車の部品で、感じて休むという文に合わない。", "乾電池": "電気を供給する物品で、感じる対象にならない。"}, "sentence_index": 6, "correct_answer": "眠気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一晩寝て、眠気がすっかり回復した。", "explanation": "ここは〈疲労〉の意味。疲労は『回復する』と言うが、眠気は『覚める・取れる』で、回復とは言わない。"}, {"text": "授業を聞いて、眠気がすっかり解けた。", "explanation": "ここは〈疑問〉の意味。疑問は『解ける』と言うが、眠気は『覚める』で、解けるとは言わない。"}, {"text": "紅茶を飲んで、眠気がすっかり冴えた。", "explanation": "ここは〈目〉の意味。目は『冴える』と言うが、眠気は『覚める』で、冴えるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36580, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薬の影響で、午前中から眠気を強くなった。", "corrected_sentence": "薬の影響で、午前中から眠気が強くなった。", "error_description": "誤りは『眠気を』。『強くなる』の主語は眠気なので『が』が正しい。『を』は目的語を示すため、『強くなる』とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36580, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝の冷たい水で、眠気がすっかり覚ました。", "corrected_sentence": "朝の冷たい水で、眠気がすっかり覚めた。", "error_description": "誤りは『覚ました』。『覚める』は自動詞で主語は眠気。『覚ました』は他動詞の形なので、眠気を主語にできない。正しくは『覚めた』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36581, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『眠気が強くなる』の主語を示す『が』。"}, {"text": "を", "is_correct": false, "explanation": "『強くなる』は自動詞なので、目的語の『を』は合わない。"}, {"text": "に", "is_correct": false, "explanation": "『強くなる』と『に』は結びつかず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列の『と』で、『眠気と強くなる』は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "『眠気が強くなる』の主語を示す『が』。", "を": "『強くなる』は自動詞なので、目的語の『を』は合わない。", "に": "『強くなる』と『に』は結びつかず、文が成り立たない。", "と": "並列の『と』で、『眠気と強くなる』は成り立たない。"}, "error_tags": {"を": "目的語", "に": "結果", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36581, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "『眠気で目が開かない』と原因を表す『で』。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』で、原因の文脈には入らない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する『の』で、『眠気の目』となり文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較や起点を表す『より』で、ここでは原因を表せない。"}], "correct_answer": "で", "explanations": {"で": "『眠気で目が開かない』と原因を表す『で』。", "へ": "方向を表す『へ』で、原因の文脈には入らない。", "の": "名詞を修飾する『の』で、『眠気の目』となり文が成り立たない。", "より": "比較や起点を表す『より』で、ここでは原因を表せない。"}, "error_tags": {"へ": "方向", "の": "名詞修飾", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36581, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ねむりたいというきもち。からだがねむりをほしがっているじょうたい。", "primary_collocate": null, "pronunciation": "ねむけ", "ipa": "nemɯke", "syllable_count": 3, "sentences": [{"text": "夜更かしをした次の日は、一日中眠気が残る。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "夜更[よふ]かしをした次[つぎ]の日[ひ]は、一日中[いちにちじゅう]眠気[ねむけ]が残[のこ]る。", "sentence_source": "generated"}, {"text": "子どもは眠気が強くなると、機嫌が悪くなる。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "子[こ]どもは眠気[ねむけ]が強[つよ]くなると、機嫌[きげん]が悪[わる]くなる。", "sentence_source": "generated"}, {"text": "温かいお茶を飲んだら、だんだん眠気が出てきた。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "温[あたた]かいお茶[ちゃ]を飲[の]んだら、だんだん眠気[ねむけ]が出[で]てきた。", "sentence_source": "generated"}, {"text": "徹夜が続いて、体が眠気を訴えている。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "徹夜[てつや]が続[つづ]いて、体[からだ]が眠気[ねむけ]を訴[うった]えている。", "sentence_source": "generated"}, {"text": "電車の揺れが心地よくて、すぐに眠気に襲われた。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の揺[ゆ]れが心地[ここち]よくて、すぐに眠気[ねむけ]に襲[おそ]われた。", "sentence_source": "generated"}, {"text": "眠気があるときは、無理に勉強しないほうがいい。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "眠気[ねむけ]があるときは、無理[むり]に勉強[べんきょう]しないほうがいい。", "sentence_source": "generated"}, {"text": "赤ちゃんは眠気が来ると、目をこすり始める。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは眠気[ねむけ]が来[く]ると、目[め]をこすり始[はじ]める。", "sentence_source": "generated"}, {"text": "部屋が暖かすぎて、眠気で目が開かない。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "部屋[へや]が暖[あたた]かすぎて、眠気[ねむけ]で目[め]が開[あ]かない。", "sentence_source": "generated"}, {"text": "映画が終わるころには、眠気がピークに達していた。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "映画[えいが]が終[お]わるころには、眠気[ねむけ]がピークに達[たっ]していた。", "sentence_source": "generated"}, {"text": "眠気をこらえて、最後まで試験を受けた。", "target_word": "眠気", "complexity_tier": "T3", "furigana": "眠気[ねむけ]をこらえて、最後[さいご]まで試験[しけん]を受[う]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "眠気", "label": "基本形"}, {"form": "眠気を", "label": "目的格（を）"}], "register": "中立", "sense_fingerprint": "体が眠りを求めている状態、眠りたいという気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36581, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眠気", "is_correct": true, "explanation": "夜更かしの翌日に一日中残る体の感覚を指す。ここでの正解。"}, {"text": "絵画", "is_correct": false, "explanation": "作品を指す名詞で、体に一日中残るという文脈に合わない。"}, {"text": "接着剤", "is_correct": false, "explanation": "物質を指す名詞で、体に残って一日を左右する話にはならない。"}, {"text": "割引", "is_correct": false, "explanation": "値引きの意味で、一日中残るという感覚の文脈に合わない。"}], "explanations": {"眠気": "夜更かしの翌日に一日中残る体の感覚を指す。ここでの正解。", "絵画": "作品を指す名詞で、体に一日中残るという文脈に合わない。", "接着剤": "物質を指す名詞で、体に残って一日を左右する話にはならない。", "割引": "値引きの意味で、一日中残るという感覚の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "眠気"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎晩の眠気時間が短いと、昼間の集中力が落ちる。", "explanation": "ここは〈睡眠〉の場面。睡眠には時間の長さがあるが、眠気には時間の長さを言わない。"}, {"text": "急に眠気が走り、布団に潜り込んだ。", "explanation": "ここは〈悪寒〉の意味。悪寒は『走る』と言うが、眠気は『襲う・来る』で、『走る』とは言わない。"}, {"text": "週末に休んで、眠気がすっかり回復した。", "explanation": "ここは〈疲労〉の場面。疲労は『回復する』と言うが、眠気は『覚める・取れる』で、回復とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36581, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眠気", "is_correct": true, "explanation": "来ると目をこするほどの体の感覚を指す。ここでの正解。"}, {"text": "地図", "is_correct": false, "explanation": "情報を載せた紙で、来て目をこする原因にはならない。"}, {"text": "乾電池", "is_correct": false, "explanation": "電気の部品で、目をこする動作の原因にならない。"}, {"text": "窓ガラス", "is_correct": false, "explanation": "建物の部品で、目をこする原因にならない。"}], "explanations": {"眠気": "来ると目をこするほどの体の感覚を指す。ここでの正解。", "地図": "情報を載せた紙で、来て目をこする原因にはならない。", "乾電池": "電気の部品で、目をこする動作の原因にならない。", "窓ガラス": "建物の部品で、目をこする原因にならない。"}, "sentence_index": 6, "correct_answer": "眠気"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜の散歩で、眠気がすっかり冴えた。", "explanation": "ここは〈目〉の意味。目は『冴える』と言うが、眠気は『覚める』で、冴えるとは言わない。"}, {"text": "解熱剤を飲んだら、眠気がすっと下がった。", "explanation": "ここは〈熱〉の場面。熱は『下がる』と言うが、眠気は『引く・覚める』で、『下がる』とは言わない。"}, {"text": "論文を読み返して、眠気が一つずつ解けた。", "explanation": "ここは〈疑問〉の場面。疑問は『解ける』と言うが、眠気は『覚める』で、解けるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36581, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昼食をとると、どうしても眠気を強くなる。", "corrected_sentence": "昼食をとると、どうしても眠気が強くなる。", "error_description": "誤りは『眠気を』。『強くなる』は自動詞で主語は眠気なので『が』が正しい。『を』は目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36581, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕方の散歩で、眠気がすっかり覚ました。", "corrected_sentence": "夕方の散歩で、眠気がすっかり覚めた。", "error_description": "誤りは『覚ました』。『覚める』は自動詞で主語は眠気。『覚ました』は他動詞の形なので、眠気を主語にできない。正しくは『覚めた』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36582, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見て」の目的語。見る対象がサインなので「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」。「サインが見て」では文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "着点や相手を示す「に」。見る対象は示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「見る」には方向を示す用法が合わない。"}], "correct_answer": "を", "explanations": {"を": "「見て」の目的語。見る対象がサインなので「を」が入る。", "が": "主語を示す「が」。「サインが見て」では文が成り立たない。", "に": "着点や相手を示す「に」。見る対象は示せない。", "へ": "方向の「へ」。「見る」には方向を示す用法が合わない。"}, "error_tags": {"が": "主語", "に": "着点・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36582, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「出す」の目的語。合図のサインを出したという文脈に合う。"}, {"text": "に", "is_correct": false, "explanation": "着点の「に」。「サインに出す」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。出す対象の指定には使えない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手の「と」。「サインと出す」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「出す」の目的語。合図のサインを出したという文脈に合う。", "に": "着点の「に」。「サインに出す」は不自然。", "へ": "方向の「へ」。出す対象の指定には使えない。", "と": "並列や相手の「と」。「サインと出す」は成り立たない。"}, "error_tags": {"に": "着点", "へ": "方向", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36582, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起こることを知らせる合図のこと。", "primary_collocate": null, "pronunciation": "さいん", "ipa": "saiɴ", "syllable_count": 3, "sentences": [{"text": "監督がバッターにバントのサインを出した。", "target_word": "サイン", "complexity_tier": "T3", "furigana": "監督[かんとく]がバッターにバントのサインを出[だ]した。", "sentence_source": "generated"}, {"text": "キャッチャーのサインを見て、ピッチャーはうなずいた。", "target_word": "サイン", "complexity_tier": "T3", "furigana": "キャッチャーのサインを見[み]て、ピッチャーはうなずいた。", "sentence_source": "generated"}, {"text": "彼女は目でサインを送ったが、彼は気づかなかった。", "target_word": "サイン", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は目[め]でサインを送[おく]ったが、彼[かれ]は気[き]づかなかった。", "sentence_source": "generated"}, {"text": "話をやめたい時は、肩をたたくサインにしよう。", "target_word": "サイン", "complexity_tier": "T3", "furigana": "話[はなし]をやめたい時[とき]は、肩[かた]をたたくサインにしよう。", "sentence_source": "generated"}, {"text": "相手にサインを読まれて、盗塁に失敗した。", "target_word": "サイン", "complexity_tier": "T3", "furigana": "相手[あいて]にサインを読[よ]まれて、盗塁[とうるい]に失敗[しっぱい]した。", "sentence_source": "generated"}, {"text": "先生が手を上げるサインをしたら、全員が静かになった。", "target_word": "サイン", "complexity_tier": "T3", "furigana": "先生[せんせい]が手[て]を上[あ]げるサインをしたら、全員[ぜんいん]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "山で笛が三回鳴ったのは、危険を知らせるサインだった。", "target_word": "サイン", "complexity_tier": "T3", "furigana": "山[やま]で笛[ふえ]が三回[さんかい]鳴[な]ったのは、危険[きけん]を知[し]らせるサインだった。", "sentence_source": "generated"}, {"text": "彼がまばたきでサインを出したので、私はすぐに部屋を出た。", "target_word": "サイン", "complexity_tier": "T3", "furigana": "彼[かれ]がまばたきでサインを出[だ]したので、私[わたし]はすぐに部屋[へや]を出[で]た。", "sentence_source": "generated"}, {"text": "打ち合わせの前に、困ったときのサインを仲間と決めた。", "target_word": "サイン", "complexity_tier": "T3", "furigana": "打[う]ち合[あ]わせの前[まえ]に、困[こま]ったときのサインを仲間[なかま]と決[き]めた。", "sentence_source": "generated"}, {"text": "審判は両手を広げて、セーフのサインを示した。", "target_word": "サイン", "complexity_tier": "T3", "furigana": "審判[しんぱん]は両手[りょうて]を広[ひろ]げて、セーフのサインを示[しめ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "サインする", "label": "動詞 基本形"}, {"form": "サインした", "label": "過去形"}, {"form": "サインして", "label": "て形"}], "register": "plain (常体)", "sense_fingerprint": "合図としてのサイン。野球の作戦の合図や目配せなど、次に起こることを前もって知らせる動作や合図。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5fbc95f-0ae8-454f-a614-42c57107f7b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36582, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "サイン", "is_correct": true, "explanation": "「バントのサインを出した」の空所。監督が出す合図の意味で、この文に合う。"}, {"text": "グラブ", "is_correct": false, "explanation": "野球の守備用の手袋。「バントのグラブを出した」は成り立たず、合図の意味にも合わない。"}, {"text": "ベース", "is_correct": false, "explanation": "塁のこと。「バントのベースを出した」は不自然で、合図の意味に合わない。"}, {"text": "ユニフォーム", "is_correct": false, "explanation": "チームの試合用の服。出す対象にはならず、合図の意味にも合わない。"}], "explanations": {"サイン": "「バントのサインを出した」の空所。監督が出す合図の意味で、この文に合う。", "グラブ": "野球の守備用の手袋。「バントのグラブを出した」は成り立たず、合図の意味にも合わない。", "ベース": "塁のこと。「バントのベースを出した」は不自然で、合図の意味に合わない。", "ユニフォーム": "チームの試合用の服。出す対象にはならず、合図の意味にも合わない。"}, "sentence_index": 0, "correct_answer": "サイン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "交差点のサインが青に変わったので、車が一斉に動き出した。", "explanation": "ここは〈信号〉の意味。信号は色が変わって車を動かすものだが、合図のサインは色が変わるものとは言わないので合わない。"}, {"text": "レースを始めるため、先生は空にサインを撃った。", "explanation": "ここは〈号砲〉の意味。号砲は空に撃つものだが、サインは撃つものではないので合わない。"}, {"text": "火事を知らせるサインを鳴らして、人を避難させた。", "explanation": "ここは〈ブザー〉の意味。ブザーは鳴らすものだが、サインは合図そのものなので「鳴らす」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36582, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "サイン", "is_correct": true, "explanation": "「危険を知らせる〜だった」の空所。危険を前もって知らせる合図の意味に合う。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓などに掛ける布。危険を知らせる役目はなく、文の意味が通らない。"}, {"text": "ホッチキス", "is_correct": false, "explanation": "書類を留める道具。危険を知らせるものではない。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "持ち物の布。危険を知らせる合図としては合わない。"}], "explanations": {"サイン": "「危険を知らせる〜だった」の空所。危険を前もって知らせる合図の意味に合う。", "カーテン": "窓などに掛ける布。危険を知らせる役目はなく、文の意味が通らない。", "ホッチキス": "書類を留める道具。危険を知らせるものではない。", "ハンカチ": "持ち物の布。危険を知らせる合図としては合わない。"}, "sentence_index": 6, "correct_answer": "サイン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "避難のためのサインを発令して、住民を集めた。", "explanation": "ここは〈警報〉の意味。警報は発令するものだが、サインは発令するものではないので、この言い方は合わない。"}, {"text": "真夜中にサインが鳴り響き、町中が目を覚ました。", "explanation": "ここは〈サイレン〉の意味。サイレンは鳴り響く音だが、サインは音を出すものではないので合わない。"}, {"text": "先生がサインを吹いて、生徒を集めた。", "explanation": "ここは〈ホイッスル〉の意味。笛は吹くものだが、サインは吹けないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36582, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三塁コーチがサインが送ると、打者は構えた。", "corrected_sentence": "三塁コーチがサインを送ると、打者は構えた。", "error_description": "「送る」は目的語に「を」を取るので、「サインが」は誤り。正しくは「サインを」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36582, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の前には、空が暗くなるサインがよく見る。", "corrected_sentence": "雨の前には、空が暗くなるサインがよく出る。", "error_description": "「サイン」が主語になって続く動詞は「出る」。「見る」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b841a379-0e4f-43ff-abfb-4d6cae412911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36584, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「実際に食べてみる」で、本当に食べてみるという副詞的用法になる。"}, {"text": "で", "is_correct": false, "explanation": "「実際で食べる」は成立せず、場所や手段の「で」は合わない。"}, {"text": "を", "is_correct": false, "explanation": "「実際を食べる」は目的語として意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「実際から食べる」は起点としての意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「実際に食べてみる」で、本当に食べてみるという副詞的用法になる。", "で": "「実際で食べる」は成立せず、場所や手段の「で」は合わない。", "を": "「実際を食べる」は目的語として意味が通らない。", "から": "「実際から食べる」は起点としての意味が通らない。"}, "error_tags": {"で": "場所・手段", "を": "目的語", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
