INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36584, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "本当に、本当のこと。", "primary_collocate": null, "pronunciation": "じっさい", "ipa": "dʑisːai", "syllable_count": 4, "sentences": [{"text": "写真で見たより、実際に行ってみる方がずっときれいだった。", "target_word": "実際", "complexity_tier": "T3", "furigana": "写真[しゃしん]で見[み]たより、実際[じっさい]に行[い]ってみる方[ほう]がずっときれいだった。", "sentence_source": "generated"}, {"text": "実際に食べてみると、思ったよりおいしかった。", "target_word": "実際", "complexity_tier": "T3", "furigana": "実際[じっさい]に食[た]べてみると、思[おも]ったよりおいしかった。", "sentence_source": "generated"}, {"text": "噂は聞いていたが、実際に会うと優しい人だった。", "target_word": "実際", "complexity_tier": "T3", "furigana": "噂[うわさ]は聞[き]いていたが、実際[じっさい]に会[あ]うと優[やさ]しい人[ひと]だった。", "sentence_source": "generated"}, {"text": "計画は立派だが、実際にやるとなると難しい。", "target_word": "実際", "complexity_tier": "T3", "furigana": "計画[けいかく]は立派[りっぱ]だが、実際[じっさい]にやるとなると難[むずか]しい。", "sentence_source": "generated"}, {"text": "実際、あの店は予約なしでは入れないほど人気だ。", "target_word": "実際", "complexity_tier": "T4", "furigana": "実際[じっさい]、あの店[みせ]は予約[よやく]なしでは入[はい]れないほど人気[にんき]だ。", "sentence_source": "generated"}, {"text": "実際に使ってみてから、買うかどうか決める。", "target_word": "実際", "complexity_tier": "T3", "furigana": "実際[じっさい]に使[つか]ってみてから、買[か]うかどうか決[き]める。", "sentence_source": "generated"}, {"text": "実際に雪を見たのは、大学生になってからだ。", "target_word": "実際", "complexity_tier": "T3", "furigana": "実際[じっさい]に雪[ゆき]を見[み]たのは、大学生[だいがくせい]になってからだ。", "sentence_source": "generated"}, {"text": "実際、私も同じ失敗をしたことがある。", "target_word": "実際", "complexity_tier": "T3", "furigana": "実際[じっさい]、私[わたし]も同[おな]じ失敗[しっぱい]をしたことがある。", "sentence_source": "generated"}, {"text": "外国語は、実際に話さなければ上達しない。", "target_word": "実際", "complexity_tier": "T3", "furigana": "外国語[がいこくご]は、実際[じっさい]に話[はな]さなければ上達[じょうたつ]しない。", "sentence_source": "generated"}, {"text": "説明を読むだけでなく、実際に触って確かめてみた。", "target_word": "実際", "complexity_tier": "T4", "furigana": "説明[せつめい]を読[よ]むだけでなく、実際[じっさい]に触[さわ]って確[たし]かめてみた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実際", "label": "基本形"}, {"form": "実際に", "label": "副詞的用法"}, {"form": "実際の", "label": "連体用法"}, {"form": "実際は", "label": "主題形"}], "register": "中立（常体）", "sense_fingerprint": "想像や話ではなく、本当に行う・起こることを表す（実際に／実際、）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36584, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実際", "is_correct": true, "explanation": "「実際に行く」は、写真で見たことと対比して本当に訪れることを表し、文脈に合う。"}, {"text": "想像", "is_correct": false, "explanation": "想像は頭の中で思い描くことなので、「想像に行く」とは言えない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は寝ている間の発言で、場所へ行く文脈に合わない。"}, {"text": "予習", "is_correct": false, "explanation": "予習は授業前の準備で、「予習に行く」は不自然。"}], "explanations": {"実際": "「実際に行く」は、写真で見たことと対比して本当に訪れることを表し、文脈に合う。", "想像": "想像は頭の中で思い描くことなので、「想像に行く」とは言えない。", "寝言": "寝言は寝ている間の発言で、場所へ行く文脈に合わない。", "予習": "予習は授業前の準備で、「予習に行く」は不自然。"}, "sentence_index": 0, "correct_answer": "実際"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "財布の実際を調べて、お金を数えた。", "explanation": "ここは〈中身〉の意味。実際は本当の状態を指し、財布の中身を表す語ではない。"}, {"text": "会議の実際は来週に延期された。", "explanation": "ここは〈日程〉の意味。実際は現実の状態を表し、予定の日時を指す語ではない。"}, {"text": "このかばんは実際が丈夫で、長く使える。", "explanation": "ここは〈素材〉の意味。実際は材料の性質を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36584, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実際", "is_correct": true, "explanation": "「実際に雪を見た」で、本当に雪を見たことを表し、文脈に合う。"}, {"text": "予告", "is_correct": false, "explanation": "予告は前もって知らせることで、「予告に雪を見た」とは言えない。"}, {"text": "伝言", "is_correct": false, "explanation": "伝言は人への言付けで、「伝言に雪を見た」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様で、「天気に雪を見た」は不自然で文脈に合わない。"}], "explanations": {"実際": "「実際に雪を見た」で、本当に雪を見たことを表し、文脈に合う。", "予告": "予告は前もって知らせることで、「予告に雪を見た」とは言えない。", "伝言": "伝言は人への言付けで、「伝言に雪を見た」は意味が通らない。", "天気": "天気は空模様で、「天気に雪を見た」は不自然で文脈に合わない。"}, "sentence_index": 6, "correct_answer": "実際"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この掃除機は実際が良く、吸い込みも強い。", "explanation": "ここは〈性能〉の意味。実際は機械の性能の良し悪しを表す語ではない。"}, {"text": "料理の実際を一つずつ確かめて作った。", "explanation": "ここは〈手順〉の意味。実際は作業の順序を指す語ではない。"}, {"text": "テストの実際が良く、先生にほめられた。", "explanation": "ここは〈成績〉の意味。実際は点数や評価を指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36584, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "実際で会ってみると、優しい人だった。", "corrected_sentence": "実際に会ってみると、優しい人だった。", "error_description": "「実際」は「に」を伴って副詞的に使う。「で」は誤りで、正しくは「実際に会う」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36584, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "図面を見るだけでなく、実際の触って確かめてみた。", "corrected_sentence": "図面を見るだけでなく、実際に触って確かめてみた。", "error_description": "「実際」は動詞「触る」を修飾する副詞なので「に」が必要。「の」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36585, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「実際のあいだ」で、実際を連体修飾する「の」になる。"}, {"text": "で", "is_correct": false, "explanation": "「実際であいだ」は成立せず、場所や手段の「で」は合わない。"}, {"text": "から", "is_correct": false, "explanation": "「実際からあいだ」は起点としての意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「実際をあいだ」は目的語として成立しない。"}], "correct_answer": "の", "explanations": {"の": "「実際のあいだ」で、実際を連体修飾する「の」になる。", "で": "「実際であいだ」は成立せず、場所や手段の「で」は合わない。", "から": "「実際からあいだ」は起点としての意味が通らない。", "を": "「実際をあいだ」は目的語として成立しない。"}, "error_tags": {"で": "場所・手段", "から": "起点", "を": "目的語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
