INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36585, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "事実や現実の状態を指す言葉。", "primary_collocate": null, "pronunciation": "じっさい", "ipa": "dʑisːai", "syllable_count": 4, "sentences": [{"text": "実際の被害は、報道されたよりずっと大きかった。", "target_word": "実際", "complexity_tier": "T4", "furigana": "実際[じっさい]の被害[ひがい]は、報道[ほうどう]されたよりずっと大[おお]きかった。", "sentence_source": "generated"}, {"text": "計画と実際のあいだには、大きな差があった。", "target_word": "実際", "complexity_tier": "T4", "furigana": "計画[けいかく]と実際[じっさい]のあいだには、大[おお]きな差[さ]があった。", "sentence_source": "generated"}, {"text": "彼は若く見えるが、実際は四十歳を超えている。", "target_word": "実際", "complexity_tier": "T3", "furigana": "彼[かれ]は若[わか]く見[み]えるが、実際[じっさい]は四十歳[よんじゅっさい]を超[こ]えている。", "sentence_source": "generated"}, {"text": "実際のところ、この問題は簡単には解決しない。", "target_word": "実際", "complexity_tier": "T4", "furigana": "実際[じっさい]のところ、この問題[もんだい]は簡単[かんたん]には解決[かいけつ]しない。", "sentence_source": "generated"}, {"text": "実際には雨が降らず、予報ははずれた。", "target_word": "実際", "complexity_tier": "T3", "furigana": "実際[じっさい]には雨[あめ]が降[ふ]らず、予報[よほう]ははずれた。", "sentence_source": "generated"}, {"text": "この小説は実際の事件をもとに書かれた。", "target_word": "実際", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は実際[じっさい]の事件[じけん]をもとに書[か]かれた。", "sentence_source": "generated"}, {"text": "実際の費用は、見積もりより二割高かった。", "target_word": "実際", "complexity_tier": "T4", "furigana": "実際[じっさい]の費用[ひよう]は、見積[みつ]もりより二割[にわり]高[たか]かった。", "sentence_source": "generated"}, {"text": "理想を語るのはいいが、実際の現場は厳しい。", "target_word": "実際", "complexity_tier": "T4", "furigana": "理想[りそう]を語[かた]るのはいいが、実際[じっさい]の現場[げんば]は厳[きび]しい。", "sentence_source": "generated"}, {"text": "実際の人口を調べるため、市は調査を行った。", "target_word": "実際", "complexity_tier": "T4", "furigana": "実際[じっさい]の人口[じんこう]を調[しら]べるため、市[し]は調査[ちょうさ]を行[おこな]った。", "sentence_source": "generated"}, {"text": "彼女は自信があるように話すが、実際は不安でいっぱいだった。", "target_word": "実際", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は自信[じしん]があるように話[はな]すが、実際[じっさい]は不安[ふあん]でいっぱいだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実際", "label": "基本形"}, {"form": "実際の", "label": "連体用法"}, {"form": "実際は", "label": "主題形"}, {"form": "実際には", "label": "対比用法"}], "register": "中立（常体）", "sense_fingerprint": "建前や予想ではなく、事実・現実の状態を指す名詞（実際の〜／実際は）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36585, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "実際", "is_correct": true, "explanation": "「実際の被害」は事実としての被害を指し、報道との比較に合う。"}, {"text": "予習", "is_correct": false, "explanation": "予習は授業前の準備で、被害を修飾する語としては成立しない。"}, {"text": "伝言", "is_correct": false, "explanation": "伝言は人への言付けで、「伝言の被害」は意味が通らない。"}, {"text": "寝言", "is_correct": false, "explanation": "寝言は寝ている間の発言で、被害の大きさを表す文脈に合わない。"}], "explanations": {"実際": "「実際の被害」は事実としての被害を指し、報道との比較に合う。", "予習": "予習は授業前の準備で、被害を修飾する語としては成立しない。", "伝言": "伝言は人への言付けで、「伝言の被害」は意味が通らない。", "寝言": "寝言は寝ている間の発言で、被害の大きさを表す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "実際"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅行の実際を十万円までと決めた。", "explanation": "ここは〈予算〉の意味。実際は事実の状態で、金額の上限を表す語ではない。"}, {"text": "映画の実際を聞いて、友達と話した。", "explanation": "ここは〈感想〉の意味。実際は作品への受け止めを指す語ではない。"}, {"text": "プロジェクトの実際を立てて、チームに配った。", "explanation": "ここは〈計画〉の意味。実際は現状を表す語で、計画を立てる対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36585, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "実際", "is_correct": true, "explanation": "「実際の費用」は実際にかかった金額を指し、見積もりとの比較に合う。"}, {"text": "見通し", "is_correct": false, "explanation": "見通しは今後の予測で、「見通しの費用」は意味が通らない。"}, {"text": "助言", "is_correct": false, "explanation": "助言は人へのアドバイスで、費用を修飾する語としては成立しない。"}, {"text": "雑談", "is_correct": false, "explanation": "雑談は世間話で、「雑談の費用」は文脈に合わない。"}], "explanations": {"実際": "「実際の費用」は実際にかかった金額を指し、見積もりとの比較に合う。", "見通し": "見通しは今後の予測で、「見通しの費用」は意味が通らない。", "助言": "助言は人へのアドバイスで、費用を修飾する語としては成立しない。", "雑談": "雑談は世間話で、「雑談の費用」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "実際"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の実際を、一週間の予定表に書き込んだ。", "explanation": "ここは〈予定〉の意味。実際は現状を表す語で、予定表に書き込む対象ではない。"}, {"text": "今朝の実際はあまり良くなく、頭が痛かった。", "explanation": "ここは〈体調〉の意味。実際は体の状態を指す語ではない。"}, {"text": "この料理の実際は、少し辛いのが好みだ。", "explanation": "ここは〈好み〉の意味。実際は味の好みを表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
