INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36585, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実際で工事費は、見積もりより二割高かった。", "corrected_sentence": "実際の工事費は、見積もりより二割高かった。", "error_description": "連体修飾の「の」を「で」にした誤り。正しくは「実際の工事費」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36586, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「映像が急に止まる」で、映像を主語にする「が」になる。"}, {"text": "を", "is_correct": false, "explanation": "「映像を止まる」は目的語の「を」では自動詞の「止まる」と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「映像で止まる」は場所や手段の「で」で、文の主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「映像へ止まる」は方向の「へ」で、止まる主体を表さない。"}], "correct_answer": "が", "explanations": {"が": "「映像が急に止まる」で、映像を主語にする「が」になる。", "を": "「映像を止まる」は目的語の「を」では自動詞の「止まる」と合わない。", "で": "「映像で止まる」は場所や手段の「で」で、文の主語にならない。", "へ": "「映像へ止まる」は方向の「へ」で、止まる主体を表さない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
