INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36586, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "テレビやパソコンで見る、うごく絵のことです。", "primary_collocate": null, "pronunciation": "えいぞう", "ipa": "eːzoː", "syllable_count": 4, "sentences": [{"text": "新しいテレビは映像がとてもきれいだ。", "target_word": "映像", "complexity_tier": "T2", "furigana": "新[あたら]しいテレビは映像[えいぞう]がとてもきれいだ。", "sentence_source": "generated"}, {"text": "パソコンの映像が急に止まってしまった。", "target_word": "映像", "complexity_tier": "T2", "furigana": "パソコンの映像[えいぞう]が急[きゅう]に止[と]まってしまった。", "sentence_source": "generated"}, {"text": "音は聞こえるが、映像が映らない。", "target_word": "映像", "complexity_tier": "T2", "furigana": "音[おと]は聞[き]こえるが、映像[えいぞう]が映[うつ]らない。", "sentence_source": "generated"}, {"text": "映画の映像を大きな画面で見たい。", "target_word": "映像", "complexity_tier": "T3", "furigana": "映画[えいが]の映像[えいぞう]を大[おお]きな画面[がめん]で見[み]たい。", "sentence_source": "generated"}, {"text": "映像が暗くて、顔がよく見えなかった。", "target_word": "映像", "complexity_tier": "T3", "furigana": "映像[えいぞう]が暗[くら]くて、顔[かお]がよく見[み]えなかった。", "sentence_source": "generated"}, {"text": "この動画は映像も音も古いが、なつかしい。", "target_word": "映像", "complexity_tier": "T3", "furigana": "この動画[どうが]は映像[えいぞう]も音[おと]も古[ふる]いが、なつかしい。", "sentence_source": "generated"}, {"text": "授業で、海の生き物の映像を見た。", "target_word": "映像", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]で、海[うみ]の生[い]き物[もの]の映像[えいぞう]を見[み]た。", "sentence_source": "generated"}, {"text": "ネットが遅いと、映像がときどき止まる。", "target_word": "映像", "complexity_tier": "T3", "furigana": "ネットが遅[おそ]いと、映像[えいぞう]がときどき止[と]まる。", "sentence_source": "generated"}, {"text": "兄は映像を作る仕事をしたいと言っている。", "target_word": "映像", "complexity_tier": "T3", "furigana": "兄[あに]は映像[えいぞう]を作[つく]る仕事[しごと]をしたいと言[い]っている。", "sentence_source": "generated"}, {"text": "映像を見ながら、ダンスの練習をした。", "target_word": "映像", "complexity_tier": "T3", "furigana": "映像[えいぞう]を見[み]ながら、ダンスの練習[れんしゅう]をした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "映像", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "テレビやパソコンの画面に映る動く絵(画面で見る動画)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36586, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "映像", "is_correct": true, "explanation": "「映像がとてもきれいだ」で、テレビの映りの美しさを表し、文脈に合う。"}, {"text": "値段", "is_correct": false, "explanation": "値段は価格で、「値段がきれいだ」とは言わない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは物の重量で、「重さがきれいだ」は意味が通らない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸で、テレビの話には合わない。"}], "explanations": {"映像": "「映像がとてもきれいだ」で、テレビの映りの美しさを表し、文脈に合う。", "値段": "値段は価格で、「値段がきれいだ」とは言わない。", "重さ": "重さは物の重量で、「重さがきれいだ」は意味が通らない。", "寝息": "寝息は眠っている人の呼吸で、テレビの話には合わない。"}, "sentence_index": 0, "correct_answer": "映像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しいイヤホンは映像がはっきり聞こえる。", "explanation": "ここは〈音声〉の意味。映像は見るもので、聞こえるものとは言わない。"}, {"text": "この本の映像は読みやすく、子どもにも分かる。", "explanation": "ここは〈文章〉の意味。映像は動く画像で、読みやすさを表す語ではない。"}, {"text": "鏡の映像を見て、髪を整えた。", "explanation": "ここは〈鏡に映った姿〉の意味。動く画像ではなく、鏡に映る像を指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36586, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "映像", "is_correct": true, "explanation": "「海の生き物の映像を見た」で、授業で見た動く画像を表し、文脈に合う。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸で、海の生き物の映像とは結びつかない。"}, {"text": "鳴き声", "is_correct": false, "explanation": "鳴き声は音で、「鳴き声を見た」とは言えない。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖は寝起きの髪の乱れで、海の生き物の映像とは結びつかない。"}], "explanations": {"映像": "「海の生き物の映像を見た」で、授業で見た動く画像を表し、文脈に合う。", "寝息": "寝息は眠っている人の呼吸で、海の生き物の映像とは結びつかない。", "鳴き声": "鳴き声は音で、「鳴き声を見た」とは言えない。", "寝癖": "寝癖は寝起きの髪の乱れで、海の生き物の映像とは結びつかない。"}, "sentence_index": 6, "correct_answer": "映像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい香水の映像をかぐと、花の匂いがした。", "explanation": "ここは〈香り〉の意味。映像は視覚のもので、かぐことはできない。"}, {"text": "紙の映像に文字を書いて、手紙を作った。", "explanation": "ここは〈紙〉の意味。映像は文字を書く材料にはならない。"}, {"text": "この布の映像は、さらさらして気持ちいい。", "explanation": "ここは〈手触り〉の意味。映像は触って感じるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36586, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最新のテレビは映像をとてもきれいだ。", "corrected_sentence": "最新のテレビは映像がとてもきれいだ。", "error_description": "「きれいだ」の主語を表す助詞は「が」。「を」にした誤りで、正しくは「映像がきれいだ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36586, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ネットが遅いと、映像をときどき途切れる。", "corrected_sentence": "ネットが遅いと、映像がときどき途切れる。", "error_description": "「途切れる」は自動詞なので主語は「が」。「を」にした誤りで、正しくは「映像がときどき途切れる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36587, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「防犯カメラの映像から、犯人が分かった」で、情報の出どころを表す「から」になる。"}, {"text": "を", "is_correct": false, "explanation": "「映像を、犯人が分かった」は目的語の「を」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「映像へ、犯人が分かった」は方向の「へ」で、情報の出どころを表さない。"}, {"text": "に", "is_correct": false, "explanation": "「映像に、犯人が分かった」は不自然で、出どころの意味にならない。"}], "correct_answer": "から", "explanations": {"から": "「防犯カメラの映像から、犯人が分かった」で、情報の出どころを表す「から」になる。", "を": "「映像を、犯人が分かった」は目的語の「を」では意味が通らない。", "へ": "「映像へ、犯人が分かった」は方向の「へ」で、情報の出どころを表さない。", "に": "「映像に、犯人が分かった」は不自然で、出どころの意味にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "に": "時点・帰着"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36587, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「古い映像には」で、映像に含まれているものを示す「に」になる。"}, {"text": "が", "is_correct": false, "explanation": "「映像がは」は「が」と「は」が重ならず、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「映像の、昔の町のくらしが残っている」は連体修飾にならず、文が成立しない。"}, {"text": "か", "is_correct": false, "explanation": "「映像かは」は「か」と「は」が続かず、文として不自然で成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「古い映像には」で、映像に含まれているものを示す「に」になる。", "が": "「映像がは」は「が」と「は」が重ならず、文として成り立たない。", "の": "「映像の、昔の町のくらしが残っている」は連体修飾にならず、文が成立しない。", "か": "「映像かは」は「か」と「は」が続かず、文として不自然で成り立たない。"}, "error_tags": {"が": "主語", "の": "所属・修飾", "か": "選択"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36587, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "実際のようすをうつし出した、動いている画像。", "primary_collocate": null, "pronunciation": "えいぞう", "ipa": "eːzoː", "syllable_count": 4, "sentences": [{"text": "事故の映像がニュースで流れた。", "target_word": "映像", "complexity_tier": "T2", "furigana": "事故[じこ]の映像[えいぞう]がニュースで流[なが]れた。", "sentence_source": "generated"}, {"text": "防犯カメラの映像から、犯人が分かった。", "target_word": "映像", "complexity_tier": "T3", "furigana": "防犯[ぼうはん]カメラの映像[えいぞう]から、犯人[はんにん]が分[わ]かった。", "sentence_source": "generated"}, {"text": "現場の映像を見て、被害の大きさに驚いた。", "target_word": "映像", "complexity_tier": "T3", "furigana": "現場[げんば]の映像[えいぞう]を見[み]て、被害[ひがい]の大[おお]きさに驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "火山が噴火した瞬間の映像が公開された。", "target_word": "映像", "complexity_tier": "T4", "furigana": "火山[かざん]が噴火[ふんか]した瞬間[しゅんかん]の映像[えいぞう]が公開[こうかい]された。", "sentence_source": "generated"}, {"text": "ドライブレコーダーの映像が証拠になった。", "target_word": "映像", "complexity_tier": "T4", "furigana": "ドライブレコーダーの映像[えいぞう]が証拠[しょうこ]になった。", "sentence_source": "generated"}, {"text": "生中継の映像で、試合の様子が伝えられた。", "target_word": "映像", "complexity_tier": "T4", "furigana": "生中継[なまちゅうけい]の映像[えいぞう]で、試合[しあい]の様子[ようす]が伝[つた]えられた。", "sentence_source": "generated"}, {"text": "衛星が送ってきた映像には、大きな台風が映っていた。", "target_word": "映像", "complexity_tier": "T4", "furigana": "衛星[えいせい]が送[おく]ってきた映像[えいぞう]には、大[おお]きな台風[たいふう]が映[うつ]っていた。", "sentence_source": "generated"}, {"text": "古い映像には、昔の町のくらしが残っている。", "target_word": "映像", "complexity_tier": "T3", "furigana": "古[ふる]い映像[えいぞう]には、昔[むかし]の町[まち]のくらしが残[のこ]っている。", "sentence_source": "generated"}, {"text": "警察は店の映像を調べている。", "target_word": "映像", "complexity_tier": "T3", "furigana": "警察[けいさつ]は店[みせ]の映像[えいぞう]を調[しら]べている。", "sentence_source": "generated"}, {"text": "彼は現地で撮った映像を番組に提供した。", "target_word": "映像", "complexity_tier": "T4", "furigana": "彼[かれ]は現地[げんち]で撮[と]った映像[えいぞう]を番組[ばんぐみ]に提供[ていきょう]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "映像", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "実際の出来事や現場を撮影・記録した動く画像(報道・記録の映像)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188d0434-16db-495f-a1f6-7f78712b3277') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36587, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "映像", "is_correct": true, "explanation": "「事故の映像がニュースで流れた」で、実際の事故を写した動く画像を表し、文脈に合う。"}, {"text": "注文", "is_correct": false, "explanation": "注文は品物などを頼むことで、ニュースで流れるものではない。"}, {"text": "指紋", "is_correct": false, "explanation": "指紋は指の模様で、ニュースで流れる内容として成立しない。"}, {"text": "寝息", "is_correct": false, "explanation": "寝息は眠っている人の呼吸で、事故の報道とは文脈が合わない。"}], "explanations": {"映像": "「事故の映像がニュースで流れた」で、実際の事故を写した動く画像を表し、文脈に合う。", "注文": "注文は品物などを頼むことで、ニュースで流れるものではない。", "指紋": "指紋は指の模様で、ニュースで流れる内容として成立しない。", "寝息": "寝息は眠っている人の呼吸で、事故の報道とは文脈が合わない。"}, "sentence_index": 0, "correct_answer": "映像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "報告書の映像をまとめて、上司に出した。", "explanation": "ここは〈報告書〉の意味。映像は文書ではなく、まとめて出すものでもない。"}, {"text": "人口の映像を年ごとに数えた。", "explanation": "ここは〈統計〉の意味。映像は数字の集まりではなく、数える対象にならない。"}, {"text": "夏休みの映像を、白い紙に一枚ずつ貼って展示した。", "explanation": "ここは〈写真〉の意味。映像は動く画像で、紙に貼って並べる一枚の写真とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36587, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "映像", "is_correct": true, "explanation": "「衛星が送ってきた映像には、大きな台風が映っていた」で、衛星が送った画像を表し、文脈に合う。"}, {"text": "体重", "is_correct": false, "explanation": "体重は人や物の重さで、衛星が送ってくるものとしては成立しない。"}, {"text": "名簿", "is_correct": false, "explanation": "名簿は人の名前の一覧で、台風が映っているという文脈に合わない。"}, {"text": "寝癖", "is_correct": false, "explanation": "寝癖は寝起きの髪の乱れで、衛星の送信内容として成立しない。"}], "explanations": {"映像": "「衛星が送ってきた映像には、大きな台風が映っていた」で、衛星が送った画像を表し、文脈に合う。", "体重": "体重は人や物の重さで、衛星が送ってくるものとしては成立しない。", "名簿": "名簿は人の名前の一覧で、台風が映っているという文脈に合わない。", "寝癖": "寝癖は寝起きの髪の乱れで、衛星の送信内容として成立しない。"}, "sentence_index": 6, "correct_answer": "映像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は現地で映像を描いて、道順を示した。", "explanation": "ここは〈地図〉の意味。映像は描くものではなく、道を示す図にもならない。"}, {"text": "彼は現地で映像をつけて、一日の出来事を残した。", "explanation": "ここは〈日記〉の意味。映像は文章を書き残すものではない。"}, {"text": "彼は現地で映像を塗って、日焼けを防いだ。", "explanation": "ここは〈日焼け止め〉の意味。映像は肌に塗るものではなく、日焼けを防ぐ語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36587, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい事故の映像をニュースで流れた。", "corrected_sentence": "新しい事故の映像がニュースで流れた。", "error_description": "「流れた」の主語を表す助詞は「が」。「を」にした誤りで、正しくは「映像がニュースで流れた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36587, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜中の映像を、大きな台風が映っていた。", "corrected_sentence": "夜中の映像には、大きな台風が映っていた。", "error_description": "「映像には」の「には」を「を」にした誤り。「映る」の場所は「には」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2098d868-9c46-4a40-8314-cdd4f10d4859') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
