INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36590, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "abstract", "definition": "一度見ただけでは、本当のことがよくわからないようす。", "primary_collocate": null, "pronunciation": "いっけん", "ipa": "ikkeɴ", "syllable_count": 4, "sentences": [{"text": "一見やさしそうな人だが、実は仕事にとても厳しい。", "target_word": "一見", "complexity_tier": "T3", "furigana": "一見[いっけん]やさしそうな人[ひと]だが、実[じつ]は仕事[しごと]にとても厳[きび]しい。", "sentence_source": "generated"}, {"text": "この問題は一見かんたんだが、解いてみると難しい。", "target_word": "一見", "complexity_tier": "T3", "furigana": "この問題[もんだい]は一見[いっけん]かんたんだが、解[と]いてみると難[むずか]しい。", "sentence_source": "generated"}, {"text": "彼は一見おとなしいが、話してみるとよく笑う人だ。", "target_word": "一見", "complexity_tier": "T3", "furigana": "彼[かれ]は一見[いっけん]おとなしいが、話[はな]してみるとよく笑[わら]う人[ひと]だ。", "sentence_source": "generated"}, {"text": "一見ただの石に見えるが、実は大切な化石だ。", "target_word": "一見", "complexity_tier": "T3", "furigana": "一見[いっけん]ただの石[いし]に見[み]えるが、実[じつ]は大切[たいせつ]な化石[かせき]だ。", "sentence_source": "generated"}, {"text": "この店は一見普通の家だが、中に入ると有名なレストランだ。", "target_word": "一見", "complexity_tier": "T3", "furigana": "この店[みせ]は一見[いっけん]普通[ふつう]の家[いえ]だが、中[なか]に入[はい]ると有名[ゆうめい]なレストランだ。", "sentence_source": "generated"}, {"text": "一見同じ絵に見えるが、よく見ると色が少し違う。", "target_word": "一見", "complexity_tier": "T3", "furigana": "一見[いっけん]同[おな]じ絵[え]に見[み]えるが、よく見[み]ると色[いろ]が少[すこ]し違[ちが]う。", "sentence_source": "generated"}, {"text": "一見安い商品でも、送料を入れると高くなることがある。", "target_word": "一見", "complexity_tier": "T3", "furigana": "一見[いっけん]安[やす]い商品[しょうひん]でも、送料[そうりょう]を入[い]れると高[たか]くなることがある。", "sentence_source": "generated"}, {"text": "一見簡単な道だが、雨の日は滑りやすくて危ない。", "target_word": "一見", "complexity_tier": "T3", "furigana": "一見[いっけん]簡単[かんたん]な道[みち]だが、雨[あめ]の日[ひ]は滑[すべ]りやすくて危[あぶ]ない。", "sentence_source": "generated"}, {"text": "この箱は一見空に見えるが、底に小さな鍵が入っている。", "target_word": "一見", "complexity_tier": "T3", "furigana": "この箱[はこ]は一見[いっけん]空[から]に見[み]えるが、底[そこ]に小[ちい]さな鍵[かぎ]が入[はい]っている。", "sentence_source": "generated"}, {"text": "一見冷たそうな先生だが、生徒の相談にはいつも親切に答える。", "target_word": "一見", "complexity_tier": "T3", "furigana": "一見[いっけん]冷[つめ]たそうな先生[せんせい]だが、生徒[せいと]の相談[そうだん]にはいつも親切[しんせつ]に答[こた]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一見", "label": "基本形(副詞)"}, {"form": "一見した", "label": "サ変過去形"}], "register": "neutral", "sense_fingerprint": "一見: 一度見ただけでは実際とは違って見える(あとに「だが・実は」が続く)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ca05e1-aa05-4ad7-add9-a71a38ebfa4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36590, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一見", "is_correct": true, "explanation": "正解。見ただけでは本当のことはわからず、「だが」で実際を続ける文に合う。"}, {"text": "必ず", "is_correct": false, "explanation": "確実であることを表す副詞。「必ずやさしそうな人だが」は見かけの話として成り立たない。"}, {"text": "一斉に", "is_correct": false, "explanation": "同時に行われることを表す。人の見かけを述べる文には入らない。"}, {"text": "瞬時に", "is_correct": false, "explanation": "一瞬でを表す。見かけの印象と実際の対比を示す文には合わない。"}], "explanations": {"一見": "正解。見ただけでは本当のことはわからず、「だが」で実際を続ける文に合う。", "必ず": "確実であることを表す副詞。「必ずやさしそうな人だが」は見かけの話として成り立たない。", "一斉に": "同時に行われることを表す。人の見かけを述べる文には入らない。", "瞬時に": "一瞬でを表す。見かけの印象と実際の対比を示す文には合わない。"}, "sentence_index": 0, "correct_answer": "一見"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は一見さんお断りだ。", "explanation": "ここは〈初めての客〉の意味（一見さん）。「一見」は見かけの印象を表す副詞で、客の種類は表せない。"}, {"text": "彼は一見の価値がある作品を見逃した。", "explanation": "ここは〈見る価値〉の意味（一見の価値）。「一見」は見かけの印象を表す副詞で、この意味では使わない。"}, {"text": "この曲は一見で弾くのが難しい。", "explanation": "ここは「初見」の場面にあたる。「一見」は「見ただけでは」の副詞で、楽譜を初めて弾く場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36590, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一見", "is_correct": true, "explanation": "正解。安く見えても送料で高くなる、という見かけと実際の違いを示す文に合う。"}, {"text": "急遽", "is_correct": false, "explanation": "予定を変えて急にという意味。安い商品の見かけを述べる文には入らない。"}, {"text": "猛然と", "is_correct": false, "explanation": "勢いが激しいさまを表す。商品の値段を述べる文の導入にはならない。"}, {"text": "厳密に", "is_correct": false, "explanation": "細かく正確にという意味。見かけと実際の対比を示す文には合わない。"}], "explanations": {"一見": "正解。安く見えても送料で高くなる、という見かけと実際の違いを示す文に合う。", "急遽": "予定を変えて急にという意味。安い商品の見かけを述べる文には入らない。", "猛然と": "勢いが激しいさまを表す。商品の値段を述べる文の導入にはならない。", "厳密に": "細かく正確にという意味。見かけと実際の対比を示す文には合わない。"}, "sentence_index": 6, "correct_answer": "一見"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は一見、その店に行ったことがある。", "explanation": "ここは〈一度〉の意味。「一見」は見かけの印象を表す副詞で、経験の回数は表せない。"}, {"text": "一見見ただけで、本物だとわかった。", "explanation": "ここは「一瞬」の意味。「一見」は副詞で「見る」と重ねられず、「見ただけで」の意味を単独で表せない。"}, {"text": "彼女は私に一見もくれず、通り過ぎた。", "explanation": "ここは「ちらっと見ること」の意味の「一瞥」。「一見」は「見ただけでは」の副詞で、「もくれず」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36590, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一見でおだやかそうな人だが、実は仕事にとても厳しい。", "corrected_sentence": "一見おだやかそうな人だが、実は仕事にとても厳しい。", "error_description": "「一見」は副詞なので、「で」を付けると不自然。「一見おだやかそうな」と続けるのが正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36590, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一見の平らな道だが、雨の日は滑りやすくて危ない。", "corrected_sentence": "一見平らな道だが、雨の日は滑りやすくて危ない。", "error_description": "「一見」の後に「の」を付けると、初めての客を表す名詞の用法になり、この文の意味に合わない。「の」は不要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a0dc298-6400-44f3-a314-0d2bcbaf39a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36592, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "複雑", "is_correct": true, "explanation": "「単純」の対義語で、ふくざつであること。「単純に考える」に対応する。"}, {"text": "簡単", "is_correct": false, "explanation": "「単純」に近い意味の語で、対義語ではない。"}, {"text": "明快", "is_correct": false, "explanation": "わかりやすいことを表す語で、対義語ではない。"}, {"text": "純粋", "is_correct": false, "explanation": "混じりけがないことを表す語で、対義語ではない。"}], "correct_answer": "複雑", "explanations": {"複雑": "「単純」の対義語で、ふくざつであること。「単純に考える」に対応する。", "簡単": "「単純」に近い意味の語で、対義語ではない。", "明快": "わかりやすいことを表す語で、対義語ではない。", "純粋": "混じりけがないことを表す語で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36592, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "複雑", "is_correct": true, "explanation": "「単純」の対義語で、ふくざつであること。「単純ではなく」に対応する。"}, {"text": "平易", "is_correct": false, "explanation": "やさしくわかりやすいことを表す語で、対義語ではない。"}, {"text": "明瞭", "is_correct": false, "explanation": "はっきりしていることを表す語で、対義語ではない。"}, {"text": "簡明", "is_correct": false, "explanation": "短くわかりやすいことを表す語で、対義語ではない。"}], "correct_answer": "複雑", "explanations": {"複雑": "「単純」の対義語で、ふくざつであること。「単純ではなく」に対応する。", "平易": "やさしくわかりやすいことを表す語で、対義語ではない。", "明瞭": "はっきりしていることを表す語で、対義語ではない。", "簡明": "短くわかりやすいことを表す語で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36592, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "かんたんなこと。ふくざつじゃないこと。", "primary_collocate": null, "pronunciation": "たんじゅん", "ipa": "taɲd͡ʑɯɴ", "syllable_count": 4, "sentences": [{"text": "この問題の答えは、思ったより単純だった。", "target_word": "単純", "complexity_tier": "T3", "furigana": "この問題[もんだい]の答[こた]えは、思[おも]ったより単純[たんじゅん]だった。", "sentence_source": "generated"}, {"text": "単純な作りの機械は、こわれにくい。", "target_word": "単純", "complexity_tier": "T3", "furigana": "単純[たんじゅん]な作[つく]りの機械[きかい]は、こわれにくい。", "sentence_source": "generated"}, {"text": "話が単純で、子どもにもわかりやすい。", "target_word": "単純", "complexity_tier": "T3", "furigana": "話[はなし]が単純[たんじゅん]で、子[こ]どもにもわかりやすい。", "sentence_source": "generated"}, {"text": "単純に考えれば、答えは二つだけだ。", "target_word": "単純", "complexity_tier": "T3", "furigana": "単純[たんじゅん]に考[かんが]えれば、答[こた]えは二[ふた]つだけだ。", "sentence_source": "generated"}, {"text": "このゲームのルールは単純だ。", "target_word": "単純", "complexity_tier": "T3", "furigana": "このゲームのルールは単純[たんじゅん]だ。", "sentence_source": "generated"}, {"text": "複雑な計算を、単純な形に直した。", "target_word": "単純", "complexity_tier": "T3", "furigana": "複雑[ふくざつ]な計算[けいさん]を、単純[たんじゅん]な形[かたち]に直[なお]した。", "sentence_source": "generated"}, {"text": "部屋のデザインは単純だが、落ち着く。", "target_word": "単純", "complexity_tier": "T3", "furigana": "部屋[へや]のデザインは単純[たんじゅん]だが、落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "仕事を単純にして、時間を短くした。", "target_word": "単純", "complexity_tier": "T3", "furigana": "仕事[しごと]を単純[たんじゅん]にして、時間[じかん]を短[みじか]くした。", "sentence_source": "generated"}, {"text": "単純な方法ほど、長く続けやすい。", "target_word": "単純", "complexity_tier": "T3", "furigana": "単純[たんじゅん]な方法[ほうほう]ほど、長[なが]く続[つづ]けやすい。", "sentence_source": "generated"}, {"text": "この話は単純ではなく、いろいろな事情があった。", "target_word": "単純", "complexity_tier": "T3", "furigana": "この話[はなし]は単純[たんじゅん]ではなく、いろいろな事情[じじょう]があった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "単純だ", "label": "終止形"}, {"form": "単純な", "label": "連体形"}, {"form": "単純に", "label": "連用形"}, {"form": "単純で", "label": "て形"}], "register": "普通体", "sense_fingerprint": "しくみや内容が簡単で複雑でないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df666cf-660e-4a65-8685-1c7e60c94a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36592, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "単純", "is_correct": true, "explanation": "答えの性質を表す形状詞で、「思ったより単純だった」と続けて文が成り立つ。"}, {"text": "大切", "is_correct": false, "explanation": "重要さを表す語で、答えの簡単さを言う文脈には合わない。"}, {"text": "派手", "is_correct": false, "explanation": "目立つ様子を表す語で、答えの性質の説明には使えない。"}, {"text": "不器用", "is_correct": false, "explanation": "手先などの器用さを表す語で、答えには使えない。"}], "explanations": {"単純": "答えの性質を表す形状詞で、「思ったより単純だった」と続けて文が成り立つ。", "大切": "重要さを表す語で、答えの簡単さを言う文脈には合わない。", "派手": "目立つ様子を表す語で、答えの性質の説明には使えない。", "不器用": "手先などの器用さを表す語で、答えには使えない。"}, "sentence_index": 0, "correct_answer": "単純"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の肌は単純で、とてもきれいだ。", "explanation": "ここは〈滑らか〉（表面がなめらかで、ひっかからない）の意味。〈単純〉は仕組みや考えが簡単でふくざつでないことを表すので、肌の状態には使わない。"}, {"text": "この地域は単純で、冬は雪が多い。", "explanation": "ここは〈寒冷〉（気温が低い）の意味。〈単純〉は仕組みや考えが簡単という意味なので、気温の状態は表せない。"}, {"text": "夏の海は単純で、人がとても多い。", "explanation": "ここは〈にぎやか〉（人が多く活気がある）の意味。〈単純〉は仕組みや考えが簡単という意味なので、人の多さや活気は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36592, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "単純", "is_correct": true, "explanation": "「デザインは単純だが、落ち着く」と続く。デザインの性質を表して文が成り立つ。"}, {"text": "元気", "is_correct": false, "explanation": "人や動物の状態を表す語で、デザインの性質には使えない。"}, {"text": "豪快", "is_correct": false, "explanation": "勢いの強さを表す語で、デザインの説明には合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "人の明るい性格を表す語で、デザインには使えない。"}], "explanations": {"単純": "「デザインは単純だが、落ち着く」と続く。デザインの性質を表して文が成り立つ。", "元気": "人や動物の状態を表す語で、デザインの性質には使えない。", "豪快": "勢いの強さを表す語で、デザインの説明には合わない。", "陽気": "人の明るい性格を表す語で、デザインには使えない。"}, "sentence_index": 6, "correct_answer": "単純"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海は単純で、波が静かだ。", "explanation": "ここは〈穏やか〉（波が静かで落ち着いている）の意味。〈単純〉はふくざつでないという意味で、海の様子を表す語ではない。"}, {"text": "この山の水は単純で、とてもおいしい。", "explanation": "ここは〈純粋〉（混じりけがない）の意味。〈単純〉はふくざつでないという意味で、水の純度は表せない。"}, {"text": "この通りは毎晩単純だ。", "explanation": "ここは〈にぎやか〉（人が多く活気がある）の意味。〈単純〉は仕組みや考えが簡単という意味で、人の多さや活気は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36592, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この道具は単純を作りだから、使いやすい。", "corrected_sentence": "この道具は単純な作りだから、使いやすい。", "error_description": "形状詞の「単純」は名詞を修飾するとき「な」を付ける。「を」は誤りで、正しくは「単純な作り」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "単純な", "is_correct": true, "explanation": "連体形。後ろの名詞「作り」を修飾しているので正しい。"}, {"text": "単純だ", "is_correct": false, "explanation": "終止形。名詞を直接修飾できないので、「作り」の前には置けない。"}, {"text": "単純で", "is_correct": false, "explanation": "て形。文を続ける形で、名詞を修飾することはできない。"}, {"text": "単純に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、名詞を修飾できないので合わない。"}], "correct_form": "単純な", "base_form": "単純", "form_label": "連体形", "sentence_index": 1, "explanations": {"単純な": "連体形。後ろの名詞「作り」を修飾しているので正しい。", "単純だ": "終止形。名詞を直接修飾できないので、「作り」の前には置けない。", "単純で": "て形。文を続ける形で、名詞を修飾することはできない。", "単純に": "連用形。動詞や形容詞を修飾する形で、名詞を修飾できないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36592, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この計画は単純の内容で、わかりやすい。", "corrected_sentence": "この計画は単純な内容で、わかりやすい。", "error_description": "形状詞の「単純」は名詞を修飾するとき「な」を付ける。「の」は誤りで、正しくは「単純な内容」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "単純に", "is_correct": true, "explanation": "連用形。「単純にして」と動詞に続いて、やり方を示している。"}, {"text": "単純な", "is_correct": false, "explanation": "連体形。名詞を修飾する形なので、「にして」の前には置けない。"}, {"text": "単純ではない", "is_correct": false, "explanation": "否定の形。「仕事を〜にして」の流れに入らず、文が成り立たない。"}, {"text": "単純だった", "is_correct": false, "explanation": "過去の終止形。「にして」の前には置けず、文が成り立たない。"}], "correct_form": "単純に", "base_form": "単純", "form_label": "連用形", "sentence_index": 7, "explanations": {"単純に": "連用形。「単純にして」と動詞に続いて、やり方を示している。", "単純な": "連体形。名詞を修飾する形なので、「にして」の前には置けない。", "単純ではない": "否定の形。「仕事を〜にして」の流れに入らず、文が成り立たない。", "単純だった": "過去の終止形。「にして」の前には置けず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36594, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主格を表す。「動作が速い」の「が」で、後ろの形容詞の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表すが、「動作を速い選手」は形容詞の前に置けない。"}, {"text": "に", "is_correct": false, "explanation": "場所や対象を表すが、「動作に速い選手」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、ここでは名詞の様子を述べる文にならない。"}], "correct_answer": "が", "explanations": {"が": "主格を表す。「動作が速い」の「が」で、後ろの形容詞の主語になる。", "を": "目的語を表すが、「動作を速い選手」は形容詞の前に置けない。", "に": "場所や対象を表すが、「動作に速い選手」は成り立たない。", "へ": "方向を表すが、ここでは名詞の様子を述べる文にならない。"}, "error_tags": {"を": "目的語", "に": "位置・対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36594, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36594, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が何かをするときの、体のうごきのことです。", "primary_collocate": null, "pronunciation": "どうさ", "ipa": "doːsa", "syllable_count": 3, "sentences": [{"text": "彼は動作がゆっくりで、いつも最後に教室を出る。", "target_word": "動作", "complexity_tier": "T3", "furigana": "彼[かれ]は動作[どうさ]がゆっくりで、いつも最後[さいご]に教室[きょうしつ]を出[で]る。", "sentence_source": "generated"}, {"text": "動作が速い選手は、試合でも有利だ。", "target_word": "動作", "complexity_tier": "T3", "furigana": "動作[どうさ]が速[はや]い選手[せんしゅ]は、試合[しあい]でも有利[ゆうり]だ。", "sentence_source": "generated"}, {"text": "体操の先生が、基本の動作を見せてくれた。", "target_word": "動作", "complexity_tier": "T3", "furigana": "体操[たいそう]の先生[せんせい]が、基本[きほん]の動作[どうさ]を見[み]せてくれた。", "sentence_source": "generated"}, {"text": "おじいさんは、動作は遅いが、いつも丁寧だ。", "target_word": "動作", "complexity_tier": "T3", "furigana": "おじいさんは、動作[どうさ]は遅[おそ]いが、いつも丁寧[ていねい]だ。", "sentence_source": "generated"}, {"text": "荷物が重くて、歩く動作さえ大変だった。", "target_word": "動作", "complexity_tier": "T3", "furigana": "荷物[にもつ]が重[おも]くて、歩[ある]く動作[どうさ]さえ大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "犬は主人の動作をじっと見て、次の命令を待っている。", "target_word": "動作", "complexity_tier": "T3", "furigana": "犬[いぬ]は主人[しゅじん]の動作[どうさ]をじっと見[み]て、次[つぎ]の命令[めいれい]を待[ま]っている。", "sentence_source": "generated"}, {"text": "朝のラジオ体操では、大きな動作で体を伸ばす。", "target_word": "動作", "complexity_tier": "T3", "furigana": "朝[あさ]のラジオ体操[たいそう]では、大[おお]きな動作[どうさ]で体[からだ]を伸[の]ばす。", "sentence_source": "generated"}, {"text": "映画の俳優は、細かい動作で気持ちを表した。", "target_word": "動作", "complexity_tier": "T3", "furigana": "映画[えいが]の俳優[はいゆう]は、細[こま]かい動作[どうさ]で気持[きも]ちを表[あらわ]した。", "sentence_source": "generated"}, {"text": "けがをした足では、座る動作もうまくできない。", "target_word": "動作", "complexity_tier": "T3", "furigana": "けがをした足[あし]では、座[すわ]る動作[どうさ]もうまくできない。", "sentence_source": "generated"}, {"text": "動作を間違えないよう、ゆっくり練習しましょう。", "target_word": "動作", "complexity_tier": "T3", "furigana": "動作[どうさ]を間違[まちが]えないよう、ゆっくり練習[れんしゅう]しましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動作", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人が何かをするときの体の動き(名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36594, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動作", "is_correct": true, "explanation": "名詞。「彼は動作がゆっくりで」と主語になり、文が自然に続く。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、「彼は天気がゆっくりで」は意味が通らない。"}, {"text": "教室", "is_correct": false, "explanation": "場所を表す語で、「彼は教室がゆっくりで」は人の様子として成り立たない。"}, {"text": "窓ガラス", "is_correct": false, "explanation": "物の名前で、人の動きの遅さを表す主語にはならない。"}], "explanations": {"動作": "名詞。「彼は動作がゆっくりで」と主語になり、文が自然に続く。", "天気": "空模様を表す語で、「彼は天気がゆっくりで」は意味が通らない。", "教室": "場所を表す語で、「彼は教室がゆっくりで」は人の様子として成り立たない。", "窓ガラス": "物の名前で、人の動きの遅さを表す主語にはならない。"}, "sentence_index": 0, "correct_answer": "動作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町内会は、夏に大きな動作を催した。", "explanation": "ここは〈行事〉の意味。「行事を催す」の〈行事〉で、動作は催すものではないので合わない。"}, {"text": "運転手は、歩行者に動作を払った。", "explanation": "ここは〈注意〉の意味。「注意を払う」の〈注意〉で、動作は払うものではない。"}, {"text": "試写会の後、観客は舞台の動作を述べた。", "explanation": "ここは〈感想〉の意味。「感想を述べる」の〈感想〉で、動作は述べるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36594, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動作", "is_correct": true, "explanation": "名詞。「大きな動作で体を伸ばす」の手段として自然に入る。"}, {"text": "腕時計", "is_correct": false, "explanation": "身につける道具で、「大きな腕時計で体を伸ばす」は成り立たない。"}, {"text": "教科書", "is_correct": false, "explanation": "授業で使う本で、体を伸ばす手段にはならない。"}, {"text": "段ボール", "is_correct": false, "explanation": "箱などに使う材料で、体を伸ばす手段としては意味が通らない。"}], "explanations": {"動作": "名詞。「大きな動作で体を伸ばす」の手段として自然に入る。", "腕時計": "身につける道具で、「大きな腕時計で体を伸ばす」は成り立たない。", "教科書": "授業で使う本で、体を伸ばす手段にはならない。", "段ボール": "箱などに使う材料で、体を伸ばす手段としては意味が通らない。"}, "sentence_index": 6, "correct_answer": "動作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、生徒の動作を求めた。", "explanation": "ここは〈意見〉の意味。「意見を求める」の〈意見〉で、動作は人に求めるものではない。"}, {"text": "先生から大事な動作を受けた。", "explanation": "ここは〈報告〉の意味。「報告を受ける」の〈報告〉で、動作は受け取るものではない。"}, {"text": "先生は、廊下で生徒に動作をかけた。", "explanation": "ここは〈声〉の意味。「声をかける」の〈声〉で、動作は体の動きなので誰かにかけるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36594, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その犬は主人の動作に見て、ドアの前で待つ。", "corrected_sentence": "その犬は主人の動作を見て、ドアの前で待つ。", "error_description": "「見る」は目的語に「を」を取る。ここは「に」が使われているので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36594, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は大きな動作なボールを受け止めた。", "corrected_sentence": "彼は大きな動作でボールを受け止めた。", "error_description": "手段を表す「で」が必要。「な」は形容動詞の連体形で、名詞「動作」には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36595, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語を表す格助詞。「手の動作を使う」の「を」。"}, {"text": "が", "is_correct": false, "explanation": "主格を表すが、「動作が使って」では主語にならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「動作へ使って」は動詞の目的語として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表すが、「動作より使って」は文の骨組みに合わない。"}], "correct_answer": "を", "explanations": {"を": "目的語を表す格助詞。「手の動作を使う」の「を」。", "が": "主格を表すが、「動作が使って」では主語にならず文が成り立たない。", "へ": "方向を表すが、「動作へ使って」は動詞の目的語として成り立たない。", "より": "比較を表すが、「動作より使って」は文の骨組みに合わない。"}, "error_tags": {"が": "主格", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36595, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36595, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が何かをするときの、体や部分の動き。特に、目的や意味がある動きを指します。", "primary_collocate": null, "pronunciation": "どうさ", "ipa": "doːsa", "syllable_count": 3, "sentences": [{"text": "その一つひとつの動作が、彼女の認知能力と社会性を育む養分となる。", "target_word": "動作", "complexity_tier": "T4", "furigana": "その一[ひと]つひとつの動作[どうさ]が、彼女[かのじょ]の認知能力[にんちのうりょく]と社会性[しゃかいせい]を育[はぐく]む養分[ようぶん]となる。", "sentence_source": "mined"}, {"text": "先生は、手の動作を使って、ゆっくり説明してくれた。", "target_word": "動作", "complexity_tier": "T3", "furigana": "先生[せんせい]は、手[て]の動作[どうさ]を使[つか]って、ゆっくり説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "彼女のお茶をいれる動作は、無駄がなくて美しい。", "target_word": "動作", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のお茶[ちゃ]をいれる動作[どうさ]は、無駄[むだ]がなくて美[うつく]しい。", "sentence_source": "generated"}, {"text": "料理人は素早い動作で、野菜を細かく切っていった。", "target_word": "動作", "complexity_tier": "T3", "furigana": "料理人[りょうりにん]は素早[すばや]い動作[どうさ]で、野菜[やさい]を細[こま]かく切[き]っていった。", "sentence_source": "generated"}, {"text": "ダンスの動作を覚えるために、毎日鏡の前で練習している。", "target_word": "動作", "complexity_tier": "T3", "furigana": "ダンスの動作[どうさ]を覚[おぼ]えるために、毎日[まいにち]鏡[かがみ]の前[まえ]で練習[れんしゅう]している。", "sentence_source": "generated"}, {"text": "病気のあとは、立ち上がる動作もつらかった。", "target_word": "動作", "complexity_tier": "T3", "furigana": "病気[びょうき]のあとは、立[た]ち上[あ]がる動作[どうさ]もつらかった。", "sentence_source": "generated"}, {"text": "手話では、顔の表情と手の動作で意味を伝える。", "target_word": "動作", "complexity_tier": "T3", "furigana": "手話[しゅわ]では、顔[かお]の表情[ひょうじょう]と手[て]の動作[どうさ]で意味[いみ]を伝[つた]える。", "sentence_source": "generated"}, {"text": "彼は慌てていたので、動作が雑になって、皿を落としてしまった。", "target_word": "動作", "complexity_tier": "T3", "furigana": "彼[かれ]は慌[あわ]てていたので、動作[どうさ]が雑[ざつ]になって、皿[さら]を落[お]としてしまった。", "sentence_source": "generated"}, {"text": "動作の一つ一つに意味があるので、茶道は奥が深い。", "target_word": "動作", "complexity_tier": "T3", "furigana": "動作[どうさ]の一[ひと]つ一[ひと]つに意味[いみ]があるので、茶道[さどう]は奥[おく]が深[ふか]い。", "sentence_source": "generated"}, {"text": "赤ちゃんがおもちゃをつかむ動作は、とても真剣だ。", "target_word": "動作", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんがおもちゃをつかむ動作[どうさ]は、とても真剣[しんけん]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動作", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "目的や意味をもった、体や手足などの動き(名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99762afa-59c1-4c2e-a5e4-2262b3d2a431') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36595, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動作", "is_correct": true, "explanation": "名詞。「一つひとつの動作が」という主語になり、「養分となる」に続く。"}, {"text": "腕時計", "is_correct": false, "explanation": "身につける道具で、「彼女の認知能力を育む養分」の主語としては意味が通らない。"}, {"text": "海岸", "is_correct": false, "explanation": "場所を表す語で、「一つひとつの海岸が養分となる」は意味が通らない。"}, {"text": "ホッチキス", "is_correct": false, "explanation": "文房具で、認知能力を育む養分とは言えない。"}], "explanations": {"動作": "名詞。「一つひとつの動作が」という主語になり、「養分となる」に続く。", "腕時計": "身につける道具で、「彼女の認知能力を育む養分」の主語としては意味が通らない。", "海岸": "場所を表す語で、「一つひとつの海岸が養分となる」は意味が通らない。", "ホッチキス": "文房具で、認知能力を育む養分とは言えない。"}, "sentence_index": 0, "correct_answer": "動作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は来年の動作を決めた。", "explanation": "ここは〈方針〉の意味。「方針を決める」の〈方針〉で、動作（体の動き）は決めるものではないので合わない。"}, {"text": "彼女は、きれいな動作を書いた。", "explanation": "ここは〈文章〉の意味。「文章を書く」の〈文章〉で、動作は書くものではないので合わない。"}, {"text": "来場者は、舞台の動作を述べた。", "explanation": "ここは〈感想〉の意味。感想は述べるものだが、動作は述べるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36595, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動作", "is_correct": true, "explanation": "名詞。「手の動作で意味を伝える」の手段として自然に入る。"}, {"text": "文房具", "is_correct": false, "explanation": "物の名前で、「手の文房具で意味を伝える」は成り立たない。"}, {"text": "段ボール", "is_correct": false, "explanation": "箱などに使う材料で、手話の手段としては意味が通らない。"}, {"text": "調味料", "is_correct": false, "explanation": "料理に使う物で、顔の表情と並べて意味を伝える手段にはならない。"}], "explanations": {"動作": "名詞。「手の動作で意味を伝える」の手段として自然に入る。", "文房具": "物の名前で、「手の文房具で意味を伝える」は成り立たない。", "段ボール": "箱などに使う材料で、手話の手段としては意味が通らない。", "調味料": "料理に使う物で、顔の表情と並べて意味を伝える手段にはならない。"}, "sentence_index": 6, "correct_answer": "動作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、生徒に動作を出した。", "explanation": "ここは〈指示〉の意味。「指示を出す」の〈指示〉で、動作は体の動きなので人に出すものではない。"}, {"text": "彼は周囲に動作を払って歩いた。", "explanation": "ここは〈注意〉の意味。「注意を払う」の〈注意〉で、動作は払うものではない。"}, {"text": "先生から動作を受けた。", "explanation": "ここは〈報告〉の意味。「報告を受ける」の〈報告〉で、動作は受け取るものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36595, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもは、大人の動作にまねして覚える。", "corrected_sentence": "子どもは、大人の動作をまねして覚える。", "error_description": "「まねする」は目的語に「を」を取る。ここは「に」が使われているので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36595, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店員は、手の動作だ客を呼んだ。", "corrected_sentence": "店員は、手の動作で客を呼んだ。", "error_description": "手段を表す「で」が必要。「だ」は文を言い切る形で、後の「客を呼んだ」とつながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74db7eed-5d9a-45a8-a0e9-e766affdf1f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36596, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「体を動かす」の「を」で、動かす対象を示すので文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「体が動かす」では意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点を示すので、「体に動かす」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手を示すので、「体と動かす」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「体を動かす」の「を」で、動かす対象を示すので文に合う。", "が": "「が」は主語を示すので、「体が動かす」では意味が通らない。", "に": "「に」は到達点を示すので、「体に動かす」は成り立たない。", "と": "「と」は相手を示すので、「体と動かす」は意味が通らない。"}, "error_tags": {"が": "主語", "に": "方向", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36596, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「体を冷やさない」の「を」で、冷やす対象を示すので文に合う。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐもので、動詞の目的語には置けない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「体より冷やさない」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すので、「体で冷やさない」は目的語にならず不自然。"}], "correct_answer": "を", "explanations": {"を": "「体を冷やさない」の「を」で、冷やす対象を示すので文に合う。", "の": "「の」は名詞どうしをつなぐもので、動詞の目的語には置けない。", "より": "「より」は比較を示すので、「体より冷やさない」は成り立たない。", "で": "「で」は手段を示すので、「体で冷やさない」は目的語にならず不自然。"}, "error_tags": {"の": "連体修飾", "より": "比較", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36596, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "生き物のからだのことです。", "primary_collocate": null, "pronunciation": "からだ", "ipa": "kaɾada", "syllable_count": 3, "sentences": [{"text": "風邪をひいて、体が重い。", "target_word": "体", "complexity_tier": "T3", "furigana": "風邪(かぜ)をひいて、体(からだ)が重(おも)い。", "sentence_source": "generated"}, {"text": "毎朝、体を動かすようにしています。", "target_word": "体", "complexity_tier": "T3", "furigana": "毎朝(まいあさ)、体(からだ)を動(うご)かすようにしています。", "sentence_source": "generated"}, {"text": "犬は体をふるわせて、水を飛ばした。", "target_word": "体", "complexity_tier": "T3", "furigana": "犬(いぬ)は体(からだ)をふるわせて、水(みず)を飛(と)ばした。", "sentence_source": "generated"}, {"text": "体が大きいので、この服は着られない。", "target_word": "体", "complexity_tier": "T3", "furigana": "体(からだ)が大(おお)きいので、この服(ふく)は着(き)られない。", "sentence_source": "generated"}, {"text": "温かいお風呂に入ると、体がほぐれる。", "target_word": "体", "complexity_tier": "T3", "furigana": "温(あたた)かいお風呂(ふろ)に入(はい)ると、体(からだ)がほぐれる。", "sentence_source": "generated"}, {"text": "夜ふかしをすると、次の日は体がだるい。", "target_word": "体", "complexity_tier": "T3", "furigana": "夜(よる)ふかしをすると、次(つぎ)の日(ひ)は体(からだ)がだるい。", "sentence_source": "generated"}, {"text": "魚の体はうろこでおおわれている。", "target_word": "体", "complexity_tier": "T3", "furigana": "魚(さかな)の体(からだ)はうろこでおおわれている。", "sentence_source": "generated"}, {"text": "寒い日は、体を冷やさないように気をつけてください。", "target_word": "体", "complexity_tier": "T3", "furigana": "寒(さむ)い日(ひ)は、体(からだ)を冷(ひ)やさないように気(き)をつけてください。", "sentence_source": "generated"}, {"text": "祖父は年をとっても、体が丈夫だ。", "target_word": "体", "complexity_tier": "T3", "furigana": "祖父(そふ)は年(とし)をとっても、体(からだ)が丈夫(じょうぶ)だ。", "sentence_source": "generated"}, {"text": "赤ちゃんの小さな体を、そっとだきあげた。", "target_word": "体", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんの小(ちい)さな体(からだ)を、そっとだきあげた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "体", "label": "基本形"}], "register": "日常語", "sense_fingerprint": "人や動物の身体全体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: ふるわせ (Zipf 2.35)','sentence 4 above tier T1: contains vocabulary far above tier T1: ほぐれる (Zipf 2.01)']::text[], 'c0767258-83b5-4171-bcae-53bbc15f4a23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36596, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体", "is_correct": true, "explanation": "身体全体が重く感じられる状態を表し、風邪の文脈に合う。"}, {"text": "歌", "is_correct": false, "explanation": "歌は風邪で重くなるものではなく、「歌が重い」は文脈に合わない。"}, {"text": "午後", "is_correct": false, "explanation": "時間は重くならないので、体調を表す文として成り立たない。"}, {"text": "夏", "is_correct": false, "explanation": "季節は重くならないので、「夏が重い」は文が成り立たない。"}], "explanations": {"体": "身体全体が重く感じられる状態を表し、風邪の文脈に合う。", "歌": "歌は風邪で重くなるものではなく、「歌が重い」は文脈に合わない。", "午後": "時間は重くならないので、体調を表す文として成り立たない。", "夏": "季節は重くならないので、「夏が重い」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この文章は体が長く、読み終わるまで時間がかかる。", "explanation": "ここは〈分量〉の意味。体は生き物の身体を指すので、文章の分量には使わない。"}, {"text": "この服は体が大きく、着ると窮屈だ。", "explanation": "ここは〈寸法・サイズ〉の意味。体は身体を指すので、服の寸法には使わない。"}, {"text": "彼は体が広い。", "explanation": "「心が広い」と混同した誤用。「体」は身体の大きさを表し、性格を表す用法はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36596, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体", "is_correct": true, "explanation": "魚の身体を指し、うろこで覆われる部分として自然に文に合う。"}, {"text": "空", "is_correct": false, "explanation": "空は魚の身体ではないので、うろこで覆われる対象にならない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は魚の身体ではないので、文が成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は魚のものではなく、うろこで覆われる対象にならない。"}], "explanations": {"体": "魚の身体を指し、うろこで覆われる部分として自然に文に合う。", "空": "空は魚の身体ではないので、うろこで覆われる対象にならない。", "窓": "窓は魚の身体ではないので、文が成り立たない。", "雨": "雨は魚のものではなく、うろこで覆われる対象にならない。"}, "sentence_index": 6, "correct_answer": "体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地域の体を代表して、委員が発言した。", "explanation": "「体」は単独で団体の意味では使わず、「団体」を使う。"}, {"text": "この箱は体が小さいので、重ねて収納できる。", "explanation": "箱の大きさは「大きさ」などで表し、「体」は生き物の身体を指すので箱には使わない。"}, {"text": "この店は体が広くて、客が入りやすい。", "explanation": "ここは〈面積〉の意味。体は身体を指すので、店の面積には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36596, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は体がほぐして、ストレッチを始めた。", "corrected_sentence": "兄は体をほぐして、ストレッチを始めた。", "error_description": "「ほぐす」は他動詞なので、目的語を「を」で示す。「体が」は誤り。正しくは「体を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36596, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子犬は体がふるわせて、寒さをこらえていた。", "corrected_sentence": "子犬は体をふるわせて、寒さをこらえていた。", "error_description": "「ふるわせる」は他動詞なので、体に続く助詞は「を」で示す。「体が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61c717cd-5f43-408e-bc1d-bd831fa0a53c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36602, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「教える」の内容（メカニズム）を示す目的語として正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は教える相手を示すので、内容を表す「メカニズム」には使えない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すので、「メカニズムと教えてくれた」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「メカニズムへやさしく教えた」は不自然で、内容を表せない。"}], "correct_answer": "を", "explanations": {"を": "「教える」の内容（メカニズム）を示す目的語として正しい。", "に": "「に」は教える相手を示すので、内容を表す「メカニズム」には使えない。", "と": "「と」は並列や共同を示すので、「メカニズムと教えてくれた」は意味が通らない。", "へ": "「へ」は方向を示すが、「メカニズムへやさしく教えた」は不自然で、内容を表せない。"}, "error_tags": {"に": "dative", "と": "comitative", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
