INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36602, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が動く仕組みのこと。", "primary_collocate": null, "pronunciation": "めかにずむ", "ipa": "mekanizɯmɯ", "syllable_count": 5, "sentences": [{"text": "時計が動くメカニズムを、図で説明します。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "時計[とけい]が動[うご]くメカニズムを、図[ず]で説明[せつめい]します。", "sentence_source": "generated"}, {"text": "先生は、雨が降るメカニズムをやさしく教えてくれました。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "先生[せんせい]は、雨[あめ]が降[ふ]るメカニズムをやさしく教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "このおもちゃのメカニズムは、中のばねを使っています。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "このおもちゃのメカニズムは、中[なか]のばねを使[つか]っています。", "sentence_source": "generated"}, {"text": "体が熱を下げるメカニズムは、とてもよくできています。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "体[からだ]が熱[ねつ]を下[さ]げるメカニズムは、とてもよくできています。", "sentence_source": "generated"}, {"text": "地震が起きるメカニズムを、研究している人がいます。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "地震[じしん]が起[お]きるメカニズムを、研究[けんきゅう]している人[ひと]がいます。", "sentence_source": "generated"}, {"text": "機械のメカニズムがわかると、故障も直しやすくなります。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "機械[きかい]のメカニズムがわかると、故障[こしょう]も直[なお]しやすくなります。", "sentence_source": "generated"}, {"text": "兄はドアのカギのメカニズムに興味を持って、中を分解しました。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "兄[あに]はドアのカギのメカニズムに興味[きょうみ]を持[も]って、中[なか]を分解[ぶんかい]しました。", "sentence_source": "generated"}, {"text": "病気が広がるメカニズムがわかれば、防ぎやすくなります。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "病気[びょうき]が広[ひろ]がるメカニズムがわかれば、防[ふせ]ぎやすくなります。", "sentence_source": "generated"}, {"text": "花がさくメカニズムを、ノートにまとめました。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "花[はな]がさくメカニズムを、ノートにまとめました。", "sentence_source": "generated"}, {"text": "自動ドアのメカニズムは、センサーが人を見つけることから始まります。", "target_word": "メカニズム", "complexity_tier": "T3", "furigana": "自動[じどう]ドアのメカニズムは、センサーが人[ひと]を見[み]つけることから始[はじ]まります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "メカニズム", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "機械や自然現象などが、どのように動いて成り立つかという仕組み", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b00aee-abfc-4ceb-97c6-d90782564abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36602, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "メカニズム", "is_correct": true, "explanation": "「時計が動くメカニズム」は、動く仕組みを表し、文の空欄に合う。"}, {"text": "ヨーグルト", "is_correct": false, "explanation": "「時計が動くヨーグルト」は意味をなさない。ヨーグルトは食品で、動く仕組みではない。"}, {"text": "カーテン", "is_correct": false, "explanation": "「時計が動くカーテン」は文として成り立たない。カーテンは動く仕組みの説明対象にならない。"}, {"text": "まくら", "is_correct": false, "explanation": "まくらは寝具で、「時計が動くまくらを図で説明する」は不自然で、仕組みを表さない。"}], "explanations": {"メカニズム": "「時計が動くメカニズム」は、動く仕組みを表し、文の空欄に合う。", "ヨーグルト": "「時計が動くヨーグルト」は意味をなさない。ヨーグルトは食品で、動く仕組みではない。", "カーテン": "「時計が動くカーテン」は文として成り立たない。カーテンは動く仕組みの説明対象にならない。", "まくら": "まくらは寝具で、「時計が動くまくらを図で説明する」は不自然で、仕組みを表さない。"}, "sentence_index": 0, "correct_answer": "メカニズム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このケーキはメカニズムが新鮮で、とても香りがよい。", "explanation": "ここは〈材料〉の意味。メカニズムは仕組みを指し、食べ物の原料の新しさは表せない。"}, {"text": "彼はメカニズムが穏やかで、みんなに好かれる。", "explanation": "ここは〈性格〉の意味。メカニズムは仕組みや働き方を指し、人の気質は表さない。"}, {"text": "今年のメカニズムは、毎日本を一冊読むことだ。", "explanation": "ここは〈目標〉の意味。メカニズムは仕組みを指し、目指す到達点は表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36602, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メカニズム", "is_correct": true, "explanation": "「ドアのカギのメカニズムに興味を持つ」は、仕組みを表し、分解するという文脈に合う。"}, {"text": "カレンダー", "is_correct": false, "explanation": "「ドアのカギのカレンダー」は意味をなさない。カレンダーは日付を示す道具で、カギの仕組みではない。"}, {"text": "ジュース", "is_correct": false, "explanation": "「ドアのカギのジュース」は文として成り立たない。飲み物はカギの仕組みを表さない。"}, {"text": "マフラー", "is_correct": false, "explanation": "マフラーは防寒具で、「ドアのカギのマフラーに興味を持つ」は不自然。"}], "explanations": {"メカニズム": "「ドアのカギのメカニズムに興味を持つ」は、仕組みを表し、分解するという文脈に合う。", "カレンダー": "「ドアのカギのカレンダー」は意味をなさない。カレンダーは日付を示す道具で、カギの仕組みではない。", "ジュース": "「ドアのカギのジュース」は文として成り立たない。飲み物はカギの仕組みを表さない。", "マフラー": "マフラーは防寒具で、「ドアのカギのマフラーに興味を持つ」は不自然。"}, "sentence_index": 6, "correct_answer": "メカニズム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このスープはメカニズムが濃くて、とてもおいしい。", "explanation": "ここは〈味〉の意味。メカニズムは仕組みを指し、料理の味の濃さは表せない。"}, {"text": "山の上からのメカニズムがとてもきれいだ。", "explanation": "ここは〈景色〉の意味。メカニズムは仕組みなので、見渡せる眺めは表さない。"}, {"text": "メカニズムを超えないように、買い物を控えた。", "explanation": "ここは〈予算〉の意味。メカニズムは仕組みを指し、使えるお金の上限は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36602, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は、雨が降るメカニズムに図で説明した。", "corrected_sentence": "先生は、雨が降るメカニズムを図で説明した。", "error_description": "「説明する」の対象は「を」で示す。「に」を付けたのは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36602, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、病気が広がるメカニズムが調べている。", "corrected_sentence": "研究者は、病気が広がるメカニズムを調べている。", "error_description": "「調べる」の対象は「を」で示す。「が」を付けたのは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36604, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「暗闇に潜む」の場所を示す助詞。隠れている場所を指定する。"}, {"text": "を", "is_correct": false, "explanation": "「暗闇を潜む」は目的語として成り立たず、隠れる場所の表現にならない。"}, {"text": "が", "is_correct": false, "explanation": "「暗闇が潜む」は主語にするには不自然で、敵が隠れる文の意味と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「暗闇へ」は方向を示すが、潜む場所を表す文にならない。"}], "correct_answer": "に", "explanations": {"に": "「暗闇に潜む」の場所を示す助詞。隠れている場所を指定する。", "を": "「暗闇を潜む」は目的語として成り立たず、隠れる場所の表現にならない。", "が": "「暗闇が潜む」は主語にするには不自然で、敵が隠れる文の意味と合わない。", "へ": "「暗闇へ」は方向を示すが、潜む場所を表す文にならない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36604, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「自分でも知らない力が潜んでいる」の主語を示す助詞。力が隠れている主体になる。"}, {"text": "を", "is_correct": false, "explanation": "「力を潜んでいる」は目的語として成り立たず、隠れている主体を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「力と潜んでいる」は並列の相手を示すだけで、隠れている主体を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「力へ潜んでいる」は方向を示すが、力が隠れている文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「自分でも知らない力が潜んでいる」の主語を示す助詞。力が隠れている主体になる。", "を": "「力を潜んでいる」は目的語として成り立たず、隠れている主体を示せない。", "と": "「力と潜んでいる」は並列の相手を示すだけで、隠れている主体を表せない。", "へ": "「力へ潜んでいる」は方向を示すが、力が隠れている文として成り立たない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36604, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "かくれて見えないところにある。", "primary_collocate": null, "pronunciation": "ひそむ", "ipa": "çisomɯ", "syllable_count": 3, "sentences": [{"text": "池の底の石の陰に、小さなカニが潜んでいる。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "池[いけ]の底[そこ]の石[いし]の陰[かげ]に、小[ちい]さなカニが潜[ひそ]んでいる。", "sentence_source": "generated"}, {"text": "暗闇に潜む敵に気をつけてください。", "target_word": "潜む", "complexity_tier": "T3", "furigana": "暗闇[くらやみ]に潜[ひそ]む敵[てき]に気[き]をつけてください。", "sentence_source": "generated"}, {"text": "草の中に蛇が潜んでいるから、足元に注意しましょう。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "草[くさ]の中[なか]に蛇[へび]が潜[ひそ]んでいるから、足元[あしもと]に注意[ちゅうい]しましょう。", "sentence_source": "generated"}, {"text": "彼は物陰に潜んで、友達を驚かせようとした。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "彼[かれ]は物陰[ものかげ]に潜[ひそ]んで、友達[ともだち]を驚[おどろ]かせようとした。", "sentence_source": "generated"}, {"text": "このゲームには、まだ見つかっていない特別な機能が潜んでいる。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "このゲームには、まだ見[み]つかっていない特別[とくべつ]な機能[きのう]が潜[ひそ]んでいる。", "sentence_source": "generated"}, {"text": "病気は気づかないうちに、体の中に潜んでいることがある。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "病気[びょうき]は気[き]づかないうちに、体[からだ]の中[なか]に潜[ひそ]んでいることがある。", "sentence_source": "generated"}, {"text": "夜、泥棒は庭の木の陰に潜んでいた。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "夜[よる]、泥棒[どろぼう]は庭[にわ]の木[き]の陰[かげ]に潜[ひそ]んでいた。", "sentence_source": "generated"}, {"text": "人の心には、自分でも知らない力が潜んでいる。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "人[ひと]の心[こころ]には、自分[じぶん]でも知[し]らない力[ちから]が潜[ひそ]んでいる。", "sentence_source": "generated"}, {"text": "山奥の洞窟にクマが潜んでいたという話を聞いた。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "山奥[やまおく]の洞窟[どうくつ]にクマが潜[ひそ]んでいたという話[はなし]を聞[き]いた。", "sentence_source": "generated"}, {"text": "地震の危険は、身近な場所にも潜んでいる。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "地震[じしん]の危険[きけん]は、身近[みぢか]な場所[ばしょ]にも潜[ひそ]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜む", "label": "終止形"}, {"form": "潜み", "label": "連用形"}, {"form": "潜んで", "label": "て形"}, {"form": "潜んだ", "label": "過去形"}, {"form": "潜まない", "label": "否定形"}, {"form": "潜めば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "隠れて見えない場所にある、いる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36604, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜んで", "is_correct": true, "explanation": "「小さなカニが潜んでいる」の て形。石の陰に隠れている状態を表す正しい形。"}, {"text": "潜んだ", "is_correct": false, "explanation": "過去形。「潜んだいる」となり、「いる」に続かない。"}, {"text": "潜まない", "is_correct": false, "explanation": "否定形。「潜まないいる」となり、存在の表現にならない。"}, {"text": "潜めば", "is_correct": false, "explanation": "仮定形。「潜めばいる」となり、文の述語として成り立たない。"}], "explanations": {"潜んで": "「小さなカニが潜んでいる」の て形。石の陰に隠れている状態を表す正しい形。", "潜んだ": "過去形。「潜んだいる」となり、「いる」に続かない。", "潜まない": "否定形。「潜まないいる」となり、存在の表現にならない。", "潜めば": "仮定形。「潜めばいる」となり、文の述語として成り立たない。"}, "sentence_index": 0, "correct_answer": "潜んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "白い旗が丘の上に潜んでいて、一目でわかる。", "explanation": "ここは〈目立つ〉の意味。潜むは見えないことが前提なので、一目でわかるものには使わない。"}, {"text": "湖の表面に、小さな魚が潜んでぽっかり浮かんでいる。", "explanation": "ここは〈姿を見せる〉（外から見える）の意味。潜むは外から見えない状態なので、水面にぽっかり姿を見せている魚には使わない。"}, {"text": "ダイバーは深い湖の底へ潜んで、写真を撮った。", "explanation": "ここは〈潜る〉（水中に入る）の意味。潜むは隠れている状態で、湖に入る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36604, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜んで", "is_correct": true, "explanation": "「泥棒は木の陰に潜んでいた」の て形。隠れていた状態を表す正しい形。"}, {"text": "潜む", "is_correct": false, "explanation": "終止形。「潜むいた」となり、「いた」に続かない。"}, {"text": "潜み", "is_correct": false, "explanation": "連用形。「潜みいた」となり、「ていた」の形にならない。"}, {"text": "潜まない", "is_correct": false, "explanation": "否定形。隠れていた事実を述べる文と合わない。"}], "explanations": {"潜んで": "「泥棒は木の陰に潜んでいた」の て形。隠れていた状態を表す正しい形。", "潜む": "終止形。「潜むいた」となり、「いた」に続かない。", "潜み": "連用形。「潜みいた」となり、「ていた」の形にならない。", "潜まない": "否定形。隠れていた事実を述べる文と合わない。"}, "sentence_index": 6, "correct_answer": "潜んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コップの水が縁から潜んで、テーブルに広がった。", "explanation": "ここは〈あふれる〉（外へ溢れ出る）の意味。潜むは中に隠れている状態なので、外へ流れ出る様子には使わない。"}, {"text": "夜空の星が一つだけ、強く潜んで光っている。", "explanation": "ここは〈輝く〉（目立って光を放つ）の意味。潜むは外から見えない状態を表すので、目立って輝いている星には使わない。"}, {"text": "彼は大きな声で潜んで、みんなに話しかけた。", "explanation": "ここは〈潜める〉（声を小さくする）の意味。潜むは隠れている状態で、大声を出す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36604, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "押し入れの奥に、古い人形が潜むでいる。", "corrected_sentence": "押し入れの奥に、古い人形が潜んでいる。", "error_description": "〈潜む〉の「ている」形は「潜んでいる」。「潜むで」は活用の誤りで、正しくは「潜んで」（て形）になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "潜む", "is_correct": true, "explanation": "文中の形そのもの。終止形（連体形と同形）で、後ろの名詞「敵」を修飾している。"}, {"text": "潜んで", "is_correct": false, "explanation": "て形では「暗闇に潜んで敵に」となり、名詞「敵」を修飾できない。"}, {"text": "潜めば", "is_correct": false, "explanation": "仮定形では「潜めば敵」となり、名詞を修飾する形として成り立たない。"}, {"text": "潜もう", "is_correct": false, "explanation": "意志形では「潜もう敵」となり、名詞を修飾する形として成り立たない。"}], "correct_form": "潜む", "base_form": "潜む", "form_label": "終止形", "sentence_index": 1, "explanations": {"潜む": "文中の形そのもの。終止形（連体形と同形）で、後ろの名詞「敵」を修飾している。", "潜んで": "て形では「暗闇に潜んで敵に」となり、名詞「敵」を修飾できない。", "潜めば": "仮定形では「潜めば敵」となり、名詞を修飾する形として成り立たない。", "潜もう": "意志形では「潜もう敵」となり、名詞を修飾する形として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36604, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工場の裏の倉庫に、古い機械が潜んでいだ。", "corrected_sentence": "工場の裏の倉庫に、古い機械が潜んでいる。", "error_description": "〈潜む〉を「ている」で続ける形は「潜んでいる」。「潜んでいだ」は「いる」の誤りで、存在を述べる文の形にならない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "潜んで", "is_correct": true, "explanation": "「力が潜んでいる」の て形。内面に隠れている状態を表す正しい形。"}, {"text": "潜まない", "is_correct": false, "explanation": "否定形。力が存在するという肯定の文と合わない。"}, {"text": "潜み", "is_correct": false, "explanation": "連用形。「力が潜みている」となり、「ている」の形として成り立たない。"}, {"text": "潜もう", "is_correct": false, "explanation": "意志形。「力が潜もうでいる」となり、「ている」に続かず、存在を述べる文として成り立たない。"}], "correct_form": "潜んで", "base_form": "潜む", "form_label": "て形", "sentence_index": 7, "explanations": {"潜んで": "「力が潜んでいる」の て形。内面に隠れている状態を表す正しい形。", "潜まない": "否定形。力が存在するという肯定の文と合わない。", "潜み": "連用形。「力が潜みている」となり、「ている」の形として成り立たない。", "潜もう": "意志形。「力が潜もうでいる」となり、「ている」に続かず、存在を述べる文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36605, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「危険な動物が潜んでいる」の主語を示す助詞。動物が隠れている主体になる。"}, {"text": "を", "is_correct": false, "explanation": "「動物を潜んでいる」は目的語の用法として成り立たず、隠れている主体を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「動物で潜んでいる」は場所や手段として文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「動物へ潜んでいる」は方向を示すが、隠れている主体を表す文にならない。"}], "correct_answer": "が", "explanations": {"が": "「危険な動物が潜んでいる」の主語を示す助詞。動物が隠れている主体になる。", "を": "「動物を潜んでいる」は目的語の用法として成り立たず、隠れている主体を示せない。", "で": "「動物で潜んでいる」は場所や手段として文が成立しない。", "へ": "「動物へ潜んでいる」は方向を示すが、隠れている主体を表す文にならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
