INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36605, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "外からは見えないが、内部に存在している。気づかれないように隠れている。", "primary_collocate": null, "pronunciation": "ひそむ", "ipa": "çisomɯ", "syllable_count": 3, "sentences": [{"text": "私の内面に潜む情動を、誰にも話せずにいた。", "target_word": "潜む", "complexity_tier": "T3", "furigana": "私[わたし]の内面[ないめん]に潜[ひそ]む情動[じょうどう]を、誰[だれ]にも話[はな]せずにいた。", "sentence_source": "generated"}, {"text": "暗い森の奥には、危険な動物が潜んでいるかもしれない。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "暗[くら]い森[もり]の奥[おく]には、危険[きけん]な動物[どうぶつ]が潜[ひそ]んでいるかもしれない。", "sentence_source": "generated"}, {"text": "犯人は人通りの少ない路地に潜み、男が通るのを待っていた。", "target_word": "潜み", "complexity_tier": "T3", "furigana": "犯人[はんにん]は人通[ひとどお]りの少[すく]ない路地[ろじ]に潜[ひそ]み、男[おとこ]が通[とお]るのを待[ま]っていた。", "sentence_source": "generated"}, {"text": "この小さな町の穏やかな暮らしの裏には、大きな問題が潜んでいる。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "この小[ちい]さな町[まち]の穏[おだ]やかな暮[く]らしの裏[うら]には、大[おお]きな問題[もんだい]が潜[ひそ]んでいる。", "sentence_source": "generated"}, {"text": "彼の笑顔の陰に、深い悲しみが潜んでいることに誰も気づかなかった。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "彼[かれ]の笑顔[えがお]の陰[かげ]に、深[ふか]い悲[かな]しみが潜[ひそ]んでいることに誰[だれ]も気[き]づかなかった。", "sentence_source": "generated"}, {"text": "猫は鳥に気づかれないように、草むらに潜んで近づくのを待った。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "猫[ねこ]は鳥[とり]に気[き]づかれないように、草[くさ]むらに潜[ひそ]んで近[ちか]づくのを待[ま]った。", "sentence_source": "generated"}, {"text": "便利な機能の中にも、思わぬ危険が潜んでいる場合がある。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "便利[べんり]な機能[きのう]の中[なか]にも、思[おも]わぬ危険[きけん]が潜[ひそ]んでいる場合[ばあい]がある。", "sentence_source": "generated"}, {"text": "兵士たちは夜になるまで、山の中に潜んでいた。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "兵士[へいし]たちは夜[よる]になるまで、山[やま]の中[なか]に潜[ひそ]んでいた。", "sentence_source": "generated"}, {"text": "古い建物の地下には、まだ誰も知らない秘密が潜んでいるという噂だ。", "target_word": "潜んで", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]の地下[ちか]には、まだ誰[だれ]も知[し]らない秘密[ひみつ]が潜[ひそ]んでいるという噂[うわさ]だ。", "sentence_source": "generated"}, {"text": "彼女の言葉に潜む本当の意味を、私はあとで理解した。", "target_word": "潜む", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の言葉[ことば]に潜[ひそ]む本当[ほんとう]の意味[いみ]を、私[わたし]はあとで理解[りかい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜む", "label": "終止形"}, {"form": "潜み", "label": "連用形"}, {"form": "潜んで", "label": "て形"}, {"form": "潜んだ", "label": "過去形"}, {"form": "潜まない", "label": "否定形"}, {"form": "潜めば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "表からは見えず内部に存在する、または気づかれないよう隠れている", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36605, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜む", "is_correct": true, "explanation": "「私の内面に潜む情動」で、内側に隠れてある情動を修飾する正しい連体形。"}, {"text": "崩す", "is_correct": false, "explanation": "「内面を崩す」は成立するが、「崩す情動」は意味が通らず、隠れて存在する状態に合わない。"}, {"text": "削る", "is_correct": false, "explanation": "「削る」は物を削り取る動作で、内面の情動を修飾しても意味が合わない。"}, {"text": "凍らせる", "is_correct": false, "explanation": "「凍らせる情動」は意味が通らず、内面に隠れて存在するという文脈に合わない。"}], "explanations": {"潜む": "「私の内面に潜む情動」で、内側に隠れてある情動を修飾する正しい連体形。", "崩す": "「内面を崩す」は成立するが、「崩す情動」は意味が通らず、隠れて存在する状態に合わない。", "削る": "「削る」は物を削り取る動作で、内面の情動を修飾しても意味が合わない。", "凍らせる": "「凍らせる情動」は意味が通らず、内面に隠れて存在するという文脈に合わない。"}, "sentence_index": 0, "correct_answer": "潜む"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水面に大きな泡が潜んで、ぽかりと浮かんでいる。", "explanation": "ここは〈姿を見せる〉（外から見える）の意味。潜むは外から見えない状態を表すので、水面に出て見えている泡には使わない。"}, {"text": "赤い看板が通りの角に潜んでいて、遠くからでもよく見える。", "explanation": "ここは〈目立つ〉の意味。潜むは見えないことが前提なので、よく見えるものを説明する文では使わない。"}, {"text": "彼女は深い海に潜んで、サンゴの写真を撮った。", "explanation": "ここは〈潜る〉（水中に入る）の意味。潜むは隠れている状態を表し、海に入る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36605, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜んで", "is_correct": true, "explanation": "「便利な機能の中に思わぬ危険が潜んでいる」の て形。隠れて存在している状態を述べる。"}, {"text": "眺めて", "is_correct": false, "explanation": "「眺めている場合がある」では意味が通らず、危険が見えない状態に合わない。"}, {"text": "叩いて", "is_correct": false, "explanation": "「叩いている場合」は危険の在り方を述べる文として意味が合わない。"}, {"text": "拭いて", "is_correct": false, "explanation": "「拭いている場合」では危険を説明する文にならない。"}], "explanations": {"潜んで": "「便利な機能の中に思わぬ危険が潜んでいる」の て形。隠れて存在している状態を述べる。", "眺めて": "「眺めている場合がある」では意味が通らず、危険が見えない状態に合わない。", "叩いて": "「叩いている場合」は危険の在り方を述べる文として意味が合わない。", "拭いて": "「拭いている場合」では危険を説明する文にならない。"}, "sentence_index": 6, "correct_answer": "潜んで"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "霧が晴れると、山の頂が潜んだ。", "explanation": "ここは〈現れる〉（姿が見えてくる）の意味。潜むは隠れて見えない状態で、出てくる動きには使わない。"}, {"text": "その選手は大きな声で潜んで、観客を沸かせた。", "explanation": "ここは〈声を張る〉の意味。潜むは隠れている状態を表すので、大声で話す場面には使わない。"}, {"text": "煙が部屋いっぱいに潜んで、窓から逃げ場がなくなった。", "explanation": "ここは〈広がる〉（範囲が増す）の意味。潜むは一か所に隠れる状態で、範囲が広がる様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36605, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベッドの下に猫が潜むでいる。", "corrected_sentence": "ベッドの下に猫が潜んでいる。", "error_description": "〈潜む〉の「ている」形は「潜んでいる」。「潜むで」は活用の誤りで、正しくは「潜んで」（て形）になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "潜んで", "is_correct": true, "explanation": "「潜んでいるかもしれない」の て形。動物がそこに隠れている状態を表す正しい形。"}, {"text": "潜んだ", "is_correct": false, "explanation": "過去形。ここでは現在の状態を述べているため合わない。"}, {"text": "潜まない", "is_correct": false, "explanation": "否定形。文は肯定的に存在を述べているので合わない。"}, {"text": "潜めば", "is_correct": false, "explanation": "仮定形。「潜めば」で文を続けると条件文になり、文の形が合わない。"}], "correct_form": "潜んで", "base_form": "潜む", "form_label": "て形", "sentence_index": 1, "explanations": {"潜んで": "「潜んでいるかもしれない」の て形。動物がそこに隠れている状態を表す正しい形。", "潜んだ": "過去形。ここでは現在の状態を述べているため合わない。", "潜まない": "否定形。文は肯定的に存在を述べているので合わない。", "潜めば": "仮定形。「潜めば」で文を続けると条件文になり、文の形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36605, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地下室の箱の中に、古い鍵が潜むでいた。", "corrected_sentence": "地下室の箱の中に、古い鍵が潜んでいた。", "error_description": "〈潜む〉の「ていた」形は「潜んでいた」。「潜むで」は活用の誤りで、正しくは「潜んで」（て形）になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "潜んで", "is_correct": true, "explanation": "「潜んでいた」の て形。兵士が山の中に隠れていた状態を表す正しい形。"}, {"text": "潜む", "is_correct": false, "explanation": "終止形（連体形と同形）。「潜むいた」となり、「ていた」の形にならない。"}, {"text": "潜み", "is_correct": false, "explanation": "連用形。「潜みいた」となり、「ていた」の形に続かない。"}, {"text": "潜もう", "is_correct": false, "explanation": "意志形。「潜もういた」となり、過去の状態を述べる文と合わない。"}], "correct_form": "潜んで", "base_form": "潜む", "form_label": "て形", "sentence_index": 7, "explanations": {"潜んで": "「潜んでいた」の て形。兵士が山の中に隠れていた状態を表す正しい形。", "潜む": "終止形（連体形と同形）。「潜むいた」となり、「ていた」の形にならない。", "潜み": "連用形。「潜みいた」となり、「ていた」の形に続かない。", "潜もう": "意志形。「潜もういた」となり、過去の状態を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36607, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『哺乳の方法』と所属を表す『の』。"}, {"text": "を", "is_correct": false, "explanation": "『哺乳を方法』は成り立たず、名詞の所属には『の』を使う。"}, {"text": "に", "is_correct": false, "explanation": "『哺乳に方法』と名詞を直接つなげられず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』で、名詞の所属には使わない。"}], "correct_answer": "の", "explanations": {"の": "『哺乳の方法』と所属を表す『の』。", "を": "『哺乳を方法』は成り立たず、名詞の所属には『の』を使う。", "に": "『哺乳に方法』と名詞を直接つなげられず、不自然。", "へ": "方向を表す『へ』で、名詞の所属には使わない。"}, "error_tags": {"を": "目的語", "に": "場所・時点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
