INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36607, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "子どもに乳を与えて育てること。", "primary_collocate": null, "pronunciation": "ほにゅう", "ipa": "hoɲɯː", "syllable_count": 3, "sentences": [{"text": "母親は一日に何回も赤ちゃんに哺乳をする。", "target_word": "哺乳", "complexity_tier": "T3", "furigana": "母親[ははおや]は一日[いちにち]に何回[なんかい]も赤[あか]ちゃんに哺乳[ほにゅう]をする。", "sentence_source": "generated"}, {"text": "病院では、哺乳の方法を看護師が教えてくれた。", "target_word": "哺乳", "complexity_tier": "T3", "furigana": "病院[びょういん]では、哺乳[ほにゅう]の方法[ほうほう]を看護師[かんごし]が教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "母親が病気のときは、哺乳が難しくなる。", "target_word": "哺乳", "complexity_tier": "T3", "furigana": "母親[ははおや]が病気[びょうき]のときは、哺乳[ほにゅう]が難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "母ネコは哺乳の時期、いつもより多くの食べ物が必要だ。", "target_word": "哺乳", "complexity_tier": "T3", "furigana": "母[はは]ネコは哺乳[ほにゅう]の時期[じき]、いつもより多[おお]くの食[た]べ物[もの]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "ミルクで哺乳する場合も、赤ちゃんを抱いて飲ませるとよい。", "target_word": "哺乳", "complexity_tier": "T3", "furigana": "ミルクで哺乳[ほにゅう]する場合[ばあい]も、赤[あか]ちゃんを抱[だ]いて飲[の]ませるとよい。", "sentence_source": "generated"}, {"text": "子牛への哺乳は、朝と夕方の二回行う。", "target_word": "哺乳", "complexity_tier": "T3", "furigana": "子牛[こうし]への哺乳[ほにゅう]は、朝[あさ]と夕方[ゆうがた]の二回[にかい]行[おこな]う。", "sentence_source": "generated"}, {"text": "哺乳によって、子どもは必要な栄養を母親から受け取る。", "target_word": "哺乳", "complexity_tier": "T3", "furigana": "哺乳[ほにゅう]によって、子[こ]どもは必要[ひつよう]な栄養[えいよう]を母親[ははおや]から受[う]け取[と]る。", "sentence_source": "generated"}, {"text": "動物園では、母親が育てられない子トラに人が哺乳している。", "target_word": "哺乳", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では、母親[ははおや]が育[そだ]てられない子[こ]トラに人[ひと]が哺乳[ほにゅう]している。", "sentence_source": "generated"}, {"text": "夜中の哺乳で、母親は十分に眠れない日が続いた。", "target_word": "哺乳", "complexity_tier": "T3", "furigana": "夜中[よなか]の哺乳[ほにゅう]で、母親[ははおや]は十分[じゅうぶん]に眠[ねむ]れない日[ひ]が続[つづ]いた。", "sentence_source": "generated"}, {"text": "哺乳は、子どもを育てる大切な行いである。", "target_word": "哺乳", "complexity_tier": "T3", "furigana": "哺乳[ほにゅう]は、子[こ]どもを育[そだ]てる大切[たいせつ]な行[おこな]いである。", "sentence_source": "generated"}], "morphological_forms": [{"form": "哺乳する", "label": "サ変動詞形"}], "register": "標準（普通体）", "sense_fingerprint": "子に乳を与えて育てる行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36607, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哺乳", "is_correct": true, "explanation": "乳を与えて子を育てる行為を表す語。ここでの正解。"}, {"text": "採点", "is_correct": false, "explanation": "点数をつける行為で、赤ちゃんに対しては成り立たない。"}, {"text": "反省", "is_correct": false, "explanation": "自分の行いを省みることで、赤ちゃんへの行為にはならない。"}, {"text": "献金", "is_correct": false, "explanation": "寄付のお金を出す行為で、赤ちゃんに対する行為にはならない。"}], "explanations": {"哺乳": "乳を与えて子を育てる行為を表す語。ここでの正解。", "採点": "点数をつける行為で、赤ちゃんに対しては成り立たない。", "反省": "自分の行いを省みることで、赤ちゃんへの行為にはならない。", "献金": "寄付のお金を出す行為で、赤ちゃんに対する行為にはならない。"}, "sentence_index": 0, "correct_answer": "哺乳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大人は毎朝、哺乳を一人で済ませて出勤する。", "explanation": "ここは〈食事〉の場面。朝食は大人も食べるが、哺乳は乳児に乳を与える行為で、大人の食事には使わない。"}, {"text": "毎朝、庭の花に哺乳をやる。", "explanation": "ここは〈水やり〉の場面。水は植物にやるが、哺乳は乳を与える行為で、植物には使わない。"}, {"text": "毎週末、部屋の哺乳をする。", "explanation": "ここは〈掃除〉の場面。掃除は部屋を対象にするが、哺乳は乳を与える行為で、部屋を対象にできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36607, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哺乳", "is_correct": true, "explanation": "乳を与える行為で、母親から栄養を受け取る流れに合う。ここでの正解。"}, {"text": "散髪", "is_correct": false, "explanation": "髪を切ることで、栄養の受け取りとは結びつかない。"}, {"text": "洗濯", "is_correct": false, "explanation": "衣類を洗う行為で、栄養の話と合わない。"}, {"text": "運転", "is_correct": false, "explanation": "車を動かす行為で、栄養の受け取りには合わない。"}], "explanations": {"哺乳": "乳を与える行為で、母親から栄養を受け取る流れに合う。ここでの正解。", "散髪": "髪を切ることで、栄養の受け取りとは結びつかない。", "洗濯": "衣類を洗う行為で、栄養の話と合わない。", "運転": "車を動かす行為で、栄養の受け取りには合わない。"}, "sentence_index": 6, "correct_answer": "哺乳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哺乳は、体を休める大切な行いである。", "explanation": "ここは〈睡眠〉の場面。睡眠は体を休めるものだが、哺乳は乳を与える行為で、体を休めるためのものではない。"}, {"text": "哺乳は、食卓を彩る大切な献立である。", "explanation": "ここは〈料理〉の場面。料理は食卓を彩るものだが、哺乳は乳を与える行為で、料理とは言わない。"}, {"text": "哺乳は、子どもに文字を教える大切な行いである。", "explanation": "ここは〈教育〉の場面。教育は文字を教えるものだが、哺乳は乳を与える行為で、教えることとは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36607, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哺乳に間は、母親がそばで体を温める。", "corrected_sentence": "哺乳の間は、母親がそばで体を温める。", "error_description": "誤りは『に』。『哺乳の間』の『の』が正しい。『に』は場所や時点を表すため、名詞『間』を修飾できず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36607, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母親は哺乳を続いて、赤ちゃんの体重を増やした。", "corrected_sentence": "母親は哺乳を続けて、赤ちゃんの体重を増やした。", "error_description": "誤りは『続いて』。『続ける』は他動詞で『哺乳を』を取る。『続いて』は自動詞の形で、目的語『哺乳を』と合わない。正しくは『続けて』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36608, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『鳥類の多く』と所属・修飾の関係を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の印。鳥類は『多くは』の対象ではなく、ここには入らない。"}, {"text": "に", "is_correct": false, "explanation": "位置・帰着の印。『鳥類に多くは』は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の印。『鳥類で多くは』は不自然。"}], "correct_answer": "の", "explanations": {"の": "『鳥類の多く』と所属・修飾の関係を示す。", "を": "目的語の印。鳥類は『多くは』の対象ではなく、ここには入らない。", "に": "位置・帰着の印。『鳥類に多くは』は意味が通らない。", "で": "場所・手段の印。『鳥類で多くは』は不自然。"}, "error_tags": {"を": "目的語", "に": "位置・帰着", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36608, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36608, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "からだに羽がある動物です。", "primary_collocate": null, "pronunciation": "ちょうるい", "ipa": "tɕoːɾɯi", "syllable_count": 4, "sentences": [{"text": "スズメやカラスは鳥類で、体に羽がある。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "スズメやカラスは鳥類[ちょうるい]で、体[からだ]に羽[はね]がある。", "sentence_source": "generated"}, {"text": "鳥類の多くは、羽を使って空を飛ぶことができる。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "鳥類[ちょうるい]の多[おお]くは、羽[はね]を使[つか]って空[そら]を飛[と]ぶことができる。", "sentence_source": "generated"}, {"text": "ペンギンは鳥類だが、空を飛べない。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "ペンギンは鳥類[ちょうるい]だが、空[そら]を飛[と]べない。", "sentence_source": "generated"}, {"text": "公園で、いろいろな鳥類を見つけて写真を撮った。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "公園[こうえん]で、いろいろな鳥類[ちょうるい]を見[み]つけて写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "鳥類は卵を産んで、親が温めてヒナを育てる。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "鳥類[ちょうるい]は卵[たまご]を産[う]んで、親[おや]が温[あたた]めてヒナを育[そだ]てる。", "sentence_source": "generated"}, {"text": "森には、鳥類を観察しに来る人が多い。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "森[もり]には、鳥類[ちょうるい]を観察[かんさつ]しに来[く]る人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "ワシやタカは、鳥類の中でも大きくて力が強い。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "ワシやタカは、鳥類[ちょうるい]の中[なか]でも大[おお]きくて力[ちから]が強[つよ]い。", "sentence_source": "generated"}, {"text": "コウモリは羽があるが、鳥類ではなく哺乳類だ。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "コウモリは羽[はね]があるが、鳥類[ちょうるい]ではなく哺乳類[ほにゅうるい]だ。", "sentence_source": "generated"}, {"text": "図鑑で鳥類のページを開くと、美しい羽の絵がたくさんあった。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "図鑑[ずかん]で鳥類[ちょうるい]のページを開[ひら]くと、美[うつく]しい羽[はね]の絵[え]がたくさんあった。", "sentence_source": "generated"}, {"text": "春になると、渡ってくる鳥類が増えて、山がにぎやかになる。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "春[はる]になると、渡[わた]ってくる鳥類[ちょうるい]が増[ふ]えて、山[やま]がにぎやかになる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鳥類", "label": "基本形"}], "register": "標準（普通体）", "sense_fingerprint": "からだに羽がある鳥の仲間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36608, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鳥類", "is_correct": true, "explanation": "羽のある動物の分類で、スズメとカラスに当てはまる。"}, {"text": "哺乳類", "is_correct": false, "explanation": "乳で子を育てる分類。『体に羽がある』という文脈と矛盾する。"}, {"text": "両生類", "is_correct": false, "explanation": "水辺で暮らす分類。羽を持つスズメ・カラスには当てはまらない。"}, {"text": "爬虫類", "is_correct": false, "explanation": "うろこで覆われた分類。羽がある文脈と合わない。"}], "explanations": {"鳥類": "羽のある動物の分類で、スズメとカラスに当てはまる。", "哺乳類": "乳で子を育てる分類。『体に羽がある』という文脈と矛盾する。", "両生類": "水辺で暮らす分類。羽を持つスズメ・カラスには当てはまらない。", "爬虫類": "うろこで覆われた分類。羽がある文脈と合わない。"}, "sentence_index": 0, "correct_answer": "鳥類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷蔵庫の鳥類を焼いて、夕飯のおかずにした。", "explanation": "ここは食材の〈鶏肉〉の意味。鳥類は動物の分類で、料理の材料としては言わない。"}, {"text": "寒くて、腕に鳥類が立った。", "explanation": "ここは〈鳥肌〉の意味。鳥類は動物の分類で、『鳥肌が立つ』の慣用句では使わない。"}, {"text": "神社の前で、大きな鳥類をくぐって参道に入った。", "explanation": "ここは〈鳥居〉（神社の門）の意味。鳥類は動物の分類で、くぐる門の名前ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36608, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鳥類", "is_correct": true, "explanation": "鳥の分類で、ワシやタカに当てはまる。"}, {"text": "魚類", "is_correct": false, "explanation": "えらで呼吸する水中の分類。空を飛ぶワシやタカとは合わない。"}, {"text": "昆虫", "is_correct": false, "explanation": "六本脚の分類。ワシやタカの説明には当てはまらない。"}, {"text": "甲殻類", "is_correct": false, "explanation": "殻を持つ水生の分類。ワシやタカとは合わない。"}], "explanations": {"鳥類": "鳥の分類で、ワシやタカに当てはまる。", "魚類": "えらで呼吸する水中の分類。空を飛ぶワシやタカとは合わない。", "昆虫": "六本脚の分類。ワシやタカの説明には当てはまらない。", "甲殻類": "殻を持つ水生の分類。ワシやタカとは合わない。"}, "sentence_index": 6, "correct_answer": "鳥類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜になると、彼は鳥類になって何も見えなくなる。", "explanation": "ここは〈鳥目〉（夜に見えにくくなる症状）の意味。鳥類は動物の分類で、この症状は表さない。"}, {"text": "木の枝に鳥類を塗って、セミを捕まえた。", "explanation": "ここは〈鳥もち〉（枝に塗る粘着剤）の意味。鳥類は生き物の分類で、道具の名前にはならない。"}, {"text": "大きな鳥類を広げて、崖から飛び立った。", "explanation": "ここは〈翼〉の意味。鳥類は動物全体の分類で、広げられるのは翼である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36608, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鳥類を多くは、羽で空を飛ぶ。", "corrected_sentence": "鳥類の多くは、羽で空を飛ぶ。", "error_description": "『鳥類』の後は所属・修飾の『の』が正しいが、『を』（目的語の印）になっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36608, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春になると、渡ってくる鳥類を増えて、森がにぎやかになる。", "corrected_sentence": "春になると、渡ってくる鳥類が増えて、森がにぎやかになる。", "error_description": "『増える』の主語は『鳥類』なので『が』が正しい。『を』は目的語の印で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36609, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『鳥類の前肢』と所属・修飾の関係を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の印。『鳥類を前肢』では前肢との関係が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置・帰着の印。『鳥類に前肢は』は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の印。『鳥類で前肢は』は不自然。"}], "correct_answer": "の", "explanations": {"の": "『鳥類の前肢』と所属・修飾の関係を示す。", "を": "目的語の印。『鳥類を前肢』では前肢との関係が成り立たない。", "に": "位置・帰着の印。『鳥類に前肢は』は意味が通らない。", "で": "場所・手段の印。『鳥類で前肢は』は不自然。"}, "error_tags": {"を": "目的語", "に": "位置・帰着", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36609, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『鳥類の種類』と所属・修飾の関係を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の印。『変わる』は目的語を取らないので、『鳥類を種類も』は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の印。『鳥類で種類も変わる』は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点の印。『鳥類から種類』は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "『鳥類の種類』と所属・修飾の関係を示す。", "を": "目的語の印。『変わる』は目的語を取らないので、『鳥類を種類も』は成り立たない。", "で": "場所・手段の印。『鳥類で種類も変わる』は意味が通らない。", "から": "起点の印。『鳥類から種類』は意味が通らない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36609, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "脊椎動物の一群で、体が羽毛で覆われ、前肢が翼に変化し、卵を産んで子を育てます。", "primary_collocate": null, "pronunciation": "ちょうるい", "ipa": "tɕoːɾɯi", "syllable_count": 4, "sentences": [{"text": "鳥類は脊椎動物の一群で、体が羽毛でおおわれている。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "鳥類[ちょうるい]は脊椎動物[せきついどうぶつ]の一群[いちぐん]で、体[からだ]が羽毛[うもう]でおおわれている。", "sentence_source": "generated"}, {"text": "鳥類の前肢は翼に変化し、種類によっては空を飛ぶ。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "鳥類[ちょうるい]の前肢[ぜんし]は翼[つばさ]に変化[へんか]し、種類[しゅるい]によっては空[そら]を飛[と]ぶ。", "sentence_source": "generated"}, {"text": "鳥類は卵を産み、多くの種で親が子を育てる。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "鳥類[ちょうるい]は卵[たまご]を産[う]み、多[おお]くの種[しゅ]で親[おや]が子[こ]を育[そだ]てる。", "sentence_source": "generated"}, {"text": "恐竜の一部が進化して、現在の鳥類になったと考えられている。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "恐竜[きょうりゅう]の一部[いちぶ]が進化[しんか]して、現在[げんざい]の鳥類[ちょうるい]になったと考[かんが]えられている。", "sentence_source": "generated"}, {"text": "鳥類は恒温動物なので、体温を一定に保つことができる。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "鳥類[ちょうるい]は恒温動物[こうおんどうぶつ]なので、体温[たいおん]を一定[いってい]に保[たも]つことができる。", "sentence_source": "generated"}, {"text": "学者は、島に住む鳥類の数を毎年調べている。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "学者[がくしゃ]は、島[しま]に住[す]む鳥類[ちょうるい]の数[かず]を毎年[まいとし]調[しら]べている。", "sentence_source": "generated"}, {"text": "ダチョウは飛べないが、羽毛と翼を持つ鳥類である。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "ダチョウは飛[と]べないが、羽毛[うもう]と翼[つばさ]を持[も]つ鳥類[ちょうるい]である。", "sentence_source": "generated"}, {"text": "環境が変わると、その土地の鳥類の種類も変わることがある。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "環境[かんきょう]が変[か]わると、その土地[とち]の鳥類[ちょうるい]の種類[しゅるい]も変[か]わることがある。", "sentence_source": "generated"}, {"text": "鳥類の骨は軽くて、中が空洞のものが多い。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "鳥類[ちょうるい]の骨[ほね]は軽[かる]くて、中[なか]が空洞[くうどう]のものが多[おお]い。", "sentence_source": "generated"}, {"text": "鳥類と哺乳類は、どちらも体温を保つしくみを持っている。", "target_word": "鳥類", "complexity_tier": "T3", "furigana": "鳥類[ちょうるい]と哺乳類[ほにゅうるい]は、どちらも体温[たいおん]を保[たも]つしくみを持[も]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "鳥類", "label": "基本形"}], "register": "標準（説明的な普通体）", "sense_fingerprint": "分類学上の脊椎動物の一群としての鳥類", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36609, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鳥類", "is_correct": true, "explanation": "脊椎動物の一群で、体が羽毛でおおわれる分類に当てはまる。"}, {"text": "魚類", "is_correct": false, "explanation": "えらで呼吸する分類で、羽毛を持たないので文脈と合わない。"}, {"text": "両生類", "is_correct": false, "explanation": "皮膚で呼吸する分類で、羽毛がない。文脈と矛盾する。"}, {"text": "爬虫類", "is_correct": false, "explanation": "うろこで覆われる分類で、羽毛という特徴と合わない。"}], "explanations": {"鳥類": "脊椎動物の一群で、体が羽毛でおおわれる分類に当てはまる。", "魚類": "えらで呼吸する分類で、羽毛を持たないので文脈と合わない。", "両生類": "皮膚で呼吸する分類で、羽毛がない。文脈と矛盾する。", "爬虫類": "うろこで覆われる分類で、羽毛という特徴と合わない。"}, "sentence_index": 0, "correct_answer": "鳥類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷蔵庫の鳥類を、今夜のスープに入れた。", "explanation": "ここは食材の〈鶏肉〉の意味。鳥類は動物の分類で、料理の材料には言わない。"}, {"text": "神社の前で、大きな鳥類をくぐって参道に入った。", "explanation": "ここは〈鳥居〉（神社の門）の意味。鳥類は動物の分類で、くぐる門の名前ではない。"}, {"text": "山頂から見ると、町が鳥類のように見える。", "explanation": "ここは〈鳥瞰〉（空から見下ろすような見方）の意味。鳥類は動物の分類で、見下ろす眺めを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36609, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鳥類", "is_correct": true, "explanation": "羽毛と翼を持つ分類で、ダチョウに当てはまる。"}, {"text": "哺乳類", "is_correct": false, "explanation": "乳で子を育てる分類。羽毛と翼を持つ文脈と合わない。"}, {"text": "昆虫", "is_correct": false, "explanation": "六本脚の分類。羽毛を持つダチョウとは合わない。"}, {"text": "甲殻類", "is_correct": false, "explanation": "殻を持つ水生の分類。羽毛のダチョウには当てはまらない。"}], "explanations": {"鳥類": "羽毛と翼を持つ分類で、ダチョウに当てはまる。", "哺乳類": "乳で子を育てる分類。羽毛と翼を持つ文脈と合わない。", "昆虫": "六本脚の分類。羽毛を持つダチョウとは合わない。", "甲殻類": "殻を持つ水生の分類。羽毛のダチョウには当てはまらない。"}, "sentence_index": 6, "correct_answer": "鳥類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな鳥類を広げて、空へ舞い上がった。", "explanation": "ここは〈翼〉の意味。鳥類は生き物全体の分類で、広げるのは翼である。"}, {"text": "木の枝に鳥類を塗って、セミを捕まえた。", "explanation": "ここは〈鳥もち〉の意味。鳥類は動物の分類で、粘着剤の名前にはならない。"}, {"text": "夜になると、彼は鳥類になって何も見えなくなる。", "explanation": "ここは〈鳥目〉の意味。鳥類は動物の分類で、夜に見えなくなる症状は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36609, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鳥類に恒温動物で、体温を一定に保つことができる。", "corrected_sentence": "鳥類は恒温動物で、体温を一定に保つことができる。", "error_description": "文の主題を示す『は』が正しいが、『に』（位置・帰着）になっていて文の骨組みが崩れている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36609, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鳥類を哺乳類は、どちらも体温を保つしくみを持つ。", "corrected_sentence": "鳥類と哺乳類は、どちらも体温を保つしくみを持つ。", "error_description": "『鳥類』と『哺乳類』を並べる『と』が正しいが、『を』（目的語の印）になっている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36610, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『爬虫類』を主題として示し、後ろの説明を導く。"}, {"text": "を", "is_correct": false, "explanation": "目的語の印。『爬虫類を寒いと』は文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置・帰着の印。『爬虫類に寒いと』は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の印。『爬虫類で寒いと』は不自然。"}], "correct_answer": "は", "explanations": {"は": "『爬虫類』を主題として示し、後ろの説明を導く。", "を": "目的語の印。『爬虫類を寒いと』は文が成り立たない。", "に": "位置・帰着の印。『爬虫類に寒いと』は意味が通らない。", "で": "場所・手段の印。『爬虫類で寒いと』は不自然。"}, "error_tags": {"を": "目的語", "に": "位置・帰着", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36610, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『爬虫類の体』と所属・修飾の関係を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の印。覆われている『体』の文には目的語が残らず、成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点の印。『爬虫類から体は』は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の印。『爬虫類へ体は』は文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "『爬虫類の体』と所属・修飾の関係を示す。", "を": "目的語の印。覆われている『体』の文には目的語が残らず、成り立たない。", "から": "起点の印。『爬虫類から体は』は意味が通らない。", "へ": "方向の印。『爬虫類へ体は』は文が成り立たない。"}, "error_tags": {"を": "目的語", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36610, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "じめんを はって うごく いきもの。", "primary_collocate": null, "pronunciation": "はちゅう", "ipa": "hatɕɯː", "syllable_count": 3, "sentences": [{"text": "ヘビやトカゲは爬虫類で、地面をはって動く。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "ヘビやトカゲは爬虫類[はちゅうるい]で、地面[じめん]をはって動[うご]く。", "sentence_source": "generated"}, {"text": "爬虫類は寒いと体が冷えて、あまり動けなくなる。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "爬虫類[はちゅうるい]は寒[さむ]いと体[からだ]が冷[ひ]えて、あまり動[うご]けなくなる。", "sentence_source": "generated"}, {"text": "友だちの家で、爬虫類のカメを飼っている。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "友[とも]だちの家[いえ]で、爬虫類[はちゅうるい]のカメを飼[か]っている。", "sentence_source": "generated"}, {"text": "爬虫類の多くは、卵を産んで子どもを増やす。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "爬虫類[はちゅうるい]の多[おお]くは、卵[たまご]を産[う]んで子[こ]どもを増[ふ]やす。", "sentence_source": "generated"}, {"text": "動物園の爬虫類館で、大きなワニを見た。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]の爬虫類館[はちゅうるいかん]で、大[おお]きなワニを見[み]た。", "sentence_source": "generated"}, {"text": "日なたで体を温める爬虫類を、池のそばで見かけた。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "日[ひ]なたで体[からだ]を温[あたた]める爬虫類[はちゅうるい]を、池[いけ]のそばで見[み]かけた。", "sentence_source": "generated"}, {"text": "ヤモリは小さいが、立派な爬虫類の仲間だ。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "ヤモリは小[ちい]さいが、立派[りっぱ]な爬虫類[はちゅうるい]の仲間[なかま]だ。", "sentence_source": "generated"}, {"text": "爬虫類の体は、かたいうろこでおおわれている。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "爬虫類[はちゅうるい]の体[からだ]は、かたいうろこでおおわれている。", "sentence_source": "generated"}, {"text": "カエルは水辺にいるけれど、爬虫類ではない。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "カエルは水辺[みずべ]にいるけれど、爬虫類[はちゅうるい]ではない。", "sentence_source": "generated"}, {"text": "弟は爬虫類が大好きで、図鑑をいつも読んでいる。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "弟[おとうと]は爬虫類[はちゅうるい]が大好[だいす]きで、図鑑[ずかん]をいつも読[よ]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "爬虫類", "label": "基本形（動物のグループ）"}], "register": "標準（普通体）", "sense_fingerprint": "地面をはって動く生き物（爬虫類）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36610, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爬虫類", "is_correct": true, "explanation": "地面をはって動く分類で、ヘビとトカゲに当てはまる。"}, {"text": "両生類", "is_correct": false, "explanation": "水辺で暮らす分類。地面をはって動く文脈と合わない。"}, {"text": "哺乳類", "is_correct": false, "explanation": "乳で子を育てる分類。はって動く特徴と合わない。"}, {"text": "鳥類", "is_correct": false, "explanation": "羽で空を飛ぶ分類。地面をはう文脈と合わない。"}], "explanations": {"爬虫類": "地面をはって動く分類で、ヘビとトカゲに当てはまる。", "両生類": "水辺で暮らす分類。地面をはって動く文脈と合わない。", "哺乳類": "乳で子を育てる分類。はって動く特徴と合わない。", "鳥類": "羽で空を飛ぶ分類。地面をはう文脈と合わない。"}, "sentence_index": 0, "correct_answer": "爬虫類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "足の指に爬虫類ができて、かゆくてたまらない。", "explanation": "ここは〈水虫〉（足の皮膚の病気）の意味。爬虫類は動物の分類で、病名には使わない。"}, {"text": "小さな文字は、爬虫類で拡大して読んだ。", "explanation": "ここは〈虫眼鏡〉（物を大きく見せる道具）の意味。爬虫類は動物の分類で、道具の名前にはならない。"}, {"text": "夜になると、彼の目は爬虫類になって何も見えなくなる。", "explanation": "ここは〈鳥目〉（夜に見えにくくなる症状）の意味。爬虫類は動物の分類で、この症状は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36610, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爬虫類", "is_correct": true, "explanation": "うろこのある爬虫類の仲間として、ヤモリに当てはまる。"}, {"text": "魚類", "is_correct": false, "explanation": "えらで呼吸する水中の分類で、ヤモリとは合わない。"}, {"text": "昆虫", "is_correct": false, "explanation": "六本脚の分類で、ヤモリには当てはまらない。"}, {"text": "甲殻類", "is_correct": false, "explanation": "殻を持つ水生の分類で、ヤモリとは合わない。"}], "explanations": {"爬虫類": "うろこのある爬虫類の仲間として、ヤモリに当てはまる。", "魚類": "えらで呼吸する水中の分類で、ヤモリとは合わない。", "昆虫": "六本脚の分類で、ヤモリには当てはまらない。", "甲殻類": "殻を持つ水生の分類で、ヤモリとは合わない。"}, "sentence_index": 6, "correct_answer": "爬虫類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大工さんは、板を爬虫類で削って薄くした。", "explanation": "ここは〈かんな〉（板を削る大工道具）の意味。爬虫類は動物の分類で、道具の名前にはならない。"}, {"text": "奥歯の爬虫類が痛くて、歯医者に行った。", "explanation": "ここは〈虫歯〉の意味。爬虫類は動物の分類で、歯の病気の名前ではない。"}, {"text": "道が爬虫類のように曲がりくねっている。", "explanation": "ここは〈蛇行〉（蛇がくねるように曲がること）の意味。爬虫類は動物の分類で、曲がりくねる様子を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36610, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ヘビやトカゲは爬虫類を、地面をはって進む。", "corrected_sentence": "ヘビやトカゲは爬虫類で、地面をはって進む。", "error_description": "『爬虫類』は判断の『で』で続けるのが正しいが、『を』（目的語の印）が付いている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36610, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "庭の石の下で、爬虫類をトカゲを見つけた。", "corrected_sentence": "庭の石の下で、爬虫類のトカゲを見つけた。", "error_description": "『爬虫類』は後ろの『トカゲ』を修飾する『の』が正しいが、『を』（目的語の印）が付いて目的語が二つ重なり、不自然になっている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36611, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『爬虫類』を主題として示し、変温動物であることを説明する。"}, {"text": "を", "is_correct": false, "explanation": "目的語の印。『爬虫類を変温動物で』は主題にならない。"}, {"text": "に", "is_correct": false, "explanation": "位置・帰着の印。『爬虫類に変温動物で』は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の印。『爬虫類で変温動物』は成り立たない。"}], "correct_answer": "は", "explanations": {"は": "『爬虫類』を主題として示し、変温動物であることを説明する。", "を": "目的語の印。『爬虫類を変温動物で』は主題にならない。", "に": "位置・帰着の印。『爬虫類に変温動物で』は意味が通らない。", "で": "場所・手段の印。『爬虫類で変温動物』は成り立たない。"}, "error_tags": {"を": "目的語", "に": "位置・帰着", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36611, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "『爬虫類』を主題として示し、呼吸の仕方を説明する。"}, {"text": "と", "is_correct": false, "explanation": "並列の『と』。『爬虫類と肺で呼吸し』は主語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点の印。『爬虫類から肺で呼吸し』は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の印。『爬虫類へ肺で呼吸し』は文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "『爬虫類』を主題として示し、呼吸の仕方を説明する。", "と": "並列の『と』。『爬虫類と肺で呼吸し』は主語を示せない。", "から": "起点の印。『爬虫類から肺で呼吸し』は意味が通らない。", "へ": "方向の印。『爬虫類へ肺で呼吸し』は文が成り立たない。"}, "error_tags": {"と": "並列", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36611, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "うろこでおおわれ、肺で呼吸する変温動物の一群。多く「爬虫類」の形で使う。", "primary_collocate": null, "pronunciation": "はちゅう", "ipa": "hatɕɯː", "syllable_count": 3, "sentences": [{"text": "ヘビ、トカゲ、カメ、ワニは、みな爬虫類に入る。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "ヘビ、トカゲ、カメ、ワニは、みな爬虫類[はちゅうるい]に入[はい]る。", "sentence_source": "generated"}, {"text": "爬虫類は変温動物で、体温が気温に左右される。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "爬虫類[はちゅうるい]は変温動物[へんおんどうぶつ]で、体温[たいおん]が気温[きおん]に左右[さゆう]される。", "sentence_source": "generated"}, {"text": "冬になると、爬虫類は冬眠する種が多い。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、爬虫類[はちゅうるい]は冬眠[とうみん]する種[しゅ]が多[おお]い。", "sentence_source": "generated"}, {"text": "恐竜は、大昔に栄えた爬虫類の一種と考えられている。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "恐竜[きょうりゅう]は、大昔[おおむかし]に栄[さか]えた爬虫類[はちゅうるい]の一種[いっしゅ]と考[かんが]えられている。", "sentence_source": "generated"}, {"text": "この店では、珍しい爬虫類をペットとして売っている。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "この店[みせ]では、珍[めずら]しい爬虫類[はちゅうるい]をペットとして売[う]っている。", "sentence_source": "generated"}, {"text": "爬虫類の皮はじょうぶで、財布の材料にも使われる。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "爬虫類[はちゅうるい]の皮[かわ]はじょうぶで、財布[さいふ]の材料[ざいりょう]にも使[つか]われる。", "sentence_source": "generated"}, {"text": "砂漠には、暑さに強い爬虫類が多く住んでいる。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "砂漠[さばく]には、暑[あつ]さに強[つよ]い爬虫類[はちゅうるい]が多[おお]く住[す]んでいる。", "sentence_source": "generated"}, {"text": "爬虫類は肺で呼吸し、両生類とは体のつくりが違う。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "爬虫類[はちゅうるい]は肺[はい]で呼吸[こきゅう]し、両生類[りょうせいるい]とは体[からだ]のつくりが違[ちが]う。", "sentence_source": "generated"}, {"text": "研究者が、新しく見つかった爬虫類について発表した。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "研究者[けんきゅうしゃ]が、新[あたら]しく見[み]つかった爬虫類[はちゅうるい]について発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "爬虫類を飼うときは、温度の管理がとても大切だ。", "target_word": "爬虫類", "complexity_tier": "T3", "furigana": "爬虫類[はちゅうるい]を飼[か]うときは、温度[おんど]の管理[かんり]がとても大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "爬虫類", "label": "基本形（多く使われる形）"}], "register": "標準（説明的な普通体）", "sense_fingerprint": "ヘビ・トカゲ・カメ・ワニなどを含む動物の分類（爬虫類）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '100ddb14-3d80-402d-8bc8-fc2b77060f64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36611, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爬虫類", "is_correct": true, "explanation": "ヘビ・トカゲ・カメ・ワニを含む分類として、ここに入る。"}, {"text": "鳥類", "is_correct": false, "explanation": "羽のある分類で、ヘビやワニは含まれない。"}, {"text": "両生類", "is_correct": false, "explanation": "水辺で暮らす分類。カメ・ワニを含まないので合わない。"}, {"text": "哺乳類", "is_correct": false, "explanation": "乳で子を育てる分類で、ヘビ・トカゲは含まれない。"}], "explanations": {"爬虫類": "ヘビ・トカゲ・カメ・ワニを含む分類として、ここに入る。", "鳥類": "羽のある分類で、ヘビやワニは含まれない。", "両生類": "水辺で暮らす分類。カメ・ワニを含まないので合わない。", "哺乳類": "乳で子を育てる分類で、ヘビ・トカゲは含まれない。"}, "sentence_index": 0, "correct_answer": "爬虫類"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の夜、林で爬虫類が大合唱していた。", "explanation": "ここは〈虫〉の鳴き声の意味。爬虫類は動物の分類で、虫が鳴く様子には使わない。"}, {"text": "寒くて、腕に爬虫類が立った。", "explanation": "ここは〈鳥肌〉の意味。爬虫類は動物の分類で、『鳥肌が立つ』の慣用句では使わない。"}, {"text": "山頂から見ると、町が爬虫類のように見える。", "explanation": "ここは〈鳥瞰〉（空から見下ろすような見方）の意味。爬虫類は動物の分類で、見下ろす眺めを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36611, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爬虫類", "is_correct": true, "explanation": "乾燥に強い爬虫類が砂漠に住むという文脈に当てはまる。"}, {"text": "魚類", "is_correct": false, "explanation": "えらで呼吸する水中の分類で、砂漠に住む生き物とは合わない。"}, {"text": "両生類", "is_correct": false, "explanation": "水辺で暮らす分類で、乾燥した砂漠に多く住む文脈と合わない。"}, {"text": "甲殻類", "is_correct": false, "explanation": "殻を持つ水生の分類で、砂漠に住む生き物とは合わない。"}], "explanations": {"爬虫類": "乾燥に強い爬虫類が砂漠に住むという文脈に当てはまる。", "魚類": "えらで呼吸する水中の分類で、砂漠に住む生き物とは合わない。", "両生類": "水辺で暮らす分類で、乾燥した砂漠に多く住む文脈と合わない。", "甲殻類": "殻を持つ水生の分類で、砂漠に住む生き物とは合わない。"}, "sentence_index": 6, "correct_answer": "爬虫類"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窓の枠に爬虫類を塗って、ハエを捕まえた。", "explanation": "ここは〈鳥もち〉（粘着性のある捕獲用の物）の意味。爬虫類は動物の分類で、粘着剤の名前にはならない。"}, {"text": "道が爬虫類のように曲がりくねっている。", "explanation": "ここは〈蛇行〉の意味。爬虫類は動物の分類で、曲がりくねる様子を表さない。"}, {"text": "夜になると、彼は爬虫類になって何も見えなくなる。", "explanation": "ここは〈鳥目〉（夜に見えにくくなる症状）の意味。爬虫類は動物の分類で、この症状は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36611, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爬虫類を変温動物で、体温が周りの気温に左右される。", "corrected_sentence": "爬虫類は変温動物で、体温が周りの気温に左右される。", "error_description": "主題を示す『は』が正しいが、『を』（目的語の印）になっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36611, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爬虫類を肺で呼吸するが、両生類とは体のつくりが違う。", "corrected_sentence": "爬虫類は肺で呼吸するが、両生類とは体のつくりが違う。", "error_description": "主題を示す『は』が正しいが、『を』（目的語の印）になっている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf76badc-0f83-4eb7-8752-e71c6b3edd63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36612, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特殊", "is_correct": true, "explanation": "普遍の対義語。すべてに当てはまる普遍に対し、特定の場所や集団だけに見られる性質を表す。"}, {"text": "料理", "is_correct": false, "explanation": "対義語ではない。料理は食べ物を作ることで、普遍とは対になる語ではない。"}, {"text": "偶然", "is_correct": false, "explanation": "対義語ではない。偶然は思いがけず起こることで、普遍の反対とは言えない。"}, {"text": "流行", "is_correct": false, "explanation": "対義語ではない。流行は一時的に広まることで、普遍とは対になる語ではない。"}], "correct_answer": "特殊", "explanations": {"特殊": "普遍の対義語。すべてに当てはまる普遍に対し、特定の場所や集団だけに見られる性質を表す。", "料理": "対義語ではない。料理は食べ物を作ることで、普遍とは対になる語ではない。", "偶然": "対義語ではない。偶然は思いがけず起こることで、普遍の反対とは言えない。", "流行": "対義語ではない。流行は一時的に広まることで、普遍とは対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36612, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特殊", "is_correct": true, "explanation": "普遍の対義語。すべての場所に当てはまる普遍に対し、特定の場所や集団だけに見られる性質を表す。"}, {"text": "天気", "is_correct": false, "explanation": "対義語ではない。天気は空模様のことで、普遍の反対概念ではない。"}, {"text": "散歩", "is_correct": false, "explanation": "対義語ではない。散歩は外を歩くことで、普遍とは対になる語ではない。"}, {"text": "料理", "is_correct": false, "explanation": "対義語ではない。料理は食べ物を作ることで、普遍の反対概念ではない。"}], "correct_answer": "特殊", "explanations": {"特殊": "普遍の対義語。すべての場所に当てはまる普遍に対し、特定の場所や集団だけに見られる性質を表す。", "天気": "対義語ではない。天気は空模様のことで、普遍の反対概念ではない。", "散歩": "対義語ではない。散歩は外を歩くことで、普遍とは対になる語ではない。", "料理": "対義語ではない。料理は食べ物を作ることで、普遍の反対概念ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36612, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "たくさんのものに、同じようにあること。", "primary_collocate": null, "pronunciation": "ふへん", "ipa": "ɸɯheɴ", "syllable_count": 3, "sentences": [{"text": "数学の法則は、どの国でも同じように成り立つ普遍の真理だ。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "数学[すうがく]の法則[ほうそく]は、どの国[くに]でも同[おな]じように成[な]り立[た]つ普遍[ふへん]の真理[しんり]だ。", "sentence_source": "generated"}, {"text": "親が子を思う気持ちは、時代が変わっても普遍である。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "親[おや]が子[こ]を思[おも]う気持[きも]ちは、時代[じだい]が変[か]わっても普遍[ふへん]である。", "sentence_source": "generated"}, {"text": "人権は、国や民族に関係なくすべての人に認められる普遍の価値だ。", "target_word": "普遍", "complexity_tier": "T4", "furigana": "人権[じんけん]は、国[くに]や民族[みんぞく]に関係[かんけい]なくすべての人[ひと]に認[みと]められる普遍[ふへん]の価値[かち]だ。", "sentence_source": "generated"}, {"text": "この物語は、どんな国の人にも共感される普遍のテーマを描いている。", "target_word": "普遍", "complexity_tier": "T4", "furigana": "この物語[ものがたり]は、どんな国[くに]の人[ひと]にも共感[きょうかん]される普遍[ふへん]のテーマを描[えが]いている。", "sentence_source": "generated"}, {"text": "重力は地球だけでなく、宇宙のどこでも働く普遍の力である。", "target_word": "普遍", "complexity_tier": "T4", "furigana": "重力[じゅうりょく]は地球[ちきゅう]だけでなく、宇宙[うちゅう]のどこでも働[はたら]く普遍[ふへん]の力[ちから]である。", "sentence_source": "generated"}, {"text": "彼の研究は一つの例にとどまらず、あらゆる場合に当てはまる普遍の法則を見つけた。", "target_word": "普遍", "complexity_tier": "T4", "furigana": "彼[かれ]の研究[けんきゅう]は一[ひと]つの例[れい]にとどまらず、あらゆる場合[ばあい]に当[あ]てはまる普遍[ふへん]の法則[ほうそく]を見[み]つけた。", "sentence_source": "generated"}, {"text": "美しいものに心を動かされるのは、人間に普遍の感情だと言われる。", "target_word": "普遍", "complexity_tier": "T4", "furigana": "美[うつく]しいものに心[こころ]を動[うご]かされるのは、人間[にんげん]に普遍[ふへん]の感情[かんじょう]だと言[い]われる。", "sentence_source": "generated"}, {"text": "先生は、どの文化にも見られる普遍の価値観について話した。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "先生[せんせい]は、どの文化[ぶんか]にも見[み]られる普遍[ふへん]の価値観[かちかん]について話[はな]した。", "sentence_source": "generated"}, {"text": "一つの町でしか通用しないルールではなく、普遍の原則を学びたい。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "一[ひと]つの町[まち]でしか通用[つうよう]しないルールではなく、普遍[ふへん]の原則[げんそく]を学[まな]びたい。", "sentence_source": "generated"}, {"text": "家族を大切にするという考えは、世界中で普遍だと思う。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "家族[かぞく]を大切[たいせつ]にするという考[かんが]えは、世界中[せかいじゅう]で普遍[ふへん]だと思[おも]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "普遍", "label": "基本形"}, {"form": "普遍の", "label": "連体形(の)"}, {"form": "普遍だ", "label": "断定"}, {"form": "普遍である", "label": "である体"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "すべてのものに共通して当てはまること(普遍の真理・価値)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36612, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普遍", "is_correct": true, "explanation": "「どの国でも同じように成り立つ真理」という文脈に合い、どこにでも当てはまる意味の「普遍」が入る。"}, {"text": "偶然", "is_correct": false, "explanation": "「偶然の真理」は意味が通らない。偶然は思いがけず起こることで、法則とは結びつかない。"}, {"text": "流行", "is_correct": false, "explanation": "「流行の真理」は不自然。流行は一時的に広まる意味で、どの国でも成り立つ真理とは合わない。"}, {"text": "一時", "is_correct": false, "explanation": "「一時の真理」は矛盾する。一時は短い期間を表し、どの国でも成り立つ法則とは合わない。"}], "explanations": {"普遍": "「どの国でも同じように成り立つ真理」という文脈に合い、どこにでも当てはまる意味の「普遍」が入る。", "偶然": "「偶然の真理」は意味が通らない。偶然は思いがけず起こることで、法則とは結びつかない。", "流行": "「流行の真理」は不自然。流行は一時的に広まる意味で、どの国でも成り立つ真理とは合わない。", "一時": "「一時の真理」は矛盾する。一時は短い期間を表し、どの国でも成り立つ法則とは合わない。"}, "sentence_index": 0, "correct_answer": "普遍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人は普遍の趣味があって、よく一緒に出かける。", "explanation": "ここは〈共通〉の意味。普遍はどこにでも・誰にでも当てはまる性質を指すので、二人だけが持つ趣味には使わない。"}, {"text": "彼は普遍の会社員だ。", "explanation": "ここは〈普通〉（ありふれた）の意味。普遍は「どこでも当てはまる」という意味で、「ありふれている」とは言わない。"}, {"text": "このお店は普遍のお客さんにも人気がある。", "explanation": "ここは〈一般〉の意味。普遍はものごとが広く行き渡る性質を指し、客の種類を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36612, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普遍", "is_correct": true, "explanation": "人間に共通する感情についての一般論なので、どこにでも当てはまる意味の「普遍」が入る。"}, {"text": "局地", "is_correct": false, "explanation": "「人間に局地の感情」は意味が通らない。局地は限られた土地を指し、人間全般の感情には合わない。"}, {"text": "地域的", "is_correct": false, "explanation": "「地域的の感情」は不自然。地域的は地域に関わる性質で、人間に共通する感情とは結びつかない。"}, {"text": "局所", "is_correct": false, "explanation": "「局所の感情」は不自然。局所は一部分を指し、すべての人に共通する感情とは合わない。"}], "explanations": {"普遍": "人間に共通する感情についての一般論なので、どこにでも当てはまる意味の「普遍」が入る。", "局地": "「人間に局地の感情」は意味が通らない。局地は限られた土地を指し、人間全般の感情には合わない。", "地域的": "「地域的の感情」は不自然。地域的は地域に関わる性質で、人間に共通する感情とは結びつかない。", "局所": "「局所の感情」は不自然。局所は一部分を指し、すべての人に共通する感情とは合わない。"}, "sentence_index": 6, "correct_answer": "普遍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この薬は普遍の患者だけに効く。", "explanation": "ここは〈特定〉の意味。特定は決まった相手だけを指すが、普遍は「すべてに当てはまる」ことなので、「だけ」という限定と矛盾する。"}, {"text": "多くの人が、普遍の命を願っている。", "explanation": "ここは〈永遠〉の意味。永遠は時間が終わらないことを指すが、普遍は広く行き渡る性質で、時間の長さは表さない。"}, {"text": "それぞれの事情に合わせて、普遍の対応をする。", "explanation": "ここは〈個別〉の意味。個別は一つ一つ別々に扱うことで、普遍はすべてに共通する性質を指すので、事情ごとに違う対応とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36612, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この歌は、国境を越えて多くの人に響く普遍を魅力を持つ。", "corrected_sentence": "この歌は、国境を越えて多くの人に響く普遍の魅力を持つ。", "error_description": "「普遍」の直後の助詞が誤り。名詞を修飾するときは「普遍の魅力」と「の」を使う。「を」は目的語を示すので「普遍を魅力」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36612, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この習慣は世界中で普遍にある。", "corrected_sentence": "この習慣は世界中で普遍である。", "error_description": "「普遍」は「である」で述べる語。「にある」は存在を表す形で、「世界中で普遍にある」は不自然。正しくは「普遍である」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
