INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36613, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "広く行き渡っていること。どこにでもあること。", "primary_collocate": null, "pronunciation": "ふへん", "ipa": "ɸɯheɴ", "syllable_count": 3, "sentences": [{"text": "都会の駅で人々がスマートフォンを見る姿は、もはや普遍の光景だ。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "都会[とかい]の駅[えき]で人々[ひとびと]がスマートフォンを見[み]る姿[すがた]は、もはや普遍[ふへん]の光景[こうけい]だ。", "sentence_source": "generated"}, {"text": "この問題は特別な地域だけでなく、どの町にも見られる普遍の現象だ。", "target_word": "普遍", "complexity_tier": "T4", "furigana": "この問題[もんだい]は特別[とくべつ]な地域[ちいき]だけでなく、どの町[まち]にも見[み]られる普遍[ふへん]の現象[げんしょう]だ。", "sentence_source": "generated"}, {"text": "緑茶を飲む習慣は、昔の日本の家庭に普遍のものだった。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "緑茶[りょくちゃ]を飲[の]む習慣[しゅうかん]は、昔[むかし]の日本[にほん]の家庭[かてい]に普遍[ふへん]のものだった。", "sentence_source": "generated"}, {"text": "少子化は、多くの先進国に普遍の悩みとなっている。", "target_word": "普遍", "complexity_tier": "T4", "furigana": "少子化[しょうしか]は、多[おお]くの先進国[せんしんこく]に普遍[ふへん]の悩[なや]みとなっている。", "sentence_source": "generated"}, {"text": "電気のある暮らしは、都市では普遍のものになった。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "電気[でんき]のある暮[く]らしは、都市[とし]では普遍[ふへん]のものになった。", "sentence_source": "generated"}, {"text": "昔は村のどこにでも井戸があり、それは普遍の風景だった。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "昔[むかし]は村[むら]のどこにでも井戸[いど]があり、それは普遍[ふへん]の風景[ふうけい]だった。", "sentence_source": "generated"}, {"text": "この季節に風邪が流行するのは、どの学校でも起こる普遍の現象だ。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "この季節[きせつ]に風邪[かぜ]が流行[りゅうこう]するのは、どの学校[がっこう]でも起[お]こる普遍[ふへん]の現象[げんしょう]だ。", "sentence_source": "generated"}, {"text": "英語を学ぶことは、世界の学生に普遍の経験になりつつある。", "target_word": "普遍", "complexity_tier": "T4", "furigana": "英語[えいご]を学[まな]ぶことは、世界[せかい]の学生[がくせい]に普遍[ふへん]の経験[けいけん]になりつつある。", "sentence_source": "generated"}, {"text": "駅前にコンビニがあるのは、日本では普遍の姿だ。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "駅前[えきまえ]にコンビニがあるのは、日本[にほん]では普遍[ふへん]の姿[すがた]だ。", "sentence_source": "generated"}, {"text": "あいさつは、どの地域でも見られる普遍の文化だ。", "target_word": "普遍", "complexity_tier": "T3", "furigana": "あいさつは、どの地域[ちいき]でも見[み]られる普遍[ふへん]の文化[ぶんか]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "普遍", "label": "基本形"}, {"form": "普遍の", "label": "連体形(の)"}, {"form": "普遍だ", "label": "断定"}, {"form": "普遍である", "label": "である体"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "広く行き渡っていて、どこでも見られること(普遍の光景・現象)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36613, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普遍", "is_correct": true, "explanation": "駅で誰もがスマホを見る姿は、どこでも見られるという文脈。広く行き渡る意味の「普遍」が入る。"}, {"text": "局所", "is_correct": false, "explanation": "「局所の光景」は不自然。局所は一部分を指し、どこでも見られるという文脈に合わない。"}, {"text": "限定", "is_correct": false, "explanation": "「限定の光景」は文脈と逆になる。限定は範囲を絞る意味で、どこでも見られるという文脈に合わない。"}, {"text": "偶発", "is_correct": false, "explanation": "「偶発の光景」は不自然。偶発は思いがけず起こる意味で、ありふれた光景とは合わない。"}], "explanations": {"普遍": "駅で誰もがスマホを見る姿は、どこでも見られるという文脈。広く行き渡る意味の「普遍」が入る。", "局所": "「局所の光景」は不自然。局所は一部分を指し、どこでも見られるという文脈に合わない。", "限定": "「限定の光景」は文脈と逆になる。限定は範囲を絞る意味で、どこでも見られるという文脈に合わない。", "偶発": "「偶発の光景」は不自然。偶発は思いがけず起こる意味で、ありふれた光景とは合わない。"}, "sentence_index": 0, "correct_answer": "普遍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この制度は普遍の人にはまだ知られていない。", "explanation": "ここは〈一般〉の意味。普遍は人の範囲を表す語ではなく、ものごとが広く行き渡る性質を指す。"}, {"text": "この動物は、この地域にしか見られない普遍の習性を持つ。", "explanation": "ここは〈特有〉の意味。特有はその場所・そのものだけに見られることで、どこにでもある普遍とは逆になる。"}, {"text": "普遍の学生がこの案に賛成した。", "explanation": "ここは〈大多数〉の意味。普遍は人数の多さではなく、どこにでも当てはまる性質を指すので、人数の話には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36613, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普遍", "is_correct": true, "explanation": "風邪がどの学校でも起こるという一般的な話なので、広く行き渡る意味の「普遍」が入る。"}, {"text": "偶然", "is_correct": false, "explanation": "「偶然の現象」は、どの学校でも起こるという文脈と矛盾する。偶然は思いがけず起こることを指す。"}, {"text": "一時", "is_correct": false, "explanation": "「一時の現象」は、どの学校でも起こるという文脈と矛盾する。一時は短い期間を表す。"}, {"text": "局地", "is_correct": false, "explanation": "「局地の現象」は限られた地域の話で、どの学校でも起こるという文脈と矛盾する。"}], "explanations": {"普遍": "風邪がどの学校でも起こるという一般的な話なので、広く行き渡る意味の「普遍」が入る。", "偶然": "「偶然の現象」は、どの学校でも起こるという文脈と矛盾する。偶然は思いがけず起こることを指す。", "一時": "「一時の現象」は、どの学校でも起こるという文脈と矛盾する。一時は短い期間を表す。", "局地": "「局地の現象」は限られた地域の話で、どの学校でも起こるという文脈と矛盾する。"}, "sentence_index": 6, "correct_answer": "普遍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この花は普遍で、山の奥にしか咲かない。", "explanation": "ここは〈希少〉の意味。希少は数が少ないことで、どこでも見られるという普遍とは逆になる。"}, {"text": "これは私の普遍の意見にすぎない。", "explanation": "ここは〈個人的〉の意味。普遍は誰にでも当てはまる性質で、私一人の考えを表す文脈には合わない。"}, {"text": "スマートフォンの普遍が急速に進んだ。", "explanation": "ここは〈普及〉の意味。普及は広まっていく過程を指し「普及が進む」と言うが、普遍は広く行き渡っている状態を指すので、過程を表す名詞としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36613, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この習慣は、どの町でも見られる普遍を姿だ。", "corrected_sentence": "この習慣は、どの町でも見られる普遍の姿だ。", "error_description": "「普遍」に続く助詞が誤り。名詞を修飾するには「の」を使い「普遍の姿」とする。「を」は目的語を示すので「普遍を姿」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36613, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この習慣は、世界中で普遍をものになっている。", "corrected_sentence": "この習慣は、世界中で普遍のものになっている。", "error_description": "「普遍」に続く助詞が誤り。「ものになる」は「普遍の」で名詞を修飾する形が必要。「を」は目的語を示すので「普遍をものになっている」は不自然。「の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36614, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36614, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「保存には〜がかかる」の形で、保存という行為を話題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「保存を」は目的語を示すが、後ろの「多くのお金がかかる」とつながらず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「保存が」は主語を示すが、後ろの「は」と重なり、文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「保存の」は連体修飾で、続く名詞がないため「は」と続けると文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "正解。「保存には〜がかかる」の形で、保存という行為を話題として示す。", "を": "「保存を」は目的語を示すが、後ろの「多くのお金がかかる」とつながらず、文が成り立たない。", "が": "「保存が」は主語を示すが、後ろの「は」と重なり、文が成立しない。", "の": "「保存の」は連体修飾で、続く名詞がないため「は」と続けると文が成立しない。"}, "error_tags": {"を": "object", "が": "subject", "の": "genitive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36614, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ずっと同じままにしておくこと。", "primary_collocate": null, "pronunciation": "ほぞん", "ipa": "hozoɴ", "syllable_count": 3, "sentences": [{"text": "町の人たちは、百年前の駅舎をそのまま保存することに決めた。", "target_word": "保存", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]たちは、百年前[ひゃくねんまえ]の駅舎[えきしゃ]をそのまま保存[ほぞん]することに決[き]めた。", "sentence_source": "generated"}, {"text": "古い手紙を、箱に入れて大切に保存している。", "target_word": "保存", "complexity_tier": "T2", "furigana": "古[ふる]い手紙[てがみ]を、箱[はこ]に入[い]れて大切[たいせつ]に保存[ほぞん]している。", "sentence_source": "generated"}, {"text": "昔の言葉を保存するため、お年寄りの話を録音している。", "target_word": "保存", "complexity_tier": "T3", "furigana": "昔[むかし]の言葉[ことば]を保存[ほぞん]するため、お年寄[としよ]りの話[はなし]を録音[ろくおん]している。", "sentence_source": "generated"}, {"text": "貴重な遺跡は、壊さずに保存しなければならない。", "target_word": "保存", "complexity_tier": "T3", "furigana": "貴重[きちょう]な遺跡[いせき]は、壊[こわ]さずに保存[ほぞん]しなければならない。", "sentence_source": "generated"}, {"text": "祖父は、戦争中の日記を今も保存している。", "target_word": "保存", "complexity_tier": "T3", "furigana": "祖父[そふ]は、戦争中[せんそうちゅう]の日記[にっき]を今[いま]も保存[ほぞん]している。", "sentence_source": "generated"}, {"text": "伝統の祭りを保存する会が、毎年集まりを開いている。", "target_word": "保存", "complexity_tier": "T3", "furigana": "伝統[でんとう]の祭[まつ]りを保存[ほぞん]する会[かい]が、毎年[まいとし]集[あつ]まりを開[ひら]いている。", "sentence_source": "generated"}, {"text": "自然の森を保存するために、開発の計画は中止された。", "target_word": "保存", "complexity_tier": "T3", "furigana": "自然[しぜん]の森[もり]を保存[ほぞん]するために、開発[かいはつ]の計画[けいかく]は中止[ちゅうし]された。", "sentence_source": "generated"}, {"text": "古い建物の保存には、多くのお金がかかる。", "target_word": "保存", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]の保存[ほぞん]には、多[おお]くのお金[かね]がかかる。", "sentence_source": "generated"}, {"text": "この資料は、将来のために永久に保存される予定だ。", "target_word": "保存", "complexity_tier": "T3", "furigana": "この資料[しりょう]は、将来[しょうらい]のために永久[えいきゅう]に保存[ほぞん]される予定[よてい]だ。", "sentence_source": "generated"}, {"text": "村の景色を保存したいという声が、住民の間で高まった。", "target_word": "保存", "complexity_tier": "T3", "furigana": "村[むら]の景色[けしき]を保存[ほぞん]したいという声[こえ]が、住民[じゅうみん]の間[あいだ]で高[たか]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "保存する", "label": "基本形"}, {"form": "保存した", "label": "過去形"}, {"form": "保存して", "label": "て形"}, {"form": "保存される", "label": "受身形"}], "register": "中立", "sense_fingerprint": "建物・資料・文化などを壊さず長く同じ状態で残す保存", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36614, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保存", "is_correct": true, "explanation": "正解。駅舎を壊さずに同じ状態で残す意味で、「そのまま保存する」と文が通る。"}, {"text": "改築", "is_correct": false, "explanation": "〈改築〉は建物を建て直すこと。「そのまま改築する」は矛盾し、そのままの状態で残す文脈に合わない。"}, {"text": "撤去", "is_correct": false, "explanation": "〈撤去〉は取り払うこと。「そのまま撤去する」は矛盾し、残す決定の文には入らない。"}, {"text": "解体", "is_correct": false, "explanation": "〈解体〉は建物を壊して分けること。「そのまま解体する」は矛盾し、残すという文の流れに合わない。"}], "explanations": {"保存": "正解。駅舎を壊さずに同じ状態で残す意味で、「そのまま保存する」と文が通る。", "改築": "〈改築〉は建物を建て直すこと。「そのまま改築する」は矛盾し、そのままの状態で残す文脈に合わない。", "撤去": "〈撤去〉は取り払うこと。「そのまま撤去する」は矛盾し、残す決定の文には入らない。", "解体": "〈解体〉は建物を壊して分けること。「そのまま解体する」は矛盾し、残すという文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "保存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭の花を、保存して育てた。", "explanation": "ここは〈栽培〉の意味。〈保存〉は既にある物を変えずに残す意味で、生き物を育てる場面には使えない。"}, {"text": "新しい機械を、工場で大量に製造した。", "explanation": "ここは〈製造〉の意味。〈保存〉は既にある物を残す意味で、新たに作る場面には使えない。"}, {"text": "古いパソコンを、廃棄して処分した。", "explanation": "ここは〈廃棄〉の意味。〈保存〉は物を残す意味で、捨てる場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36614, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保存", "is_correct": true, "explanation": "正解。自然の森を壊さず残す意味で、「保存するために」と文が通る。"}, {"text": "演奏", "is_correct": false, "explanation": "〈演奏〉は音楽を奏でること。「自然の森を演奏するために」は成立しない。"}, {"text": "印刷", "is_correct": false, "explanation": "〈印刷〉は文字や図を紙に写すこと。「自然の森を印刷するために」は意味が通らない。"}, {"text": "飛行", "is_correct": false, "explanation": "〈飛行〉は空を飛ぶこと。「自然の森を飛行するために」は成立しない。"}], "explanations": {"保存": "正解。自然の森を壊さず残す意味で、「保存するために」と文が通る。", "演奏": "〈演奏〉は音楽を奏でること。「自然の森を演奏するために」は成立しない。", "印刷": "〈印刷〉は文字や図を紙に写すこと。「自然の森を印刷するために」は意味が通らない。", "飛行": "〈飛行〉は空を飛ぶこと。「自然の森を飛行するために」は成立しない。"}, "sentence_index": 6, "correct_answer": "保存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨でイベントを保存した。", "explanation": "ここは〈中止〉の意味。〈保存〉は建物や資料を残す意味で、行事を取りやめる場面には使えない。"}, {"text": "畑の野菜を、保存して大量に生産した。", "explanation": "ここは〈生産〉の意味。〈保存〉は既にある物を残す意味で、新しく作り出す場面には使えない。"}, {"text": "古い新聞を、まとめてごみに出した。", "explanation": "ここは〈廃棄〉の意味。〈保存〉は物を残す意味で、ごみとして出す場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36614, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この古い寺が、市は文化財として保存している。", "corrected_sentence": "この古い寺を、市は文化財として保存している。", "error_description": "「保存している」の対象は「寺を」で示す。「寺が」は主語になり、保存する人の対象として成立しないので、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36614, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "記録は、市の資料館で保存られている。", "corrected_sentence": "記録は、市の資料館で保存されている。", "error_description": "「保存」は「保存する」の受け身「保存される」で用いる。「保存られている」は誤った形で、正しくは「保存されている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36615, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36615, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「保存には〜が大切だ」の形で、保存という行為を話題として示す。"}, {"text": "を", "is_correct": false, "explanation": "「保存を」は目的語を示すが、後ろの「温度の管理が大切だ」とつながらず、主語と述語が対応しない。"}, {"text": "が", "is_correct": false, "explanation": "「保存が」は主語を示すが、後ろの「は」と重なり、文が成立しない。"}, {"text": "の", "is_correct": false, "explanation": "「保存の」は連体修飾で、続く名詞がないため「は」と続けると文が成立しない。"}], "correct_answer": "に", "explanations": {"に": "正解。「保存には〜が大切だ」の形で、保存という行為を話題として示す。", "を": "「保存を」は目的語を示すが、後ろの「温度の管理が大切だ」とつながらず、主語と述語が対応しない。", "が": "「保存が」は主語を示すが、後ろの「は」と重なり、文が成立しない。", "の": "「保存の」は連体修飾で、続く名詞がないため「は」と続けると文が成立しない。"}, "error_tags": {"を": "object", "が": "subject", "の": "genitive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36615, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物や状態を、そのままの形で変えずに保つこと。", "primary_collocate": null, "pronunciation": "ほぞん", "ipa": "hozoɴ", "syllable_count": 3, "sentences": [{"text": "微生物の代謝作用である発酵は、単なる保存技法の域を超え、主食の持つ潜在能力を飛躍的に拡張する化学的芸術である。", "target_word": "保存", "complexity_tier": "T4", "furigana": "微生物[びせいぶつ]の代謝作用[たいしゃさよう]である発酵[はっこう]は、単[たん]なる保存技法[ほぞんぎほう]の域[いき]を超[こ]え、主食[しゅしょく]の持[も]つ潜在能力[せんざいのうりょく]を飛躍的[ひやくてき]に拡張[かくちょう]する化学的芸術[かがくてきげいじゅつ]である。", "sentence_source": "mined"}, {"text": "肉は冷凍すれば、味を変えずに長く保存できる。", "target_word": "保存", "complexity_tier": "T3", "furigana": "肉[にく]は冷凍[れいとう]すれば、味[あじ]を変[か]えずに長[なが]く保存[ほぞん]できる。", "sentence_source": "generated"}, {"text": "この缶詰は、常温で三年間保存することができる。", "target_word": "保存", "complexity_tier": "T3", "furigana": "この缶詰[かんづめ]は、常温[じょうおん]で三年間[さんねんかん]保存[ほぞん]することができる。", "sentence_source": "generated"}, {"text": "古い写真は、日光の当たらない場所に保存してください。", "target_word": "保存", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]は、日光[にっこう]の当[あ]たらない場所[ばしょ]に保存[ほぞん]してください。", "sentence_source": "generated"}, {"text": "博物館では、湿度を一定にして貴重な絵を保存している。", "target_word": "保存", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、湿度[しつど]を一定[いってい]にして貴重[きちょう]な絵[え]を保存[ほぞん]している。", "sentence_source": "generated"}, {"text": "開封後は冷蔵庫で保存し、早めにお召し上がりください。", "target_word": "保存", "complexity_tier": "T3", "furigana": "開封後[かいふうご]は冷蔵庫[れいぞうこ]で保存[ほぞん]し、早[はや]めにお召[め]し上[あ]がりください。", "sentence_source": "generated"}, {"text": "昔の人は、塩を使って魚を保存した。", "target_word": "保存", "complexity_tier": "T2", "furigana": "昔[むかし]の人[ひと]は、塩[しお]を使[つか]って魚[さかな]を保存[ほぞん]した。", "sentence_source": "generated"}, {"text": "食品の保存には、温度の管理が大切だ。", "target_word": "保存", "complexity_tier": "T3", "furigana": "食品[しょくひん]の保存[ほぞん]には、温度[おんど]の管理[かんり]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "果物の保存がうまくいかず、箱の中で腐ってしまった。", "target_word": "保存", "complexity_tier": "T3", "furigana": "果物[くだもの]の保存[ほぞん]がうまくいかず、箱[はこ]の中[なか]で腐[くさ]ってしまった。", "sentence_source": "generated"}, {"text": "瓶に入れて保存すれば、梅干しは何年ももつ。", "target_word": "保存", "complexity_tier": "T3", "furigana": "瓶[びん]に入[い]れて保存[ほぞん]すれば、梅干[うめぼ]しは何年[なんねん]ももつ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "保存する", "label": "基本形"}, {"form": "保存した", "label": "過去形"}, {"form": "保存して", "label": "て形"}, {"form": "保存される", "label": "受身形"}], "register": "中立", "sense_fingerprint": "食品や物を傷めず元の状態のまま保つ、サ変名詞の保存", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cadf245-b057-4a4f-80e4-458d2df7fe35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36615, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保存", "is_correct": true, "explanation": "正解。「単なる保存技法」の〈保存〉で、食品などを変えずに保つ技術を指し、文が通る。"}, {"text": "腐敗", "is_correct": false, "explanation": "〈腐敗〉は食品が傷んで悪くなること。「単なる腐敗技法」は、保つことと逆の意味になり成立しない。"}, {"text": "窒息", "is_correct": false, "explanation": "〈窒息〉は呼吸ができなくなること。「単なる窒息技法」は意味が通らない。"}, {"text": "散策", "is_correct": false, "explanation": "〈散策〉は気ままに歩くこと。「単なる散策技法」は文脈に合わない。"}], "explanations": {"保存": "正解。「単なる保存技法」の〈保存〉で、食品などを変えずに保つ技術を指し、文が通る。", "腐敗": "〈腐敗〉は食品が傷んで悪くなること。「単なる腐敗技法」は、保つことと逆の意味になり成立しない。", "窒息": "〈窒息〉は呼吸ができなくなること。「単なる窒息技法」は意味が通らない。", "散策": "〈散策〉は気ままに歩くこと。「単なる散策技法」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "保存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古いタイヤを、新品に保存した。", "explanation": "ここは〈交換〉の意味。〈保存〉は物を変えずに残す意味で、別の物に替える場面には使えない。"}, {"text": "毎日の運動で、体重を大きく増やした。", "explanation": "ここは〈増加〉の意味。〈保存〉は物を変えずに残す意味で、数値を増やす場面には使えない。"}, {"text": "古い看板を、新しい看板に取り替えた。", "explanation": "ここは〈交換〉の意味。〈保存〉は残す意味で、別の物に替える場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36615, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保存", "is_correct": true, "explanation": "正解。塩を使って魚を傷めず残す意味で、「魚を保存した」と自然につながる。"}, {"text": "演奏", "is_correct": false, "explanation": "〈演奏〉は楽器などで音楽を奏でること。「魚を演奏した」は成立しない。"}, {"text": "洗濯", "is_correct": false, "explanation": "〈洗濯〉は衣類などを洗うこと。「魚を洗濯した」は意味が通らない。"}, {"text": "散髪", "is_correct": false, "explanation": "〈散髪〉は髪を切ること。「魚を散髪した」は成立しない。"}], "explanations": {"保存": "正解。塩を使って魚を傷めず残す意味で、「魚を保存した」と自然につながる。", "演奏": "〈演奏〉は楽器などで音楽を奏でること。「魚を演奏した」は成立しない。", "洗濯": "〈洗濯〉は衣類などを洗うこと。「魚を洗濯した」は意味が通らない。", "散髪": "〈散髪〉は髪を切ること。「魚を散髪した」は成立しない。"}, "sentence_index": 6, "correct_answer": "保存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨でイベントを保存した。", "explanation": "ここは〈中止〉の意味。〈保存〉は物や食品を残す意味で、行事を取りやめる場面には使えない。"}, {"text": "白い布を、保存して赤く染めた。", "explanation": "ここは〈染色〉の意味。〈保存〉は物を変えずに残す意味で、色を変える場面には使えない。"}, {"text": "古い雑誌を、まとめて処分した。", "explanation": "ここは〈廃棄〉の意味。〈保存〉は物を残す意味で、処分する場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36615, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このジャムは、冷暗所で保存られる。", "corrected_sentence": "このジャムは、冷暗所で保存できる。", "error_description": "「保存できる」が正しい。「保存」に続けて「られる」を付けた形は誤りで、可能の形は「できる」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36615, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大切な写真が、データにして保存しておこう。", "corrected_sentence": "大切な写真を、データにして保存しておこう。", "error_description": "「保存する」は「〜を保存する」と対象を「を」で示す。「写真が」は主語になり、保存する行為の対象として成立しないので、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5fa85734-4702-4ee4-8b6d-fd6e1534aa8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36616, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「では」の「で」。「一説では」の形で話の出どころを示している。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞。「一説」は動作の対象ではないので合わない。"}, {"text": "や", "is_correct": false, "explanation": "並列を示す助詞。「一説や」の後に「は」は続かず、文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「一説へは」は意味が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「では」の「で」。「一説では」の形で話の出どころを示している。", "を": "目的語を示す助詞。「一説」は動作の対象ではないので合わない。", "や": "並列を示す助詞。「一説や」の後に「は」は続かず、文として成り立たない。", "へ": "方向を示す助詞。「一説へは」は意味が成り立たない。"}, "error_tags": {"を": "対象", "が": "主語", "や": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36616, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「として」の「と」。一説を〈〜として〉位置づけている。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞。「一説がして」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「一説へして」は文として成り立たない。"}, {"text": "や", "is_correct": false, "explanation": "並列を示す助詞。「一説やして」は文として成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「として」の「と」。一説を〈〜として〉位置づけている。", "が": "主語を示す助詞。「一説がして」は文として成り立たない。", "へ": "方向を示す助詞。「一説へして」は文として成り立たない。", "や": "並列を示す助詞。「一説やして」は文として成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "や": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36616, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある考えについて、人によって意見がちがうときに使う言葉です。", "primary_collocate": null, "pronunciation": "いっせつ", "ipa": "isːetsɯ", "syllable_count": 4, "sentences": [{"text": "一説によると、この寺は千年前に建てられたそうだ。", "target_word": "一説", "complexity_tier": "T3", "furigana": "一説[いっせつ]によると、この寺[てら]は千年前[せんねんまえ]に建[た]てられたそうだ。", "sentence_source": "generated"}, {"text": "一説では、その名前は昔の王から来ているという。", "target_word": "一説", "complexity_tier": "T3", "furigana": "一説[いっせつ]では、その名前[なまえ]は昔[むかし]の王[おう]から来[き]ているという。", "sentence_source": "generated"}, {"text": "一説には、彼は海外で生きているともいわれる。", "target_word": "一説", "complexity_tier": "T3", "furigana": "一説[いっせつ]には、彼[かれ]は海外[かいがい]で生[い]きているともいわれる。", "sentence_source": "generated"}, {"text": "これはあくまで一説で、確かな証拠はない。", "target_word": "一説", "complexity_tier": "T3", "furigana": "これはあくまで一説[いっせつ]で、確[たし]かな証拠[しょうこ]はない。", "sentence_source": "generated"}, {"text": "一説によれば、この祭りは雨ごいから始まったらしい。", "target_word": "一説", "complexity_tier": "T3", "furigana": "一説[いっせつ]によれば、この祭[まつ]りは雨[あま]ごいから始[はじ]まったらしい。", "sentence_source": "generated"}, {"text": "一説では、猫は昔、船に乗って日本へ来たそうだ。", "target_word": "一説", "complexity_tier": "T3", "furigana": "一説[いっせつ]では、猫[ねこ]は昔[むかし]、船[ふね]に乗[の]って日本[にほん]へ来[き]たそうだ。", "sentence_source": "generated"}, {"text": "この話は一説として、今も語られている。", "target_word": "一説", "complexity_tier": "T3", "furigana": "この話[はなし]は一説[いっせつ]として、今[いま]も語[かた]られている。", "sentence_source": "generated"}, {"text": "歴史の本には、一説としていくつかの考えが書かれている。", "target_word": "一説", "complexity_tier": "T3", "furigana": "歴史[れきし]の本[ほん]には、一説[いっせつ]としていくつかの考[かんが]えが書[か]かれている。", "sentence_source": "generated"}, {"text": "一説によると、あの城の下に宝が眠っている。", "target_word": "一説", "complexity_tier": "T3", "furigana": "一説[いっせつ]によると、あの城[しろ]の下[した]に宝[たから]が眠[ねむ]っている。", "sentence_source": "generated"}, {"text": "人によって意見が違うので、これも一説にすぎない。", "target_word": "一説", "complexity_tier": "T3", "furigana": "人[ひと]によって意見[いけん]が違[ちが]うので、これも一説[いっせつ]にすぎない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一説", "label": "基本形"}], "register": "やや硬い普通体", "sense_fingerprint": "意見が分かれるときの、そのうちの一つの説", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0df666cf-660e-4a65-8685-1c7e60c94a22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36616, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一説", "is_correct": true, "explanation": "「一説によると」の形で、ある説を紹介する語として文が成り立つ。"}, {"text": "一歩", "is_correct": false, "explanation": "歩みの単位を表す語で、「によると」に続けて説を示すことはできない。"}, {"text": "一人", "is_correct": false, "explanation": "人数を表す語で、情報の出どころを示す文脈には合わない。"}, {"text": "一年", "is_correct": false, "explanation": "期間を表す語で、「によると」に続けると文が成り立たない。"}], "explanations": {"一説": "「一説によると」の形で、ある説を紹介する語として文が成り立つ。", "一歩": "歩みの単位を表す語で、「によると」に続けて説を示すことはできない。", "一人": "人数を表す語で、情報の出どころを示す文脈には合わない。", "一年": "期間を表す語で、「によると」に続けると文が成り立たない。"}, "sentence_index": 0, "correct_answer": "一説"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この映画を一説で言えば、感動作だ。", "explanation": "ここは〈一言〉（短い言葉で言い表す）の意味。〈一説〉は意見の一つという意味なので、短く要約する場面には合わない。"}, {"text": "この説は今では誰もが認める一説になっている。", "explanation": "ここは〈定説（確立した説）〉の意味。〈一説〉は確かでない一部の説なので、誰もが認める説の代わりにはならない。"}, {"text": "この本の一説を選んで、みんなの前で読んだ。", "explanation": "ここは〈一節〉（文章の一部分）の意味。〈一説〉は意見の一つという意味なので、本の一部を指す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36616, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一説", "is_correct": true, "explanation": "「この話は一説として、今も語られている」と続き、一部で言われる説として文が成り立つ。"}, {"text": "一晩", "is_correct": false, "explanation": "夜の時間を表す語で、「として」に続けると文が成り立たない。"}, {"text": "一日", "is_correct": false, "explanation": "期間を表す語で、「この話は〜として」の形には合わない。"}, {"text": "一回", "is_correct": false, "explanation": "回数を表す語で、話の位置づけを示す文脈には合わない。"}], "explanations": {"一説": "「この話は一説として、今も語られている」と続き、一部で言われる説として文が成り立つ。", "一晩": "夜の時間を表す語で、「として」に続けると文が成り立たない。", "一日": "期間を表す語で、「この話は〜として」の形には合わない。", "一回": "回数を表す語で、話の位置づけを示す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "一説"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その本の一説を朗読したら、会場が静かになった。", "explanation": "ここは〈一節〉（文章の一部分）の意味。〈一説〉は意見の一つという意味なので、本の一部を指す場面には合わない。"}, {"text": "その戦いの記録は一説として確認されている。", "explanation": "ここは〈史実（確かな事実）〉の意味。〈一説〉は根拠の確かでない説なので、〈確認されている〉とは合わない。"}, {"text": "市の一説として、新しい計画が発表された。", "explanation": "ここは〈公式見解〉（組織が正式に示した見解）の意味。〈一説〉は一部で言われる説なので、正式な発表の場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36616, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一説が、その寺は火事で焼けたらしい。", "corrected_sentence": "一説では、その寺は火事で焼けたらしい。", "error_description": "「一説では」の形で話の出どころを示す。「一説が」は主語を示す形になり不自然なので、正しくは「一説では」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36616, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この昔話は一説の、今も語られている。", "corrected_sentence": "この昔話は一説として、今も語られている。", "error_description": "「一説として」の形で位置づけを示す。「一説の」では助詞が合わず不自然なので、正しくは「一説として」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5af064-3ff8-4b14-9bb3-e416536b569f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36618, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「役割を持つ」の「を」は、持つ対象の役割を目的語として示す。"}, {"text": "が", "is_correct": false, "explanation": "「役割が持っている」では役割が主語になり、持つ主体が分からない。ここは人が役割を持つ文。"}, {"text": "に", "is_correct": false, "explanation": "「役割に持っている」は持つ対象を示す格として不自然。役割は目的語として持つ。"}, {"text": "と", "is_correct": false, "explanation": "「役割と持っている」は共同や引用の意味になり、文の意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「役割を持つ」の「を」は、持つ対象の役割を目的語として示す。", "が": "「役割が持っている」では役割が主語になり、持つ主体が分からない。ここは人が役割を持つ文。", "に": "「役割に持っている」は持つ対象を示す格として不自然。役割は目的語として持つ。", "と": "「役割と持っている」は共同や引用の意味になり、文の意味が通らない。"}, "error_tags": {"が": "主格（主語）", "に": "方向・相手", "と": "共同・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36618, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「役割をしている」の「を」は、役割を目的語として示す。"}, {"text": "へ", "is_correct": false, "explanation": "「役割へしている」は方向を示す格で、ここでは意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「役割からしている」は起点を示す格で、文の意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「役割よりしている」は比較の格で、比べる対象がなく不自然。"}], "correct_answer": "を", "explanations": {"を": "「役割をしている」の「を」は、役割を目的語として示す。", "へ": "「役割へしている」は方向を示す格で、ここでは意味が通らない。", "から": "「役割からしている」は起点を示す格で、文の意味が通らない。", "より": "「役割よりしている」は比較の格で、比べる対象がなく不自然。"}, "error_tags": {"へ": "方向・目的地", "から": "起点・由来", "より": "比較・基準"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36618, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするための、自分に決められた仕事。", "primary_collocate": null, "pronunciation": "やくわり", "ipa": "jakɯwaɾi", "syllable_count": 4, "sentences": [{"text": "学級委員の役割は、クラスの意見をまとめることだ。", "target_word": "役割", "complexity_tier": "T2", "furigana": "学級委員[がっきゅういいん]の役割[やくわり]は、クラスの意見[いけん]をまとめることだ。", "sentence_source": "generated"}, {"text": "家族の中で、それぞれが自分の役割を持っている。", "target_word": "役割", "complexity_tier": "T2", "furigana": "家族[かぞく]の中[なか]で、それぞれが自分[じぶん]の役割[やくわり]を持[も]っている。", "sentence_source": "generated"}, {"text": "駅員の役割は、乗客の安全を守ることだ。", "target_word": "役割", "complexity_tier": "T3", "furigana": "駅員[えきいん]の役割[やくわり]は、乗客[じょうきゃく]の安全[あんぜん]を守[まも]ることだ。", "sentence_source": "generated"}, {"text": "新しいメンバーは、まず自分の役割を理解する必要がある。", "target_word": "役割", "complexity_tier": "T3", "furigana": "新[あたら]しいメンバーは、まず自分[じぶん]の役割[やくわり]を理解[りかい]する必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "この委員会では、新しく入った会員にも役割が割り当てられる。", "target_word": "役割", "complexity_tier": "T3", "furigana": "この委員会[いいんかい]では、新[あたら]しく入[はい]った会員[かいいん]にも役割[やくわり]が割り当[わりあ]てられる。", "sentence_source": "generated"}, {"text": "会議では、司会者が話を進める役割を担う。", "target_word": "役割", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、司会者[しかいしゃ]が話[はなし]を進[すす]める役割[やくわり]を担[にな]う。", "sentence_source": "generated"}, {"text": "兄は家事をする役割を決められていて、毎晩皿を洗う。", "target_word": "役割", "complexity_tier": "T3", "furigana": "兄[あに]は家事[かじ]をする役割[やくわり]を決[き]められていて、毎晩[まいばん]皿[さら]を洗[あら]う。", "sentence_source": "generated"}, {"text": "彼女はチームの中で、みんなをつなぐ役割をしている。", "target_word": "役割", "complexity_tier": "T2", "furigana": "彼女[かのじょ]はチームの中[なか]で、みんなをつなぐ役割[やくわり]をしている。", "sentence_source": "generated"}, {"text": "自分の役割がわからなくて、何をすればいいか迷った。", "target_word": "役割", "complexity_tier": "T3", "furigana": "自分[じぶん]の役割[やくわり]がわからなくて、何[なに]をすればいいか迷[まよ]った。", "sentence_source": "generated"}, {"text": "この劇では、一人ひとりに役割が決められている。", "target_word": "役割", "complexity_tier": "T3", "furigana": "この劇[げき]では、一人一人[ひとりひとり]に役割[やくわり]が決[き]められている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "役割", "label": "基本形"}, {"form": "役割を", "label": "目的語(を)"}, {"form": "役割が", "label": "主語(が)"}, {"form": "役割は", "label": "主題(は)"}], "register": "中立", "sense_fingerprint": "集団やしくみの中で、その人やものが受け持つ務め", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36618, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "役割", "is_correct": true, "explanation": "学級委員が受け持つ務めを説明する文なので、割り当てられた務めを表す「役割」が入る。"}, {"text": "教科", "is_correct": false, "explanation": "「学級委員の教科は」は不自然。教科は授業の科目で、学級委員の務めとは結びつかない。"}, {"text": "制服", "is_correct": false, "explanation": "「学級委員の制服は」は文脈に合わない。制服は着る服を指し、務めの内容を表さない。"}, {"text": "教室", "is_correct": false, "explanation": "「学級委員の教室は」は意味が通らない。教室は場所で、務めの内容を表す語ではない。"}], "explanations": {"役割": "学級委員が受け持つ務めを説明する文なので、割り当てられた務めを表す「役割」が入る。", "教科": "「学級委員の教科は」は不自然。教科は授業の科目で、学級委員の務めとは結びつかない。", "制服": "「学級委員の制服は」は文脈に合わない。制服は着る服を指し、務めの内容を表さない。", "教室": "「学級委員の教室は」は意味が通らない。教室は場所で、務めの内容を表す語ではない。"}, "sentence_index": 0, "correct_answer": "役割"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は料理の役割がとても上手だ。", "explanation": "ここは〈技術〉（腕前）の意味。技術は腕前そのものを指すので「上手だ」と言えるが、役割は任された務めのことで、腕前の良し悪しは表さない。"}, {"text": "この本は受験勉強の役割に立つ。", "explanation": "ここは〈役に立つ〉の意味。「役に立つ」は「役に」の形で使い、「役割に立つ」とは言わない。"}, {"text": "彼女は今、難しい役割にある。", "explanation": "ここは〈立場〉の意味。立場は置かれた状況を指し「立場にある」と言う。役割は務めを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36618, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "役割", "is_correct": true, "explanation": "家事をする務めを割り当てられたという文なので、割り当てられた務めを表す「役割」が入る。"}, {"text": "天気", "is_correct": false, "explanation": "「家事をする天気を決められて」は意味が通らない。天気は務めの対象にならない。"}, {"text": "寝室", "is_correct": false, "explanation": "「家事をする寝室を決められて」は不自然。寝室は寝る部屋で、務めとは結びつかない。"}, {"text": "歌詞", "is_correct": false, "explanation": "「家事をする歌詞」は意味が通らない。歌詞は歌の言葉で、家事の務めとは合わない。"}], "explanations": {"役割": "家事をする務めを割り当てられたという文なので、割り当てられた務めを表す「役割」が入る。", "天気": "「家事をする天気を決められて」は意味が通らない。天気は務めの対象にならない。", "寝室": "「家事をする寝室を決められて」は不自然。寝室は寝る部屋で、務めとは結びつかない。", "歌詞": "「家事をする歌詞」は意味が通らない。歌詞は歌の言葉で、家事の務めとは合わない。"}, "sentence_index": 6, "correct_answer": "役割"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、その答えが役割だと言った。", "explanation": "ここは〈正解〉の意味。役割は割り当てられた務めのことで、答えが正しいことは表さない。"}, {"text": "このワンピースの役割は白だ。", "explanation": "ここは〈色〉の意味。役割は務めを指す語で、服の色を表す語ではない。"}, {"text": "このバッグの役割は三万円だ。", "explanation": "ここは〈値段〉の意味。役割は任された務めのことで、金額を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36618, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新人は、まず自分の役割に覚えることが大切だ。", "corrected_sentence": "新人は、まず自分の役割を覚えることが大切だ。", "error_description": "「覚える」の対象は「を」で示す。「役割に覚える」は助詞が誤りで、正しくは「役割を覚える」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36618, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、チームの中で大事な役割りを担っている。", "corrected_sentence": "彼は、チームの中で大事な役割を担っている。", "error_description": "「役割」は送り仮名を付けない語。「役割り」は誤った表記で、正しくは「役割」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
