INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36622, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "体を動かしたり、何かをしたりすること。", "primary_collocate": null, "pronunciation": "かつどう", "ipa": "katsɯdoː", "syllable_count": 4, "sentences": [{"text": "朝ごはんを食べないと、午前中の活動に力が出ない。", "target_word": "活動", "complexity_tier": "T3", "furigana": "朝[あさ]ごはんを食[た]べないと、午前中[ごぜんちゅう]の活動[かつどう]に力[ちから]が出[で]ない。", "sentence_source": "generated"}, {"text": "体が冷えると、活動するための力が出にくい。", "target_word": "活動", "complexity_tier": "T3", "furigana": "体[からだ]が冷[ひ]えると、活動[かつどう]するための力[ちから]が出[で]にくい。", "sentence_source": "generated"}, {"text": "長い活動のあとは、しっかり休んで力を取りもどす。", "target_word": "活動", "complexity_tier": "T3", "furigana": "長[なが]い活動[かつどう]のあとは、しっかり休[やす]んで力[ちから]を取[と]りもどす。", "sentence_source": "generated"}, {"text": "活動をしすぎて、体の力を使い切ってしまった。", "target_word": "活動", "complexity_tier": "T3", "furigana": "活動[かつどう]をしすぎて、体[からだ]の力[ちから]を使[つか]い切[き]ってしまった。", "sentence_source": "generated"}, {"text": "子どもは活動が多いので、たくさん食べる必要がある。", "target_word": "活動", "complexity_tier": "T3", "furigana": "子[こ]どもは活動[かつどう]が多[おお]いので、たくさん食[た]べる必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "活動に必要な力は、食べ物からもらっている。", "target_word": "活動", "complexity_tier": "T3", "furigana": "活動[かつどう]に必要[ひつよう]な力[ちから]は、食[た]べ物[もの]からもらっている。", "sentence_source": "generated"}, {"text": "運動などの活動をすると、体の中の力が使われる。", "target_word": "活動", "complexity_tier": "T3", "furigana": "運動[うんどう]などの活動[かつどう]をすると、体[からだ]の中[なか]の力[ちから]が使[つか]われる。", "sentence_source": "generated"}, {"text": "山での活動は、思ったより力が必要だった。", "target_word": "活動", "complexity_tier": "T3", "furigana": "山[やま]での活動[かつどう]は、思[おも]ったより力[ちから]が必要[ひつよう]だった。", "sentence_source": "generated"}, {"text": "寝不足だと、一日の活動に使う力が足りなくなる。", "target_word": "活動", "complexity_tier": "T3", "furigana": "寝不足[ねぶそく]だと、一日[いちにち]の活動[かつどう]に使[つか]う力[ちから]が足[た]りなくなる。", "sentence_source": "generated"}, {"text": "活動のあとにお米を食べて、力を戻した。", "target_word": "活動", "complexity_tier": "T3", "furigana": "活動[かつどう]のあとにお米[こめ]を食[た]べて、力[ちから]を戻[もど]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "活動", "label": "基本形"}, {"form": "活動する", "label": "辞書形"}, {"form": "活動した", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "体を動かして何かをする行い・動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: もどす (Zipf 2.38)']::text[], '0407d051-9691-48fa-9fde-4e2c2cf19218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36622, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活動", "is_correct": true, "explanation": "「午前中の活動に力が出ない」で、ここに入るのは活動の語だけ。"}, {"text": "天気", "is_correct": false, "explanation": "「午前中の天気に力が出ない」とは言わないので、文の意味が合わない。"}, {"text": "体温", "is_correct": false, "explanation": "「午前中の体温に力が出ない」は意味が通らないので合わない。"}, {"text": "食器", "is_correct": false, "explanation": "「午前中の食器に力が出ない」は意味が通らないので合わない。"}], "explanations": {"活動": "「午前中の活動に力が出ない」で、ここに入るのは活動の語だけ。", "天気": "「午前中の天気に力が出ない」とは言わないので、文の意味が合わない。", "体温": "「午前中の体温に力が出ない」は意味が通らないので合わない。", "食器": "「午前中の食器に力が出ない」は意味が通らないので合わない。"}, "sentence_index": 0, "correct_answer": "活動"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一日中走って、体に活動がたまった。", "explanation": "ここは〈疲れ〉の意味。体にたまるのは疲れで、活動とは言えないので合わない。"}, {"text": "活動が落ちて、長い距離を歩けなくなった。", "explanation": "ここは〈体力〉の意味。体の疲れで落ちるのは体力で、活動とは言い換えられないので合わない。"}, {"text": "朝からひどい活動におそわれて、ぼんやりしていた。", "explanation": "ここは〈眠気〉の意味。おそってくるのは眠気で、活動では言い換えられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36622, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活動", "is_correct": true, "explanation": "「運動などの活動をすると」で、体を動かす行いを表すので合う。"}, {"text": "入浴", "is_correct": false, "explanation": "「運動などの入浴」は並びとして不自然で、ここには合わない。"}, {"text": "食事", "is_correct": false, "explanation": "「運動などの食事」は並びとして不自然で、ここには合わない。"}, {"text": "通話", "is_correct": false, "explanation": "「運動などの通話」は意味が通らないので合わない。"}], "explanations": {"活動": "「運動などの活動をすると」で、体を動かす行いを表すので合う。", "入浴": "「運動などの入浴」は並びとして不自然で、ここには合わない。", "食事": "「運動などの食事」は並びとして不自然で、ここには合わない。", "通話": "「運動などの通話」は意味が通らないので合わない。"}, "sentence_index": 6, "correct_answer": "活動"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宿題をしていたら、活動が切れて進まなかった。", "explanation": "ここは〈集中力〉の意味。途切れるのは集中力で、活動は途切れるとは言えないので合わない。"}, {"text": "ボールの活動がすごくて、遠くまで飛んでいった。", "explanation": "ここは〈勢い〉の意味。ボールの飛ぶ強さは勢いで、活動とは言えないので合わない。"}, {"text": "このスープは活動が濃くておいしい。", "explanation": "ここは〈味〉の意味。味の濃さは活動とは言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36622, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "活動を終わって、体の力が戻った。", "corrected_sentence": "活動が終わって、体の力が戻った。", "error_description": "「終わる」は自動詞で、主語に「が」を取る。「活動を終わって」の「を」が誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36622, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪山での活動を、思ったより力が必要だった。", "corrected_sentence": "雪山での活動は、思ったより力が必要だった。", "error_description": "話題を示す「活動は」で受ける。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e666854-b664-433d-a130-ebf4d3a11098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36624, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「信頼が生じた」の「が」は、生じる主体の信頼を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「信頼へ生じた」は方向を示す格で、主体を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「信頼を生じた」は不自然。生じるは自動詞で、対象を「を」で示せない。"}, {"text": "の", "is_correct": false, "explanation": "「信頼の生じた」は名詞修飾になり、ここでは文が終わらない。"}], "correct_answer": "が", "explanations": {"が": "「信頼が生じた」の「が」は、生じる主体の信頼を示す。", "へ": "「信頼へ生じた」は方向を示す格で、主体を示せない。", "を": "「信頼を生じた」は不自然。生じるは自動詞で、対象を「を」で示せない。", "の": "「信頼の生じた」は名詞修飾になり、ここでは文が終わらない。"}, "error_tags": {"へ": "方向・目的地", "を": "目的語（対象）", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
