INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36624, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "（義務・権利・感情などが）新たにできること。", "primary_collocate": null, "pronunciation": "しょうずる", "ipa": "ɕoːzɯɾɯ", "syllable_count": 4, "sentences": [{"text": "契約を結ぶと、双方に守る義務が生ずる。", "target_word": "生ずる", "complexity_tier": "T4", "furigana": "契約[けいやく]を結[むす]ぶと、双方[そうほう]に守[まも]る義務[ぎむ]が生[しょう]ずる。", "sentence_source": "generated"}, {"text": "長い間話すうちに、二人の間に信頼が生じた。", "target_word": "生じた", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]話[はな]すうちに、二人[ふたり]の間[あいだ]に信頼[しんらい]が生[しょう]じた。", "sentence_source": "generated"}, {"text": "実際に使ってみて、この方法なら続けられるという自信が生じた。", "target_word": "生じた", "complexity_tier": "T4", "furigana": "実際[じっさい]に使[つか]ってみて、この方法[ほうほう]なら続[つづ]けられるという自信[じしん]が生[しょう]じた。", "sentence_source": "generated"}, {"text": "十八歳になると、選挙で投票する権利が生じる。", "target_word": "生じる", "complexity_tier": "T3", "furigana": "十八歳[じゅうはっさい]になると、選挙[せんきょ]で投票[とうひょう]する権利[けんり]が生[しょう]じる。", "sentence_source": "generated"}, {"text": "本を読み進めるうちに、もっと知りたいという気持ちが生じた。", "target_word": "生じた", "complexity_tier": "T3", "furigana": "本[ほん]を読[よ]み進[すす]めるうちに、もっと知[し]りたいという気持[きも]ちが生[しょう]じた。", "sentence_source": "generated"}, {"text": "新しい仕事を任されて、責任が生じることを実感した。", "target_word": "生じる", "complexity_tier": "T3", "furigana": "新[あたら]しい仕事[しごと]を任[まか]されて、責任[せきにん]が生[しょう]じることを実感[じっかん]した。", "sentence_source": "generated"}, {"text": "練習を重ねたので、人前でも落ち着いて話せる余裕が生じた。", "target_word": "生じた", "complexity_tier": "T4", "furigana": "練習[れんしゅう]を重[かさ]ねたので、人前[ひとまえ]でも落[お]ち着[つ]いて話[はな]せる余裕[よゆう]が生[しょう]じた。", "sentence_source": "generated"}, {"text": "支払いが遅れると、利息が生ずる。", "target_word": "生ずる", "complexity_tier": "T4", "furigana": "支払[しはら]いが遅[おく]れると、利息[りそく]が生[しょう]ずる。", "sentence_source": "generated"}, {"text": "親になって、この子を守りたいという強い思いが生じた。", "target_word": "生じた", "complexity_tier": "T3", "furigana": "親[おや]になって、この子[こ]を守[まも]りたいという強[つよ]い思[おも]いが生[しょう]じた。", "sentence_source": "generated"}, {"text": "この書類にサインしなければ、法的な責任は生じない。", "target_word": "生じない", "complexity_tier": "T4", "furigana": "この書類[しょるい]にサインしなければ、法的[ほうてき]な責任[せきにん]は生[しょう]じない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生ずる", "label": "終止形・連体形"}, {"form": "生じる", "label": "終止形(同義の形)"}, {"form": "生じた", "label": "過去形"}, {"form": "生じて", "label": "て形"}, {"form": "生じない", "label": "否定形"}, {"form": "生ずれば", "label": "仮定形"}], "register": "書き言葉・硬い", "sense_fingerprint": "義務・権利・気持ちなどが新しくできる、発生する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81da9844-740f-4ffe-9e77-80aebb2b7405') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36624, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生ずる", "is_correct": true, "explanation": "義務が新たにできるという意味なので、「生ずる」が入る。"}, {"text": "結ぶ", "is_correct": false, "explanation": "「義務が結ぶ」は意味が通らない。結ぶは人や物を繋ぐ動作で、義務を主語にできない。"}, {"text": "破る", "is_correct": false, "explanation": "「義務が破る」は不自然。破るは守るべきものを壊す動作で、主語は人になる。"}, {"text": "届く", "is_correct": false, "explanation": "「義務が届く」は意味が通らない。届くは相手や場所に達する意味で、義務の発生には合わない。"}], "explanations": {"生ずる": "義務が新たにできるという意味なので、「生ずる」が入る。", "結ぶ": "「義務が結ぶ」は意味が通らない。結ぶは人や物を繋ぐ動作で、義務を主語にできない。", "破る": "「義務が破る」は不自然。破るは守るべきものを壊す動作で、主語は人になる。", "届く": "「義務が届く」は意味が通らない。届くは相手や場所に達する意味で、義務の発生には合わない。"}, "sentence_index": 0, "correct_answer": "生ずる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その家に、双子の赤ちゃんが生じた。", "explanation": "ここは〈生まれる〉の意味。生じるは義務・権利・感情など抽象的なものが新たにできる場合に使い、人の誕生には使わない。"}, {"text": "この部屋は、父が一人で生じた。", "explanation": "ここは〈作る〉の意味。生じるは自然に現れる・起きることを指し、人が意図して作ることには使わない。"}, {"text": "この町の人口は、年々生じている。", "explanation": "ここは〈増える〉の意味。生じるは新しく現れることで、人口の増加を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36624, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生じた", "is_correct": true, "explanation": "練習を重ねた結果、余裕が新たにできたという文脈なので、「生じた」が入る。"}, {"text": "散った", "is_correct": false, "explanation": "「余裕が散った」は意味が通らない。散るは花や物がばらばらになる動きで、余裕とは結びつかない。"}, {"text": "配られた", "is_correct": false, "explanation": "「余裕が配られた」は意味が通らない。配るは人に物を分ける動作で、余裕は配れない。"}, {"text": "割れた", "is_correct": false, "explanation": "「余裕が割れた」は意味が通らない。割れるは物が砕ける意味で、余裕の発生には合わない。"}], "explanations": {"生じた": "練習を重ねた結果、余裕が新たにできたという文脈なので、「生じた」が入る。", "散った": "「余裕が散った」は意味が通らない。散るは花や物がばらばらになる動きで、余裕とは結びつかない。", "配られた": "「余裕が配られた」は意味が通らない。配るは人に物を分ける動作で、余裕は配れない。", "割れた": "「余裕が割れた」は意味が通らない。割れるは物が砕ける意味で、余裕の発生には合わない。"}, "sentence_index": 6, "correct_answer": "生じた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ずっと探していた財布が、ようやく生じた。", "explanation": "ここは〈見つかる〉の意味。生じるは新しく現れる事柄に使い、既にあったものを見つけることには使わない。"}, {"text": "ダイエットを続けたら、体重が生じて驚いた。", "explanation": "ここは〈減る〉の意味。生じるは新しく現れることを指し、体重が落ちる意味では使わない。"}, {"text": "ネットで注文した荷物が、昨日生じた。", "explanation": "ここは〈届く〉の意味。生じるは物が到着することには使わず、新たに発生した事柄に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36624, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試験に落ちると、悔しい気持ちが生じなる。", "corrected_sentence": "試験に落ちると、悔しい気持ちが生じる。", "error_description": "「生じる」の活用を誤っている。終止形は「生じる」で、「生じなる」は正しい形ではない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "生じた", "is_correct": true, "explanation": "過去形で、話し続けるうちに信頼が生まれたという出来事を述べる。"}, {"text": "生じて", "is_correct": false, "explanation": "て形で、この位置では文を終えられない。"}, {"text": "生じない", "is_correct": false, "explanation": "否定形で、信頼が生まれたという文脈と矛盾する。"}, {"text": "生ずれば", "is_correct": false, "explanation": "仮定形で、主節がなく文を終えられない。"}], "correct_form": "生じた", "base_form": "生ずる", "form_label": "過去形", "sentence_index": 1, "explanations": {"生じた": "過去形で、話し続けるうちに信頼が生まれたという出来事を述べる。", "生じて": "て形で、この位置では文を終えられない。", "生じない": "否定形で、信頼が生まれたという文脈と矛盾する。", "生ずれば": "仮定形で、主節がなく文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36624, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この契約書を読まずにサインすると、思わぬ義務が生づる。", "corrected_sentence": "この契約書を読まずにサインすると、思わぬ義務が生ずる。", "error_description": "表記が誤り。「生ずる」は「ず」で書く。「生づる」は誤った表記。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "生ずる", "is_correct": true, "explanation": "終止形で、支払いが遅れた結果として利息が発生するという条件の結果を述べる。"}, {"text": "生じよう", "is_correct": false, "explanation": "意志の形で、利息が発生するという事実を述べる文には合わない。"}, {"text": "生じれば", "is_correct": false, "explanation": "仮定形で、主節がなく文を終えられない。"}, {"text": "生じ", "is_correct": false, "explanation": "連用形で、この位置では文を終えられない。"}], "correct_form": "生ずる", "base_form": "生ずる", "form_label": "終止形・連体形", "sentence_index": 7, "explanations": {"生ずる": "終止形で、支払いが遅れた結果として利息が発生するという条件の結果を述べる。", "生じよう": "意志の形で、利息が発生するという事実を述べる文には合わない。", "生じれば": "仮定形で、主節がなく文を終えられない。", "生じ": "連用形で、この位置では文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
