INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36625, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「被害が生ずる」の「が」。生ずるの主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、主語の「被害」を示せず「被害と生ずる」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、生ずるの行き先にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を示すので、「被害より生ずる」では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「被害が生ずる」の「が」。生ずるの主語を示す。", "と": "「と」は相手や並列を示すので、主語の「被害」を示せず「被害と生ずる」は成り立たない。", "へ": "「へ」は方向を示すので、生ずるの行き先にはならない。", "より": "「より」は比較や起点を示すので、「被害より生ずる」では文が成り立たない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96d180a7-07d8-4c7b-b08f-1bf5f6ee1c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
